                second = Task {
                    try await store.open(command: secondCommand, capacityProfile: profile, roomShardID: "room-a",
                        roomID: .init(uuid: UUID()), now: Date(timeIntervalSince1970: 1_750_000_000))
                }
                try await waitForWriters(2)
                await gate.releaseTransaction()
                try await holder.value
                guard case .opened(let opened) = try await first.value else { throw CancellationError() }
                #expect(opened.roomID == expectedRoomID)
                let secondResult = try await #require(second).value
                switch path {
                case "different-operation": #expect(secondResult == .opened(opened))
                case "different-target": #expect(secondResult == .idempotencyConflict)
                default: #expect(secondResult == .idempotent(opened))
                }
                let operationCount: Int64 = (existingPair ? 1 : 0) + (path == "different-operation" ? 2 : 1)
                #expect(try await count("im_v2.direct_room_operations", on: sql) == operationCount)
                #expect(try await count("im_v2.direct_room_pairs", on: sql) == 1)
                #expect(try await count("im_v2.rooms WHERE room_kind = 'direct'", on: sql) == 1)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.direct_room_operations op JOIN im_v2.direct_room_pairs pair ON pair.room_id = op.room_id JOIN im_v2.rooms room ON room.room_id = pair.room_id WHERE op.created_at = pair.created_at AND room.created_at = pair.created_at").first(decoding: CountRow.self)?.value == operationCount)
                #expect(try await sql.raw("SELECT created_at AS value FROM im_v2.direct_room_pairs WHERE room_id = \(bind: opened.roomID.uuidValue!)").first(decoding: RevocationClockDateRow.self)?.value == opened.createdAt)
                #expect(try await sql.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == nil)
                #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_room_profile'", on: sql) == 0)
                #expect(try await count("im_v2.user_state_event_outbox WHERE projection_kind = 'direct_room_profile'", on: sql) == 1)
                #expect(try await sql.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox event
                    JOIN im_v2.rooms room ON room.room_id = (event.payload->>'room_id')::uuid
                    WHERE event.projection_kind = 'direct_room_profile'
                      AND (event.payload->>'room_created_at_ms')::bigint = floor(extract(epoch FROM room.created_at) * 1000)::bigint
                    """).first(decoding: CountRow.self)?.value == 1)
                func snapshot() async throws -> [String] {
                    var values: [String] = []
                    for table in ["rooms", "direct_room_pairs", "direct_room_operations", "room_memberships", "room_admission", "user_direct_send_policy_versions", "user_sync_sequences", "user_sync_log", "user_state_event_outbox"] {
                        guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                        values.append(row.value)
                    }
                    return values
                }
                let committed = try await snapshot()
                let conflict = try V2OpenDirectRoomCommand(actorUserID: senderID, operationID: .init(uuid: operation), targetUserID: otherTarget)
                for date in [Date(timeIntervalSince1970: .nan), Date(timeIntervalSince1970: .infinity), now] {
                    let calls = shadow.calls
                    #expect(try await store.open(command: command, capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: date) == .idempotent(opened))
                    #expect(try await store.open(command: conflict, capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: date) == .idempotencyConflict)
                    #expect(shadow.calls == calls)
                    #expect(try await snapshot() == committed)
                }
            } catch {
                first.cancel()
                second?.cancel()
                await gate.releaseTransaction()
                _ = await holder.result
                _ = await first.result
                if let second { _ = await second.result }
                throw error
            }
        }
    }

    @Test("Concurrent direct preference retries retain one policy transition and committed timestamp",
          arguments: ["stranger", "stranger-final-revision", "user-add"], [false, true])
    func directPreferenceConcurrentReplay(path: String, mismatch: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 946_684_800 + 0.00000125)
            let later = Date(timeIntervalSince1970: 1_750_000_000)
            let stranger = path != "user-add"
            let finalRevision = path == "stranger-final-revision"
            let table = stranger ? "user_stranger_message_preferences" : "user_add_preferences"
            let column = stranger ? "allows_stranger_messages" : "allows_being_added"
            let operations = stranger ? "stranger_message_preference_operations" : "user_add_preference_operations"
            try await sql.raw("INSERT INTO im_v2.\(unsafeRaw: table) (user_id, \(unsafeRaw: column), updated_at) VALUES (\(bind: senderUUID), TRUE, \(bind: later))").run()
            if stranger {
                try await sql.raw("INSERT INTO im_v2.user_direct_send_policy_versions (user_id, revision, updated_at) VALUES (\(bind: senderUUID), \(bind: finalRevision ? Int64.max - 1 : 1), \(bind: later)) ON CONFLICT (user_id) DO UPDATE SET revision = EXCLUDED.revision, updated_at = EXCLUDED.updated_at").run()
            }
            let operation = UUID()
            let shadow = PreferenceReplayClockShadow()
            let store = PostgresV2DirectMessagingStore(database: database, shadowForwarder: shadow)
            func perform(conflict: Bool, date: Date) async throws -> V2ConversationCapabilitiesOutcome<Date> {
                if stranger {
                    switch try await store.setStrangerMessagePermission(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: operation), permission: conflict ? .allow : .deny), now: date) {
                    case .updated(_, let time): return .applied(time)
                    case .idempotent(_, let time): return .idempotent(time)
                    case .idempotencyConflict: return .idempotencyConflict
                    }
                }
                switch try await store.setUserAddPermission(command: .init(actorUserID: senderID,
                    operationID: .init(uuid: operation), permission: conflict ? .allow : .deny), now: date) {
                case .updated(_, let time): return .applied(time)
                case .idempotent(_, let time): return .idempotent(time)
                case .idempotencyConflict: return .idempotencyConflict
                }
            }
            let gate = PostgreSQLTransactionGate()
            let holder = Task {
                try await database.transaction { transaction in
                    let held = try #require(transaction as? any SQLDatabase)
                    try await held.raw("SELECT user_id FROM im_v2.\(unsafeRaw: table) WHERE user_id = \(bind: senderUUID) FOR UPDATE").run()
                    await gate.holdTransaction()
                }
            }
            await gate.waitUntilHeld()
            func waitForWriters(_ expected: Int64) async throws {
                for _ in 0..<500 {
                    let waiting = try await sql.raw("SELECT COUNT(*) AS value FROM pg_stat_activity WHERE datname = current_database() AND wait_event_type = 'Lock' AND (query LIKE \(bind: "%im_v2." + table + "%") OR query LIKE '%pg_advisory_xact_lock%')").first(decoding: CountRow.self)?.value ?? 0
                    if waiting == expected { return }
                    try await Task.sleep(for: .milliseconds(10))
                }
                Issue.record("Expected overlapping direct preference writers to wait on database locks")
                throw CancellationError()
            }
            let first = Task { try await perform(conflict: false, date: now) }
            var second: Task<V2ConversationCapabilitiesOutcome<Date>, Error>?
            do {
                try await waitForWriters(1)
                second = Task { try await perform(conflict: mismatch, date: later) }
                try await waitForWriters(2)
                await gate.releaseTransaction()
                try await holder.value
                guard case .applied(let persisted) = try await first.value else { throw CancellationError() }
                #expect(try await #require(second).value == (mismatch ? .idempotencyConflict : .idempotent(persisted)))
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table) preference JOIN im_v2.\(unsafeRaw: operations) op ON op.actor_user_id = preference.user_id JOIN im_v2.user_sync_log log ON log.user_id = op.actor_user_id AND log.source_event_id = op.operation_id WHERE preference.user_id = \(bind: senderUUID) AND op.operation_id = \(bind: operation) AND NOT preference.\(unsafeRaw: column) AND preference.updated_at = \(bind: now) AND op.updated_at = preference.updated_at AND log.created_at = op.updated_at").first(decoding: CountRow.self)?.value == 1)
                if stranger {
                    #expect(try await sql.raw("SELECT revision AS value FROM im_v2.user_direct_send_policy_versions WHERE user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == (finalRevision ? Int64.max : 2))
                }
                func snapshot() async throws -> [String] {
                    var values: [String] = []
                    for name in [table, operations, "user_direct_send_policy_versions", "user_sync_sequences", "user_sync_log"] {
                        guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                        values.append(row.value)
                    }
                    return values
                }
                let committed = try await snapshot()
                let call = PreferenceReplayClockShadow.Call(userID: senderID, sourceEventID: .init(uuid: operation),
                    kinds: [stranger ? "stranger_message_permission" : "user_add_permission"])
                #expect(shadow.calls == Array(repeating: call, count: mismatch ? 1 : 2))
                for date in [Date(timeIntervalSince1970: .nan), Date(timeIntervalSince1970: .infinity), later] {
                    let calls = shadow.calls
                    #expect(try await perform(conflict: false, date: date) == .idempotent(persisted))
                    #expect(try await perform(conflict: true, date: date) == .idempotencyConflict)
                    #expect(shadow.calls == calls + [call])
                    #expect(try await snapshot() == committed)
                }
                #expect(try await count("im_v2." + operations, on: sql) == 1)
                #expect(try await sql.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == 1)
            } catch {
                first.cancel()
                second?.cancel()
                await gate.releaseTransaction()
                _ = await holder.result
                _ = await first.result
                if let second { _ = await second.result }
                throw error
            }
        }
    }

    @Test("Direct policy revision exhaustion rolls back first replies and policy changes",
          arguments: ["planner", "preplanned", "room-log", "atomic", "stranger", "relationship", "block"])
    func directPolicyRevisionBoundary(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let isSend = ["planner", "preplanned", "room-log", "atomic"].contains(path)
            let direct = PostgresV2DirectMessagingStore(database: database)
            let social = PostgresV2SocialRelationshipStore(database: database)
            var rooms: [RoomID] = []
            for peer in path == "atomic" ? [memberTwoUUID, memberThreeUUID] : [memberTwoUUID] {
                guard case .opened(let room) = try await direct.open(command: .init(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: .init(uuid: peer)), capacityProfile: profile,
                    roomShardID: "room-a", roomID: .init(uuid: UUID()), now: now) else { throw CancellationError() }
                rooms.append(room.roomID)
            }
            if path == "block" {
                try await sql.raw("INSERT INTO im_v2.user_relationships (lower_user_id, higher_user_id, state, requested_by_user_id, updated_at) VALUES (LEAST(\(bind: senderUUID), \(bind: memberTwoUUID)), GREATEST(\(bind: senderUUID), \(bind: memberTwoUUID)), 'accepted', \(bind: senderUUID), \(bind: now))").run()
            }
            func store(credits: Bool) throws -> PostgresV2RoomWriteStore {
                PostgresV2RoomWriteStore(database: database,
                    strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                    directRoomLogAdmissionMode: .shardOnly,
                    shardAdmissionCommandCreditPool: credits ? .init(database: database, batchSize: 1) : nil)
            }
            let writer = try store(credits: path == "atomic")
            let replayWriter = try store(credits: false)
            func request(_ room: RoomID) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: room, senderUserID: senderID, clientMessageID: .init(uuid: UUID()),
                    text: "direct revision boundary", limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            let inputs = try rooms.map { try request($0) }
            let operation = UUID()
            var receipts: [V2MessageAcceptanceReceipt] = []
            func perform(replay: Bool) async throws {
                switch path {
                case "stranger":
                    switch try await direct.setStrangerMessagePermission(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: operation), permission: .deny), now: now) {
                    case .updated: #expect(!replay)
                    case .idempotent: #expect(replay)
                    default: Issue.record("Expected a committed permission change")
                    }
                case "relationship":
                    switch try await social.changeRelationship(.init(actorUserID: senderID, operationID: .init(uuid: operation),
                        targetUserID: .init(uuid: memberTwoUUID), action: .request), now: now) {
                    case .changed: #expect(!replay)
                    case .idempotent: #expect(replay)
                    default: Issue.record("Expected a committed relationship change")
                    }
                case "block":
                    switch try await social.changeUserBlock(.init(actorUserID: senderID, operationID: .init(uuid: operation),
                        targetUserID: .init(uuid: memberTwoUUID), action: .block), now: now) {
                    case .changed: #expect(!replay)
                    case .idempotent: #expect(replay)
                    default: Issue.record("Expected a committed block change")
                    }
                default:
                    var outcomes: [V2SendMessageOutcome] = []
                    if path == "atomic" && !replay { outcomes = try await writer.acceptAtomically(requests: inputs) }
                    else {
                        let active = replay ? replayWriter : writer
                        for input in inputs {
                            outcomes.append(try await active.accept(command: input.command, capacityProfile: profile,
                                identifiers: input.identifiers, now: input.now))
                        }
                    }
                    for (index, outcome) in outcomes.enumerated() {
                        switch outcome {
                        case .accepted(let message): #expect(!replay); receipts.append(message.receipt)
                        case .idempotent(let receipt): #expect(replay); #expect(receipts[index] == receipt)
                        default: Issue.record("Expected a committed message")
                        }
                    }
                }
            }
            let room = try #require(rooms[0].uuidValue)
            let table = path == "stranger" ? "user_direct_send_policy_versions" : "direct_room_pairs"
            let key = path == "stranger" ? "user_id" : "room_id"
            let rowID = path == "stranger" ? senderUUID : room
            let column = path == "stranger" ? "revision" : "direct_policy_revision"
            try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: Int64.max) WHERE \(unsafeRaw: key) = \(bind: rowID)").run()
            func revision() async throws -> Int64? {
                try await sql.raw("SELECT \(unsafeRaw: column) AS value FROM im_v2.\(unsafeRaw: table) WHERE \(unsafeRaw: key) = \(bind: rowID)").first(decoding: CountRow.self)?.value
            }
            func snapshot() async throws -> [String] {
                var result = [try await crossStoreClockState(on: sql)]
                for name in ["rooms", "room_memberships", "direct_room_pairs", "room_admission", "shard_admission_pools",
                    "messages", "message_send_completions", "message_projection_states", "message_content_versions", "room_events",
                    "stranger_message_windows",
                    "user_direct_send_policy_versions", "user_stranger_message_preferences", "stranger_message_preference_operations",
                    "user_relationships", "user_relationship_operations", "user_blocks", "user_block_operations"] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    result.append(row.value)
                }
                return result
            }
            let before = try await snapshot()
            for _ in 0..<2 {
                do { try await perform(replay: false); Issue.record("Expected revision exhaustion") }
                catch {
                    switch path {
                    case "stranger": #expect(error as? V2DirectMessagingStoreError == .corruptPersistenceState)
                    case "relationship", "block": #expect(error as? V2SocialRelationshipStoreError == .corruptPersistenceState)
                    case "atomic": #expect(error is V2RoomWriteStoreError || error is V2AtomicRoomWriteBatchError)
                    default: #expect(error as? V2RoomWriteStoreError == .corruptPersistenceState)
                    }
                }
                #expect(try await snapshot() == before)
            }
            try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: Int64.max - 1) WHERE \(unsafeRaw: key) = \(bind: rowID)").run()
            try await perform(replay: false)
            #expect(try await revision() == Int64.max)
            let committed = try await snapshot()
            for _ in 0..<2 { try await perform(replay: true); #expect(try await snapshot() == committed) }
            if isSend {
                // Once the first-reply marker is true, ordinary later messages
                // need no policy revision. The maximum revision stays usable.
                for room in rooms {
                    let input = try request(room)
                    guard case .accepted = try await replayWriter.accept(command: input.command, capacityProfile: profile,
                        identifiers: input.identifiers, now: input.now) else { throw CancellationError() }
                }
                #expect(try await revision() == Int64.max)
                #expect(try await count("im_v2.messages", on: sql) == Int64(rooms.count * 2))
            }
        }
    }

    @Test("Room and timeline cursor exhaustion preserves rollback and committed replay",
          arguments: ["planner", "preplanned", "room-log", "group", "hybrid", "direct-cold", "direct-hot", "hybrid-batch", "denial"], [false, true])
    func roomWriteCursorBoundary(path: String, timeline: Bool) async throws {
        let hybrid = path.hasPrefix("hybrid")
        let direct = path != "group" && !hybrid
        let batch = path == "direct-cold" || path == "direct-hot" || path == "hybrid-batch"
        try await withForwardOwnerDatabases(mode: hybrid ? .large : .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            var rooms: [RoomID] = []
            if direct {
                let peers = batch ? [memberTwoUUID, memberThreeUUID] : [memberTwoUUID]
                for peer in peers {
                    guard case .opened(let opened) = try await PostgresV2DirectMessagingStore(database: database).open(
                        command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: peer)),
                        capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: now)
                    else { throw CancellationError() }
                    rooms.append(opened.roomID)
                }
            } else { rooms = batch ? [roomID, roomID] : [roomID] }
            let cache = V2DirectRoomLogFastAppendCache()
            let credits = V2ShardAdmissionCommandCreditPool(database: database, batchSize: 1)
            func store(warm: Bool, withCredits: Bool) throws -> PostgresV2RoomWriteStore {
                PostgresV2RoomWriteStore(database: database,
                    strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                    directRoomLogAdmissionMode: .shardOnly,
                    directRoomLogFastAppendCache: warm ? cache : .init(),
                    shardAdmissionCommandCreditPool: withCredits ? credits : nil)
            }
            let warm = try store(warm: true, withCredits: batch)
            let replay = try store(warm: false, withCredits: false)
            func request(_ room: RoomID) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: room, senderUserID: senderID, clientMessageID: .init(uuid: UUID()),
                    text: "room cursor boundary", limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            func scalar(_ input: V2RoomWriteRequest, on writer: PostgresV2RoomWriteStore) async throws -> V2SendMessageOutcome {
                try await writer.accept(command: input.command, capacityProfile: profile, identifiers: input.identifiers, now: input.now)
            }
            var baseline: [(V2RoomWriteRequest, V2MessageAcceptanceReceipt)] = []
            for room in Set(rooms) {
                let input = try request(room)
                guard case .accepted(let message) = try await scalar(input, on: warm) else { throw CancellationError() }
                baseline.append((input, message.receipt))
            }
            if path == "denial" {
                _ = try await PostgresV2DirectMessagingStore(database: database).setStrangerMessagePermission(
                    command: .init(actorUserID: .init(uuid: memberTwoUUID), operationID: .init(uuid: UUID()), permission: .deny), now: now)
            }
            let writer = path == "direct-hot" ? warm : try store(warm: false, withCredits: batch)
            let inputs = try rooms.map { try request($0) }
            func perform() async throws -> [V2SendMessageOutcome] {
                if batch { return try await writer.acceptAtomically(requests: inputs) }
                return [try await scalar(inputs[0], on: writer)]
            }
            func snapshot() async throws -> [String] {
                var result = [try await crossStoreClockState(on: sql)]
                for table in ["rooms", "room_memberships", "direct_room_pairs", "room_admission", "messages",
                    "message_send_completions", "message_projection_states", "message_content_versions", "message_media_references",
                    "message_mentions", "room_events", "room_timeline_activities", "direct_message_denials",
                    "stranger_message_windows",
                    "group_event_wake_outbox"] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    result.append(row.value)
                }
                // Precharged process credits can remain durably reserved after
                // rollback; their in-flight and committed counts are checked below.
                return result
            }
            let column = timeline ? "timeline_sequence" : "room_sequence"
            let room = try #require(rooms[0].uuidValue)
            let needed: Int64 = path == "hybrid-batch" ? 2 : 1
            try await sql.raw("UPDATE im_v2.rooms SET \(unsafeRaw: column) = \(bind: Int64.max - needed + 1) WHERE room_id = \(bind: room)").run()
            let before = try await snapshot()
            for (input, receipt) in baseline { #expect(try await scalar(input, on: replay) == .idempotent(receipt)) }
            #expect(try await snapshot() == before)
            if path == "denial" && !timeline {
                // A private denial consumes only a timeline position. A full
                // message cursor must not suppress this normal business result.
                guard case .denied(let denial) = try await scalar(inputs[0], on: writer) else { throw CancellationError() }
                let committed = try await snapshot()
                #expect(try await scalar(inputs[0], on: replay) == .denied(denial))
                #expect(try await snapshot() == committed)
                #expect(try await sql.raw("SELECT room_sequence AS value FROM im_v2.rooms WHERE room_id = \(bind: room)").first(decoding: CountRow.self)?.value == Int64.max)
                return
            }
            let initialCredits = await credits.snapshot()
            let initialFast = await cache.snapshot()
            for attempt in 0..<2 {
                do { _ = try await perform(); Issue.record("Expected cursor exhaustion to reject the whole write") }
                catch {
                    if path == "hybrid-batch" { #expect(error is V2RoomWriteStoreError || error is V2AtomicRoomWriteBatchError) }
                    else { #expect(error as? V2RoomWriteStoreError == .corruptPersistenceState) }
                }
                #expect(try await snapshot() == before)
                let currentCredits = await credits.snapshot()
                #expect(currentCredits.inFlightCredits == 0 && currentCredits.committedCredits == initialCredits.committedCredits)
                if path == "direct-hot" && attempt == 0 {
                    #expect(await cache.snapshot().attemptedAppends > initialFast.attemptedAppends)
                }
            }
            try await sql.raw("UPDATE im_v2.rooms SET \(unsafeRaw: column) = \(bind: Int64.max - needed) WHERE room_id = \(bind: room)").run()
            let outcomes = try await perform()
            #expect(outcomes.count == inputs.count)
            #expect(try await sql.raw("SELECT \(unsafeRaw: column) AS value FROM im_v2.rooms WHERE room_id = \(bind: room)").first(decoding: CountRow.self)?.value == Int64.max)
            let committed = try await snapshot()
            for _ in 0..<2 {
                for (input, outcome) in zip(inputs, outcomes) {
                    switch outcome {
                    case .accepted(let message): #expect(try await scalar(input, on: replay) == .idempotent(message.receipt))
                    case .denied(let denial): #expect(path == "denial"); #expect(try await scalar(input, on: replay) == .denied(denial))
                    default: Issue.record("Expected a committed result at the final valid cursor")
                    }
                }
                #expect(try await snapshot() == committed)
            }
        }
    }

    @Test("User sequence exhaustion preserves committed direct messages and recoverable personal events",
          arguments: ["scalar-sender", "scalar-peer", "atomic-sender", "atomic-peer", "denial-activity", "denial-capability"])
    func directWriteProjectionSequenceBoundary(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, target, sql, targetSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let atomic = path.hasPrefix("atomic")
            let denied = path.hasPrefix("denial")
            let peers = atomic ? [memberTwoUUID, memberThreeUUID] : [memberTwoUUID]
            let direct = PostgresV2DirectMessagingStore(database: database)
            var rooms: [RoomID] = []
            for peer in peers {
                guard case .opened(let room) = try await direct.open(command: .init(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: .init(uuid: peer)), capacityProfile: profile,
                    roomShardID: "room-a", roomID: .init(uuid: UUID()), now: now) else { throw CancellationError() }
                rooms.append(room.roomID)
            }
            if denied {
                _ = try await direct.setStrangerMessagePermission(command: .init(actorUserID: .init(uuid: memberTwoUUID),
                    operationID: .init(uuid: UUID()), permission: .deny), now: now)
            }
            func store(batch: Bool) throws -> PostgresV2RoomWriteStore {
                PostgresV2RoomWriteStore(database: database,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                directRoomLogAdmissionMode: .shardOnly,
                shardAdmissionCommandCreditPool: batch ? .init(database: database, batchSize: 1) : nil)
            }
            let writer = try store(batch: atomic)
            let replayWriter = try store(batch: false)
            let requests = try rooms.map { room in
                V2RoomWriteRequest(command: try .init(roomID: room, senderUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "direct sequence boundary", limits: .init(maxUTF8Bytes: 64)),
                    capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            func scalar(_ request: V2RoomWriteRequest, on active: PostgresV2RoomWriteStore) async throws -> V2SendMessageOutcome {
                try await active.accept(command: request.command, capacityProfile: profile,
                    identifiers: request.identifiers, now: request.now)
            }
            func perform() async throws -> [V2SendMessageOutcome] {
                if atomic { return try await writer.acceptAtomically(requests: requests) }
                return [try await scalar(requests[0], on: writer)]
            }
            func snapshot() async throws -> [String] {
                var result = [try await crossStoreClockState(on: sql)]
                for table in ["rooms", "room_memberships", "direct_room_pairs", "room_admission", "shard_admission_pools",
                    "messages", "message_send_completions", "message_projection_states", "message_content_versions",
                    "message_media_references", "message_mentions", "room_events", "room_timeline_activities",
                    "direct_message_denials", "stranger_message_windows", "user_state_event_outbox",
                    ] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    result.append(row.value)
                }
                return result
            }
            let recipient = path.hasSuffix("peer") ? memberTwoUUID : senderUUID
            let needed: Int64 = denied || path == "atomic-sender" ? 2 : 1
            let outbox = try PostgresV2UserStateEventOutbox(database: database)
            let projector = try PostgresV2UserStateEventProjector(database: target)
            let worker = V2UserStateEventWorker(outbox: outbox, projector: projector, now: { now })
            _ = try await worker.runOnce(limit: 100)
            for connection in [sql, targetSQL] {
                try await connection.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: recipient), \(bind: Int64.max)) ON CONFLICT (user_id) DO UPDATE SET next_sequence = EXCLUDED.next_sequence").run()
            }
            let outcomes = try await perform()
            #expect(outcomes.count == requests.count)
            // The room commit is independent of the exhausted user target.
            _ = try await worker.runOnce(limit: 100)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox WHERE user_id = \(bind: recipient) AND state = 'paused'").first(decoding: CountRow.self)?.value == needed)
            #expect(try await targetSQL.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: recipient)").first(decoding: CountRow.self)?.value == Int64.max)
            #expect(try await targetSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE user_id = \(bind: recipient) AND user_sync_sequence = \(bind: Int64.max)").first(decoding: CountRow.self)?.value == 0)
            #expect(try await worker.runOnce(limit: 100) == 0)
            // Restore test capacity and replay the preserved source events.
            try await targetSQL.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max - needed) WHERE user_id = \(bind: recipient)").run()
            try await sql.raw("UPDATE im_v2.user_state_event_outbox SET state = 'pending', next_attempt_at = \(bind: now) WHERE user_id = \(bind: recipient) AND state = 'paused'").run()
            #expect(try await worker.runOnce(limit: 100) == Int(needed))
            #expect(try await targetSQL.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: recipient)").first(decoding: CountRow.self)?.value == Int64.max)
            #expect(try await targetSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE user_id = \(bind: recipient) AND user_sync_sequence > \(bind: Int64.max - needed)").first(decoding: CountRow.self)?.value == needed)
            #expect(try await sql.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: recipient)").first(decoding: CountRow.self)?.value == Int64.max)
            #expect(try await count("im_v2.messages", on: sql) == (denied ? 0 : Int64(requests.count)))
            #expect(try await count("im_v2.direct_message_denials", on: sql) == (denied ? 1 : 0))
            let committed = try await snapshot()
            // A restarted worker replays durable operations through the scalar
            // path without precharged process credits. Replay must not need
            // another sequence allocation or alter the committed state.
            for _ in 0..<2 {
                for (request, outcome) in zip(requests, outcomes) {
                    switch outcome {
                    case .accepted(let message): #expect(try await scalar(request, on: replayWriter) == .idempotent(message.receipt))
                    case .denied(let denial): #expect(denied); #expect(try await scalar(request, on: replayWriter) == .denied(denial))
                    default: Issue.record("Expected a committed accepted or denied operation")
                    }
                }
                #expect(try await snapshot() == committed)
            }
        }
    }

    @Test("First direct sends preserve profile and capability timestamp precision across scalar and atomic writes",
          arguments: ["scalar", "atomic"], [0, 1, 2, 3, 4, 5, 6])
    func directAuxiliaryProjectionTimestampPrecision(path: String, clock: Int) async throws {
        let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000125, 1_750_000_000 + 0.12375,
            1_750_000_000 + 0.99999975, -0.00075, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10]
        let seconds = dates[clock]
        try await withForwardOwnerDatabases(mode: .standard) { database, target, sql, targetSQL, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let sourceTime = Date(timeIntervalSince1970: seconds)
            // Keep stranger quota cutoffs representable while testing extreme source profile dates.
            let now = seconds < -1_000_000_000 ? base : sourceTime
            try await sql.raw("UPDATE im_v2.public_user_profiles SET updated_at = \(bind: sourceTime)").run()
            let profile = try forwardImportTestProfile()
            let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry)").run()
            var rooms: [RoomID] = []
            var openingIDs: [UUID] = []
            for peer in [memberTwoUUID, memberThreeUUID] {
                let operation = UUID()
                guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: operation), targetUserID: .init(uuid: peer)),
                    capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
                rooms.append(room.roomID); openingIDs.append(operation)
            }
            let writer = PostgresV2RoomWriteStore(database: database,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                directRoomLogAdmissionMode: .shardOnly,
                shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            let requests = try rooms.map { room in
                V2RoomWriteRequest(command: try .init(roomID: room, senderUserID: senderID, clientMessageID: .init(uuid: UUID()),
                    text: "Direct auxiliary precision", limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            let outcomes: [V2SendMessageOutcome]
            if path == "atomic" { outcomes = try await writer.acceptAtomically(requests: requests) }
            else {
                var values: [V2SendMessageOutcome] = []
                for request in requests { values.append(try await writer.accept(command: request.command, capacityProfile: profile, identifiers: request.identifiers, now: now)) }
                outcomes = values
            }
            #expect(outcomes.count == 2)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 0)
            let outbox = try PostgresV2UserStateEventOutbox(database: database)
            let projector = try PostgresV2UserStateEventProjector(database: target)
            let deliveryTime = max(base, now)
            let leases = try await outbox.claim(now: deliveryTime, leaseDuration: 1, limit: 100)
            #expect(leases.count == 6)
            for lease in leases where lease.event.kind == .directRoomProfile {
                let object = try #require(JSONSerialization.jsonObject(with: Data(lease.event.payloadJSON.utf8)) as? [String: Any])
                #expect((object["room_created_at_ms"] as? NSNumber)?.int64Value == Int64(base.timeIntervalSince1970 * 1000))
            }
            for lease in leases {
                let sequence = try await projector.project(lease.event)
                #expect(try await projector.project(lease.event) == sequence)
                #expect(try await outbox.acknowledge(lease, sequence: sequence, now: deliveryTime))
            }
            for (index, outcome) in outcomes.enumerated() {
                guard case .accepted(let message) = outcome else { throw CancellationError() }
                let source = try #require(message.sourceEventID).uuidValue!
                let stored = try await sql.raw("SELECT created_at AS value FROM im_v2.messages WHERE message_id = \(bind: message.messageID.uuidValue!)").first(decoding: RevocationClockDateRow.self)
                let storedTime = try #require(stored).value
                let expectedProfile = try await sql.raw("SELECT updated_at AS value FROM im_v2.public_user_profiles WHERE user_id = \(bind: senderUUID)").first(decoding: RevocationClockDateRow.self)
                let profileMS = try v2GatewayMilliseconds(#require(expectedProfile).value)
                let opening = try await targetSQL.raw("SELECT (payload->>'updated_at_ms')::bigint AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: openingIDs[index]) AND projection_kind = 'direct_room_profile'").first(decoding: CountRow.self)
                #expect(opening?.value == profileMS)
                let projections = try await targetSQL.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.user_sync_log l
                    WHERE l.source_event_id = \(bind: source) AND l.created_at = \(bind: now) AND (
                        (l.projection_kind = 'direct_sending_capability' AND l.user_id = \(bind: senderUUID)
                         AND (l.payload->>'updated_at_ms')::bigint = \(bind: try v2GatewayMilliseconds(storedTime)))
                        OR (l.projection_kind = 'direct_room_profile' AND l.user_id = \(bind: index == 0 ? memberTwoUUID : memberThreeUUID)
                            AND (l.payload->>'updated_at_ms')::bigint = \(bind: profileMS))
                    )
                    """).first(decoding: CountRow.self)
                #expect(projections?.value == 2)
                let before = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.user_state_event_outbox r").first(decoding: StringValueRow.self)
                let request = requests[index]
                #expect(try await writer.accept(command: request.command, capacityProfile: profile, identifiers: request.identifiers, now: base) == .idempotent(message.receipt))
                let after = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.user_state_event_outbox r").first(decoding: StringValueRow.self)
                #expect(before?.value == after?.value)
            }
            #expect(try await count("im_v2.messages", on: sql) == 2)
            #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_room_profile'", on: targetSQL) == 4)
            #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_sending_capability'", on: targetSQL) == 2)
        }
    }

    @Test("Group creation returns the committed timestamp across all audience paths",
          arguments: [V2GroupCapacityClass.standard, .large], ["inline", "control-inline", "staged", "control-staged"])
    func groupCreationResponseTimestampPrecision(mode: V2GroupCapacityClass, path: String) async throws {
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let store = PostgresV2GroupMessagingStore(database: database)
            let control = PostgresV2GroupRoomCreationIntentStore(database: database)
            let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry)").run()
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["rooms", "group_rooms", "room_memberships", "group_room_operations", "room_events",
                    "user_state_event_outbox", "room_admission", "shard_admission_pools", "room_owner_routes",
                    "group_room_creation_drafts", "group_room_creation_draft_members", "group_room_creation_intents",
                    "group_room_creation_intent_members", "group_room_creation_intent_pages"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
                1_750_000_000 + 0.99999975, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10]
            for seconds in dates {
                let now = Date(timeIntervalSince1970: seconds)
                let operation = GroupRoomOperationID(uuid: UUID()), newRoom = RoomID(uuid: UUID())
                let event = EventID(uuid: UUID())
                let command = try V2CreateGroupRoomCommand(actorUserID: senderID, operationID: operation, title: "Precision group",
                    capacityClass: mode, initialMemberUserIDs: [.init(uuid: memberTwoUUID)])
                let staged = try V2StagedGroupRoomCommand(actorUserID: senderID, operationID: operation, title: command.title, capacityClass: mode, stagedMemberCount: 1)
                let intent = try V2GroupRoomCreationIntent(actorUserID: senderID, operationID: operation, roomID: newRoom, eventID: event,
                    roomShardID: "room-a", routeEpoch: 0, requestFingerprint: Data(repeating: 0x12, count: 32), audienceMemberCount: 2)
                if path == "staged" || path == "control-staged" {
                    let drafts = PostgresV2GroupAudienceImportStore(database: database)
                    let policy = V2GroupAudienceImportPolicy(maximumActiveDraftsPerActor: 10, maximumStagedMembersPerActor: 10)
                    _ = try await drafts.begin(actorUserID: senderID, operationID: operation, title: command.title, policy: policy, now: base)
                    _ = try await drafts.append(actorUserID: senderID, operationID: operation, memberUserIDs: command.initialMemberUserIDs, maximumMembers: 10, policy: policy, now: base)
                    _ = try await drafts.freeze(actorUserID: senderID, operationID: operation, policy: policy, now: base)
                }
                if path == "control-staged" {
                    #expect(try await control.prepareStaged(intent, command: staged, now: base) == .prepared(intent))
                    try await store.stageControlValidatedAudience(intent: intent,
                        page: .init(pageNumber: 0, memberUserIDs: command.allMemberUserIDs, isFinal: true), now: base)
                } else if path == "control-inline" {
                    #expect(try await control.prepare(intent, memberUserIDs: command.allMemberUserIDs, now: base) == .prepared(intent))
                }
                func create(at time: Date) async throws -> V2CreateGroupRoomOutcome {
                    switch path {
                    case "inline": return try await store.create(command: command, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, eventID: event, now: time)
                    case "control-inline": return try await store.createControlValidated(command: command, validatedMemberUserIDs: command.allMemberUserIDs, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, eventID: event, now: time)
                    case "staged": return try await store.createStaged(command: staged, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, eventID: event, now: time)
                    default: return try await store.createControlValidatedStaged(command: staged, intent: intent, capacityProfile: profile, now: time)
                    }
                }
                guard case .created(let first) = try await create(at: now) else { throw CancellationError() }
                let room = newRoom.uuidValue!
                let row = try await sql.raw("SELECT created_at AS value FROM im_v2.group_room_operations WHERE room_id = \(bind: room)").first(decoding: RevocationClockDateRow.self)
                let stored = try #require(row).value
                #expect(first.createdAt == stored && first.roomID == newRoom && first.memberCount == 2 && first.capacityClass == mode)
                #expect(try v2GatewayMilliseconds(first.createdAt) == v2GatewayMilliseconds(stored))
                let exact = try await sql.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.rooms r JOIN im_v2.group_rooms g USING (room_id)
                    JOIN im_v2.group_room_operations o USING (room_id) JOIN im_v2.room_events e USING (room_id)
                    JOIN im_v2.user_state_event_outbox b ON b.source_event_id = e.event_id
                    WHERE r.room_id = \(bind: room) AND r.created_at = \(bind: now) AND g.created_at = r.created_at
                        AND o.created_at = r.created_at AND e.created_at = r.created_at AND b.created_at = r.created_at
                        AND (e.payload->>'created_at_ms')::bigint = \(bind: try v2GatewayMilliseconds(stored))
                    """).first(decoding: CountRow.self)
                #expect(exact?.value == 2)
                let before = try await snapshot()
                #expect(try await create(at: base) == .idempotent(first))
                #expect(try await snapshot() == before)
            }
            #expect(try await count("im_v2.group_room_operations", on: sql) == 6)
        }
    }

    @Test("Direct receipt responses and visible projections preserve committed time with monotonic cursors",
          arguments: [false, true], [false, true])
    func directReceiptResponseTimestampPrecision(batch: Bool, hidden: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, userDatabase, sql, userSQL, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)),
                capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
            struct Fence: V2UserShardRouteFencing {
                let database: any Database
                func withCurrentRoute<Result: Sendable>(for userID: UserID,
                    _ operation: @escaping @Sendable (V2UserShardRoute, any Database) async throws -> Result) async throws -> Result {
                    try await database.transaction { transaction in
                        try await operation(.init(bucket: "user", observedRouterEpoch: 1), transaction)
                    }
                }
            }
            let projector = try V2RoutedUserStateEventProjector(routeFence: Fence(database: database),
                registry: V2StaticUserShardStorageRegistry(locations: [.init(bucket: "user", database: userDatabase, schema: "im_v2")]))
            let store = PostgresV2ReadReceiptStore(database: database)
            if hidden {
                guard case .updated = try await store.setPreferences(command: .init(actorUserID: .init(uuid: memberTwoUUID), operationID: .init(uuid: UUID()),
                    allowsDirectReadReceipts: false, allowsGroupReadReceipts: true), now: base) else { throw CancellationError() }
            }
            let sender = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { base })
            func record(_ command: V2RecordReadReceiptCommand, at now: Date) async throws -> V2ReadReceiptOutcome {
                if !batch { return try await store.record(command: command, now: now) }
                let results = try await store.recordBatch([.init(command: command, now: now)])
                guard results.count == 1, case .success(let outcome) = results[0] else { throw CancellationError() }
                return outcome
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["rooms", "room_read_receipts", "read_receipt_operations", "user_sync_sequences", "user_sync_log",
                    "room_events", "room_admission", "shard_admission_pools", "user_state_event_outbox"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                values.append(try await crossStoreClockState(on: userSQL))
                return values
            }
            let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
                1_750_000_000 + 0.99999975, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10]
            for (index, seconds) in dates.enumerated() {
                guard case .accepted(let message) = try await sender.send(.init(roomID: room.roomID,
                    actorUserID: index % 2 == 0 ? .init(uuid: memberTwoUUID) : senderID,
                    clientMessageID: .init(uuid: UUID()), text: "Receipt precision fixture")) else { throw CancellationError() }
                let now = Date(timeIntervalSince1970: seconds)
                for advancing in [true, false] {
                    let operationTime = advancing ? now : now.addingTimeInterval(0.125)
                    let command = try V2RecordReadReceiptCommand(roomID: room.roomID, actorUserID: senderID,
                        operationID: .init(uuid: UUID()), readThroughRoomSequence: advancing ? message.roomSequence : 1)
                    guard case .recorded(let first) = try await record(command, at: operationTime) else { throw CancellationError() }
                    let operation = command.operationID.uuidValue!
                    let row = try await sql.raw("SELECT recorded_at AS value FROM im_v2.read_receipt_operations WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
                    let stored = try #require(row).value
                    let exactOperation = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.read_receipt_operations WHERE operation_id = \(bind: operation) AND recorded_at = \(bind: operationTime)").first(decoding: CountRow.self)
                    #expect(exactOperation?.value == 1)
                    #expect(first.recordedAt == stored && first.readThroughRoomSequence == message.roomSequence)
                    #expect(try v2GatewayMilliseconds(first.recordedAt) == v2GatewayMilliseconds(stored))
                    let state = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.room_read_receipts WHERE room_id = \(bind: room.roomID.uuidValue!) AND user_id = \(bind: senderUUID) AND read_through_room_sequence = \(bind: Int64(message.roomSequence)) AND updated_at = \(bind: now)").first(decoding: CountRow.self)
                    #expect(state?.value == 1)
                    struct Candidate: Decodable {
                        let userID: UUID
                        let kind: String
                        let payload: String
                        let createdAt: V2PostgresTimestamp
                    }
                    let candidates = try await sql.raw("SELECT user_id AS \"userID\", projection_kind AS kind, payload::text AS payload, created_at AS \"createdAt\" FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: operation)").all(decoding: Candidate.self)
                    #expect(candidates.count == (advancing ? 2 : 0))
                    for candidate in candidates {
                        let personal = try V2UserStateEvent(sourceEventID: .init(uuid: operation), userID: .init(uuid: candidate.userID), kind: try #require(V2UserStateEventKind(rawValue: candidate.kind)), payload: Data(candidate.payload.utf8), createdAt: candidate.createdAt)
                        let sequence = try await projector.project(personal)
                        #expect(try await projector.project(personal) == sequence)
                        #expect(try await userSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: operation) AND user_id = \(bind: candidate.userID) AND created_at = \(bind: candidate.createdAt)").first(decoding: CountRow.self)?.value == 1)
                    }
                    #expect(try await userSQL.raw("""
                        SELECT COUNT(*) AS value FROM im_v2.user_sync_log
                        WHERE source_event_id = \(bind: operation) AND projection_kind = 'direct_read_receipt'
                            AND user_id = \(bind: memberTwoUUID)
                            AND (payload->>'is_visible')::boolean = \(bind: !hidden)
                            AND (payload->>'read_through_room_sequence')::bigint = \(bind: hidden ? Int64(0) : Int64(message.roomSequence))
                            AND (payload->>'recorded_at_ms')::bigint = \(bind: try v2GatewayMilliseconds(stored))
                        """).first(decoding: CountRow.self)?.value == (advancing ? 1 : 0))
                    let before = try await snapshot()
                    #expect(try await record(command, at: base) == .idempotent(first))
                    #expect(try await snapshot() == before)
                }
            }
            #expect(try await count("im_v2.read_receipt_operations", on: sql) == 12)
            #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt'", on: sql) == 0)
            #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt'", on: userSQL) == 6)
            #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt' AND (payload->>'is_visible')::boolean", on: userSQL) == (hidden ? 0 : 6))
        }
    }

    @Test("Membership changes preserve committed response and event time through every entry path",
          arguments: [V2GroupCapacityClass.standard, .large], [0, 1, 2])
    func membershipResponseTimestampPrecision(mode: V2GroupCapacityClass, path: Int) async throws {
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let target = UserID(uuid: memberTwoUUID)
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: senderUUID)").run()
            let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry)").run()
            let store = PostgresV2RoomMembershipStore(database: database)
            let identity = try await V2PostgresMembershipIdentitySnapshotValidator(database: database).snapshot(actorUserID: senderID, targetUserID: target)
            let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            func invoke(_ command: V2ChangeRoomMembershipCommand, now: Date) async throws -> V2RoomMembershipChangeOutcome {
                let event = EventID(uuid: UUID())
                if path == 0 { return try await store.change(command: command, capacityProfile: profile, eventID: event, now: now) }
                if path == 1 {
                    return try await store.changeControlValidated(command: command, ownerRoute: route, identitySnapshot: identity,
                        capacityProfile: profile, eventID: event, now: now)
                }
                return try await database.transaction { transaction in
                    try await PostgresV2RoomMembershipStore.change(in: #require(transaction as? any SQLDatabase), command: command,
                        capacityProfile: profile, eventID: event, now: now)
                }
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for name in ["group_rooms", "rooms", "room_memberships", "room_membership_operations",
                    "room_events", "user_state_event_outbox", "room_admission", "shard_admission_pools"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
                1_750_000_000 + 0.99999975, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10]
            for (index, seconds) in dates.enumerated() {
                let now = Date(timeIntervalSince1970: seconds)
                let command = try V2ChangeRoomMembershipCommand(roomID: roomID, actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: target, action: index % 2 == 0 ? .remove : .add, expectedMembershipRevision: UInt64(index))
                guard case .changed(let first) = try await invoke(command, now: now) else { throw CancellationError() }
                #expect(first.membershipRevision == UInt64(index + 1) && first.roomSequence == UInt64(index + 1) && first.action == command.action)
                let event = first.eventID.uuidValue!
                let row = try await sql.raw("SELECT created_at AS value FROM im_v2.room_membership_operations WHERE operation_id = \(bind: command.operationID.uuidValue!)").first(decoding: RevocationClockDateRow.self)
                let stored = try #require(row).value
                #expect(first.createdAt == stored)
                #expect(try v2GatewayMilliseconds(first.createdAt) == v2GatewayMilliseconds(stored))
                let exact = try await sql.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.room_membership_operations o
                    JOIN im_v2.room_events e ON e.event_id = o.event_id
                    JOIN im_v2.user_state_event_outbox p ON p.source_event_id = o.event_id
                    WHERE e.event_id = \(bind: event) AND o.created_at = \(bind: now) AND e.created_at = o.created_at AND p.created_at = o.created_at
                        AND o.resulting_membership_revision = e.committed_membership_revision
                        AND e.room_sequence = o.room_sequence
                        AND (e.payload->>'server_created_at_ms')::bigint = \(bind: try v2GatewayMilliseconds(stored))
                    """).first(decoding: CountRow.self)
                #expect(exact?.value == 1)
                let targets = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: event)").first(decoding: CountRow.self)
                #expect(targets?.value == 1)
                let before = try await snapshot()
                #expect(try await invoke(command, now: base) == .idempotent(first))
                #expect(try await snapshot() == before)
            }
            #expect(try await count("im_v2.room_membership_operations", on: sql) == 6)
            #expect(try await count("im_v2.room_memberships WHERE left_revision IS NULL", on: sql) == 3)
        }
    }

    @Test("Moderation responses, mute deadlines and audit records retain database timestamp precision",
          arguments: [V2GroupCapacityClass.standard, .large],
          ["redact", "redact-owner", "mute", "mute-owner", "remove", "remove-owner", "control", "control-owner"])
    func moderationResponseTimestampPrecision(mode: V2GroupCapacityClass, path: String) async throws {
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try V2CapacityProfile(id: "standard", limits: .init(maxEligibleMembers: 10, maxCommandsPerWindow: 20,

                retryAfterSeconds: 3))
            let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry), command_window_limit = 20").run()
            try await sql.raw("UPDATE im_v2.room_admission SET command_window_limit = 20").run()
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: senderUUID)").run()
            let store = PostgresV2ModerationStore(database: database)
            let memberships = PostgresV2RoomMembershipStore(database: database)
            let sender = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { base })
            let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            let kind = String(path.split(separator: "-")[0])
            let owner = path.hasSuffix("-owner")
            func invoke(_ command: V2ModerationCommand, now: Date) async throws -> V2ModerationOutcome {
                let event = EventID(uuid: UUID())
                if kind == "control" {
                    if owner { return try await store.applyTrustedSafetyOwnerValidated(command: command, ownerRoute: route, capacityProfile: profile, eventID: event, now: now) }
                    return try await store.applyTrustedSafety(command: command, capacityProfile: profile, eventID: event, now: now)
                }
                if owner { return try await store.applyOwnerValidated(command: command, ownerRoute: route, capacityProfile: profile, eventID: event, now: now) }
                return try await store.apply(command: command, capacityProfile: profile, eventID: event, now: now)
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for name in ["rooms", "room_memberships", "room_member_mutes", "messages", "message_media_references", "message_projection_states",
                    "moderation_operations", "moderation_audit_entries", "room_events", "user_state_event_outbox", "room_admission", "shard_admission_pools"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            // Leave room for the mandatory 180-day audit retention at the upper bound.
            let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
                1_750_000_000 + 0.99999975, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 180 * 86_400 - 10]
            for (index, seconds) in dates.enumerated() {
                let now = Date(timeIntervalSince1970: seconds)
                var messageID: MessageID?
                if kind == "redact" {
                    guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID,
                        clientMessageID: .init(uuid: UUID()), text: "Moderation precision fixture")) else { throw CancellationError() }
                    messageID = message.messageID
                }
                if kind == "remove", index > 0 {
                    guard case .changed = try await memberships.change(command: .init(roomID: roomID, actorUserID: senderID,
                        operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID), action: .add, expectedMembershipRevision: UInt64(index * 2 - 1)),
                        capacityProfile: profile, eventID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
                }
                let action: V2ModerationAction = kind == "redact" ? .redactMessage : kind == "mute" ? .muteMember
                    : kind == "remove" ? .removeMember : index % 2 == 0 ? .freezeRoom : .unfreezeRoom
                let mute = kind == "mute" ? Date(timeIntervalSince1970: max(seconds, base.timeIntervalSince1970) + Double((index + 1) * 10) + 0.99999975) : nil
                let command = try V2ModerationCommand(roomID: roomID, actorUserID: senderID, operationID: .init(uuid: UUID()), action: action,
                    targetUserID: ["mute", "remove"].contains(kind) ? .init(uuid: memberTwoUUID) : nil,
                    messageID: messageID, muteUntil: mute, reasonCode: .init("abuse_spam"))
                guard case .applied(let first) = try await invoke(command, now: now) else { throw CancellationError() }
                #expect(first.action == action && first.operationID == command.operationID && first.targetUserID == command.targetUserID && first.messageID == messageID)
                let event = first.eventID.uuidValue!, operation = command.operationID.uuidValue!
                let row = try await sql.raw("SELECT created_at AS value FROM im_v2.moderation_operations WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
                let stored = try #require(row).value
                #expect(first.createdAt == stored)
                #expect(try v2GatewayMilliseconds(first.createdAt) == v2GatewayMilliseconds(stored))
                let retainUntil = now.addingTimeInterval(180 * 86_400)
                let exact = try await sql.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.moderation_operations o
                    JOIN im_v2.room_events e ON e.event_id = o.event_id
                    LEFT JOIN im_v2.user_state_event_outbox u ON u.source_event_id = o.event_id
                    JOIN im_v2.moderation_audit_entries a ON a.actor_user_id = o.actor_user_id AND a.operation_id = o.operation_id
                    WHERE o.operation_id = \(bind: operation) AND o.created_at = \(bind: now) AND e.created_at = o.created_at
                        AND (o.action <> 'remove_member' OR u.created_at = o.created_at) AND a.occurred_at = o.created_at AND a.retain_until = \(bind: retainUntil)
                        AND e.room_sequence = o.room_sequence
                        AND (e.payload->>'server_created_at_ms')::bigint = \(bind: try v2GatewayMilliseconds(stored))
                    """).first(decoding: CountRow.self)
                #expect(exact?.value == 1)
                if let mute {
                    let muted = try await sql.raw("SELECT mute_until AS value FROM im_v2.moderation_operations WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
                    let storedMute = try #require(muted).value
                    #expect(first.muteUntil == storedMute)
                    let deadline = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.room_member_mutes m JOIN im_v2.room_events e ON e.event_id = \(bind: event) WHERE m.operation_id = \(bind: operation) AND m.mute_until = \(bind: mute) AND (e.payload->>'mute_until_ms')::bigint = \(bind: try v2GatewayMilliseconds(storedMute))").first(decoding: CountRow.self)
                    #expect(deadline?.value == 1)
                }
                let before = try await snapshot()
                #expect(try await invoke(command, now: base) == .idempotent(first))
                #expect(try await snapshot() == before)
            }
            #expect(try await count("im_v2.moderation_operations", on: sql) == 6)
            #expect(try await count("im_v2.moderation_audit_entries", on: sql) == 6)
        }
    }

    @Test("Atomic room-log appends retain independent timeline and event sequences after an edit",
          arguments: ["direct-cold", "direct-hot", "hybrid"])
    func roomLogAppendAfterMutation(path: String) async throws {
        let hybrid = path == "hybrid"
        try await withForwardOwnerDatabases(mode: hybrid ? .large : .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            var rooms: [RoomID] = []
            if hybrid { rooms = [roomID, roomID] }
            else {
                for target in [memberTwoUUID, memberThreeUUID] {
                    guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                        command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: target)),
                        capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
                    rooms.append(room.roomID)
                }
            }
            let fastCache = V2DirectRoomLogFastAppendCache()
            func writer(cache: V2DirectRoomLogFastAppendCache) throws -> PostgresV2RoomWriteStore {
                PostgresV2RoomWriteStore(database: database,
                    strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                    directRoomLogFastAppendCache: cache,
                    shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            }
            let warm = try writer(cache: fastCache)
            func request(_ index: Int) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: rooms[index], senderUserID: hybrid && index == 1 ? .init(uuid: memberTwoUUID) : senderID,
                    clientMessageID: .init(uuid: UUID()), text: "Room log after mutation", limits: .init(maxUTF8Bytes: 64)),
                    capacityProfile: profile, identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: base)
            }
            var accepted: [V2AcceptedMessage] = []
            for index in 0..<2 {
                let input = try request(index)
                guard case .accepted(let message) = try await warm.accept(command: input.command, capacityProfile: profile, identifiers: input.identifiers, now: base) else { throw CancellationError() }
                accepted.append(message)
            }
            for message in hybrid ? [accepted[0]] : accepted {
                guard case .edited = try await PostgresV2MessageEditStore(database: database).edit(
                    command: .init(roomID: message.roomID, actorUserID: message.senderUserID, operationID: .init(uuid: UUID()),
                        messageID: message.messageID, expectedMessageRevision: 1, text: "Edited before next append", maximumUTF8Bytes: 64),
                    capacityProfile: profile, eventID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
            }
            let eventCount = try await count("im_v2.room_events", on: sql)
            let beforeFast = await fastCache.snapshot()
            let active = path == "direct-cold" ? try writer(cache: .init()) : warm
            let requests = try [request(0), request(1)]
            let outcomes = try await active.acceptAtomically(requests: requests)
            #expect(outcomes.count == 2)
            if path == "direct-hot" {
                let afterFast = await fastCache.snapshot()
                #expect(afterFast.committedAppends - beforeFast.committedAppends == 2)
                #expect(afterFast.fallbackAppends == beforeFast.fallbackAppends)
            }
            for (index, outcome) in outcomes.enumerated() {
                guard case .accepted(let message) = outcome else { throw CancellationError() }
                #expect(message.roomSequence == UInt64(hybrid ? index + 4 : 3))
                #expect(message.timelineSequence == UInt64(hybrid ? index + 3 : 2))
                let stored = try await sql.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.messages m
                    JOIN im_v2.message_send_completions c ON c.message_id = m.message_id
                    JOIN im_v2.room_events e ON e.event_id = c.event_id
                    WHERE m.message_id = \(bind: message.messageID.uuidValue!)
                        AND m.accepted_event_storage = 'room_event' AND m.accepted_event_id IS NULL
                        AND m.accepted_membership_revision IS NULL
                        AND e.room_sequence = m.room_sequence AND e.committed_membership_revision = c.accepted_membership_revision
                        AND (e.payload->>'room_sequence')::bigint = m.room_sequence
                        AND (e.payload->>'timeline_sequence')::bigint = m.timeline_sequence
                        AND e.payload->>'text' = m.text_body AND e.payload->>'message_id' = \(bind: message.messageID.rawValue)
                    """).first(decoding: CountRow.self)
                #expect(stored?.value == 1)
                let original = requests[index]
                guard case .idempotent(let replay) = try await active.accept(command: original.command, capacityProfile: profile, identifiers: original.identifiers, now: base) else { throw CancellationError() }
                #expect(replay == message.receipt)
                let page = try await PostgresV2GroupEventLogStore(database: database).pull(roomID: message.roomID,
                    actorUserID: original.command.senderUserID, afterRoomSequence: message.roomSequence - 1, pageSize: 20)
                #expect(page.events.first?.sourceEventID == message.sourceEventID)
            }
            #expect(try await count("im_v2.room_events", on: sql) == eventCount + 2)
            #expect(try await count("im_v2.messages", on: sql) == 4)
            #expect(try await count("im_v2.message_send_completions", on: sql) == 4)
        }
    }

    @Test("Message mutations preserve response and event timestamp precision across accepted delivery authorities",
          arguments: ["groupPersonal", "groupRoomLog", "directPersonal", "directPreplanned", "directRoomLog"],
          ["edit", "edit-owner", "withdraw", "withdraw-owner", "reaction", "reaction-owner"])
    func messageMutationTimestampPrecision(deliveryKind: String, path: String) async throws {
        let mode: V2GroupCapacityClass = deliveryKind == "groupRoomLog" ? .large : .standard
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try V2CapacityProfile(id: "standard", limits: .init(maxEligibleMembers: 10, maxCommandsPerWindow: 20,

                retryAfterSeconds: 3))
            let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry), command_window_limit = 20").run()
            try await sql.raw("UPDATE im_v2.room_admission SET command_window_limit = 20").run()
            let destination: RoomID
            if deliveryKind.hasPrefix("direct") {
                guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)),
                    capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
                destination = room.roomID
            } else { destination = roomID }
            let destinationUUID = try #require(destination.uuidValue)
            let roomLog = deliveryKind.contains("RoomLog")
            let writer = PostgresV2RoomWriteStore(database: database,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled)
            let send = try V2SendMessageService(store: writer, capacityProfile: profile, limits: .init(maxUTF8Bytes: 64), now: { base })
            let edits = PostgresV2MessageEditStore(database: database)
            let withdrawals = PostgresV2MessageWithdrawalStore(database: database)
            let reactions = PostgresV2MessageReactionStore(database: database)
            let owner = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            let ownerValidated = path.hasSuffix("-owner")
            let kind = String(path.split(separator: "-")[0])
            let table = kind == "edit" ? "message_edit_operations" : kind == "withdraw" ? "message_withdrawal_operations" : "message_reaction_operations"
            func invoke(_ id: UUID, message: MessageID, remove: Bool, now: Date, replay: Bool) async throws -> (Date, UInt64, EventID) {
                let event = EventID(uuid: UUID())
                switch kind {
                case "edit":
                    let command = try V2EditMessageCommand(roomID: destination, actorUserID: senderID, operationID: .init(uuid: id),
                        messageID: message, expectedMessageRevision: 1, text: "Edited clock fixture", maximumUTF8Bytes: 64)
                    let outcome = try await ownerValidated
                        ? edits.editOwnerValidated(command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : edits.edit(command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2MessageEdit
                    switch outcome {
                    case .edited(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == destination && value.messageID == message && value.text == command.text && value.messageRevision == 2)
                    return (value.createdAt, value.roomSequence, value.eventID)
                case "withdraw":
                    let command = try V2WithdrawMessageCommand(roomID: destination, actorUserID: senderID, operationID: .init(uuid: id),
                        messageID: message, expectedMessageRevision: 1)
                    let outcome = try await ownerValidated
                        ? withdrawals.withdrawOwnerValidated(command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : withdrawals.withdraw(command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2MessageWithdrawal
                    switch outcome {
                    case .withdrawn(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == destination && value.messageID == message && value.messageRevision == 2)
                    return (value.createdAt, value.roomSequence, value.eventID)
                default:
                    let command = try V2ChangeMessageReactionCommand(roomID: destination, actorUserID: senderID, operationID: .init(uuid: id),
                        messageID: message, reaction: "👍", action: remove ? .remove : .add)
                    let outcome = try await ownerValidated
                        ? reactions.changeOwnerValidated(command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : reactions.change(command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2MessageReactionChange
                    switch outcome {
                    case .changed(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == destination && value.messageID == message && value.actorUserID == senderID && value.reaction == command.reaction && value.action == command.action)
                    return (value.createdAt, value.roomSequence, value.eventID)
                }
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for name in ["rooms", "messages", "room_memberships", "room_admission", "shard_admission_pools", "room_events",
                    "message_projection_states", "content_review_jobs", "message_reactions", table] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
                1_750_000_000 + 0.99999975, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10]
            for seconds in dates {
                guard case .accepted(let message) = try await send.send(.init(roomID: destination, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "Original clock fixture")) else { throw CancellationError() }
                let now = Date(timeIntervalSince1970: seconds)
                for remove in kind == "reaction" ? [false, true] : [false] {
                    let operation = UUID()
                    let first = try await invoke(operation, message: message.messageID, remove: remove, now: now, replay: false)
                    #expect(first.1 == message.roomSequence + (remove ? 2 : 1))
                    let row = try await sql.raw("SELECT created_at AS value FROM im_v2.\(unsafeRaw: table) WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
                    let stored = try #require(row).value
                    #expect(first.0 == stored)
                    #expect(try v2GatewayMilliseconds(first.0) == v2GatewayMilliseconds(stored))
                    let exact = try await sql.raw("""
                        SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table) o
                        JOIN im_v2.room_events e ON e.event_id = o.event_id
                        WHERE o.operation_id = \(bind: operation) AND o.created_at = \(bind: now)
                            AND e.created_at = o.created_at
                            AND e.event_id = \(bind: first.2.uuidValue!)
                            AND e.room_sequence = o.room_sequence AND e.room_sequence = \(bind: Int64(first.1))
                        """).first(decoding: CountRow.self)
                    #expect(exact?.value == 1)
                    let payload = try await sql.raw("SELECT (payload->>'server_created_at_ms')::bigint AS value FROM im_v2.room_events WHERE event_id = \(bind: first.2.uuidValue!)").first(decoding: CountRow.self)
                    #expect(try payload?.value == v2GatewayMilliseconds(stored))
                    if kind != "reaction" {
                        let state = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.message_projection_states WHERE state_event_id = \(bind: first.2.uuidValue!) AND created_at = \(bind: now)").first(decoding: CountRow.self)
                        #expect(state?.value == 1)
                    }
                    let before = try await snapshot()
                    let replay = try await invoke(operation, message: message.messageID, remove: remove, now: base, replay: true)
                    #expect(replay.0 == first.0 && replay.1 == first.1 && replay.2 == first.2)
                    #expect(try await snapshot() == before)
                }
                let original = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.messages WHERE message_id = \(bind: message.messageID.uuidValue!) AND created_at = \(bind: base)").first(decoding: CountRow.self)
                #expect(original?.value == 1)
            }
            #expect(try await count("im_v2." + table, on: sql) == (kind == "reaction" ? 12 : 6))
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.messages WHERE room_id = \(bind: destinationUUID)").first(decoding: CountRow.self)?.value == 6)
            if kind == "reaction" { #expect(try await count("im_v2.message_reactions", on: sql) == 0) }
        }
    }

    @Test("Group controls preserve response and event timestamp precision for both delivery modes and owner paths",
          arguments: [V2GroupCapacityClass.standard, .large],
          ["pin", "pin-owner", "announcement", "announcement-owner", "permissions", "permissions-owner", "role", "role-owner"])
    func groupCapabilityTimestampPrecision(mode: V2GroupCapacityClass, path: String) async throws {
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let groups = PostgresV2GroupCapabilitiesStore(database: database)
            let owner = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            let ownerValidated = path.hasSuffix("-owner")
            let kind = String(path.split(separator: "-")[0])
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: senderUUID)").run()
            try await sql.raw("UPDATE im_v2.rooms SET membership_revision = 1 WHERE room_id = \(bind: roomUUID)").run()
            let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry)").run()
            let send = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { base })
            guard case .accepted(let message) = try await send.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "Group timestamp fixture")) else { throw CancellationError() }
            let table = kind == "pin" ? "room_pinned_message_operations" : kind == "announcement" ? "group_announcement_operations"
                : kind == "permissions" ? "group_permission_operations" : "group_role_operations"
            func invoke(_ id: UUID, index: Int, now: Date, replay: Bool) async throws -> (Date?, UInt64) {
                let event = EventID(uuid: UUID())
                switch kind {
                case "pin":
                    let command = V2PinnedMessageCommand(operationID: .init(uuid: id), roomID: roomID, messageID: message.messageID, isPinned: index % 2 == 0)
                    let outcome = try await ownerValidated
                        ? groups.setPinnedMessageOwnerValidated(actorUserID: senderID, command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : groups.setPinnedMessage(actorUserID: senderID, command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2PinnedMessage
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.messageID == message.messageID && value.isPinned == command.isPinned)
                    return (value.updatedAt, value.roomSequence)
                case "announcement":
                    let command = try V2GroupAnnouncementCommand(operationID: .init(uuid: id), roomID: roomID, body: "Announcement \(index)", expectedRevision: UInt64(index))
                    let outcome = try await ownerValidated
                        ? groups.setAnnouncementOwnerValidated(actorUserID: senderID, command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : groups.setAnnouncement(actorUserID: senderID, command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2GroupAnnouncement
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.body == command.body && value.revision == UInt64(index + 1))
                    return (value.updatedAt, value.roomSequence)
                case "permissions":
                    let command = try V2GroupRolePermissionsCommand(operationID: .init(uuid: id), roomID: roomID, role: .member,
                        permissions: index % 2 == 0 ? [.sendMessages] : [], expectedRevision: UInt64(index + 1))
                    let outcome = try await ownerValidated
                        ? groups.setRolePermissionsOwnerValidated(actorUserID: senderID, command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : groups.setRolePermissions(actorUserID: senderID, command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2GroupRolePermissionsChange
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.role == .member && value.permissions == command.permissions && value.revision == UInt64(index + 2))
                    return (nil, value.roomSequence)
                default:
                    let command = try V2GroupMemberRoleCommand(operationID: .init(uuid: id), roomID: roomID,
                        targetUserID: .init(uuid: memberTwoUUID), role: index % 2 == 0 ? .admin : .member, expectedMembershipRevision: UInt64(index + 1))
                    let outcome = try await ownerValidated
                        ? groups.changeMemberRoleOwnerValidated(actorUserID: senderID, command: command, ownerRoute: owner, capacityProfile: profile, eventID: event, now: now)
                        : groups.changeMemberRole(actorUserID: senderID, command: command, capacityProfile: profile, eventID: event, now: now)
                    let value: V2GroupMemberRoleChange
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.targetUserID == command.targetUserID && value.role == command.role && value.membershipRevision == UInt64(index + 2))
                    return (nil, value.roomSequence)
                }
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for name in ["rooms", "room_memberships", "room_admission", "shard_admission_pools", "room_events",
                    "room_pinned_messages", "group_announcements", "group_role_policies", "group_role_permissions", table] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
                1_750_000_000 + 0.99999975, 946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10]
            for (index, seconds) in dates.enumerated() {
                let now = Date(timeIntervalSince1970: seconds), operation = UUID()
                let first = try await invoke(operation, index: index, now: now, replay: false)
                #expect(first.1 == UInt64(index + 2))
                let row = try await sql.raw("SELECT created_at AS value FROM im_v2.\(unsafeRaw: table) WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
                let stored = try #require(row).value
                if ["pin", "announcement"].contains(kind) {
                    #expect(first.0 == stored)
                    #expect(try first.0.map(v2GatewayMilliseconds) == v2GatewayMilliseconds(stored))
                }
                let exact = try await sql.raw("""
                    SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table) o
                    JOIN im_v2.room_events e ON e.event_id = o.event_id
                    WHERE o.operation_id = \(bind: operation) AND o.created_at = \(bind: now) AND e.created_at = o.created_at
                        AND e.room_sequence = o.room_sequence AND e.room_sequence = \(bind: Int64(first.1))
                        AND (e.payload->>'room_sequence')::bigint = e.room_sequence
                    """).first(decoding: CountRow.self)
                #expect(exact?.value == 1)
                let payload = try await sql.raw("SELECT (e.payload->>'server_created_at_ms')::bigint AS value FROM im_v2.room_events e JOIN im_v2.\(unsafeRaw: table) o ON o.event_id = e.event_id WHERE o.operation_id = \(bind: operation)").first(decoding: CountRow.self)
                #expect(try payload?.value == v2GatewayMilliseconds(stored))
                let before = try await snapshot()
                let replay = try await invoke(operation, index: index, now: base, replay: true)
                #expect(replay.0 == first.0 && replay.1 == first.1)
                #expect(try await snapshot() == before)
            }
            #expect(try await count("im_v2." + table, on: sql) == 6)
            #expect(try await count("im_v2.room_events", on: sql) == 7)
            let page = try await PostgresV2GroupEventLogStore(database: database).pull(roomID: roomID, actorUserID: senderID, afterRoomSequence: 1, pageSize: 20)
            #expect(page.events.count == 6 && page.nextRoomSequence == 7 && !page.hasMore)
        }
    }

    @Test("Direct and social responses preserve database timestamp precision across transitions and retries",
          arguments: ["direct", "stranger", "userAdd", "request", "accept", "reject", "remove", "block", "unblock", "block-remove"],
          [Double](arrayLiteral: 946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 946_684_800 + 0.00000125,
              1_750_000_000 + 0.99999975,
              946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10))
    func directSocialResponseTimestampPrecision(kind: String, seconds: Double) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, deliveryDB, sql, deliverySQL, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let now = Date(timeIntervalSince1970: seconds)
            let direct = PostgresV2DirectMessagingStore(database: database)
            let social = PostgresV2SocialRelationshipStore(database: database)
            let profile = try forwardImportTestProfile()
            let target = UserID(uuid: memberTwoUUID)
            let newRoom = RoomID(uuid: UUID())
            let table: String
            switch kind {
            case "direct": table = "direct_room_operations"
            case "stranger": table = "stranger_message_preference_operations"
            case "userAdd": table = "user_add_preference_operations"
            case "block", "unblock", "block-remove": table = "user_block_operations"
            default: table = "user_relationship_operations"
            }
            let column = kind == "direct" ? "created_at" : "updated_at"
            let relationshipAction: V2RelationshipAction = kind == "accept" ? .accept : kind == "reject" ? .reject : kind == "remove" ? .remove : .request
            let blockAction: V2UserBlockAction = kind == "unblock" ? .unblock : .block
            if ["accept", "reject", "remove", "block-remove"].contains(kind) {
                guard case .changed = try await social.changeRelationship(.init(actorUserID: target,
                    operationID: .init(uuid: UUID()), targetUserID: senderID, action: .request), now: base) else { throw CancellationError() }
                if ["remove", "block-remove"].contains(kind) {
                    guard case .changed = try await social.changeRelationship(.init(actorUserID: senderID,
                        operationID: .init(uuid: UUID()), targetUserID: target, action: .accept), now: base) else { throw CancellationError() }
                }
            }
            if kind == "unblock" {
                guard case .changed = try await social.changeUserBlock(.init(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: target, action: .block), now: base) else { throw CancellationError() }
            }
            if kind == "direct" {
                let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
                try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry)").run()
            }
            func invoke(_ operation: UUID, replay: Bool, at clock: Date) async throws -> Date {
                switch kind {
                case "direct":
                    let outcome = try await direct.open(command: .init(actorUserID: senderID, operationID: .init(uuid: operation), targetUserID: target),
                        capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, now: clock)
                    let value: V2DirectRoom
                    switch outcome {
                    case .opened(let room): #expect(!replay); value = room
                    case .idempotent(let room): #expect(replay); value = room
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == newRoom && value.actorUserID == senderID && value.targetUserID == target)
                    return value.createdAt
                case "stranger":
                    switch try await direct.setStrangerMessagePermission(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: operation), permission: .deny), now: clock) {
                    case .updated(let permission, let date): #expect(!replay && permission == .deny); return date
                    case .idempotent(let permission, let date): #expect(replay && permission == .deny); return date
                    default: throw CancellationError()
                    }
                case "userAdd":
                    switch try await direct.setUserAddPermission(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: operation), permission: .deny), now: clock) {
                    case .updated(let permission, let date): #expect(!replay && permission == .deny); return date
                    case .idempotent(let permission, let date): #expect(replay && permission == .deny); return date
                    default: throw CancellationError()
                    }
                case "block", "unblock", "block-remove":
                    let outcome = try await social.changeUserBlock(.init(actorUserID: senderID,
                        operationID: .init(uuid: operation), targetUserID: target, action: blockAction), now: clock)
                    let value: V2UserBlockChange
                    switch outcome {
                    case .changed(let change): #expect(!replay); value = change
                    case .idempotent(let change): #expect(replay); value = change
                    default: throw CancellationError()
                    }
                    #expect(value.actorUserID == senderID && value.targetUserID == target && value.action == blockAction && value.isBlocked == (blockAction == .block))
                    return value.updatedAt
                default:
                    let outcome = try await social.changeRelationship(.init(actorUserID: senderID,
                        operationID: .init(uuid: operation), targetUserID: target, action: relationshipAction), now: clock)
                    let value: V2RelationshipChange
                    switch outcome {
                    case .changed(let change): #expect(!replay); value = change
                    case .idempotent(let change): #expect(replay); value = change
                    default: throw CancellationError()
                    }
                    let state: V2RelationshipState = kind == "request" ? .pending : kind == "accept" ? .accepted : .none
                    #expect(value.actorUserID == senderID && value.targetUserID == target && value.action == relationshipAction && value.resultingState == state)
                    return value.updatedAt
                }
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for name in ["rooms", "room_memberships", "room_admission", "shard_admission_pools", "direct_room_pairs",
                    "direct_room_operations", "user_stranger_message_preferences", "stranger_message_preference_operations",
                    "user_add_preferences", "user_add_preference_operations", "user_relationships", "user_relationship_operations",
                    "user_blocks", "user_block_operations", "user_direct_send_policy_versions", "user_sync_sequences", "user_sync_log", "user_state_event_outbox"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            let operation = UUID()
            let first = try await invoke(operation, replay: false, at: now)
            let row = try await sql.raw("SELECT \(unsafeRaw: column) AS value FROM im_v2.\(unsafeRaw: table) WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
            let stored = try #require(row).value
            #expect(first == stored)
            #expect(try v2GatewayMilliseconds(first) == v2GatewayMilliseconds(stored))
            let exact = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table) WHERE operation_id = \(bind: operation) AND \(unsafeRaw: column) = \(bind: now)").first(decoding: CountRow.self)
            #expect(exact?.value == 1)
            let projectionCount: Int64 = kind == "block-remove" ? 3 : ["request", "accept", "reject", "remove"].contains(kind) ? 2 : 1
            if kind == "direct" {
                #expect(try await count("im_v2.user_sync_log", on: sql) == 0)
                let outbox = try PostgresV2UserStateEventOutbox(database: database)
                let projector = try PostgresV2UserStateEventProjector(database: deliveryDB)
                let deliveryTime = max(base, now)
                let leases = try await outbox.claim(now: deliveryTime, leaseDuration: 1, limit: 100)
                #expect(leases.count == 1)
                for lease in leases {
                    let sequence = try await projector.project(lease.event)
                    #expect(try await projector.project(lease.event) == sequence)
                    #expect(try await outbox.acknowledge(lease, sequence: sequence, now: deliveryTime))
                }
            }
            let projectionSQL: any SQLDatabase = kind == "direct" ? deliverySQL : sql
            let projections = try await projectionSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: operation) AND created_at = \(bind: now)").first(decoding: CountRow.self)
            #expect(projections?.value == projectionCount)
            if kind != "direct" {
                let payloads = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: operation) AND (payload->>'updated_at_ms')::bigint = \(bind: try v2GatewayMilliseconds(stored))").first(decoding: CountRow.self)
                #expect(payloads?.value == projectionCount)
            }
            let beforeReplay = try await snapshot()
            #expect(try await invoke(operation, replay: true, at: base) == first)
            #expect(try await snapshot() == beforeReplay)
            if kind == "direct" {
                // A new operation opening the existing pair must copy its native timestamp exactly.
                let reopen = UUID()
                #expect(try await invoke(reopen, replay: false, at: base) == stored)
                let copied = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.direct_room_operations o JOIN im_v2.direct_room_pairs p USING (room_id) WHERE o.operation_id = \(bind: reopen) AND o.created_at = p.created_at").first(decoding: CountRow.self)
                #expect(copied?.value == 1)
                let beforeReopenReplay = try await snapshot()
                #expect(try await invoke(reopen, replay: true, at: base) == stored)
                #expect(try await snapshot() == beforeReopenReplay)
                #expect(try await count("im_v2.direct_room_pairs", on: sql) == 1)
                #expect(try await count("im_v2.direct_room_operations", on: sql) == 2)
            }
        }
    }

    @Test("Preference responses and projections use the persisted timestamp on first write and replay",
          arguments: ["conversation", "favorite", "receipts", "live"])
    func preferenceResponseTimestampPrecision(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let shadow = PreferenceReplayClockShadow()
            let conversations = PostgresV2ConversationCapabilitiesStore(database: database, shadowForwarder: shadow)
            let receipts = PostgresV2ReadReceiptStore(database: database, shadowForwarder: shadow)
            let live = try PostgresV2LiveActivityStore(database: database)
            var messageID = MessageID(uuid: UUID())
            if kind == "favorite" {
                let send = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: try forwardImportTestProfile(),
                    limits: try .init(maxUTF8Bytes: 64), now: { base })
                guard case .accepted(let message) = try await send.send(.init(roomID: roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "Preference precision fixture")) else { throw CancellationError() }
                messageID = message.messageID
            }
            let table = kind == "conversation" ? "user_room_preference_operations" : kind == "favorite" ? "user_message_favorite_operations"
                : kind == "receipts" ? "read_receipt_preference_operations" : "user_live_activity_preference_operations"
            func invoke(_ id: UUID, at now: Date, muteUntil: Date, replay: Bool) async throws -> (Date, Date?) {
                switch kind {
                case "conversation":
                    let outcome = try await conversations.setConversationState(actorUserID: senderID,
                        command: .init(operationID: .init(uuid: id), roomID: roomID, isPinned: true, isArchived: true, muteUntil: muteUntil), now: now)
                    let value: V2ConversationState
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.isPinned && value.isArchived)
                    return (value.updatedAt, value.muteUntil)
                case "favorite":
                    let outcome = try await conversations.setMessageFavorite(actorUserID: senderID,
                        command: .init(operationID: .init(uuid: id), roomID: roomID, messageID: messageID, isFavorited: true), now: now)
                    let value: V2MessageFavorite
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.messageID == messageID && value.isFavorited)
                    return (value.updatedAt, nil)
                case "receipts":
                    let outcome = try await receipts.setPreferences(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: id), allowsDirectReadReceipts: false, allowsGroupReadReceipts: true), now: now)
                    let value: V2ReadReceiptPreferences
                    switch outcome {
                    case .updated(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(!value.allowsDirectReadReceipts && value.allowsGroupReadReceipts)
                    return (value.updatedAt, nil)
                default:
                    let outcome = try await live.setPreferences(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: id), allowsOnlinePresence: false, allowsTypingIndicators: true), now: now)
                    let value: V2LiveActivityPreferences
                    switch outcome {
                    case .updated(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(!value.allowsOnlinePresence && value.allowsTypingIndicators)
                    return (value.updatedAt, nil)
                }
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for name in [table, "user_room_preferences", "user_message_favorites", "user_read_receipt_preferences",
                    "user_live_activity_preferences", "read_receipt_preference_propagation_outbox", "user_sync_sequences", "user_sync_log"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            for seconds in [Double](arrayLiteral: 946_684_800 - 0.00000075, 946_684_800 + 0.00000075, 1_750_000_000 + 0.99999975,
                946_684_800 - 211_813_488_000, 946_684_800 + 9_223_371_331_200 - 10) {
                let now = Date(timeIntervalSince1970: seconds)
                // Mute deadlines are positive client values; the server clock may be historical.
                let muteUntil = seconds > 0 ? now : base
                let operation = UUID()
                let first = try await invoke(operation, at: now, muteUntil: muteUntil, replay: false)
                let storedRow = try await sql.raw("SELECT updated_at AS value FROM im_v2.\(unsafeRaw: table) WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)
                let stored = try #require(storedRow).value
                #expect(first.0 == stored)
                #expect(try v2GatewayMilliseconds(first.0) == v2GatewayMilliseconds(stored))
                let exact = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table) WHERE operation_id = \(bind: operation) AND updated_at = \(bind: now)").first(decoding: CountRow.self)
                #expect(exact?.value == 1)
                let storedMute = seconds > 0 ? stored : base
                if kind == "conversation" { #expect(first.1 == storedMute) }
                if kind == "live" {
                    let queried = try await live.preferences(userID: senderID, now: base)
                    #expect(queried.updatedAt == first.0)
                } else {
                    let projection = try await sql.raw("SELECT (payload->>'updated_at_ms')::bigint AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: operation)").first(decoding: CountRow.self)
                    #expect(try projection?.value == v2GatewayMilliseconds(stored))
                    let timestamp = try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: operation) AND created_at = \(bind: now)").first(decoding: CountRow.self)
                    #expect(timestamp?.value == 1)
                    if kind == "conversation" {
                        let mute = try await sql.raw("SELECT (payload->>'mute_until_ms')::bigint AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: operation)").first(decoding: CountRow.self)
                        #expect(try mute?.value == v2GatewayMilliseconds(storedMute))
                    }
                }
                let beforeReplay = try await snapshot()
                let replay = try await invoke(operation, at: base, muteUntil: muteUntil, replay: true)
                #expect(replay.0 == first.0 && replay.1 == first.1)
                #expect(try await snapshot() == beforeReplay)
            }
        }
    }

    @Test("Business denials preserve receipt and private-event time through retries",
          arguments: ["scalar", "batch"], ["generic", "system"])
    func denialResponseTimestampPrecision(path: String, reason: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, deliveryDB, sql, deliverySQL, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let direct = PostgresV2DirectMessagingStore(database: database)
            var rooms: [RoomID] = []
            for target in [memberTwoUUID, memberThreeUUID] {
                guard case .opened(let room) = try await direct.open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: target)),
                    capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                else { throw CancellationError() }
                rooms.append(room.roomID)
            }
            if reason == "system" {
                try await sql.raw("INSERT INTO im_v2.special_accounts (account_user_id, stable_key, account_kind, allows_customer_messages, allows_service_messages, created_at, updated_at) VALUES (\(bind: memberTwoUUID), 'clock_system_target', 'system', false, true, \(bind: base), \(bind: base))").run()
                try await sql.raw("UPDATE im_v2.public_user_profiles SET account_kind = 'system', revision = revision + 1 WHERE user_id = \(bind: memberTwoUUID)").run()
            } else {
                _ = try await direct.setStrangerMessagePermission(command: .init(actorUserID: .init(uuid: memberTwoUUID),
                    operationID: .init(uuid: UUID()), permission: .deny), now: base)
            }
            let writer = PostgresV2RoomWriteStore(database: database,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            let batcher = V2SendMessageAdmissionBatcher(store: writer,
                configuration: .init(maximumBatchSize: 2, maximumDelay: .milliseconds(2)))
            func scalar(_ request: V2RoomWriteRequest) async throws -> V2SendMessageOutcome {
                try await writer.accept(command: request.command, capacityProfile: request.capacityProfile,
                    identifiers: request.identifiers, now: request.now)
            }
            func request(room: RoomID, now: Date) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: room, senderUserID: senderID, clientMessageID: .init(uuid: UUID()),
                    text: "business response time", limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["direct_message_denials", "room_timeline_activities", "user_state_event_outbox", "user_sync_log", "user_sync_sequences", "rooms", "direct_room_pairs"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let dates = [Date(timeIntervalSince1970: 946_684_799.99999925),
                         Date(timeIntervalSince1970: 946_684_800.00000075), base.addingTimeInterval(0.99999975),
                         Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)]
            let deniedRoom = try #require(rooms[0].uuidValue)
            for date in dates {
                // Exercise both private events even after an earlier denial
                // has already set the sender's cached capability to false.
                try await sql.raw("UPDATE im_v2.direct_room_pairs SET lower_can_send = true, higher_can_send = true WHERE room_id = \(bind: deniedRoom)").run()
                let input = try request(room: rooms[0], now: date)
                let sibling = try request(room: rooms[1], now: base)
                let outcome: V2SendMessageOutcome
                if path == "batch" {
                    async let denied = batcher.accept(input)
                    async let allowed = batcher.accept(sibling)
                    let pair = try await (denied, allowed)
                    outcome = pair.0
                    guard case .accepted = pair.1 else { throw CancellationError() }
                } else {
                    outcome = try await scalar(input)
                    guard case .accepted = try await scalar(sibling) else { throw CancellationError() }
                }
                guard case .denied(let denial) = outcome else { Issue.record("Expected normal business denial"); throw CancellationError() }
                #expect(denial.reason == (reason == "system" ? .systemAccountReadOnly : .generic))
                let eventID = try #require(input.identifiers.eventID.uuidValue)
                let storedRow = try await sql.raw("SELECT created_at AS value FROM im_v2.direct_message_denials WHERE source_event_id = \(bind: eventID)").first(decoding: RevocationClockDateRow.self)
                let stored = try #require(storedRow).value
                #expect(denial.createdAt == stored)
                let milliseconds = try v2GatewayMilliseconds(stored)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: eventID)").first(decoding: CountRow.self)?.value == 0)
                let outbox = try PostgresV2UserStateEventOutbox(database: database)
                let projector = try PostgresV2UserStateEventProjector(database: deliveryDB)
                let deliveryTime = max(base, date)
                let leases = try await outbox.claim(now: deliveryTime, leaseDuration: 1, limit: 100)
                #expect(leases.filter { $0.event.sourceEventID.uuidValue == eventID }.count == 2)
                for lease in leases {
                    let sequence = try await projector.project(lease.event)
                    #expect(try await projector.project(lease.event) == sequence)
                    #expect(try await outbox.acknowledge(lease, sequence: sequence, now: deliveryTime))
                }
                for (kind, field) in [("timeline_activity", "server_created_at_ms"), ("direct_sending_capability", "updated_at_ms")] {
                    #expect(try await deliverySQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: eventID) AND projection_kind = \(bind: kind) AND (payload->>\(bind: field))::bigint = \(bind: milliseconds) AND created_at = \(bind: date)::timestamptz").first(decoding: CountRow.self)?.value == 1)
                }
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.room_timeline_activities WHERE source_event_id = \(bind: eventID) AND created_at = \(bind: date)::timestamptz").first(decoding: CountRow.self)?.value == 1)
                let before = try await snapshot()
                let replay = V2RoomWriteRequest(command: input.command, capacityProfile: profile, identifiers: input.identifiers, now: base)
                #expect(try await scalar(replay) == outcome)
                #expect(try await batcher.accept(replay) == outcome)
                #expect(try await snapshot() == before)
            }
            #expect(try await count("im_v2.direct_message_denials", on: sql) == Int64(dates.count))
            #expect(try await count("im_v2.room_timeline_activities", on: sql) == Int64(dates.count))
            #expect(try await count("im_v2.messages", on: sql) == Int64(dates.count))
        }
    }

    @Test("Stranger quota cutoff bounds and precision agree in scalar, cold and hot writes",
          arguments: ["scalar", "cold", "hot"], ["precision", "lower", "tiny"])
    func strangerQuotaCutoffBounds(path: String, scenario: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            var rooms: [RoomID] = []
            for target in [memberTwoUUID, memberThreeUUID] {
                guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: target)),
                    capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                else { throw CancellationError() }
                rooms.append(room.roomID)
            }
            let interval: TimeInterval = scenario == "precision" ? 0.1234567 : scenario == "tiny" ? 0.0000001 : 86_400
            func writer(window: TimeInterval, cache: V2DirectRoomLogFastAppendCache = .init()) throws -> PostgresV2RoomWriteStore {
                PostgresV2RoomWriteStore(database: database,
                    strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: window), contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                    directRoomLogFastAppendCache: cache,
                    shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            }
            let fastCache = V2DirectRoomLogFastAppendCache()
            let warm = try writer(window: interval, cache: fastCache)
            func request(_ index: Int, now: Date) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: rooms[index], senderUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "quota window", limits: .init(maxUTF8Bytes: 64)),
                    capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            func scalar(_ request: V2RoomWriteRequest, on store: PostgresV2RoomWriteStore) async throws -> V2SendMessageOutcome {
                try await store.accept(command: request.command, capacityProfile: request.capacityProfile,
                    identifiers: request.identifiers, now: request.now)
            }
            for index in rooms.indices {
                guard case .accepted = try await scalar(request(index, now: base), on: warm) else { throw CancellationError() }
            }
            let store = path == "hot" ? warm : try writer(window: interval)
            let now: Date = scenario == "precision" ? Date(timeIntervalSince1970: 946_684_800.00000075)
                : scenario == "lower" ? Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + 86_399)
                : Date(timeIntervalSince1970: 946_684_800)
            let inputs = try rooms.indices.map { try request($0, now: now) }
            func send(on active: PostgresV2RoomWriteStore) async throws -> [V2SendMessageOutcome] {
                if path != "scalar" { return try await active.acceptAtomically(requests: inputs) }
                var outcomes: [V2SendMessageOutcome] = []
                for input in inputs { outcomes.append(try await scalar(input, on: active)) }
                return outcomes
            }
            func snapshot() async throws -> [String] {
                var rows: [String] = []
                for table in ["messages", "message_send_completions", "stranger_message_windows", "rooms", "direct_room_pairs", "room_admission", "room_events"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    rows.append(try #require(row).value)
                }
                return rows
            }
            if scenario != "precision" {
                let before = try await snapshot()
                var actual: V2RoomWriteStoreError?
                do { _ = try await send(on: store) } catch { actual = error as? V2RoomWriteStoreError }
                #expect(actual == .corruptPersistenceState)
                #expect(try await snapshot() == before)
                return
            }
            let cutoff = now.addingTimeInterval(-interval)
            // The canonical scalar cutoff is inclusive: a full window exactly
            // at that timestamp resets, while one microsecond later does not.
            try await sql.raw("UPDATE im_v2.stranger_message_windows SET window_started_at = \(bind: cutoff)::timestamptz + INTERVAL '1 microsecond', message_count = 10").run()
            let before = try await snapshot()
            // A separate rejecting writer preserves the warmed cache so the
            // following successful reset must exercise the prepared fast path.
            let rejecting = try writer(window: interval)
            do { _ = try await send(on: rejecting); Issue.record("Quota must remain exhausted before its cutoff") }
            catch { #expect(error is V2RoomWriteStoreError || error is V2AtomicRoomWriteBatchError) }
            #expect(try await snapshot() == before)
            try await sql.raw("UPDATE im_v2.stranger_message_windows SET window_started_at = \(bind: cutoff)").run()
            let beforeFast = await fastCache.snapshot()
            let outcomes = try await send(on: store)
            if path == "hot" {
                let afterFast = await fastCache.snapshot()
                #expect(afterFast.committedAppends - beforeFast.committedAppends == 2)
                #expect(afterFast.fallbackAppends == beforeFast.fallbackAppends)
            }
            #expect(outcomes.count == 2)
            for (input, outcome) in zip(inputs, outcomes) {
                guard case .accepted(let message) = outcome else { throw CancellationError() }
                #expect(try await scalar(input, on: store) == .idempotent(message.receipt))
            }
            #expect(try await count("im_v2.messages", on: sql) == 4)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.stranger_message_windows WHERE message_count = 1 AND window_started_at = \(bind: now)::timestamptz").first(decoding: CountRow.self)?.value == 2)
        }
    }

    @Test("Message batches share scalar mute expiry and quota timestamp precision",
          arguments: ["hybrid", "direct"], [946_684_799.99999925, 946_684_800.00000075, 1_750_000_000.1234567])
    func messageBatchCurrentTimestampPrecision(path: String, seconds: Double) async throws {
        try await withForwardOwnerDatabases(mode: path == "hybrid" ? .large : .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: seconds)
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            var rooms = [roomID, roomID]
            var senders = [senderID, UserID(uuid: memberTwoUUID)]
            if path == "direct" {
                rooms = []
                senders = [senderID, senderID]
                for target in [memberTwoUUID, memberThreeUUID] {
                    guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                        command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: target)),
                        capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                    else { throw CancellationError() }
                    rooms.append(room.roomID)
                }
            }
            func store() throws -> PostgresV2RoomWriteStore {
                PostgresV2RoomWriteStore(database: database,
                    strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                    shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            }
            func request(_ index: Int) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: rooms[index], senderUserID: senders[index],
                    clientMessageID: .init(uuid: UUID()), text: "expiry clock", limits: .init(maxUTF8Bytes: 64)),
                    capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: now)
            }
            func scalar(_ request: V2RoomWriteRequest, on writer: PostgresV2RoomWriteStore) async throws -> V2SendMessageOutcome {
                try await writer.accept(command: request.command, capacityProfile: request.capacityProfile,
                    identifiers: request.identifiers, now: request.now)
            }
            let mutedRoom = try #require(rooms[0].uuidValue)
            let mutedSender = try #require(senders[0].uuidValue)
            try await sql.raw("""
                INSERT INTO im_v2.room_member_mutes (room_id, user_id, mute_until, actor_user_id, operation_id, created_at)
                VALUES (\(bind: mutedRoom), \(bind: mutedSender), \(bind: now)::timestamptz + INTERVAL '1 microsecond',
                        \(bind: memberTwoUUID), \(bind: UUID()), \(bind: now.addingTimeInterval(-1)))
                """).run()
            let writer = try store()
            let muted = try request(0), sibling = try request(1)
            await #expect(throws: V2RoomWriteStoreError.actorMuted) { try await scalar(muted, on: writer) }
            var batchError: V2AtomicRoomWriteBatchError?
            do { _ = try await writer.acceptAtomically(requests: [muted, sibling]) }
            catch { batchError = error as? V2AtomicRoomWriteBatchError }
            try #require(batchError?.reason == .authorizationState)
            for table in ["messages", "message_send_completions", "room_events", "stranger_message_windows"] {
                #expect(try await count("im_v2." + table, on: sql) == 0)
            }
            let batcher = V2SendMessageAdmissionBatcher(store: writer,
                configuration: .init(maximumBatchSize: 2, maximumDelay: .milliseconds(2)))
            async let rejected: Void = { () async -> Void in
                await #expect(throws: V2RoomWriteStoreError.actorMuted) { try await batcher.accept(muted) }
            }()
            async let accepted = batcher.accept(sibling)
            let (_, siblingOutcome) = try await (rejected, accepted)
            guard case .accepted = siblingOutcome else { Issue.record("Normal sibling must complete"); throw CancellationError() }
            #expect(try await count("im_v2.messages", on: sql) == 1)

            // At the exact stored deadline the mute has ended. A fresh writer
            // forces the normal batch preflight rather than a warmed fast path.
            try await sql.raw("UPDATE im_v2.room_member_mutes SET mute_until = \(bind: now) WHERE room_id = \(bind: mutedRoom) AND user_id = \(bind: mutedSender)").run()
            guard case .accepted = try await scalar(request(1), on: writer) else { throw CancellationError() }
            let cold = try store()
            let expiredRequests = [muted, try request(1)]
            let outcomes = try await cold.acceptAtomically(requests: expiredRequests)
            #expect(outcomes.count == 2)
            for (request, outcome) in zip(expiredRequests, outcomes) {
                guard case .accepted(let message) = outcome else { throw CancellationError() }
                #expect(try await scalar(request, on: cold) == .idempotent(message.receipt))
            }
            #expect(try await count("im_v2.messages", on: sql) == 4)
            #expect(try await count("im_v2.message_send_completions", on: sql) == 4)
            if path == "direct" {
                #expect(try await count("im_v2.stranger_message_windows", on: sql) == 2)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.stranger_message_windows WHERE window_started_at IS DISTINCT FROM \(bind: now)::timestamptz").first(decoding: CountRow.self)?.value == 0)
                #expect(try await sql.raw("SELECT SUM(message_count)::bigint AS value FROM im_v2.stranger_message_windows").first(decoding: CountRow.self)?.value == 4)
            }
        }
    }

    @Test("Message append paths retain the scalar timestamp and replay the same wire milliseconds",
          arguments: ["group", "hybrid", "hybrid-batch", "direct", "direct-room", "direct-batch"], [false, true])
    func messageAppendTimestampPrecision(path: String, nearDatabaseBounds: Bool) async throws {
        try await withForwardOwnerDatabases(mode: path.hasPrefix("hybrid") ? .large : .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            var rooms = [roomID, roomID]
            if path.hasPrefix("direct") {
                rooms = []
                for target in [memberTwoUUID, memberThreeUUID] {
                    guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                        command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: target)),
                        capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                    else { throw CancellationError() }
                    rooms.append(room.roomID)
                }
            }
            let store = PostgresV2RoomWriteStore(database: database,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                directRoomLogAdmissionMode: path == "direct-room" ? .room : .shardOnly,
                shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            func scalar(_ request: V2RoomWriteRequest) async throws -> V2SendMessageOutcome {
                try await store.accept(command: request.command, capacityProfile: request.capacityProfile,
                    identifiers: request.identifiers, now: request.now)
            }
            let dates: [Date]
            if nearDatabaseBounds {
                // Direct sends also need a representable preceding quota window.
                let lowerOffset: TimeInterval = path.hasPrefix("direct") ? 86_400 : 0
                dates = [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + lowerOffset),
                         Date(timeIntervalSince1970: -0.00000075),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 120),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)]
                let expiry = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 1)
                try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: expiry)").run()
            } else {
                dates = [Date(timeIntervalSince1970: 946_684_799.99999925),
                         Date(timeIntervalSince1970: 946_684_800.00000075),
                         base.addingTimeInterval(0.1234567),
                         base.addingTimeInterval(0.99999975)]
            }
            for date in dates {
                let requests = try rooms.enumerated().map { offset, room in
                    V2RoomWriteRequest(command: try .init(roomID: room, senderUserID: senderID,
                        clientMessageID: .init(uuid: UUID()), text: "message clock", limits: .init(maxUTF8Bytes: 64)),
                        capacityProfile: profile,
                        identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())),
                        now: date.addingTimeInterval(Double(offset) * 0.25))
                }
                let outcomes: [V2SendMessageOutcome]
                if path.hasSuffix("batch") { outcomes = try await store.acceptAtomically(requests: requests) }
                else {
                    var values: [V2SendMessageOutcome] = []
                    for request in requests { values.append(try await scalar(request)) }
                    outcomes = values
                }
                #expect(outcomes.count == requests.count)
                for (request, outcome) in zip(requests, outcomes) {
                    guard case .accepted(let message) = outcome else { Issue.record("Expected fresh acceptance"); throw CancellationError() }
                    let messageID = try #require(request.identifiers.messageID.uuidValue)
                    // Verify the actual timestamp in SQL, not just its decoded Date.
                    for table in ["messages", "message_send_completions"] {
                        #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table) WHERE message_id = \(bind: messageID) AND created_at = \(bind: request.now)::timestamptz").first(decoding: CountRow.self)?.value == 1)
                    }
                    let native = try #require(try await sql.raw("""
                        SELECT floor(extract(epoch FROM created_at) * 1000)::bigint AS value
                        FROM im_v2.messages WHERE message_id = \(bind: messageID)
                        """).first(decoding: CountRow.self)).value
                    if let event = try await sql.raw("""
                        SELECT (payload->>'server_created_at_ms')::bigint AS value
                        FROM im_v2.room_events WHERE event_id = \(bind: request.identifiers.eventID.uuidValue!)
                          AND payload ? 'server_created_at_ms'
                        """).first(decoding: CountRow.self) {
                        #expect(event.value == native)
                    }
                    let projection = try V2MessageProjectionState(accepted: message, forwardedFromMessageID: nil, forwardedFromUserID: nil)
                    #expect(projection.acceptedAtUnixMilliseconds == native)
                    if path.hasPrefix("direct") {
                        let payload = try #require(V2DirectRoomLogPayloadCodec.encode(message))
                        let cached = try JSONDecoder().decode(V2MessageProjectionState.self, from: payload)
                        #expect(cached.acceptedAtUnixMilliseconds == native)
                        let live = try #require(V2DirectRoomLiveEvent(message))
                        #expect(live.payload == payload)
                        let cache = V2DirectRoomLogEventCache(configuration: .init(maximumEvents: 4, maximumBytes: 1_048_576, maximumEventsPerRoom: 4))
                        await cache.recordCommittedPlainDirectMessage(message)
                        let page = try #require(await cache.page(roomID: message.roomID, actorJoinedRevision: 0, actorLeftRevision: nil,
                            currentHighWatermark: message.roomSequence, afterRoomSequence: message.roomSequence - 1, pageSize: 1))
                        #expect(page.events.map(\.payload) == [payload])
                        await cache.finish()
                    }
                    guard case .idempotent(let receipt) = try await scalar(request) else { Issue.record("Expected canonical replay"); throw CancellationError() }
                    #expect(try v2GatewayMilliseconds(receipt.createdAt) == v2GatewayMilliseconds(message.createdAt))
                    #expect(receipt.messageID == message.messageID)
                }
            }
            #expect(try await count("im_v2.messages", on: sql) == Int64(dates.count * 2))
            #expect(try await count("im_v2.message_send_completions", on: sql) == Int64(dates.count * 2))
        }
    }

    @Test("Scalar and batched presence renewals agree at microsecond expiry boundaries")
    func liveLeaseBatchTimestampPrecision() async throws {
        guard let databaseURL = Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"),
              Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" else { return }
        let app = try await Application.make(.testing)
        do {
            app.databases.use(try .postgres(url: databaseURL), as: .psql, isDefault: true)
            let sql = try #require(app.db(.psql) as? any SQLDatabase)
            try await installSchema(on: sql)
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let user = UUID(), device = UUID(), scalarConnection = UUID(), batchConnection = UUID()
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: user), \(bind: device), \(bind: base), \(bind: base))").run()
            let identity = V2AuthenticatedConnection(userID: .init(uuid: user), deviceID: .init(uuid: device), capabilityProfile: "base")
            let store = try PostgresV2LiveActivityStore(database: app.db(.psql))
            let dates = [Date(timeIntervalSince1970: 946_684_800.00000075),
                         Date(timeIntervalSince1970: 946_684_799.99999925),
                         base.addingTimeInterval(0.1234567),
                         Date(timeIntervalSince1970: 946_684_800.99999975),
                         Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 120)]
            for now in dates {
                for remainingMicroseconds in [Int64(0), 1, 1_000_000] {
                    try await sql.raw("DELETE FROM im_v2.user_live_presence_leases").run()
                    let earlier = now.addingTimeInterval(-1)
                    let initialUpdate = v2PostgresTimestampCanEncode(earlier) ? earlier : now
                    // Seed identical leases using the scalar driver's time representation.
                    // SQL keeps the one-microsecond difference even where Date cannot.
                    for connection in [scalarConnection, batchConnection] {
                        try await sql.raw("""
                            INSERT INTO im_v2.user_live_presence_leases
                                (user_id, device_id, connection_id, expires_at, updated_at)
                            VALUES (\(bind: user), \(bind: device), \(bind: connection),
                                    \(bind: now)::timestamptz + \(bind: remainingMicroseconds) * INTERVAL '1 microsecond',
                                    \(bind: initialUpdate))
                            """).run()
                    }
                    let scalar = try await store.renewConnection(identity: identity, connectionID: scalarConnection, now: now)
                    let batch = try await store.renewConnections([
                        .init(identity: identity, connectionID: batchConnection, now: now)
                    ])
                    let expiryRow = try await sql.raw("SELECT \(bind: now.addingTimeInterval(90))::timestamptz AS value").first(decoding: RevocationClockDateRow.self)
                    let expectedExpiry = try #require(expiryRow).value
                    let expected: V2AuthenticatedConnectionLeaseOutcome = remainingMicroseconds > 0
                        ? .accepted(expiresAt: expectedExpiry) : .rejected
                    #expect(scalar == expected)
                    #expect(batch[batchConnection] == .init(outcome: expected, allowsOnlinePresence: true))
                    // Compare persisted timestamps in SQL, without losing microseconds
                    // through Date decoding near PostgreSQL's finite endpoints.
                    #expect(try await sql.raw("""
                        SELECT COUNT(*) AS value
                        FROM im_v2.user_live_presence_leases scalar
                        JOIN im_v2.user_live_presence_leases batched
                          ON batched.connection_id = \(bind: batchConnection)
                        WHERE scalar.connection_id = \(bind: scalarConnection)
                          AND scalar.expires_at = batched.expires_at
                          AND scalar.updated_at = batched.updated_at
                        """).first(decoding: CountRow.self)?.value == 1)
                }
            }
            try await sql.raw("DROP SCHEMA im_v2 CASCADE").run()
            try await app.asyncShutdown()
        } catch {
            if let sql = app.db(.psql) as? any SQLDatabase { try? await sql.raw("DROP SCHEMA IF EXISTS im_v2 CASCADE").run() }
            try? await app.asyncShutdown()
            throw error
        }
    }

    @Test("Scalar and batched group receipts preserve the same PostgreSQL timestamp",
          arguments: [V2GroupCapacityClass.standard, .large], ["mixed", "group", "owner"])
    func receiptBatchTimestampPrecision(mode: V2GroupCapacityClass, path: String) async throws {
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let store = PostgresV2ReadReceiptStore(database: database)
            let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            let dates = [Date(timeIntervalSince1970: 946_684_800.00000075),
                         Date(timeIntervalSince1970: 946_684_799.99999925),
                         base.addingTimeInterval(0.1234567),
                         Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)]
            try await sql.raw("UPDATE im_v2.rooms SET room_sequence = \(bind: dates.count) WHERE room_id = \(bind: roomUUID)").run()
            func batch(_ requests: [V2ReadReceiptRecordRequest]) async throws -> [V2ReadReceiptRecordResult] {
                if path == "mixed" { return try await store.recordBatch(requests) }
                let result = path == "owner"
                    ? try await store.recordGroupsOwnerValidated(requests.map { .init(request: $0, ownerRoute: route) })
                    : try await store.recordGroups(requests)
                return try result.map {
                    switch $0 {
                    case .success(.handled(let outcome)): return .success(outcome)
                    case .failure(let error): return .failure(error)
                    case .success(.notGroup): throw CancellationError()
                    }
                }
            }
            func snapshot() async throws -> String {
                let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, operation_id) FROM im_v2.read_receipt_operations r),
                        'receipts', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id, user_id) FROM im_v2.room_read_receipts r)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)
                return try #require(row).value
            }
            for (index, date) in dates.enumerated() {
                let sequence = UInt64(index + 1)
                let scalar = try V2RecordReadReceiptCommand(roomID: roomID, actorUserID: senderID,
                    operationID: .init(uuid: UUID()), readThroughRoomSequence: sequence)
                guard case .recorded(let scalarReceipt) = try await store.record(command: scalar, now: date) else { throw CancellationError() }
                let requests = try [memberTwoUUID, memberThreeUUID].enumerated().map { offset, actor in
                    V2ReadReceiptRecordRequest(command: try .init(roomID: roomID, actorUserID: .init(uuid: actor),
                        operationID: .init(uuid: UUID()), readThroughRoomSequence: sequence), now: date.addingTimeInterval(TimeInterval(offset)))
                }
                let actual = try await batch(requests)
                var expectedReceipts: [V2ReadReceipt] = []
                for (offset, request) in requests.enumerated() {
                    let expectedDate = try #require(try await sql.raw("SELECT \(bind: request.now)::timestamptz AS value").first(decoding: RevocationClockDateRow.self)).value
                    let expected = try V2ReadReceipt(roomID: roomID, userID: request.command.actorUserID,
                        readThroughRoomSequence: sequence, recordedAt: expectedDate)
                    expectedReceipts.append(expected)
                    if offset == 0 { #expect(expected.recordedAt == scalarReceipt.recordedAt) }
                    let operation = try #require(UUID(uuidString: request.command.operationID.rawValue))
                    let actor = try #require(UUID(uuidString: request.command.actorUserID.rawValue))
                    #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.read_receipt_operations WHERE operation_id = \(bind: operation) AND recorded_at IS DISTINCT FROM \(bind: request.now)::timestamptz").first(decoding: CountRow.self)?.value == 0)
                    #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.room_read_receipts WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: actor) AND updated_at IS DISTINCT FROM \(bind: request.now)::timestamptz").first(decoding: CountRow.self)?.value == 0)
                }
                #expect(actual == expectedReceipts.map { .success(.recorded($0)) })
                #expect(try await count("im_v2.read_receipt_operations", on: sql) == Int64((index + 1) * 3))
                let before = try await snapshot()
                #expect(try await store.record(command: scalar, now: base) == .idempotent(scalarReceipt))
                let retries = requests.map { V2ReadReceiptRecordRequest(command: $0.command, now: base) }
                #expect(try await batch(retries) == expectedReceipts.map { .success(.idempotent($0)) })
                for (request, expected) in zip(requests, expectedReceipts) {
                    #expect(try await store.record(command: request.command, now: base) == .idempotent(expected))
                }
                #expect(try await snapshot() == before)
            }
        }
    }

    @Test("Message storage checks caller-supplied clocks and isolates invalid batch entries",
          arguments: ["group", "hybrid", "direct-room", "direct-shard"])
    func messageStorageClockBounds(path: String) async throws {
        try await withForwardOwnerDatabases(mode: path == "hybrid" ? .large : .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let targetRoom: RoomID
            if path.hasPrefix("direct") {
                guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)),
                    capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                else { throw CancellationError() }
                targetRoom = room.roomID
            } else { targetRoom = roomID }
            let store = PostgresV2RoomWriteStore(database: database,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                directRoomLogAdmissionMode: path == "direct-shard" ? .shardOnly : .room,
                shardAdmissionCommandCreditPool: .init(database: database, batchSize: 1))
            let batcher = V2SendMessageAdmissionBatcher(store: store,
                configuration: .init(maximumBatchSize: 2, maximumDelay: .milliseconds(2)))
            let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            func request(at date: Date, actor: UserID) throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: targetRoom, senderUserID: actor, clientMessageID: .init(uuid: UUID()),
                    text: "clock fixture", limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                    identifiers: .init(messageID: .init(uuid: UUID()), eventID: .init(uuid: UUID())), now: date)
            }
            func scalar(_ request: V2RoomWriteRequest) async throws -> V2SendMessageOutcome {
                try await store.accept(command: request.command, capacityProfile: request.capacityProfile,
                    identifiers: request.identifiers, now: request.now)
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["messages", "message_send_completions", "direct_message_denials", "rooms", "room_memberships",
                    "room_events", "room_timeline_activities",
                    "room_admission", "shard_admission_pools", "direct_room_pairs", "user_sync_log", "user_sync_sequences"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            guard case .accepted = try await scalar(request(at: base, actor: senderID)) else { throw CancellationError() }
            // Start with a finite driver-encodable date outside PostgreSQL's
            // range. A missing guard fails this requirement before the test
            // reaches non-finite dates that the driver's encoder cannot handle.
            for (index, seconds) in [-1e12, Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude,
                                     -.greatestFiniteMagnitude, 1e14, -1e14].enumerated() {
                let bad = try request(at: Date(timeIntervalSince1970: seconds), actor: senderID)
                let good = try request(at: base, actor: .init(uuid: memberTwoUUID))
                let before = try await snapshot()
                var scalarError: V2RoomWriteStoreError?
                do { _ = try await scalar(bad) } catch { scalarError = error as? V2RoomWriteStoreError }
                try #require(scalarError == .corruptPersistenceState)
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                    try await store.acceptOwnerValidated(request: bad, ownerRoute: route)
                }
                let ordered = index.isMultiple(of: 2) ? [bad, good] : [good, bad]
                let invalidIndex = index.isMultiple(of: 2) ? 0 : 1
                #expect(await store.atomicBatchEligibility(requests: ordered)[invalidIndex] == false)
                #expect(await store.atomicBatchPartitions(requests: ordered)[invalidIndex] == nil)
                let batchError = V2AtomicRoomWriteBatchError(reason: .requestShape, isolatedRequestIndices: [invalidIndex])
                await #expect(throws: batchError) { try await store.acceptAtomically(requests: ordered) }
                await #expect(throws: batchError) {
                    try await store.acceptAtomicallyOwnerValidated(requests: ordered.map { .init(request: $0, ownerRoute: route) })
                }
                #expect(try await snapshot() == before)
                async let rejected: Void = { () async -> Void in
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await batcher.accept(bad) }
                }()
                async let accepted = batcher.accept(good)
                let (_, outcome) = try await (rejected, accepted)
                guard case .accepted(let message) = outcome else { Issue.record("Normal sibling failed"); throw CancellationError() }
                #expect(try await scalar(good) == .idempotent(message.receipt))
                let after = try await snapshot()
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await batcher.accept(bad) }
                #expect(try await snapshot() == after)
            }
            #expect(try await count("im_v2.messages", on: sql) == 9)
        }
    }

    @Test("Membership events validate their source group timestamp without changing completed retries",
          arguments: [V2GroupCapacityClass.standard, .large])
    func membershipSourceTimestampBounds(mode: V2GroupCapacityClass) async throws {
        try await withForwardOwnerDatabases(mode: mode) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let target = UserID(uuid: memberTwoUUID)
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: senderUUID)").run()
            let store = PostgresV2RoomMembershipStore(database: database)
            let identity = try await V2PostgresMembershipIdentitySnapshotValidator(database: database).snapshot(actorUserID: senderID, targetUserID: target)
            let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            func invoke(_ command: V2ChangeRoomMembershipCommand, path: Int) async throws -> V2RoomMembershipChangeOutcome {
                let event = EventID(uuid: UUID())
                if path == 0 {
                    return try await store.change(command: command, capacityProfile: profile, eventID: event, now: base)
                }
                if path == 1 {
                    return try await store.changeControlValidated(command: command, ownerRoute: route, identitySnapshot: identity,
                        capacityProfile: profile, eventID: event, now: base)
                }
                return try await database.transaction { transaction in
                    let transactionSQL = try #require(transaction as? any SQLDatabase)
                    return try await PostgresV2RoomMembershipStore.change(in: transactionSQL, command: command,
                        capacityProfile: profile, eventID: event, now: base)
                }
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["group_rooms", "rooms", "room_memberships", "room_membership_operations",
                    "room_events", "user_state_event_outbox", "room_admission", "shard_admission_pools", "user_sync_log", "user_sync_sequences"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            var revision: UInt64 = 0
            for (index, date) in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                                Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), base].enumerated() {
                for action in [V2RoomMembershipAction.remove, .add] {
                    let command = try V2ChangeRoomMembershipCommand(roomID: roomID, actorUserID: senderID, operationID: .init(uuid: UUID()),
                        targetUserID: target, action: action, expectedMembershipRevision: revision)
                    for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                        try await sql.raw("UPDATE im_v2.group_rooms SET created_at = \(bind: literal)::timestamptz WHERE room_id = \(bind: roomUUID)").run()
                        let before = try await snapshot()
                        for path in 0..<3 {
                            await #expect(throws: V2RoomMembershipStoreError.corruptPersistenceState) { try await invoke(command, path: path) }
                            try #require(try await snapshot() == before)
                        }
                    }
                    try await sql.raw("UPDATE im_v2.group_rooms SET created_at = \(bind: date) WHERE room_id = \(bind: roomUUID)").run()
                    guard case .changed(let changed) = try await invoke(command, path: index) else { throw CancellationError() }
                    revision += 1
                    #expect(changed.createdAt == base && changed.membershipRevision == revision && changed.roomSequence == revision)
                    let eventUUID = try #require(UUID(uuidString: changed.eventID.rawValue))
                    let projected = try await sql.raw("SELECT (payload->>'created_at_ms')::bigint AS value FROM im_v2.room_events WHERE event_id = \(bind: eventUUID)").first(decoding: CountRow.self)
                    #expect(try #require(projected).value == v2GatewayMilliseconds(date))
                    // A completed operation depends on its saved result, not
                    // a later change to the group's source profile timestamp.
                    try await sql.raw("UPDATE im_v2.group_rooms SET created_at = 'infinity'::timestamptz WHERE room_id = \(bind: roomUUID)").run()
                    let before = try await snapshot()
                    for path in 0..<3 { #expect(try await invoke(command, path: path) == .idempotent(changed)) }
                    let conflict = try V2ChangeRoomMembershipCommand(roomID: roomID, actorUserID: senderID, operationID: command.operationID,
                        targetUserID: target, action: action == .add ? .remove : .add, expectedMembershipRevision: command.expectedMembershipRevision)
                    for path in 0..<3 { #expect(try await invoke(conflict, path: path) == .idempotencyConflict) }
                    #expect(try await snapshot() == before)
                }
            }
            #expect(try await count("im_v2.room_membership_operations", on: sql) == 6)
            #expect(try await count("im_v2.room_memberships WHERE left_revision IS NULL", on: sql) == 3)
        }
    }

    @Test("Message replay validates saved response times across scalar and batched admission",
          arguments: ["group", "hybrid", "direct-planner", "direct-room-log", "direct-denial"])
    func messageReplayStoredTimestampBounds(path: String) async throws {
        try await withForwardOwnerDatabases(mode: path == "hybrid" ? .large : .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let targetRoom: RoomID
            if path.hasPrefix("direct") {
                let direct = PostgresV2DirectMessagingStore(database: database)
                guard case .opened(let room) = try await direct.open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)),
                    capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                else { throw CancellationError() }
                targetRoom = room.roomID
                if path == "direct-denial" {
                    _ = try await direct.setStrangerMessagePermission(command: .init(actorUserID: .init(uuid: memberTwoUUID),
                        operationID: .init(uuid: UUID()), permission: .deny), now: base)
                }
            } else { targetRoom = roomID }
            let store = PostgresV2RoomWriteStore(database: database)
            let batcher = V2SendMessageAdmissionBatcher(store: store,
                configuration: .init(maximumBatchSize: 2, maximumDelay: .milliseconds(2)))
            let scalar = V2SendMessageService(store: store, capacityProfile: profile, limits: try .init(maxUTF8Bytes: 64), now: { base })
            let batched = V2SendMessageService(store: store, capacityProfile: profile, limits: try .init(maxUTF8Bytes: 64), batcher: batcher, now: { base })
            let client = UUID()
            let command = V2AuthenticatedSendMessage(roomID: targetRoom, actorUserID: senderID, clientMessageID: .init(uuid: client), text: "saved response")
            let conflict = V2AuthenticatedSendMessage(roomID: targetRoom, actorUserID: senderID, clientMessageID: command.clientMessageID, text: "changed request")
            let original = try await scalar.send(command)
            func expected(at date: Date) throws -> V2SendMessageOutcome {
                switch original {
                case .accepted(let message):
                    let r = message.receipt
                    return .idempotent(.init(messageID: r.messageID, roomID: r.roomID, roomSequence: r.roomSequence,
                        timelineSequence: r.timelineSequence, senderUserID: r.senderUserID, clientMessageID: r.clientMessageID,
                        groupCapacityClass: r.groupCapacityClass, sourceEventID: r.sourceEventID,
                        acceptedMembershipRevision: r.acceptedMembershipRevision, directRecipientUserID: r.directRecipientUserID, createdAt: date))
                case .denied(let denial):
                    #expect(path == "direct-denial")
                    return .denied(.init(roomID: denial.roomID, sourceEventID: denial.sourceEventID,
                        timelineSequence: denial.timelineSequence, createdAt: date, reason: denial.reason))
                default: Issue.record("Expected initial message acceptance or business denial"); throw CancellationError()
                }
            }
            if path == "direct-denial" { guard case .denied = original else { throw CancellationError() } }
            #expect(try await scalar.send(command) == expected(at: base))
            #expect(try await batched.send(command) == expected(at: base))
            let table = path == "direct-denial" ? "direct_message_denials" : "message_send_completions"
            func setSavedTime(_ literal: String) async throws {
                // Replace only this disposable fixture row: completion UPDATEs
                // are immutable. All production constraints remain enabled.
                try await sql.raw("""
                    WITH removed AS (
                        DELETE FROM im_v2.\(unsafeRaw: table)
                        WHERE sender_user_id = \(bind: senderUUID) AND client_message_id = \(bind: client)
                        RETURNING *
                    )
                    INSERT INTO im_v2.\(unsafeRaw: table)
                    SELECT (jsonb_populate_record(NULL::im_v2.\(unsafeRaw: table),
                        to_jsonb(removed) || jsonb_build_object('created_at', \(bind: literal)::timestamptz))).*
                    FROM removed
                    """).run()
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["messages", "message_send_completions", "direct_message_denials", "rooms", "room_memberships",
                    "room_events", "room_timeline_activities",
                    "room_admission", "shard_admission_pools", "direct_room_pairs", "user_sync_log", "user_sync_sequences"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                try await setSavedTime(literal)
                let before = try await snapshot()
                for service in [scalar, batched] {
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await service.send(command) }
                    #expect(try await service.send(conflict) == .idempotencyConflict)
                }
                #expect(try await snapshot() == before)
                // An adjacent valid send must complete even when the replay
                // uses the batcher's ordinary-path fallback and fails.
                let sibling = V2AuthenticatedSendMessage(roomID: targetRoom, actorUserID: .init(uuid: memberTwoUUID),
                    clientMessageID: .init(uuid: UUID()), text: "normal sibling")
                async let rejected: Void = { () async -> Void in
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await batched.send(command) }
                }()
                async let accepted = batched.send(sibling)
                let (_, outcome) = try await (rejected, accepted)
                guard case .accepted(let message) = outcome else { Issue.record("Valid sibling did not commit"); throw CancellationError() }
                #expect(try await batched.send(sibling) == .idempotent(message.receipt))
                let after = try await snapshot()
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scalar.send(command) }
                #expect(try await snapshot() == after)
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), base] {
                let literal = try await sql.raw("SELECT \(bind: date)::timestamptz::text AS value").first(decoding: StringValueRow.self)
                try await setSavedTime(try #require(literal).value)
                let before = try await snapshot()
                for service in [scalar, batched] { #expect(try await service.send(command) == expected(at: date)) }
                #expect(try await snapshot() == before)
            }
            #expect(try await count("im_v2.messages", on: sql) == (path == "direct-denial" ? 3 : 4))
        }
    }

    @Test("Sync responses reject interior gaps without issuing capabilities and recover through the maximum sequence",
          arguments: [Int64(0), Int64.max - 3], [false, true])
    func syncResponseContiguousSequenceBoundary(start: Int64, withToken: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let userUUID = UUID(), deviceUUID = UUID()
            let user = UserID(uuid: userUUID), device = DeviceID(uuid: deviceUUID)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: deviceUUID), \(bind: now), \(bind: now))").run()
            try await sql.raw("INSERT INTO im_v2.device_sync_cursors (user_id, device_id, state, reset_generation, acknowledged_sequence) VALUES (\(bind: userUUID), \(bind: deviceUUID), 'ready', 1, \(bind: start))").run()
            let store = V2SyncService(store: PostgresV2SyncStore(database: database), now: { now })
            guard case .ready(_, let empty, let initialToken, _, _) = try await store.pull(userID: user,
                deviceID: device, syncToken: nil, requestedMaxRecords: 3) else { throw CancellationError() }
            #expect(empty.isEmpty)
            let token: V2SyncToken? = withToken ? initialToken : nil
            let events = [UUID(), UUID(), UUID()]
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: userUUID), \(bind: start + 3))").run()
            func insert(_ index: Int) async throws {
                try await sql.raw("""
                    INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at)
                    VALUES (\(bind: userUUID), \(bind: start + Int64(index) + 1), \(bind: events[index]),
                        'stranger_message_permission', '{"allows_stranger_messages":true}'::jsonb, \(bind: now))
                    """).run()
            }
            for index in events.indices { try await insert(index) }
            try await sql.raw("DELETE FROM im_v2.user_sync_log WHERE user_id = \(bind: userUUID) AND user_sync_sequence = \(bind: start + 2)").run()
            func capabilities() async throws -> String {
                guard let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'cursor', (SELECT jsonb_agg(to_jsonb(r)) FROM im_v2.device_sync_cursors r WHERE user_id = \(bind: userUUID)),
                        'tokens', (SELECT jsonb_agg(to_jsonb(r) ORDER BY token) FROM im_v2.sync_tokens r WHERE user_id = \(bind: userUUID)),
                        'receipts', (SELECT jsonb_agg(to_jsonb(r) ORDER BY receipt) FROM im_v2.sync_receipts r WHERE user_id = \(bind: userUUID))
                    )::text AS value
                    """).first(decoding: StringValueRow.self) else { throw CancellationError() }
                return row.value
            }
            let before = try await capabilities()
            for _ in 0..<2 {
                await #expect(throws: V2SyncStoreError.syncLogSequenceGap) {
                    try await store.pull(userID: user, deviceID: device, syncToken: token, requestedMaxRecords: 3)
                }
                #expect(try await capabilities() == before)
            }
            // A gap in the unsent look-ahead row does not invalidate the
            // complete prefix that fits this page.
            guard case .ready(_, let prefix, let continuation, _, let more) = try await store.pull(userID: user,
                deviceID: device, syncToken: token, requestedMaxRecords: 1) else { throw CancellationError() }
            #expect(prefix.map(\.sequence) == [UInt64(start + 1)] && more)
            // The same valid prefix can be selected by a byte budget rather
            // than by the caller's record limit.
            let narrow = V2SyncService(store: PostgresV2SyncStore(database: database, maximumEncodedRecordsBytes: 200), now: { now })
            guard case .ready(_, let bytePrefix, _, _, let byteMore) = try await narrow.pull(userID: user,
                deviceID: device, syncToken: token, requestedMaxRecords: 3) else { throw CancellationError() }
            #expect(bytePrefix == prefix && byteMore)
            let afterPrefix = try await capabilities()
            await #expect(throws: V2SyncStoreError.syncLogSequenceGap) {
                try await store.pull(userID: user, deviceID: device, syncToken: continuation, requestedMaxRecords: 3)
            }
            #expect(try await capabilities() == afterPrefix)
            try await insert(1)
            for _ in 0..<2 {
                guard case .ready(let generation, let records, let next, let receipt, let hasMore) = try await store.pull(
                    userID: user, deviceID: device, syncToken: continuation, requestedMaxRecords: 3) else { throw CancellationError() }
                #expect(records.map(\.sequence) == [UInt64(start + 2), UInt64(start + 3)] && !hasMore)
                try await store.acknowledge(userID: user, deviceID: device, generation: generation,
                    highestContiguousSequence: UInt64(start + 3), receipt: receipt)
                guard case .ready(_, let tail, _, _, let more) = try await store.pull(userID: user,
                    deviceID: device, syncToken: next, requestedMaxRecords: 3) else { throw CancellationError() }
                #expect(tail.isEmpty && !more)
            }
        }
    }

    @Test("An oversized later sync record preserves the sendable prefix and never advances past the record", arguments: [1, 2])
    func syncResponseOversizedLaterRecord(prefixCount: Int) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let userUUID = UUID(), deviceUUID = UUID(), event = UUID()
            let user = UserID(uuid: userUUID), device = DeviceID(uuid: deviceUUID)
            let last = Int64(prefixCount + 1)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: deviceUUID), \(bind: now), \(bind: now))").run()
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: userUUID), \(bind: last))").run()
            for sequence in 1...prefixCount {
                try await sql.raw("""
                    INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at)
                    VALUES (\(bind: userUUID), \(bind: Int64(sequence)), \(bind: UUID()),
                        'stranger_message_permission', '{"allows_stranger_messages":true}'::jsonb, \(bind: now))
                    """).run()
            }
            let state = try V2MessageProjectionState(accepted: .init(messageID: .init(uuid: UUID()), roomID: roomID,
                roomSequence: 1, senderUserID: senderID, clientMessageID: .init(uuid: UUID()),
                text: String(repeating: "x", count: 1_000), mediaPresentations: [], createdAt: now),
                forwardedFromMessageID: nil, forwardedFromUserID: nil)
            let payload = try state.encodedPayloadJSON()
            try await sql.raw("""
                INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at)
                VALUES (\(bind: userUUID), \(bind: last), \(bind: event), 'message', \(bind: payload)::jsonb, \(bind: now))
                """).run()
            let narrow = V2SyncService(store: PostgresV2SyncStore(database: database, maximumEncodedRecordsBytes: 512), now: { now })
            guard case .ready(let generation, let prefix, let continuation, let receipt, let more) = try await narrow.pull(
                userID: user, deviceID: device, syncToken: nil, requestedMaxRecords: 5) else { throw CancellationError() }
            #expect(prefix.map(\.sequence) == (1...prefixCount).map { UInt64($0) } && more)
            #expect(prefix.reduce(0) { $0 + v2EncodedSyncBatchRecordFieldBytes($1) } <= 512)
            #expect(try await sql.raw("SELECT watermark AS value FROM im_v2.sync_tokens WHERE token = \(bind: continuation.rawValue)").first(decoding: CountRow.self)?.value == Int64(prefixCount))
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.sync_receipts WHERE receipt = \(bind: receipt.rawValue) AND first_sequence = 1 AND last_sequence = \(bind: Int64(prefixCount))").first(decoding: CountRow.self)?.value == 1)
            try await narrow.acknowledge(userID: user, deviceID: device, generation: generation,
                highestContiguousSequence: UInt64(prefixCount), receipt: receipt)
            func capabilities() async throws -> String {
                guard let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'cursor', (SELECT jsonb_agg(to_jsonb(r)) FROM im_v2.device_sync_cursors r WHERE user_id = \(bind: userUUID)),
                        'tokens', (SELECT jsonb_agg(to_jsonb(r) ORDER BY token) FROM im_v2.sync_tokens r WHERE user_id = \(bind: userUUID)),
                        'receipts', (SELECT jsonb_agg(to_jsonb(r) ORDER BY receipt) FROM im_v2.sync_receipts r WHERE user_id = \(bind: userUUID))
                    )::text AS value
                    """).first(decoding: StringValueRow.self) else { throw CancellationError() }
                return row.value
            }
            let before = try await capabilities()
            for token: V2SyncToken? in [continuation, nil, continuation, nil] {
                await #expect(throws: V2SyncStoreError.syncRecordTooLarge) {
                    try await narrow.pull(userID: user, deviceID: device, syncToken: token, requestedMaxRecords: 5)
                }
                #expect(try await capabilities() == before)
            }
            // A larger response budget resumes at the unsent record. Neither
            // prefix delivery nor failed retries are allowed to skip it.
            let wider = V2SyncService(store: PostgresV2SyncStore(database: database, maximumEncodedRecordsBytes: 8_192), now: { now })
            guard case .ready(let resumedGeneration, let records, let next, let finalReceipt, let hasMore) = try await wider.pull(
                userID: user, deviceID: device, syncToken: continuation, requestedMaxRecords: 5) else { throw CancellationError() }
            #expect(resumedGeneration == generation && !hasMore && records.count == 1)
            let record = try #require(records.first)
            #expect(record.sequence == UInt64(last) && record.sourceEventID == EventID(uuid: event) && record.projectionKind == "message")
            #expect(v2EncodedSyncBatchRecordFieldBytes(record) > 512)
            #expect(try JSONDecoder().decode(V2MessageProjectionState.self, from: Data(record.payloadJSON.utf8)) == state)
            try await wider.acknowledge(userID: user, deviceID: device, generation: generation,
                highestContiguousSequence: UInt64(last), receipt: finalReceipt)
            guard case .ready(_, let tail, _, _, let tailMore) = try await narrow.pull(userID: user,
                deviceID: device, syncToken: next, requestedMaxRecords: 5) else { throw CancellationError() }
            #expect(tail.isEmpty && !tailMore)
        }
    }

    @Test("Pending snapshot responses do not require a new capability deadline", arguments: [false, true])
    func pendingSnapshotResponseClockBoundary(published: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let userUUID = UUID(), deviceUUID = UUID(), siblingUUID = UUID()
            let user = UserID(uuid: userUUID), device = DeviceID(uuid: deviceUUID), sibling = DeviceID(uuid: siblingUUID)
            for id in [deviceUUID, siblingUUID] {
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: id), \(bind: base), \(bind: base))").run()
            }
            let store = PostgresV2SyncStore(database: database, capabilityLifetime: 60)
            guard case .resetPreparing(let snapshotID, let generation, _) = try await store.pull(userID: user,
                deviceID: device, syncToken: nil, maxRecords: 20, requireSnapshot: true, now: base) else { throw CancellationError() }
            let builder = PostgresV2SnapshotArtifactBuilder(database: database)
            if published { while try await builder.runOnce(now: base).claimed { try Task.checkCancellation() } }
            func snapshot() async throws -> [String] {
                var rows: [String] = []
                for table in ["device_sync_cursors", "sync_snapshot_artifacts", "device_snapshot_resets", "sync_tokens", "sync_receipts", "user_projection_checkpoints"] {
                    guard let value = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    rows.append(value.value)
                }
                return rows
            }
            let before = try await snapshot()
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            #expect(v2PostgresTimestampCanEncode(upper))
            #expect(v2PostgresFutureTimestamp(now: upper, interval: 60) == nil)
            let expected: V2SyncPullResult = published
                ? .resetRequired(snapshotID: snapshotID, generation: generation, baseSequence: 0, expiresAt: base.addingTimeInterval(60))
                : .resetPreparing(snapshotID: snapshotID, generation: generation, retryAfter: 1)
            for requireSnapshot in [false, true] {
                for now in [upper, base, upper] {
                    #expect((try? await store.pull(userID: user, deviceID: device, syncToken: nil,
                        maxRecords: 20, requireSnapshot: requireSnapshot, now: now)) == expected)
                    #expect(try await snapshot() == before)
                }
                // A fresh device still needs a usable future deadline. Its
                // tentative cursor must roll back when issuance cannot proceed.
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                    try await store.pull(userID: user, deviceID: sibling, syncToken: nil,
                        maxRecords: 20, requireSnapshot: requireSnapshot, now: upper)
                }
                #expect(try await snapshot() == before)
            }
            for seconds in [Double.nan, .infinity, -.infinity, 1e14, -1e14] {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                    try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: .init(timeIntervalSince1970: seconds))
                }
                #expect(try await snapshot() == before)
            }
            while try await builder.runOnce(now: base).claimed { try Task.checkCancellation() }
            let manifest = try await store.fetchSnapshotManifest(userID: user, deviceID: device,
                snapshotID: snapshotID, generation: generation, now: base)
            try await store.acknowledgeSnapshot(userID: user, deviceID: device, snapshotID: snapshotID,
                generation: generation, baseSequence: manifest.baseSequence, receipt: manifest.receipt, now: base)
            guard case .ready(let resumed, let records, _, _, _) = try await store.pull(userID: user, deviceID: device,
                syncToken: manifest.nextSyncToken, maxRecords: 20, now: base) else { throw CancellationError() }
            #expect(resumed == generation && records.isEmpty)
        }
    }

    @Test("Shared snapshot lifetime does not extend an earlier device's reset response")
    func snapshotResponseUsesDeviceDeadline() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let userUUID = UUID(), firstUUID = UUID(), secondUUID = UUID()
            let user = UserID(uuid: userUUID), first = DeviceID(uuid: firstUUID), second = DeviceID(uuid: secondUUID)
            for device in [firstUUID, secondUUID] {
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: device), \(bind: base), \(bind: base))").run()
            }
            let store = PostgresV2SyncStore(database: database, capabilityLifetime: 60)
            guard case .resetPreparing(let snapshotID, let generation, _) = try await store.pull(userID: user, deviceID: first,
                syncToken: nil, maxRecords: 20, requireSnapshot: true, now: base) else { throw CancellationError() }
            #expect(generation == 2)
            let builder = PostgresV2SnapshotArtifactBuilder(database: database)
            while try await builder.runOnce(now: base).claimed { try Task.checkCancellation() }
            let firstManifest = try await store.fetchSnapshotManifest(userID: user, deviceID: first, snapshotID: snapshotID, generation: generation, now: base)
            #expect(firstManifest.expiresAt == base.addingTimeInterval(60))
            guard case .resetPreparing(let reused, let secondGeneration, _) = try await store.pull(userID: user, deviceID: second,
                syncToken: nil, maxRecords: 20, requireSnapshot: true, now: base.addingTimeInterval(30)) else { throw CancellationError() }
            #expect(reused == snapshotID && secondGeneration == generation)
            #expect(try await count("im_v2.sync_snapshot_artifacts", on: sql) == 1)
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["device_sync_cursors", "sync_snapshot_artifacts", "device_snapshot_resets", "sync_tokens", "sync_receipts", "user_projection_checkpoints"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let before = try await snapshot()
            for (device, deadline) in [(first, base.addingTimeInterval(60)), (second, base.addingTimeInterval(90))] {
                for observed in [base.addingTimeInterval(30), deadline.addingTimeInterval(-1)] {
                    #expect(try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: observed)
                        == .resetRequired(snapshotID: snapshotID, generation: generation, baseSequence: 0, expiresAt: deadline))
                    #expect(try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: observed).expiresAt == deadline)
                }
                for observed in [deadline, deadline.addingTimeInterval(1)] {
                    // Pull continues to identify the pending snapshot with its
                    // actual deadline; it must not advertise another device's lease.
                    #expect(try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: observed)
                        == .resetRequired(snapshotID: snapshotID, generation: generation, baseSequence: 0, expiresAt: deadline))
                    await #expect(throws: V2SyncStoreError.snapshotExpiredOrInvalid) {
                        try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: observed)
                    }
                }
                #expect(try await snapshot() == before)
            }
            #expect(try await store.fetchSnapshotManifest(userID: user, deviceID: second, snapshotID: snapshotID, generation: generation,
                now: base.addingTimeInterval(60)).expiresAt == base.addingTimeInterval(90))
            // Boundary observations above made no writes. Complete both valid
            // assignments with a clock inside their original lifetimes.
            for device in [first, second] {
                let manifest = try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base.addingTimeInterval(31))
                try await store.acknowledgeSnapshot(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation,
                    baseSequence: manifest.baseSequence, receipt: manifest.receipt, now: base.addingTimeInterval(31))
                guard case .ready(let resumed, let records, _, _, _) = try await store.pull(userID: user, deviceID: device,
                    syncToken: manifest.nextSyncToken, maxRecords: 20, now: base.addingTimeInterval(31)) else { throw CancellationError() }
                #expect(resumed == generation && records.isEmpty)
            }
            #expect(try await count("im_v2.device_sync_cursors WHERE state = 'ready' AND reset_generation = 2", on: sql) == 2)
        }
    }

    @Test("Snapshot response expiry validates the effective artifact and device deadline")
    func snapshotResponseTimestampBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000), expiry = Date(timeIntervalSince1970: 1_750_000_060)
            let userUUID = UUID(), deviceUUID = UUID()
            let user = UserID(uuid: userUUID), device = DeviceID(uuid: deviceUUID)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: deviceUUID), \(bind: base), \(bind: base))").run()
            let store = PostgresV2SyncStore(database: database, capabilityLifetime: 60)
            guard case .resetPreparing(let snapshotID, let generation, _) = try await store.pull(userID: user, deviceID: device,
                syncToken: nil, maxRecords: 20, requireSnapshot: true, now: base) else { throw CancellationError() }
            let builder = PostgresV2SnapshotArtifactBuilder(database: database)
            while try await builder.runOnce(now: base).claimed { try Task.checkCancellation() }
            let initialManifest = try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base)
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["device_sync_cursors", "sync_snapshot_artifacts", "device_snapshot_resets", "sync_tokens", "sync_receipts", "user_projection_checkpoints"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let initial = try await snapshot()
            let tables = ["sync_snapshot_artifacts", "device_snapshot_resets"]
            for affected in [[tables[0]], [tables[1]], tables] {
                for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                    for table in tables { try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET expires_at = \(bind: expiry)").run() }
                    for table in affected { try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET expires_at = \(bind: literal)::timestamptz").run() }
                    let before = try await snapshot()
                    if literal == "-infinity" || affected.count == 2 {
                        await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                            try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: base)
                        }
                        if literal == "-infinity" {
                            await #expect(throws: V2SyncStoreError.snapshotExpiredOrInvalid) {
                                try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base)
                            }
                        } else {
                            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                                try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base)
                            }
                        }
                    } else {
                        // The remaining finite lease still bounds both responses.
                        #expect(try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: base)
                            == .resetRequired(snapshotID: snapshotID, generation: generation, baseSequence: 0, expiresAt: expiry))
                        #expect(try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base) == initialManifest)
                    }
                    #expect(try await snapshot() == before)
                }
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), expiry] {
                for table in tables { try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET expires_at = \(bind: date)").run() }
                let before = try await snapshot()
                #expect(try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: base)
                    == .resetRequired(snapshotID: snapshotID, generation: generation, baseSequence: 0, expiresAt: date))
                if date > base {
                    #expect(try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base).expiresAt == date)
                } else {
                    await #expect(throws: V2SyncStoreError.snapshotExpiredOrInvalid) {
                        try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshotID, generation: generation, now: base)
                    }
                }
                #expect(try await snapshot() == before)
            }
            #expect(try await snapshot() == initial)
        }
    }

    @Test("Receipt replay rejects invalid stored times without failing sibling commands",
          arguments: ["direct", "group", "group-owner", "mixed-batch", "group-batch", "owner-batch"])
    func receiptReplayStoredTimestampBounds(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let store = PostgresV2ReadReceiptStore(database: database)
            let targetRoom: RoomID
            if path == "direct" || path == "mixed-batch" {
                guard case .opened(let room) = try await PostgresV2DirectMessagingStore(database: database).open(
                    command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)),
                    capacityProfile: forwardImportTestProfile(), roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base)
                else { throw CancellationError() }
                targetRoom = room.roomID
            } else { targetRoom = roomID }
            let targetUUID = try #require(UUID(uuidString: targetRoom.rawValue))
            try await sql.raw("UPDATE im_v2.rooms SET room_sequence = 2 WHERE room_id = \(bind: targetUUID)").run()
            let command = try V2RecordReadReceiptCommand(roomID: targetRoom, actorUserID: senderID,
                operationID: .init(uuid: UUID()), readThroughRoomSequence: 1)
            let operation = try #require(UUID(uuidString: command.operationID.rawValue))
            let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
            func batch(_ requests: [V2ReadReceiptRecordRequest]) async throws -> [V2ReadReceiptRecordResult] {
                let result: [V2GroupReadReceiptBatchResult]
                if path == "owner-batch" || path == "group-owner" {
                    result = try await store.recordGroupsOwnerValidated(requests.map { .init(request: $0, ownerRoute: route) })
                } else if path == "group-batch" {
                    result = try await store.recordGroups(requests)
                } else { return try await store.recordBatch(requests) }
                return try result.map {
                    switch $0 {
                    case .success(.handled(let outcome)): return .success(outcome)
                    case .failure(let error): return .failure(error)
                    case .success(.notGroup): throw CancellationError()
                    }
                }
            }
            func invoke(_ input: V2RecordReadReceiptCommand) async throws -> V2ReadReceiptOutcome {
                if path.hasSuffix("batch") {
                    let results = try await batch([.init(command: input, now: base)])
                    #expect(results.count == 1)
                    switch try #require(results.first) {
                    case .success(let outcome): return outcome
                    case .failure(let error): throw error
                    }
                }
                if path == "group" || path == "group-owner" {
                    let result = path == "group" ? try await store.recordGroup(command: input, now: base)
                        : try await store.recordGroupOwnerValidated(command: input, ownerRoute: route, now: base)
                    guard case .handled(let outcome) = result else { throw CancellationError() }
                    return outcome
                }
                return try await store.record(command: input, now: base)
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["rooms", "room_memberships", "read_receipt_operations", "room_read_receipts", "user_sync_sequences", "user_sync_log",
                    "room_events", "read_receipt_preference_propagation_outbox"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let saved = try V2ReadReceipt(roomID: targetRoom, userID: senderID, readThroughRoomSequence: 1, recordedAt: base)
            #expect(try await invoke(command) == .recorded(saved))
            #expect(try await invoke(command) == .idempotent(saved))
            let conflict = try V2RecordReadReceiptCommand(roomID: targetRoom, actorUserID: senderID,
                operationID: command.operationID, readThroughRoomSequence: 2)
            for (index, literal) in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"].enumerated() {
                try await sql.raw("UPDATE im_v2.read_receipt_operations SET recorded_at = \(bind: literal)::timestamptz WHERE user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)").run()
                let before = try await snapshot()
                await #expect(throws: V2ReadReceiptStoreError.corruptPersistenceState) { try await invoke(command) }
                #expect(try await invoke(conflict) == .idempotencyConflict)
                #expect(try await snapshot() == before)
                let sibling = try V2RecordReadReceiptCommand(roomID: targetRoom, actorUserID: .init(uuid: memberTwoUUID),
                    operationID: .init(uuid: UUID()), readThroughRoomSequence: 2)
                let siblingReceipt = try V2ReadReceipt(roomID: targetRoom, userID: sibling.actorUserID, readThroughRoomSequence: 2, recordedAt: base)
                let bad = V2ReadReceiptRecordRequest(command: command, now: base)
                let good = V2ReadReceiptRecordRequest(command: sibling, now: base)
                let ordered = index.isMultiple(of: 2) ? [bad, good] : [good, bad]
                let expected: [V2ReadReceiptRecordResult] = index.isMultiple(of: 2)
                    ? [.failure(.corruptPersistenceState), .success(.recorded(siblingReceipt))]
                    : [.success(.recorded(siblingReceipt)), .failure(.corruptPersistenceState)]
                #expect(try await batch(ordered) == expected)
                #expect(try await count("im_v2.read_receipt_operations", on: sql) == Int64(index + 2))
                #expect(try await sql.raw("SELECT read_through_room_sequence AS value FROM im_v2.room_read_receipts WHERE room_id = \(bind: targetUUID) AND user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == 1)
                // Retrying the valid sibling must observe the already committed
                // result even though the adjacent replay returned an error.
                #expect(try await invoke(sibling) == .idempotent(siblingReceipt))
                let after = try await snapshot()
                await #expect(throws: V2ReadReceiptStoreError.corruptPersistenceState) { try await invoke(command) }
                #expect(try await snapshot() == after)
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), base] {
                try await sql.raw("UPDATE im_v2.read_receipt_operations SET recorded_at = \(bind: date) WHERE user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)").run()
                let before = try await snapshot()
                let expected = try V2ReadReceipt(roomID: targetRoom, userID: senderID, readThroughRoomSequence: 1, recordedAt: date)
                #expect(try await invoke(command) == .idempotent(expected))
                #expect(try await snapshot() == before)
            }
        }
    }

    @Test("Moderation replay validates saved time without recomputing audit retention",
          arguments: ["redact", "mute", "remove", "freeze", "unfreeze"])
    func moderationReplayTimestampBounds(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let store = PostgresV2ModerationStore(database: database)
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: senderUUID)").run()
            let send = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { base })
            guard case .accepted(let message) = try await send.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "Moderation timestamp fixture")) else { throw CancellationError() }
            if kind == "unfreeze" {
                try await sql.raw("UPDATE im_v2.rooms SET frozen_at = \(bind: base), frozen_by_user_id = \(bind: senderUUID) WHERE room_id = \(bind: roomUUID)").run()
            }
            let operation = UUID()
            let action: V2ModerationAction = switch kind {
            case "redact": .redactMessage
            case "mute": .muteMember
            case "remove": .removeMember
            case "freeze": .freezeRoom
            default: .unfreezeRoom
            }
            func invoke(_ id: UUID, at now: Date, ownerValidated: Bool = false, conflict: Bool = false) async throws -> V2ModerationOutcome {
                let command = try V2ModerationCommand(roomID: roomID, actorUserID: senderID, operationID: .init(uuid: id), action: action,
                    targetUserID: kind == "mute" || kind == "remove" ? .init(uuid: memberTwoUUID) : nil,
                    messageID: kind == "redact" ? message.messageID : nil, muteUntil: kind == "mute" ? base.addingTimeInterval(60) : nil,
                    reasonCode: .init(conflict ? "other_reason" : "abuse_spam"))
                let event = EventID(uuid: UUID())
                let route = try V2RoomShardRoute(shardID: "room-a", epoch: 0)
                if kind == "freeze" || kind == "unfreeze" {
                    if ownerValidated {
                        return try await store.applyTrustedSafetyOwnerValidated(command: command, ownerRoute: route, capacityProfile: profile, eventID: event, now: now)
                    }
                    return try await store.applyTrustedSafety(command: command, capacityProfile: profile, eventID: event, now: now)
                }
                if ownerValidated {
                    return try await store.applyOwnerValidated(command: command, ownerRoute: route, capacityProfile: profile, eventID: event, now: now)
                }
                return try await store.apply(command: command, capacityProfile: profile, eventID: event, now: now)
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for table in ["rooms", "room_memberships", "room_member_mutes", "messages", "message_media_references", "moderation_operations",
                    "moderation_audit_entries", "room_events", "room_admission", "shard_admission_pools"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            guard case .applied(let accepted) = try await invoke(operation, at: base) else { throw CancellationError() }
            #expect(accepted.createdAt == base && accepted.roomSequence == 2 && accepted.action == action)
            let initial = try await snapshot()
            // The last clock is itself representable, but adding the required
            // audit retention would exceed PostgreSQL's finite timestamp range.
            for seconds in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude,
                            1e14, -1e14, -1e12, 946_684_800 + 9_223_371_331_200 - 10] {
                let invalid = Date(timeIntervalSince1970: seconds)
                for ownerValidated in [false, true] {
                    #expect(try await invoke(operation, at: invalid, ownerValidated: ownerValidated) == .idempotent(accepted))
                    #expect(try await invoke(operation, at: invalid, ownerValidated: ownerValidated, conflict: true) == .idempotencyConflict)
                    await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { try await invoke(UUID(), at: invalid, ownerValidated: ownerValidated) }
                    #expect(try await snapshot() == initial)
                }
            }
            for column in kind == "mute" ? ["created_at", "mute_until"] : ["created_at"] {
                for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                    try await sql.raw("UPDATE im_v2.moderation_operations SET \(unsafeRaw: column) = \(bind: literal)::timestamptz WHERE operation_id = \(bind: operation)").run()
                    let before = try await snapshot()
                    for ownerValidated in [false, true] {
                        await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { try await invoke(operation, at: base, ownerValidated: ownerValidated) }
                        #expect(try await invoke(operation, at: base, ownerValidated: ownerValidated, conflict: true) == .idempotencyConflict)
                    }
                    #expect(try await snapshot() == before)
                }
                let restored = column == "mute_until" ? base.addingTimeInterval(60) : base
                try await sql.raw("UPDATE im_v2.moderation_operations SET \(unsafeRaw: column) = \(bind: restored) WHERE operation_id = \(bind: operation)").run()
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), base] {
                try await sql.raw("UPDATE im_v2.moderation_operations SET created_at = \(bind: date) WHERE operation_id = \(bind: operation)").run()
                let before = try await snapshot()
                let expected = try V2ModerationResult(roomID: accepted.roomID, operationID: accepted.operationID, action: accepted.action,
                    targetUserID: accepted.targetUserID, messageID: accepted.messageID, messageRevision: accepted.messageRevision,
                    membershipRevision: accepted.membershipRevision, muteUntil: accepted.muteUntil, roomSequence: accepted.roomSequence,
                    eventID: accepted.eventID, createdAt: date)
                for ownerValidated in [false, true] {
                    #expect(try await invoke(operation, at: base, ownerValidated: ownerValidated) == .idempotent(expected))
                }
                #expect(try await snapshot() == before)
            }
            #expect(try await snapshot() == initial)
        }
    }

    @Test("Member mute retries preserve PostgreSQL timestamp precision")
    func moderationMuteReplayPrecision() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let store = PostgresV2ModerationStore(database: database)
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE room_id = \(bind: roomUUID) AND user_id = \(bind: senderUUID)").run()
            var differences = 0
            for fraction in [0.00000025, 0.001, 0.1234567] {
                let operation = UUID(), deadline = base.addingTimeInterval(60 + fraction)
                func command(_ expiry: Date, operationID: UUID? = nil) throws -> V2ModerationCommand {
                    try .init(roomID: roomID, actorUserID: senderID, operationID: .init(uuid: operationID ?? operation), action: .muteMember,
                        targetUserID: .init(uuid: memberTwoUUID), muteUntil: expiry, reasonCode: .init("abuse_spam"))
                }
                guard case .applied(let applied) = try await store.apply(command: command(deadline), capacityProfile: profile,
                    eventID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
                let stored = try #require(try await sql.raw("SELECT mute_until AS value FROM im_v2.moderation_operations WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)).value
                if stored != deadline { differences += 1 }
                func snapshot() async throws -> [String] {
                    var result: [String] = []
                    for table in ["rooms", "room_member_mutes", "moderation_operations", "moderation_audit_entries", "room_events", "room_admission", "shard_admission_pools"] {
                        let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                        result.append(try #require(row).value)
                    }
                    return result
                }
                let before = try await snapshot()
                let expected = try V2ModerationResult(roomID: applied.roomID, operationID: applied.operationID, action: applied.action,
                    targetUserID: applied.targetUserID, messageID: nil, muteUntil: stored, roomSequence: applied.roomSequence,
                    eventID: applied.eventID, createdAt: applied.createdAt)
                for now in [base, Date(timeIntervalSince1970: .nan)] {
                    #expect(try await store.apply(command: command(deadline), capacityProfile: profile, eventID: .init(uuid: UUID()), now: now) == .idempotent(expected))
                    #expect(try await store.applyOwnerValidated(command: command(deadline), ownerRoute: .init(shardID: "room-a", epoch: 0), capacityProfile: profile,
                        eventID: .init(uuid: UUID()), now: now) == .idempotent(expected))
                    #expect(try await store.apply(command: command(deadline.addingTimeInterval(0.01)), capacityProfile: profile,
                        eventID: .init(uuid: UUID()), now: now) == .idempotencyConflict)
                }
                // A different operation requesting the same stored deadline
                // must not append another event or consume admission again.
                #expect(try await store.apply(command: command(deadline, operationID: UUID()), capacityProfile: profile,
                    eventID: .init(uuid: UUID()), now: base) == .actionAlreadyInDesiredState)
                let unrepresentableFuture = base.addingTimeInterval(0.00000025)
                #expect(unrepresentableFuture > base && !v2PostgresTimestampPrecedes(base, unrepresentableFuture))
                await #expect(throws: V2ModerationValidationError.invalidMuteExpiry) {
                    try await store.apply(command: command(unrepresentableFuture, operationID: UUID()), capacityProfile: profile,
                        eventID: .init(uuid: UUID()), now: base)
                }
                #expect(try await snapshot() == before)
            }
            #expect(differences > 0)
            #expect(try await count("im_v2.moderation_operations", on: sql) == 3)
            #expect(try await count("im_v2.moderation_audit_entries", on: sql) == 3)
            #expect(try await count("im_v2.room_events", on: sql) == 3)
        }
    }

    @Test("Live preferences validate saved time and use the current clock only for new facts")
    func livePreferenceReplayTimestampBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let store = try PostgresV2LiveActivityStore(database: database)
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let minimum = Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000)
            let maximum = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map(Date.init(timeIntervalSince1970:))
            let operation = UUID()
            let command = V2SetLiveActivityPreferencesCommand(actorUserID: senderID, operationID: .init(uuid: operation),
                allowsOnlinePresence: false, allowsTypingIndicators: false)
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for table in ["user_live_activity_preferences", "user_live_activity_preference_operations", "user_live_presence_leases", "user_sync_sequences", "user_sync_log"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            let empty = try await snapshot()
            for invalid in invalidDates {
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) { try await store.preferences(userID: senderID, now: invalid) }
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) { try await store.setPreferences(command: command, now: invalid) }
                #expect(try await snapshot() == empty)
            }
            for date in [minimum, maximum, base] {
                #expect(try await store.preferences(userID: senderID, now: date) == .init(allowsOnlinePresence: true, allowsTypingIndicators: true, updatedAt: date))
            }
            #expect(try await snapshot() == empty)
            let saved = V2LiveActivityPreferences(allowsOnlinePresence: false, allowsTypingIndicators: false, updatedAt: base)
            #expect(try await store.setPreferences(command: command, now: base) == .updated(saved))
            let initial = try await snapshot()
            for invalid in invalidDates {
                #expect(try await store.preferences(userID: senderID, now: invalid) == saved)
                #expect(try await store.setPreferences(command: command, now: invalid) == .idempotent(saved))
                let conflict = V2SetLiveActivityPreferencesCommand(actorUserID: senderID, operationID: .init(uuid: operation),
                    allowsOnlinePresence: true, allowsTypingIndicators: false)
                #expect(try await store.setPreferences(command: conflict, now: invalid) == .idempotencyConflict)
                let fresh = V2SetLiveActivityPreferencesCommand(actorUserID: senderID, operationID: .init(uuid: UUID()),
                    allowsOnlinePresence: true, allowsTypingIndicators: true)
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) { try await store.setPreferences(command: fresh, now: invalid) }
                #expect(try await snapshot() == initial)
            }
            for table in ["user_live_activity_preferences", "user_live_activity_preference_operations"] {
                for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                    try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET updated_at = \(bind: literal)::timestamptz").run()
                    let before = try await snapshot()
                    if table == "user_live_activity_preferences" {
                        await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) { try await store.preferences(userID: senderID, now: base) }
                        #expect(try await store.setPreferences(command: command, now: base) == .idempotent(saved))
                    } else {
                        await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) { try await store.setPreferences(command: command, now: base) }
                        #expect(try await store.preferences(userID: senderID, now: base) == saved)
                        let conflict = V2SetLiveActivityPreferencesCommand(actorUserID: senderID, operationID: .init(uuid: operation),
                            allowsOnlinePresence: false, allowsTypingIndicators: true)
                        #expect(try await store.setPreferences(command: conflict, now: base) == .idempotencyConflict)
                    }
                    #expect(try await snapshot() == before)
                }
                try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET updated_at = \(bind: base)").run()
            }
            for date in [minimum, maximum, base] {
                for table in ["user_live_activity_preferences", "user_live_activity_preference_operations"] {
                    try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET updated_at = \(bind: date)").run()
                }
                let before = try await snapshot()
                let expected = V2LiveActivityPreferences(allowsOnlinePresence: false, allowsTypingIndicators: false, updatedAt: date)
                #expect(try await store.preferences(userID: senderID, now: base) == expected)
                #expect(try await store.setPreferences(command: command, now: base) == .idempotent(expected))
                #expect(try await snapshot() == before)
            }
            #expect(try await snapshot() == initial)
        }
    }

    @Test("Presence responses validate the selected lease while preserving offline and hidden states")
    func livePresenceResponseTimestampBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let direct = PostgresV2DirectMessagingStore(database: database)
            let live = try PostgresV2LiveActivityStore(database: database)
            let peer = UserID(uuid: memberTwoUUID)
            guard case .opened(let room) = try await direct.open(command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: peer),
                capacityProfile: forwardImportTestProfile(), roomShardID: "room-a", roomID: .init(uuid: UUID()), now: base) else { throw CancellationError() }
            let device = UUID(), primary = UUID(), secondary = UUID()
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: memberTwoUUID), \(bind: device), \(bind: base), \(bind: base))").run()
            for (connection, expiry) in [(primary, base.addingTimeInterval(30)), (secondary, base.addingTimeInterval(90))] {
                try await sql.raw("INSERT INTO im_v2.user_live_presence_leases (connection_id, user_id, device_id, expires_at, updated_at) VALUES (\(bind: connection), \(bind: memberTwoUUID), \(bind: device), \(bind: expiry), \(bind: base))").run()
            }
            _ = try await live.setPreferences(command: .init(actorUserID: peer, operationID: .init(uuid: UUID()), allowsOnlinePresence: true, allowsTypingIndicators: true), now: base)
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for table in ["auth_devices", "user_live_presence_leases", "user_live_activity_preferences", "user_live_activity_preference_operations", "user_sync_log"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            func presence() async throws -> V2PresenceState { try await live.presence(roomID: room.roomID, viewerUserID: senderID, now: base) }
            let original = try await snapshot()
            #expect(try await presence() == .init(roomID: room.roomID, targetUserID: peer, isOnline: true, expiresAt: base.addingTimeInterval(90)))
            #expect(try await snapshot() == original)
            for literal in ["infinity", "294276-12-31 23:59:59.999999+00"] {
                try await sql.raw("UPDATE im_v2.user_live_presence_leases SET expires_at = \(bind: literal)::timestamptz WHERE connection_id = \(bind: secondary)").run()
                let before = try await snapshot()
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) { try await presence() }
                #expect(try await snapshot() == before)
                try await sql.raw("UPDATE im_v2.user_live_activity_preferences SET allows_online_presence = false WHERE user_id = \(bind: memberTwoUUID)").run()
                let hidden = try await snapshot()
                #expect(try await presence() == .init(roomID: room.roomID, targetUserID: peer, isOnline: false, expiresAt: base))
                #expect(try await snapshot() == hidden)
                try await sql.raw("UPDATE im_v2.user_live_activity_preferences SET allows_online_presence = true WHERE user_id = \(bind: memberTwoUUID)").run()
            }
            // Expired rows do not participate in MAX(expires_at), including
            // PostgreSQL's negative infinity sentinel.
            try await sql.raw("UPDATE im_v2.user_live_presence_leases SET expires_at = '-infinity'::timestamptz WHERE connection_id = \(bind: secondary)").run()
            let expired = try await snapshot()
            #expect(try await presence() == .init(roomID: room.roomID, targetUserID: peer, isOnline: true, expiresAt: base.addingTimeInterval(30)))
            #expect(try await snapshot() == expired)
            try await sql.raw("DELETE FROM im_v2.user_live_presence_leases WHERE connection_id = \(bind: primary)").run()
            for date in [base.addingTimeInterval(-1), base, base.addingTimeInterval(1),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)] {
                try await sql.raw("UPDATE im_v2.user_live_presence_leases SET expires_at = \(bind: date) WHERE connection_id = \(bind: secondary)").run()
                let before = try await snapshot()
                #expect(try await presence() == .init(roomID: room.roomID, targetUserID: peer, isOnline: date > base, expiresAt: date > base ? date : base))
                #expect(try await snapshot() == before)
            }
        }
    }

    @Test("Preference conflicts bypass failed shadow forwarding while committed retries recover", arguments: ["conversation", "favorite"])
    func preferenceConflictShadowFailure(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 946_684_800 + 0.00000125)
            let shadow = PreferenceReplayClockShadow()
            let store = PostgresV2ConversationCapabilitiesStore(database: database, shadowForwarder: shadow)
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database),
                capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { now })
            guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "preference forwarding")) else { throw CancellationError() }
            let operation = UUID()
            func perform(conflict: Bool, date: Date) async throws -> V2ConversationCapabilitiesOutcome<Date> {
                if kind == "conversation" {
                    switch try await store.setConversationState(actorUserID: senderID,
                        command: .init(operationID: .init(uuid: operation), roomID: roomID,
                            isPinned: !conflict, isArchived: true, muteUntil: nil), now: date) {
                    case .applied(let value): return .applied(value.updatedAt)
                    case .idempotent(let value): return .idempotent(value.updatedAt)
                    case .idempotencyConflict: return .idempotencyConflict
                    }
                }
                switch try await store.setMessageFavorite(actorUserID: senderID,
                    command: .init(operationID: .init(uuid: operation), roomID: roomID,
                        messageID: message.messageID, isFavorited: !conflict), now: date) {
                case .applied(let value): return .applied(value.updatedAt)
                case .idempotent(let value): return .idempotent(value.updatedAt)
                case .idempotencyConflict: return .idempotencyConflict
                }
            }
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["user_room_preferences", "user_room_preference_operations", "user_message_favorites", "user_message_favorite_operations", "user_sync_sequences", "user_sync_log"] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    values.append(row.value)
                }
                return values
            }
            shadow.setFailure(true)
            await #expect(throws: PreferenceReplayClockShadowError.unavailable) { try await perform(conflict: false, date: now) }
            let expectedCall = PreferenceReplayClockShadow.Call(userID: senderID, sourceEventID: .init(uuid: operation),
                kinds: [kind == "conversation" ? "conversation_state" : "message_favorite"])
            #expect(shadow.calls == [expectedCall])
            let table = kind == "conversation" ? "user_room_preference_operations" : "user_message_favorite_operations"
            let persisted = try #require(try await sql.raw("SELECT updated_at AS value FROM im_v2.\(unsafeRaw: table) WHERE actor_user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)).value
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE user_id = \(bind: senderUUID) AND source_event_id = \(bind: operation) AND created_at = \(bind: now)").first(decoding: CountRow.self)?.value == 1)
            let committed = try await snapshot()
            for date in [Date(timeIntervalSince1970: .nan), Date(timeIntervalSince1970: .infinity), now] {
                #expect((try? await perform(conflict: true, date: date)) == .idempotencyConflict)
                #expect(shadow.calls == [expectedCall])
                #expect(try await snapshot() == committed)
            }
            // Matching retries must still attempt the outstanding forwarding,
            // surface a dependency failure, and recover when it is available.
            await #expect(throws: PreferenceReplayClockShadowError.unavailable) {
                try await perform(conflict: false, date: Date(timeIntervalSince1970: .nan))
            }
            #expect(shadow.calls == [expectedCall, expectedCall])
            #expect(try await snapshot() == committed)
            shadow.setFailure(false)
            #expect(try await perform(conflict: false, date: Date(timeIntervalSince1970: .infinity)) == .idempotent(persisted))
            #expect(shadow.calls == [expectedCall, expectedCall, expectedCall])
            #expect(try await snapshot() == committed)
        }
    }

    @Test("Preference replays use committed time and preserve projection forwarding",
          arguments: ["conversation", "favorite", "receipts"])
    func preferenceReplayTimestampBounds(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let shadow = PreferenceReplayClockShadow()
            let conversations = PostgresV2ConversationCapabilitiesStore(database: database, shadowForwarder: shadow)
            let receipts = PostgresV2ReadReceiptStore(database: database, shadowForwarder: shadow)
            var messageID = MessageID(uuid: UUID())
            if kind == "favorite" {
                let send = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: try forwardImportTestProfile(),
                    limits: try .init(maxUTF8Bytes: 64), now: { base })
                guard case .accepted(let message) = try await send.send(.init(roomID: roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "Favorite clock fixture")) else { throw CancellationError() }
                messageID = message.messageID
            }
            let operation = UUID()
            let projectionKind = kind == "conversation" ? "conversation_state" : kind == "favorite" ? "message_favorite" : "read_receipt_preferences"
            func invoke(_ id: UUID, at now: Date, replay: Bool = false, conflict: Bool = false) async throws -> Date? {
                switch kind {
                case "conversation":
                    let outcome = try await conversations.setConversationState(actorUserID: senderID,
                        command: .init(operationID: .init(uuid: id), roomID: roomID, isPinned: !conflict,
                            isArchived: true, muteUntil: base.addingTimeInterval(60)), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    let value: V2ConversationState
                    switch outcome {
                    case .applied(let state): #expect(!replay); value = state
                    case .idempotent(let state): #expect(replay); value = state
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.isPinned && value.isArchived && value.muteUntil == base.addingTimeInterval(60))
                    return value.updatedAt
                case "favorite":
                    let outcome = try await conversations.setMessageFavorite(actorUserID: senderID,
                        command: .init(operationID: .init(uuid: id), roomID: roomID, messageID: messageID, isFavorited: !conflict), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    let value: V2MessageFavorite
                    switch outcome {
                    case .applied(let favorite): #expect(!replay); value = favorite
                    case .idempotent(let favorite): #expect(replay); value = favorite
                    default: throw CancellationError()
                    }
                    #expect(value.roomID == roomID && value.messageID == messageID && value.isFavorited)
                    return value.updatedAt
                default:
                    let outcome = try await receipts.setPreferences(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: id), allowsDirectReadReceipts: conflict, allowsGroupReadReceipts: true), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    let value: V2ReadReceiptPreferences
                    switch outcome {
                    case .updated(let preferences): #expect(!replay); value = preferences
                    case .idempotent(let preferences): #expect(replay); value = preferences
                    default: throw CancellationError()
                    }
                    #expect(!value.allowsDirectReadReceipts && value.allowsGroupReadReceipts)
                    return value.updatedAt
                }
            }
            func expectFailure(_ id: UUID, at now: Date) async {
                let calls = shadow.calls
                do {
                    _ = try await invoke(id, at: now, replay: id == operation)
                    Issue.record("Expected a typed persistence timestamp error")
                } catch {
                    if kind == "receipts" { #expect(error as? V2ReadReceiptStoreError == .corruptPersistenceState) }
                    else { #expect(error as? V2ConversationCapabilitiesStoreError == .corruptPersistenceState) }
                }
                #expect(shadow.calls == calls)
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for table in ["rooms", "room_memberships", "messages", "room_events",
                    "user_room_preferences", "user_room_preference_operations", "user_message_favorites", "user_message_favorite_operations",
                    "user_read_receipt_preferences", "read_receipt_preference_operations", "read_receipt_preference_propagation_outbox",
                    "user_sync_sequences", "user_sync_log"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            #expect(try await invoke(operation, at: base) == base)
            #expect(shadow.calls == [.init(userID: senderID, sourceEventID: .init(uuid: operation), kinds: [projectionKind])])
            let initial = try await snapshot()
            for seconds in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12] {
                let invalid = Date(timeIntervalSince1970: seconds)
                let calls = shadow.calls
                #expect(try await invoke(operation, at: invalid, replay: true) == base)
                #expect(shadow.calls == calls + [.init(userID: senderID, sourceEventID: .init(uuid: operation), kinds: [projectionKind])])
                _ = try await invoke(operation, at: invalid, conflict: true)
                await expectFailure(UUID(), at: invalid)
                #expect(try await snapshot() == initial)
            }
            let table = kind == "conversation" ? "user_room_preference_operations" : kind == "favorite" ? "user_message_favorite_operations" : "read_receipt_preference_operations"
            for column in kind == "conversation" ? ["updated_at", "mute_until"] : ["updated_at"] {
                for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                    try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: literal)::timestamptz WHERE operation_id = \(bind: operation)").run()
                    let before = try await snapshot()
                    await expectFailure(operation, at: base)
                    _ = try await invoke(operation, at: base, conflict: true)
                    #expect(try await snapshot() == before)
                }
                let restored = column == "mute_until" ? base.addingTimeInterval(60) : base
                try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: restored) WHERE operation_id = \(bind: operation)").run()
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), base] {
                try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET updated_at = \(bind: date) WHERE operation_id = \(bind: operation)").run()
                let before = try await snapshot()
                #expect(try await invoke(operation, at: base, replay: true) == date)
                #expect(try await snapshot() == before)
            }
            #expect(try await snapshot() == initial)
            if kind == "receipts" { #expect(try await count("im_v2.read_receipt_preference_propagation_outbox", on: sql) == 1) }
        }
    }

    @Test("Conversation mute retries compare the exact stored PostgreSQL timestamp")
    func conversationMuteReplayPrecision() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let store = PostgresV2ConversationCapabilitiesStore(database: database)
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let epoch = Date(timeIntervalSince1970: 946_684_800)
            let dates: [Date?] = [nil, epoch, epoch.addingTimeInterval(0.00000025), epoch.addingTimeInterval(0.00000075),
                epoch.addingTimeInterval(0.00000125), epoch.addingTimeInterval(0.00000275), base.addingTimeInterval(0.1234567), base.addingTimeInterval(0.001)]
            var precisionDifferences = 0
            for muteUntil in dates {
                let operation = UUID()
                let command = try V2ConversationStateCommand(operationID: .init(uuid: operation), roomID: roomID,
                    isPinned: true, isArchived: false, muteUntil: muteUntil)
                guard case .applied = try await store.setConversationState(actorUserID: senderID, command: command, now: base) else { throw CancellationError() }
                let stored: Date?
                if muteUntil != nil {
                    stored = try #require(try await sql.raw("SELECT mute_until AS value FROM im_v2.user_room_preference_operations WHERE operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)).value
                } else { stored = nil }
                if stored != muteUntil { precisionDifferences += 1 }
                let before = try #require(try await sql.raw("SELECT jsonb_agg(to_jsonb(r) ORDER BY user_sync_sequence)::text AS value FROM im_v2.user_sync_log r WHERE user_id = \(bind: senderUUID)").first(decoding: StringValueRow.self)).value
                let expected = V2ConversationState(roomID: roomID, isPinned: true, isArchived: false, muteUntil: stored, updatedAt: base)
                #expect(try await store.setConversationState(actorUserID: senderID, command: command, now: base.addingTimeInterval(1)) == .idempotent(expected))
                #expect(try await store.setConversationState(actorUserID: senderID, command: command, now: Date(timeIntervalSince1970: .nan)) == .idempotent(expected))
                for other in [muteUntil == nil ? epoch : nil, (muteUntil ?? epoch).addingTimeInterval(0.01)] {
                    let conflict = try V2ConversationStateCommand(operationID: .init(uuid: operation), roomID: roomID,
                        isPinned: true, isArchived: false, muteUntil: other)
                    #expect(try await store.setConversationState(actorUserID: senderID, command: conflict, now: base) == .idempotencyConflict)
                }
                let after = try #require(try await sql.raw("SELECT jsonb_agg(to_jsonb(r) ORDER BY user_sync_sequence)::text AS value FROM im_v2.user_sync_log r WHERE user_id = \(bind: senderUUID)").first(decoding: StringValueRow.self)).value
                #expect(after == before)
            }
            #expect(precisionDifferences > 0)
            #expect(try await count("im_v2.user_room_preference_operations", on: sql) == Int64(dates.count))
            #expect(try await count("im_v2.user_sync_log", on: sql) == Int64(dates.count))
        }
    }

    @Test("Direct and social replays validate committed timestamps independently of the current clock",
          arguments: ["direct", "stranger", "userAdd", "relationship", "block"])
    func directSocialReplayTimestampBounds(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let direct = PostgresV2DirectMessagingStore(database: database)
            let social = PostgresV2SocialRelationshipStore(database: database)
            let profile = try forwardImportTestProfile()
            let createdRoom = RoomID(uuid: UUID()), operation = UUID()
            func invoke(_ id: UUID, at now: Date, replay: Bool = false, conflict: Bool = false) async throws -> Date? {
                let target = UserID(uuid: conflict ? memberThreeUUID : memberTwoUUID)
                switch kind {
                case "direct":
                    let outcome = try await direct.open(command: .init(actorUserID: senderID, operationID: .init(uuid: id), targetUserID: target),
                        capacityProfile: profile, roomShardID: "room-a", roomID: replay ? .init(uuid: UUID()) : createdRoom, now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    let value: V2DirectRoom
                    switch outcome {
                    case .opened(let room): #expect(!replay); value = room
                    case .idempotent(let room): #expect(replay); value = room
                    default: Issue.record("Expected a direct room result"); throw CancellationError()
                    }
                    #expect(value.roomID == createdRoom && value.actorUserID == senderID && value.targetUserID == target)
                    return value.createdAt
                case "stranger":
                    let outcome = try await direct.setStrangerMessagePermission(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: id), permission: conflict ? .allow : .deny), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    switch outcome {
                    case .updated(let permission, let date): #expect(!replay && permission == .deny); return date
                    case .idempotent(let permission, let date): #expect(replay && permission == .deny); return date
                    default: Issue.record("Expected a stranger preference result"); throw CancellationError()
                    }
                case "userAdd":
                    let outcome = try await direct.setUserAddPermission(command: .init(actorUserID: senderID,
                        operationID: .init(uuid: id), permission: conflict ? .allow : .deny), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    switch outcome {
                    case .updated(let permission, let date): #expect(!replay && permission == .deny); return date
                    case .idempotent(let permission, let date): #expect(replay && permission == .deny); return date
                    default: Issue.record("Expected a user-add preference result"); throw CancellationError()
                    }
                case "relationship":
                    let outcome = try await social.changeRelationship(.init(actorUserID: senderID, operationID: .init(uuid: id),
                        targetUserID: target, action: .request), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    let value: V2RelationshipChange
                    switch outcome {
                    case .changed(let change): #expect(!replay); value = change
                    case .idempotent(let change): #expect(replay); value = change
                    default: Issue.record("Expected a relationship result"); throw CancellationError()
                    }
                    #expect(value.actorUserID == senderID && value.targetUserID == target && value.action == .request && value.resultingState == .pending)
                    return value.updatedAt
                default:
                    let outcome = try await social.changeUserBlock(.init(actorUserID: senderID, operationID: .init(uuid: id),
                        targetUserID: target, action: .block), now: now)
                    if conflict { #expect(outcome == .idempotencyConflict); return nil }
                    let value: V2UserBlockChange
                    switch outcome {
                    case .changed(let change): #expect(!replay); value = change
                    case .idempotent(let change): #expect(replay); value = change
                    default: Issue.record("Expected a block result"); throw CancellationError()
                    }
                    #expect(value.actorUserID == senderID && value.targetUserID == target && value.action == .block && value.isBlocked)
                    return value.updatedAt
                }
            }
            func expectFailure(_ id: UUID, at now: Date) async {
                do {
                    _ = try await invoke(id, at: now, replay: id == operation)
                    Issue.record("Expected a typed timestamp error")
                } catch {
                    if kind == "relationship" || kind == "block" {
                        #expect(error as? V2SocialRelationshipStoreError == .corruptPersistenceState)
                    } else {
                        #expect(error as? V2DirectMessagingStoreError == .corruptPersistenceState)
                    }
                }
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                // The fixture discards shadow forwarding; compare all primary
                // business state and projection records across failed/replayed work.
                for table in ["rooms", "room_memberships", "room_admission", "shard_admission_pools", "direct_room_pairs",
                    "direct_room_operations", "user_stranger_message_preferences", "stranger_message_preference_operations",
                    "user_add_preferences", "user_add_preference_operations", "user_relationships", "user_relationship_operations",
                    "user_blocks", "user_block_operations", "user_direct_send_policy_versions", "user_sync_sequences", "user_sync_log"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    result.append(try #require(row).value)
                }
                return result
            }
            #expect(try await invoke(operation, at: base) == base)
            let initial = try await snapshot()
            for seconds in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12] {
                let bad = Date(timeIntervalSince1970: seconds)
                #expect(try await invoke(operation, at: bad, replay: true) == base)
                _ = try await invoke(operation, at: bad, conflict: true)
                await expectFailure(UUID(), at: bad)
                #expect(try await snapshot() == initial)
            }
            let table: String
            switch kind {
            case "direct": table = "direct_room_operations"
            case "stranger": table = "stranger_message_preference_operations"
            case "userAdd": table = "user_add_preference_operations"
            case "relationship": table = "user_relationship_operations"
            default: table = "user_block_operations"
            }
            let column = kind == "direct" ? "created_at" : "updated_at"
            for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: literal)::timestamptz WHERE operation_id = \(bind: operation)").run()
                let before = try await snapshot()
                await expectFailure(operation, at: base)
                _ = try await invoke(operation, at: base, conflict: true)
                #expect(try await snapshot() == before)
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), base] {
                try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: date) WHERE operation_id = \(bind: operation)").run()
                let before = try await snapshot()
                #expect(try await invoke(operation, at: base, replay: true) == date)
                #expect(try await snapshot() == before)
            }
            #expect(try await snapshot() == initial)
        }
    }

    @Test("Direct receipts commit owner outboxes and resolve control privacy across databases", arguments: [false, true])
    func directReceiptOwnerOutbox(batch: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { ownerDB, controlDB, ownerSQL, controlSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let room = RoomID(uuid: UUID())
            let profile = try forwardImportTestProfile()
            guard case .opened = try await PostgresV2DirectMessagingStore(database: ownerDB).open(
                command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)),
                capacityProfile: profile, roomShardID: "room-a", roomID: room, now: now) else { throw CancellationError() }
            let sender = V2SendMessageService(store: PostgresV2RoomWriteStore(database: ownerDB), capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { now })
            guard case .accepted = try await sender.send(.init(roomID: room, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "read me")) else { throw CancellationError() }
            let store = PostgresV2ReadReceiptStore(database: ownerDB)
            let command = try V2RecordReadReceiptCommand(roomID: room, actorUserID: senderID,
                operationID: .init(uuid: UUID()), readThroughRoomSequence: 1)
            await #expect(throws: V2ReadReceiptStoreError.ownerChanged) {
                _ = try await store.recordOwnerValidated(command: command, ownerRoute: .init(shardID: "room-a", epoch: 99), now: now)
            }
            try await controlSQL.raw("""
                INSERT INTO im_v2.room_owner_routes(room_id, room_shard_id, route_epoch, created_at, updated_at)
                VALUES (\(bind: room.uuidValue!), 'room-a', 0, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at
                """).run()
            try await controlSQL.raw("""
                INSERT INTO im_v2.user_read_receipt_preferences(user_id, allows_direct_read_receipts, preference_revision, updated_at)
                VALUES (\(bind: memberTwoUUID), false, 1, \(bind: now))
                """).run()
            let routed = try V2RoutedReadReceiptStore(router: V2PostgresRoomShardRouter(database: controlDB),
                ownerStores: ["room-a": store], controlStore: PostgresV2ReadReceiptStore(database: controlDB))
            let outcome: V2ReadReceiptOutcome
            if batch {
                let results = try await routed.recordBatch([.init(command: command, now: now)])
                guard case .success(let result) = results.first else { throw CancellationError() }
                outcome = result
            } else { outcome = try await routed.record(command: command, now: now) }
            guard case .recorded(let saved) = outcome else { throw CancellationError() }
            #expect(try await routed.record(command: command, now: now) == .idempotent(saved))
            let noChange = try V2RecordReadReceiptCommand(roomID: room, actorUserID: senderID,
                operationID: .init(uuid: UUID()), readThroughRoomSequence: 1)
            _ = try await routed.record(command: noChange, now: now)
            try await withThrowingTaskGroup(of: Void.self) { group in
                for _ in 0..<8 {
                    group.addTask {
                        let concurrent = try V2RecordReadReceiptCommand(roomID: room, actorUserID: senderID,
                            operationID: .init(uuid: UUID()), readThroughRoomSequence: 1)
                        _ = try await routed.record(command: concurrent, now: now)
                    }
                }
                try await group.waitForAll()
            }
            #expect(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.user_state_event_outbox WHERE projection_kind IN ('own_read_watermark', 'direct_read_receipt')").first(decoding: CountRow.self)?.value == 2)
            #expect(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.user_sync_log WHERE projection_kind IN ('own_read_watermark', 'direct_read_receipt')").first(decoding: CountRow.self)?.value == 0)
            #expect(try await controlSQL.raw("SELECT count(*) AS value FROM im_v2.rooms WHERE room_id = \(bind: room.uuidValue!)").first(decoding: CountRow.self)?.value == 0)
            let secondary = try #require(Environment.get("IMV2_POSTGRES_TEST_SECONDARY_DATABASE_URL"))
            try await withUserEventDatabase(databaseURL: secondary) { targetDB, targetSQL, targetSchema in
                struct Fence: V2UserShardRouteFencing {
                    let database: any Database
                    func withCurrentRoute<Result: Sendable>(for userID: UserID,
                        _ operation: @escaping @Sendable (V2UserShardRoute, any Database) async throws -> Result) async throws -> Result {
                        try await database.transaction { transaction in
                            try await operation(.init(bucket: "user", observedRouterEpoch: 1), transaction)
                        }
                    }
                }
                let projector = try V2RoutedUserStateEventProjector(routeFence: Fence(database: controlDB),
                    registry: V2StaticUserShardStorageRegistry(locations: [.init(bucket: "user", database: targetDB, schema: targetSchema)]))
                let outbox = try PostgresV2UserStateEventOutbox(database: ownerDB)
                let leases = try await outbox.claim(now: now.addingTimeInterval(1), leaseDuration: 30, limit: 100)
                    .filter { $0.event.kind == .ownReadWatermark || $0.event.kind == .directReadReceipt }
                #expect(leases.count == 2)
                for lease in leases {
                    let sequence = try await projector.project(lease.event)
                    #expect(try await projector.project(lease.event) == sequence)
                    #expect(try await outbox.acknowledge(lease, sequence: sequence, now: now.addingTimeInterval(2)))
                }
                #expect(try await targetSQL.raw("""
                    SELECT count(*) AS value FROM \(unsafeRaw: targetSchema).user_sync_log
                    WHERE projection_kind = 'direct_read_receipt' AND payload->>'is_visible' = 'false'
                      AND payload->>'viewer_preference_revision' = '1'
                    """).first(decoding: CountRow.self)?.value == 1)
                #expect(try await targetSQL.raw("SELECT count(*) AS value FROM \(unsafeRaw: targetSchema).user_sync_log WHERE projection_kind = 'own_read_watermark'").first(decoding: CountRow.self)?.value == 1)
            }
        }
    }

    @Test("Receipt policy propagation uses the control directory and survives reenable before delivery")
    func readReceiptPolicyDirectoryPropagation() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { controlDB, _, controlSQL, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let rooms = [UUID(), UUID()]
            for (room, peer) in zip(rooms, [memberTwoUUID, memberThreeUUID]) {
                try await controlSQL.raw("""
                    INSERT INTO im_v2.direct_room_owner_routes
                        (lower_user_id, higher_user_id, room_id, room_shard_id, created_at, updated_at)
                    VALUES (LEAST(\(bind: senderUUID)::text, \(bind: peer)::text)::uuid,
                            GREATEST(\(bind: senderUUID)::text, \(bind: peer)::text)::uuid,
                            \(bind: room), 'room-a', \(bind: now), \(bind: now))
                    """).run()
            }
            let preferences = PostgresV2ReadReceiptStore(database: controlDB)
            _ = try await preferences.setPreferences(command: .init(actorUserID: senderID, operationID: .init(uuid: UUID()),
                allowsDirectReadReceipts: false, allowsGroupReadReceipts: true), now: now)
            let worker = V2ReadReceiptPreferencePropagationWorker(database: controlDB, now: { now })
            #expect(try await worker.runOnce(limit: 1) == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 0))
            #expect(try await worker.runOnce(limit: 1) == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 1))
            #expect(try await worker.runOnce(limit: 1).claimedOperationCount == 0)
