    @Test("Registration samples its write clock after both uniqueness locks", arguments: ["account", "public"])
    func passwordRegistrationLockClock(lockKind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let clock = TestSequenceClock([Date(timeIntervalSince1970: 1_750_000_000)])
            let store = V2PostgresPasswordAccountStore(database: database, now: { clock.now() })
            let pending = Mutex<Task<UserID, any Error>?>(nil)
            do {
                let task = try await database.transaction { transaction in
                    guard let held = transaction as? any SQLDatabase else { throw V2PasswordAccountStoreError.unavailable }
                    let key = lockKind == "account" ? "v2-account:clock-lock" : "v2-public-handle:clock_lock"
                    try await held.raw("SELECT pg_advisory_xact_lock(hashtextextended(\(bind: key), 0))").run()
                    let task = Task {
                        try await store.register(accountHandle: "clock-lock", passwordHash: V2PasswordHashPolicy.dummyDigest,
                            publicHandle: "clock_lock", displayName: "Clock lock fixture", deviceID: DeviceID(uuid: UUID()))
                    }
                    pending.withLock { $0 = task }
                    var waiting = false
                    for _ in 0..<200 {
                        let row = try await held.raw("SELECT count(*)::bigint AS value FROM pg_locks WHERE NOT granted AND locktype='advisory' AND database=(SELECT oid FROM pg_database WHERE datname=current_database())").first(decoding: CountRow.self)
                        if (row?.value ?? 0) > 0 { waiting = true; break }
                        try await Task.sleep(for: .milliseconds(10))
                    }
                    #expect(waiting)
                    clock.set([Date(timeIntervalSince1970: .nan)])
                    return task
                }
                await #expect(throws: V2PasswordAccountStoreError.unavailable) { try await task.value }
            } catch {
                // The outer transaction has released its lock; always join the child.
                if let task = pending.withLock({ $0 }) { _ = await task.result }
                throw error
            }
            #expect(try await count("im_v2.account_password_credentials", on: sql) == 0)
            #expect(try await count("im_v2.public_user_profiles WHERE public_handle='clock_lock'", on: sql) == 0)
            #expect(try await count("im_v2.account_password_authentication_audit", on: sql) == 0)
        }
    }

    @Test("Session mutation clocks roll back every stage and preserve normal operation replay", arguments: ["current", "remote", "others"])
    func sessionMutationClockBounds(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let clock = TestSequenceClock([base])
            let service = V2PostgresDeviceSessionService(database: database, now: { clock.now() })
            let devices = [UUID(), UUID(), UUID()]
            let current = DeviceID(uuid: devices[0]), remote = DeviceID(uuid: devices[1])
            let operation = UUID()
            func seed(user: UUID, devices: [UUID], at: Date) async throws {
                for device in devices {
                    // Device metadata and inert local endpoint fixtures; no credentials are issued.
                    try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at) VALUES (\(bind: user), \(bind: device), \(bind: at), \(bind: at), \(bind: at.addingTimeInterval(1)))").run()
                    try await sql.raw("INSERT INTO im_v2.push_device_endpoints (device_id, provider, environment, endpoint_generation, encrypted_token, updated_at) VALUES (\(bind: device), 'apns', 'development', \(bind: UUID()), 'sealed-local-fixture', \(bind: at))").run()
                }
            }
            try await seed(user: senderUUID, devices: devices, at: base)
            @Sendable func mutate(user: UserID, current: DeviceID, remote: DeviceID, operation: UUID) async throws -> V2DeviceSessionMutationOutcome {
                switch kind {
                case "current": return try await service.revokeCurrentDevice(actorUserID: user, currentDeviceID: current, operationID: operation)
                case "remote": return try await service.revokeDevice(actorUserID: user, currentDeviceID: current, targetDeviceID: remote, operationID: operation)
                default: return try await service.revokeOtherDevices(actorUserID: user, currentDeviceID: current, operationID: operation)
                }
            }
            @Sendable func apply() async throws -> V2DeviceSessionMutationOutcome {
                try await mutate(user: senderID, current: current, remote: remote, operation: operation)
            }
            func snapshot() async throws -> String {
                let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'devices', (SELECT jsonb_agg(to_jsonb(r) ORDER BY device_id) FROM im_v2.auth_devices r),
                        'endpoints', (SELECT jsonb_agg(to_jsonb(r) ORDER BY device_id) FROM im_v2.push_device_endpoints r),
                        'events', (SELECT jsonb_agg(to_jsonb(r) ORDER BY event_id) FROM im_v2.device_revocation_events r),
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY actor_user_id, operation_id) FROM im_v2.device_session_operations r),
                        'access_count', (SELECT count(*) FROM im_v2.device_access_tokens),
                        'refresh_count', (SELECT count(*) FROM im_v2.device_refresh_sessions)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)
                guard let row else { throw V2DeviceSessionServiceError.malformedPersistence }
                return row.value
            }
            let initial = try await snapshot()
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let clockReads = kind == "remote" ? 3 : 2
            for bad in badDates {
                for stage in 0..<clockReads {
                    clock.set(Array(repeating: base, count: stage) + [bad])
                    await #expect(throws: V2DeviceSessionServiceError.unavailable) { try await apply() }
                    #expect(try await snapshot() == initial)
                }
                await #expect(throws: V2DeviceSessionServiceError.unavailable) { try await V2PostgresDeviceSessionService.revokeSession(sql, userID: senderUUID, deviceID: devices[1], at: bad) }
                #expect(try await snapshot() == initial)
            }
            clock.set([base])
            try await sql.raw("CREATE FUNCTION im_v2.test_session_clock_operation_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'local session operation failure'; END $$").run()
            try await sql.raw("CREATE TRIGGER test_session_clock_operation_failure BEFORE INSERT ON im_v2.device_session_operations FOR EACH ROW EXECUTE FUNCTION im_v2.test_session_clock_operation_failure()").run()
            await #expect(throws: (any Error).self) { try await apply() }
            #expect(try await snapshot() == initial)
            try await sql.raw("DROP TRIGGER test_session_clock_operation_failure ON im_v2.device_session_operations").run()
            clock.set([base.addingTimeInterval(-30)])
            let outcomes = try await withThrowingTaskGroup(of: V2DeviceSessionMutationOutcome.self) { group in
                for _ in 0..<8 { group.addTask { try await apply() } }
                var results: [V2DeviceSessionMutationOutcome] = []
                for try await result in group { results.append(result) }
                return results
            }
            #expect(outcomes.filter { $0 == .applied }.count == 1)
            #expect(outcomes.filter { $0 == .idempotent }.count == 7)
            let expectedCount: Int64 = kind == "others" ? 2 : 1
            #expect(try await count("im_v2.device_revocation_events", on: sql) == expectedCount)
            #expect(try await count("im_v2.device_session_operations", on: sql) == 1)
            #expect(try await count("im_v2.auth_devices WHERE revoked_at IS NOT NULL", on: sql) == expectedCount)
            #expect(try await count("im_v2.push_device_endpoints WHERE disabled_at IS NOT NULL", on: sql) == expectedCount)
            let committed = try await snapshot()
            for bad in badDates {
                // Current-device replay needs no fresh write. Other operations retain
                // the existing current-device check, then replay without reading a write clock.
                clock.set(kind == "current" ? [bad] : [base, bad])
                #expect(try await apply() == .idempotent)
                #expect(try await snapshot() == committed)
            }
            let expectedDevices = kind == "current" ? [devices[0]] : kind == "remote" ? [devices[1]] : [devices[1], devices[2]]
            struct DeviceState: Decodable { let deviceID: UUID; let revokedAt: Date?; let disabledAt: Date?
                enum CodingKeys: String, CodingKey { case deviceID = "device_id", revokedAt = "revoked_at", disabledAt = "disabled_at" }
            }
            let state = try await sql.raw("SELECT device.device_id, device.revoked_at, endpoint.disabled_at FROM im_v2.auth_devices device JOIN im_v2.push_device_endpoints endpoint USING (device_id) WHERE device.user_id = \(bind: senderUUID)").all(decoding: DeviceState.self)
            for device in state {
                let expected = expectedDevices.contains(device.deviceID) ? base.addingTimeInterval(-30) : nil
                #expect(device.revokedAt == expected)
                #expect(device.disabledAt == expected)
            }
            for valid in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)] {
                let user = UserID(uuid: UUID()), boundaryDevices = [UUID(), UUID(), UUID()]
                try await seed(user: user.uuidValue!, devices: boundaryDevices, at: valid)
                clock.set([valid])
                #expect(try await mutate(user: user, current: .init(uuid: boundaryDevices[0]), remote: .init(uuid: boundaryDevices[1]), operation: UUID()) == .applied)
                let dates = try await sql.raw("SELECT created_at AS value FROM im_v2.device_session_operations WHERE actor_user_id = \(bind: user.uuidValue!) UNION ALL SELECT created_at AS value FROM im_v2.device_revocation_events WHERE user_id = \(bind: user.uuidValue!)").all(decoding: RevocationClockDateRow.self)
                #expect(dates.count == Int(expectedCount) + 1)
                #expect(dates.allSatisfy { $0.value == valid })
            }
        }
    }

    @Test("Session inventory clocks reject unsafe queries and preserve normal pagination")
    func sessionInventoryClockBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let clock = TestSequenceClock([base])
            let service = V2PostgresDeviceSessionService(database: database, now: { clock.now() })
            let devices = [UUID(), UUID(), UUID()].sorted { $0.uuidString < $1.uuidString }
            for (index, device) in devices.enumerated() {
                let activeAt = base.addingTimeInterval(index == 2 ? -1 : 0)
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at, display_name, platform) VALUES (\(bind: senderUUID), \(bind: device), \(bind: base.addingTimeInterval(-60)), \(bind: activeAt), \(bind: base.addingTimeInterval(60)), 'Local test device', 'test')").run()
            }
            func snapshot() async throws -> String {
                let row = try await sql.raw("SELECT jsonb_agg(to_jsonb(d) ORDER BY device_id)::text AS value FROM im_v2.auth_devices d").first(decoding: StringValueRow.self)
                guard let row else { throw V2DeviceSessionServiceError.malformedPersistence }
                return row.value
            }
            let first = try await service.sessions(for: senderID, cursor: nil, pageSize: 1)
            #expect(first.sessions.map(\.deviceID.uuidValue) == [devices[0]])
            let cursor = try #require(first.nextCursor)
            let initial = try await snapshot()
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for bad in badDates {
                clock.set([bad])
                for value in [nil, Optional(cursor)] {
                    await #expect(throws: V2DeviceSessionServiceError.unavailable) { try await service.sessions(for: senderID, cursor: value, pageSize: 1) }
                }
                #expect(try await snapshot() == initial)
            }
            clock.set([base])
            struct LegacyCursor: Encodable { let lastActiveAt: Date; let deviceID: UUID }
            for bad in badDates where bad.timeIntervalSinceReferenceDate.isFinite {
                let stale = try JSONEncoder().encode(LegacyCursor(lastActiveAt: bad, deviceID: devices[0])).base64EncodedString()
                await #expect(throws: V2DeviceSessionServiceError.invalidRequest) { try await service.sessions(for: senderID, cursor: stale, pageSize: 1) }
                #expect(try await snapshot() == initial)
            }
            struct ExactCursor: Encodable { let lastActiveAt: Date; let deviceID: UUID; let lastActiveAtMicroseconds: Int64 }
            for microseconds: Int64 in [.min, .max, -211_813_488_000_000_001, 9_223_371_331_200_000_000] {
                let invalid = try JSONEncoder().encode(ExactCursor(lastActiveAt: base, deviceID: devices[0], lastActiveAtMicroseconds: microseconds)).base64EncodedString()
                await #expect(throws: V2DeviceSessionServiceError.invalidRequest) { try await service.sessions(for: senderID, cursor: invalid, pageSize: 1) }
                #expect(try await snapshot() == initial)
            }
            for size in [Int.min, -1, 0, 101, Int.max] {
                await #expect(throws: V2DeviceSessionServiceError.invalidRequest) { try await service.sessions(for: senderID, cursor: nil, pageSize: size) }
            }
            // A normal backwards clock adjustment preserves order and equal-time peers.
            clock.set([base.addingTimeInterval(-30)])
            let second = try await service.sessions(for: senderID, cursor: cursor, pageSize: 1)
            #expect(second.sessions.map(\.deviceID.uuidValue) == [devices[1]])
            let last = try await service.sessions(for: senderID, cursor: second.nextCursor, pageSize: 1)
            #expect(last.sessions.map(\.deviceID.uuidValue) == [devices[2]])
            #expect(last.nextCursor == nil)
            clock.set([base.addingTimeInterval(60)])
            #expect(try await service.sessions(for: senderID, cursor: nil, pageSize: 1).sessions.isEmpty)
            clock.set([base])
            #expect(try await snapshot() == initial)
            for column in ["created_at", "last_active_at"] {
                for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                    try await sql.raw("UPDATE im_v2.auth_devices SET \(unsafeRaw: column) = \(bind: literal)::timestamptz WHERE device_id = \(bind: devices[0])").run()
                    let before = try await snapshot()
                    await #expect(throws: V2DeviceSessionServiceError.malformedPersistence) { try await service.sessions(for: senderID, cursor: nil, pageSize: 100) }
                    #expect(try await snapshot() == before)
                }
                let restored = column == "created_at" ? base.addingTimeInterval(-60) : base
                try await sql.raw("UPDATE im_v2.auth_devices SET \(unsafeRaw: column) = \(bind: restored) WHERE device_id = \(bind: devices[0])").run()
            }
            #expect(try await snapshot() == initial)
            for valid in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)] {
                let user = UserID(uuid: UUID())
                let boundDevices = [UUID(), UUID()].sorted { $0.uuidString < $1.uuidString }
                for device in boundDevices {
                    try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at) VALUES (\(bind: user.uuidValue!), \(bind: device), \(bind: valid), \(bind: valid), \(bind: valid.addingTimeInterval(1)))").run()
                }
                clock.set([valid])
                let head = try await service.sessions(for: user, cursor: nil, pageSize: 1)
                #expect(head.sessions.first?.createdAt == valid)
                #expect(head.sessions.first?.lastActiveAt == valid)
                let tail = try await service.sessions(for: user, cursor: head.nextCursor, pageSize: 1)
                #expect(head.sessions.map(\.deviceID.uuidValue) + tail.sessions.map(\.deviceID.uuidValue) == boundDevices.map(Optional.some))
                #expect(tail.nextCursor == nil)
            }
        }
    }

    @Test("Session inventory pagination preserves microsecond ties", arguments: ["2000-01-01 00:00:00.000001+00", "2025-06-15 15:06:40.123456+00"])
    func sessionInventoryCursorPrecision(timestamp: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let devices = [UUID(), UUID(), UUID()].sorted { $0.uuidString < $1.uuidString }
            for device in devices {
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at) VALUES (\(bind: senderUUID), \(bind: device), \(bind: base.addingTimeInterval(-60)), \(bind: timestamp)::timestamptz, \(bind: base.addingTimeInterval(60)))").run()
            }
            let service = V2PostgresDeviceSessionService(database: database, now: { base })
            var cursor: String?
            var seen: [UUID] = []
            for _ in 0..<4 {
                let page = try await service.sessions(for: senderID, cursor: cursor, pageSize: 1)
                seen.append(contentsOf: page.sessions.compactMap(\.deviceID.uuidValue))
                cursor = page.nextCursor
                if cursor == nil { break }
            }
            #expect(seen == devices)
            #expect(cursor == nil)
            struct LegacyCursor: Encodable { let lastActiveAt: Date; let deviceID: UUID }
            let first = try await service.sessions(for: senderID, cursor: nil, pageSize: 1)
            let firstSession = try #require(first.sessions.first)
            let legacy = try JSONEncoder().encode(LegacyCursor(lastActiveAt: firstSession.lastActiveAt, deviceID: devices[0])).base64EncodedString()
            await #expect(throws: V2DeviceSessionServiceError.invalidRequest) {
                _ = try await service.sessions(for: senderID, cursor: legacy, pageSize: 1)
            }
            let second = try await service.sessions(for: senderID, cursor: first.nextCursor, pageSize: 1)
            #expect(second.sessions.map(\.deviceID.uuidValue) == [devices[1]])
        }
    }

    @Test("Local forwarding clocks isolate failed pairs and preserve durable retries", arguments: [false, true])
    func localForwardClockBounds(ownerValidated: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let clock = TestSequenceClock([base])
            let profile = try forwardImportTestProfile(), limits = try V2MessageCommandLimits(maxUTF8Bytes: 64)
            let write = PostgresV2RoomWriteStore(database: database)
            let sender = V2SendMessageService(store: write, capacityProfile: profile, limits: limits, now: { base })
            guard case .accepted(let source) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "forward clock")) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            let reference = try V2ForwardMessageReference(roomID: roomID, messageID: source.messageID, revision: .init(1))
            let command = try V2ForwardMessagesCommand(operationID: .init(uuid: UUID()), sources: [reference], targetRoomIDs: [roomID])
            let service = V2ForwardMessagesService(database: database, writeStore: write, capacityProfile: profile, limits: limits, now: { clock.now() })
            @Sendable func forward(_ command: V2ForwardMessagesCommand) async throws -> [V2ForwardMessageResult] {
                if ownerValidated {
                    return try await service.forwardOwnerValidated(actorUserID: senderID, command: command, ownerRoutes: [roomID: .init(shardID: "room-a", epoch: 0)])
                }
                return try await service.forward(actorUserID: senderID, command: command)
            }
            func snapshot(includeOperations: Bool = true) async throws -> String {
                let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'operations', CASE WHEN \(bind: includeOperations) THEN (SELECT jsonb_agg(to_jsonb(r) ORDER BY actor_user_id, operation_id, source_message_id, target_room_id) FROM im_v2.message_forward_operations r) END,
                        'messages', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.messages r),
                        'events', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id, room_sequence) FROM im_v2.room_events r),
                        'rooms', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.rooms r),
                        'room_admission', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.room_admission r),
                        'shard_admission', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_shard_id, capacity_profile_id) FROM im_v2.shard_admission_pools r),
                        'completions', (SELECT jsonb_agg(to_jsonb(r) ORDER BY sender_user_id, client_message_id) FROM im_v2.message_send_completions r)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)
                guard let row else { throw V2RoomWriteStoreError.corruptPersistenceState }
                return row.value
            }
            let unavailable = try V2ForwardMessageResult(sourceMessageID: source.messageID, targetRoomID: roomID, messageID: nil, roomSequence: nil, errorCode: "UNAVAILABLE")
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let initial = try await snapshot()
            for bad in badDates {
                clock.set([bad])
                #expect(try await forward(command) == [unavailable])
                #expect(try await snapshot() == initial)
            }
            // The staging transaction succeeds, then the acceptance clock becomes invalid.
            let initialBusiness = try await snapshot(includeOperations: false)
            clock.set([base, badDates[0]])
            #expect(try await forward(command) == [unavailable])
            #expect(try await count("im_v2.message_forward_operations WHERE result_message_id IS NULL", on: sql) == 1)
            #expect(try await snapshot(includeOperations: false) == initialBusiness)
            let staged = try await snapshot()
            let invalidAcceptanceDates = badDates + [Date(timeIntervalSince1970: -1), Date(timeIntervalSince1970: 281_474_976_710.656), Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)]
            for bad in invalidAcceptanceDates {
                clock.set([bad])
                #expect(try await forward(command) == [unavailable])
                #expect(try await snapshot() == staged)
            }
            // A recovered clock and concurrent normal retries accept exactly one message.
            clock.set([base.addingTimeInterval(-30)])
            let recovered = try await withThrowingTaskGroup(of: [V2ForwardMessageResult].self) { group in
                for _ in 0..<8 { group.addTask { try await forward(command) } }
                var results: [[V2ForwardMessageResult]] = []
                for try await result in group { results.append(result) }
                return results
            }
            let accepted = try #require(recovered.first)
            #expect(accepted.count == 1)
            #expect(accepted.first?.errorCode == nil)
            #expect(accepted.first?.messageID != nil)
            #expect(recovered.allSatisfy { $0 == accepted })
            #expect(try await count("im_v2.messages", on: sql) == 2)
            #expect(try await count("im_v2.message_forward_operations WHERE result_message_id IS NOT NULL", on: sql) == 1)
            let committed = try await snapshot()
            for bad in badDates {
                clock.set([bad])
                #expect(try await forward(command) == accepted)
                #expect(try await snapshot() == committed)
            }

            guard case .accepted(let secondSource) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "second clock source")) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            let secondReference = try V2ForwardMessageReference(roomID: roomID, messageID: secondSource.messageID, revision: .init(1))
            let multi = try V2ForwardMessagesCommand(operationID: .init(uuid: UUID()), sources: [reference, secondReference], targetRoomIDs: [roomID])
            clock.set([badDates[0], base, base])
            let partial = try await forward(multi)
            #expect(partial.count == 2)
            #expect(partial.first == unavailable)
            #expect(partial.last?.sourceMessageID == secondSource.messageID)
            #expect(partial.last?.messageID != nil)
            #expect(partial.last?.errorCode == nil)
            #expect(try await count("im_v2.messages", on: sql) == 4)
            clock.set([base])
            let completed = try await forward(multi)
            #expect(completed.count == 2)
            #expect(completed.allSatisfy { $0.errorCode == nil && $0.messageID != nil })
            #expect(completed.last == partial.last)
            #expect(try await count("im_v2.messages", on: sql) == 5)

            // An accepted message also survives a failed result-marker transaction.
            let interrupted = try V2ForwardMessagesCommand(operationID: .init(uuid: UUID()), sources: [reference], targetRoomIDs: [roomID])
            try await sql.raw("CREATE FUNCTION im_v2.test_forward_clock_result_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'local forward result write failure'; END $$").run()
            try await sql.raw("CREATE TRIGGER test_forward_clock_result_failure BEFORE UPDATE ON im_v2.message_forward_operations FOR EACH ROW EXECUTE FUNCTION im_v2.test_forward_clock_result_failure()").run()
            #expect(try await forward(interrupted) == [unavailable])
            #expect(try await count("im_v2.messages", on: sql) == 6)
            #expect(try await count("im_v2.message_forward_operations WHERE result_message_id IS NULL", on: sql) == 1)
            try await sql.raw("DROP TRIGGER test_forward_clock_result_failure ON im_v2.message_forward_operations").run()
            clock.set([badDates[0]])
            let repaired = try await forward(interrupted)
            #expect(repaired.first?.messageID != nil)
            #expect(repaired.first?.errorCode == nil)
            #expect(try await count("im_v2.messages", on: sql) == 6)
            #expect(try await count("im_v2.message_forward_operations WHERE result_message_id IS NULL", on: sql) == 0)

            // Staging accepts the full finite PostgreSQL range, independently of message acceptance.
            for valid in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)] {
                let boundary = try V2ForwardMessagesCommand(operationID: .init(uuid: UUID()), sources: [reference], targetRoomIDs: [roomID])
                clock.set([valid, badDates[0]])
                #expect(try await forward(boundary) == [unavailable])
                let row = try await sql.raw("SELECT created_at AS value FROM im_v2.message_forward_operations WHERE operation_id = \(bind: boundary.operationID.uuidValue!)").first(decoding: RevocationClockDateRow.self)
                #expect(row?.value == valid)
                #expect(try await count("im_v2.messages", on: sql) == 6)
            }
            clock.set([base])
            // New ordinary traffic remains usable after every invalid-clock path above.
            let normal = try V2ForwardMessagesCommand(operationID: .init(uuid: UUID()), sources: [reference], targetRoomIDs: [roomID])
            let result = try await forward(normal)
            #expect(result.first?.messageID != nil)
            #expect(result.first?.errorCode == nil)
            #expect(try await count("im_v2.messages", on: sql) == 7)
        }
    }

    @Test("Revocation cursor clocks preserve startup watermarks and replay cleanup after failed acknowledgement")
    func revocationCursorClockBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let clock = TestSequenceClock([base])
            let gatewayStore = V2PostgresDeviceRevocationEventStore(database: database)
            let cleanupStore = V2PostgresDeviceRevocationEventStore.projectionCleanup(database: database)
            let cleaner = V2PostgresRevokedDeviceProjectionStore(database: database)
            let node = "cluster"
            let users = [senderUUID, memberTwoUUID, memberThreeUUID]
            let devices = [UUID(), UUID(), UUID()]
            for index in 0..<3 {
                // Ordinary local device metadata; no access or refresh credentials are issued.
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, revoked_at) VALUES (\(bind: users[index]), \(bind: devices[index]), \(bind: base), \(bind: base), \(bind: base))").run()
                try await sql.raw("INSERT INTO im_v2.device_sync_cursors (user_id, device_id, state, reset_generation, acknowledged_sequence) VALUES (\(bind: users[index]), \(bind: devices[index]), 'ready', 1, 7)").run()
            }
            for index in 0..<2 {
                try await sql.raw("INSERT INTO im_v2.device_revocation_events (user_id, device_id, created_at) VALUES (\(bind: users[index]), \(bind: devices[index]), \(bind: base))").run()
            }
            let events = try await gatewayStore.events(afterCursorFor: node, limit: 8)
            #expect(events.count == 2)
            let first = try #require(events.first)
            let last = try #require(events.last)
            func cursorSnapshot() async throws -> String {
                let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY worker_name, node_id), '[]'::jsonb)::text AS value FROM im_v2.gateway_worker_cursors c").first(decoding: StringValueRow.self)
                guard let row else { throw V2GatewayAuthenticationError.corruptPersistenceState }
                return row.value
            }
            func projectionSnapshot() async throws -> String {
                let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'tombstones', (SELECT jsonb_agg(to_jsonb(t) ORDER BY user_id, device_id) FROM im_v2.revoked_device_projection_tombstones t),
                        'cursors', (SELECT jsonb_agg(to_jsonb(c) ORDER BY user_id, device_id) FROM im_v2.device_sync_cursors c)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)
                guard let row else { throw V2GatewayAuthenticationError.corruptPersistenceState }
                return row.value
            }
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let initialCursors = try await cursorSnapshot()
            let initialProjections = try await projectionSnapshot()
            for bad in invalidDates {
                for store in [gatewayStore, cleanupStore] {
                    await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.initializeCursorIfNeeded(nodeID: node, now: bad) }
                    await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.initializeCursorAtBeginningIfNeeded(nodeID: node, now: bad) }
                    await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.markProcessed(eventID: first.eventID, nodeID: node, now: bad) }
                }
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await cleaner.clean(userID: first.userID, deviceID: first.deviceID, revokedAt: bad) }
                #expect(try await cursorSnapshot() == initialCursors)
                #expect(try await projectionSnapshot() == initialProjections)
            }
            try await gatewayStore.initializeCursorIfNeeded(nodeID: node, now: base)
            // A cursor in the gateway namespace cannot satisfy cleanup initialization.
            await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await cleanupStore.initializeCursorAtBeginningIfNeeded(nodeID: node, now: invalidDates[0]) }
            try await cleanupStore.initializeCursorAtBeginningIfNeeded(nodeID: node, now: base)
            #expect(try await gatewayStore.events(afterCursorFor: node, limit: 8).isEmpty)
            #expect(try await cleanupStore.events(afterCursorFor: node, limit: 8) == events)
            let initializedCursors = try await cursorSnapshot()
            for bad in invalidDates {
                for store in [gatewayStore, cleanupStore] {
                    try await store.initializeCursorIfNeeded(nodeID: node, now: bad)
                    try await store.initializeCursorAtBeginningIfNeeded(nodeID: node, now: bad)
                    await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.markProcessed(eventID: last.eventID, nodeID: node, now: bad) }
                }
                #expect(try await cursorSnapshot() == initializedCursors)
            }
            for store in [gatewayStore, cleanupStore] {
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.initializeCursorIfNeeded(nodeID: "", now: base) }
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.initializeCursorAtBeginningIfNeeded(nodeID: "", now: base) }
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.events(afterCursorFor: "", limit: 8) }
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await store.markProcessed(eventID: first.eventID, nodeID: "", now: base) }
            }
            #expect(try await cursorSnapshot() == initializedCursors)

            let cleanupWorker = V2RevokedDeviceProjectionCleanupWorker(store: cleanupStore, cleaner: cleaner, now: { clock.now() })
            for bad in invalidDates {
                clock.set([bad])
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await cleanupWorker.runOnce(limit: 8) }
                // Cleanup committed, but the event remains pending until its cursor can commit.
                #expect(try await count("im_v2.revoked_device_projection_tombstones", on: sql) == 1)
                #expect(try await count("im_v2.device_sync_cursors", on: sql) == 2)
                #expect(try await cleanupStore.events(afterCursorFor: node, limit: 8) == events)
                #expect(try await cursorSnapshot() == initializedCursors)
            }
            let cleanedFirst = try await projectionSnapshot()
            for bad in invalidDates {
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await cleaner.clean(userID: first.userID, deviceID: first.deviceID, revokedAt: bad) }
                #expect(try await projectionSnapshot() == cleanedFirst)
            }
            clock.set([base.addingTimeInterval(-30)])
            try await sql.raw("CREATE FUNCTION im_v2.test_cursor_clock_failure() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'local cursor acknowledgement failure'; END $$").run()
            try await sql.raw("CREATE TRIGGER test_cursor_clock_failure BEFORE UPDATE ON im_v2.gateway_worker_cursors FOR EACH ROW EXECUTE FUNCTION im_v2.test_cursor_clock_failure()").run()
            await #expect(throws: (any Error).self) { try await cleanupWorker.runOnce(limit: 8) }
            #expect(try await cursorSnapshot() == initializedCursors)
            #expect(try await projectionSnapshot() == cleanedFirst)
            try await sql.raw("DROP TRIGGER test_cursor_clock_failure ON im_v2.gateway_worker_cursors").run()
            #expect(try await cleanupWorker.runOnce(limit: 8) == 2)
            #expect(try await cleanupWorker.runOnce(limit: 8) == 0)
            #expect(try await count("im_v2.revoked_device_projection_tombstones", on: sql) == 2)
            #expect(try await count("im_v2.device_sync_cursors", on: sql) == 1)

            // Events committed after startup remain visible; bad acknowledgement clocks do not skip them.
            try await sql.raw("INSERT INTO im_v2.device_revocation_events (user_id, device_id, created_at) VALUES (\(bind: users[2]), \(bind: devices[2]), \(bind: base))").run()
            let pending = try await gatewayStore.events(afterCursorFor: node, limit: 8)
            let later = try #require(pending.first)
            #expect(pending.count == 1)
            let gatewayWorker = V2DeviceRevocationWorker(store: gatewayStore, registry: V2DeviceConnectionRegistry(), nodeID: node, now: { clock.now() })
            let beforeLater = try await cursorSnapshot()
            for bad in invalidDates {
                clock.set([bad])
                try await gatewayWorker.initializeForStartup()
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await gatewayWorker.runOnce(limit: 8) }
                #expect(try await gatewayStore.events(afterCursorFor: node, limit: 8) == pending)
                #expect(try await cursorSnapshot() == beforeLater)
            }
            clock.set([base])
            #expect(try await gatewayWorker.runOnce(limit: 8) == 1)

            // PostgreSQL infinities and its rounded upper endpoint cannot be rebound as Swift Dates.
            let beforeBadHistory = try await cursorSnapshot()
            let projectionsBeforeBadHistory = try await projectionSnapshot()
            for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                try await sql.raw("UPDATE im_v2.device_revocation_events SET created_at = \(bind: literal)::timestamptz WHERE event_id = \(bind: later.eventID)").run()
                await #expect(throws: V2GatewayAuthenticationError.corruptPersistenceState) { try await cleanupWorker.runOnce(limit: 8) }
                #expect(try await cursorSnapshot() == beforeBadHistory)
                #expect(try await projectionSnapshot() == projectionsBeforeBadHistory)
            }
            try await sql.raw("UPDATE im_v2.device_revocation_events SET created_at = \(bind: base) WHERE event_id = \(bind: later.eventID)").run()
            #expect(try await cleanupWorker.runOnce(limit: 8) == 1)
            #expect(try await count("im_v2.device_sync_cursors", on: sql) == 0)
            #expect(try await count("im_v2.revoked_device_projection_tombstones", on: sql) == 3)
            for store in [gatewayStore, cleanupStore] {
                try await withThrowingTaskGroup(of: Void.self) { group in
                    for index in 0..<8 {
                        group.addTask { try await store.markProcessed(eventID: index.isMultiple(of: 2) ? first.eventID : later.eventID, nodeID: node, now: base.addingTimeInterval(-60)) }
                    }
                    try await group.waitForAll()
                }
                #expect(try await store.events(afterCursorFor: node, limit: 8).isEmpty)
            }
            // Both finite database endpoints remain usable for every timestamp write path.
            let validDates = [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)]
            for (index, valid) in validDates.enumerated() {
                let boundaryNode = "boundary-\(index)"
                try await gatewayStore.initializeCursorIfNeeded(nodeID: boundaryNode, now: valid)
                try await cleanupStore.initializeCursorAtBeginningIfNeeded(nodeID: boundaryNode, now: valid)
                let initializedTimes = try await sql.raw("SELECT updated_at AS value FROM im_v2.gateway_worker_cursors WHERE node_id = \(bind: boundaryNode)").all(decoding: RevocationClockDateRow.self)
                #expect(initializedTimes.count == 2)
                #expect(initializedTimes.allSatisfy { $0.value == valid })
                for store in [gatewayStore, cleanupStore] { try await store.markProcessed(eventID: later.eventID, nodeID: boundaryNode, now: valid) }
                let boundaryDeviceUUID = UUID()
                let boundaryDevice = try DeviceID(boundaryDeviceUUID.uuidString)
                try await cleaner.clean(userID: senderID, deviceID: boundaryDevice, revokedAt: valid)
                let times = try await sql.raw("SELECT updated_at AS value FROM im_v2.gateway_worker_cursors WHERE node_id = \(bind: boundaryNode) UNION ALL SELECT revoked_at AS value FROM im_v2.revoked_device_projection_tombstones WHERE device_id = \(bind: boundaryDeviceUUID)").all(decoding: RevocationClockDateRow.self)
                #expect(times.count == 3)
                #expect(times.allSatisfy { $0.value == valid })
            }
        }
    }

    @Test("Direct route clocks recover owner commits without publishing uncommitted cache entries", arguments: [false, true])
    func directRouteClockBounds(roomRouteExists: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let clock = TestSequenceClock([base])
            let directory = V2PostgresRoomShardRouter(database: control, now: { clock.now() })
            let cached = V2CachedRoomShardRouter(source: directory, capacity: 16, bucketCount: 2)
            let ownerStore = PostgresV2DirectMessagingStore(database: owner, shadowForwarder: SuccessfulProjectionShadowForwarder())
            let routed = try V2RoutedDirectMessagingStore(router: cached, ownerStores: ["room-b": ownerStore], controlStore: PostgresV2DirectMessagingStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder()))
            let profile = try forwardImportTestProfile()
            let createdID = UUID()
            let createdRoom = RoomID(uuid: createdID)
            let ids = V2DirectMessagingIDFactory(makeUUID: { createdID })
            let service = try V2DirectMessagingService(store: routed, capacityProfile: profile, roomShardID: "room-b", identifiers: ids, now: { base })
            let operation = DirectRoomOperationID(uuid: UUID())
            let customer = UserID(uuid: memberTwoUUID)
            @Sendable func open() async throws -> V2OpenDirectRoomOutcome {
                try await service.open(actorUserID: senderID, operationID: operation, targetUserID: customer)
            }
            if roomRouteExists {
                let direct = try V2DirectMessagingService(store: ownerStore, capacityProfile: profile, roomShardID: "room-b", identifiers: ids, now: { base })
                guard case .opened = try await direct.open(actorUserID: senderID, operationID: operation, targetUserID: customer) else { throw V2DirectMessagingStoreError.corruptPersistenceState }
                try await sql.raw("INSERT INTO im_v2.room_owner_routes(room_id, room_shard_id, route_epoch, created_at, updated_at) VALUES (\(bind: createdID), 'room-b', 0, \(bind: base), \(bind: base)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at").run()
            }
            func directorySnapshot() async throws -> String {
                let row = try await sql.raw("""
                    SELECT jsonb_build_object(
                        'rooms', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.room_owner_routes r),
                        'pairs', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.direct_room_owner_routes r)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)
                guard let row else { throw V2RoomShardRouteError.corruptPersistenceState }
                return row.value
            }
            func ownerSnapshot() async throws -> String {
                let row = try await ownerSQL.raw("""
                    SELECT jsonb_build_object(
                        'rooms', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.rooms r),
                        'pairs', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.direct_room_pairs r),
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY actor_user_id, operation_id) FROM im_v2.direct_room_operations r),
                        'members', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id, user_id) FROM im_v2.room_memberships r),
                        'admission', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.room_admission r),
                        'sync', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, user_sync_sequence) FROM im_v2.user_sync_log r)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)
                guard let row else { throw V2RoomShardRouteError.corruptPersistenceState }
                return row.value
            }
            let before = try await directorySnapshot()
            var ownerCommitted: String?
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for bad in badDates {
                clock.set([bad])
                await #expect(throws: V2RoomShardRouteError.corruptPersistenceState) { _ = try await open() }
                #expect(try await directorySnapshot() == before)
                #expect(try await count("im_v2.direct_room_pairs", on: ownerSQL) == 1)
                #expect(try await count("im_v2.direct_room_operations", on: ownerSQL) == 1)
                let current = try await ownerSnapshot()
                if let ownerCommitted { #expect(current == ownerCommitted) } else { ownerCommitted = current }
                if !roomRouteExists {
                    await #expect(throws: V2RoomShardRouteError.roomNotFound) { _ = try await cached.route(for: createdRoom) }
                    await #expect(throws: V2RoomShardRouteError.roomNotFound) { _ = try await cached.routes(for: [createdRoom]) }
                }
            }
            clock.set([base.addingTimeInterval(2)])
            try await sql.raw("CREATE FUNCTION im_v2.fail_direct_route_record() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test route record failure'; END $$").run()
            try await sql.raw("CREATE TRIGGER fail_direct_route_record BEFORE INSERT ON im_v2.direct_room_owner_routes FOR EACH ROW EXECUTE FUNCTION im_v2.fail_direct_route_record()").run()
            await #expect(throws: (any Error).self) { _ = try await open() }
            #expect(try await directorySnapshot() == before)
            #expect(try await ownerSnapshot() == ownerCommitted)
            if !roomRouteExists {
                await #expect(throws: V2RoomShardRouteError.roomNotFound) { _ = try await cached.route(for: createdRoom) }
            }
            try await sql.raw("DROP TRIGGER fail_direct_route_record ON im_v2.direct_room_owner_routes").run()
            try await sql.raw("DROP FUNCTION im_v2.fail_direct_route_record()").run()
            let results = try await withThrowingTaskGroup(of: V2OpenDirectRoomOutcome.self) { group in
                for _ in 0..<8 { group.addTask { try await open() } }
                var results: [V2OpenDirectRoomOutcome] = []
                for try await value in group { results.append(value) }
                return results
            }
            let result = try #require(results.first)
            guard case .idempotent(let room) = result else { throw V2DirectMessagingStoreError.corruptPersistenceState }
            #expect(room.roomID == createdRoom && results.count == 8)
            for value in results { #expect(value == result) }
            #expect(try await count("im_v2.room_owner_routes WHERE room_id = '\(createdID.uuidString)'::uuid", on: sql) == 1)
            #expect(try await count("im_v2.direct_room_owner_routes", on: sql) == 1)
            #expect(try await ownerSnapshot() == ownerCommitted)
            let committed = try await directorySnapshot()
            let expectedRoute = try V2RoomShardRoute(shardID: "room-b", epoch: 0)
            for bad in badDates {
                clock.set([bad])
                #expect(try await open() == result)
                #expect(try await directory.route(for: createdRoom) == expectedRoute)
                #expect(try await cached.routes(for: [createdRoom, createdRoom]) == [createdRoom: expectedRoute])
                #expect(try await directorySnapshot() == committed)
                #expect(try await ownerSnapshot() == ownerCommitted)
            }
            // An ordinary unavailable result has no room to record and must
            // remain usable without a directory timestamp.
            #expect(try await service.open(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: UUID())) == .unavailable)
            #expect(try await directorySnapshot() == committed)
            for (actor, target, valid) in [(senderID, UserID(uuid: memberThreeUUID), Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000)), (customer, UserID(uuid: memberThreeUUID), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10))] {
                clock.set([valid])
                let next = try V2DirectMessagingService(store: routed, capacityProfile: profile, roomShardID: "room-b", now: { base })
                guard case .opened(let room) = try await next.open(actorUserID: actor, operationID: .init(uuid: UUID()), targetUserID: target) else { throw V2DirectMessagingStoreError.corruptPersistenceState }
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.room_owner_routes WHERE room_id = \(bind: room.roomID.uuidValue!) AND created_at = \(bind: valid) AND updated_at = \(bind: valid)").first(decoding: CountRow.self)?.value == 1)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.direct_room_owner_routes WHERE room_id = \(bind: room.roomID.uuidValue!) AND created_at = \(bind: valid) AND updated_at = \(bind: valid)").first(decoding: CountRow.self)?.value == 1)
            }
        }
    }


    @Test("Account disable validates required revision changes without suppressing inactive-profile results",
          arguments: ["policy", "profile", "visibility", "suspended", "deleted", "absent"])
    func accountDisableRevisionBoundary(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let user = path == "absent" ? UUID() : senderUUID
            let service = try V2PostgresAccountDisableService(database: database, operatorPrincipal: "revision-maintenance", now: { now })
            let command = try V2AccountDisableCommand(userID: .init(uuid: user), operationID: UUID(), reason: .userRequested)
            if path == "suspended" || path == "deleted" {
                try await sql.raw("UPDATE im_v2.public_user_profiles SET state = \(bind: path), revision = \(bind: Int64.max), visibility_revision = \(bind: Int64.max) WHERE user_id = \(bind: user)").run()
            }
            let needsChange = ["policy", "profile", "visibility"].contains(path)
            let table = path == "policy" ? "user_direct_send_policy_versions" : "public_user_profiles"
            let column = path == "visibility" ? "visibility_revision" : "revision"
            if path == "policy" {
                try await sql.raw("INSERT INTO im_v2.user_direct_send_policy_versions (user_id, revision, updated_at) VALUES (\(bind: user), \(bind: Int64.max), \(bind: now)) ON CONFLICT (user_id) DO UPDATE SET revision = EXCLUDED.revision").run()
            } else if needsChange {
                try await sql.raw("UPDATE im_v2.public_user_profiles SET \(unsafeRaw: column) = \(bind: Int64.max) WHERE user_id = \(bind: user)").run()
            }
            func snapshot() async throws -> [String] {
                var rows: [String] = []
                for name in ["account_disables", "user_direct_send_policy_versions", "public_user_profiles", "public_profile_update_outbox",
                    "auth_devices", "device_refresh_sessions", "device_access_tokens", "device_revocation_events"] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: name) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    rows.append(row.value)
                }
                return rows
            }
            let before = try await snapshot()
            if needsChange {
                for _ in 0..<2 {
                    await #expect(throws: V2AccountDisableError.unavailable) { try await service.disable(command) }
                    #expect(try await snapshot() == before)
                }
                try await sql.raw("UPDATE im_v2.\(unsafeRaw: table) SET \(unsafeRaw: column) = \(bind: Int64.max - 1) WHERE user_id = \(bind: user)").run()
            }
            #expect(try await service.disable(command) == .disabled(disabledAt: now))
            #expect(try await count("im_v2.account_disables", on: sql) == 1)
            #expect(try await count("im_v2.public_profile_update_outbox", on: sql) == (needsChange ? 1 : 0))
            if needsChange {
                #expect(try await sql.raw("SELECT \(unsafeRaw: column) AS value FROM im_v2.\(unsafeRaw: table) WHERE user_id = \(bind: user)").first(decoding: CountRow.self)?.value == Int64.max)
                #expect(try await sql.raw("SELECT state AS value FROM im_v2.public_user_profiles WHERE user_id = \(bind: user)").first(decoding: StringValueRow.self)?.value == "suspended")
            } else if path != "absent" {
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.public_user_profiles WHERE user_id = \(bind: user) AND state = \(bind: path) AND revision = \(bind: Int64.max) AND visibility_revision = \(bind: Int64.max)").first(decoding: CountRow.self)?.value == 1)
            }
            let committed = try await snapshot()
            let other = try V2AccountDisableCommand(userID: command.userID, operationID: UUID(), reason: .userRequested)
            for _ in 0..<2 {
                #expect(try await service.disable(command) == .idempotent(disabledAt: now))
                #expect(try await service.disable(other) == .alreadyDisabled(disabledAt: now))
                #expect(try await snapshot() == committed)
            }
        }
    }

    @Test("Account disable returns the persisted timestamp consistently on first response and replay",
          arguments: [0, 1, 2, 3, 4, 5, 6])
    func accountDisableResponseTimestampPrecision(clockIndex: Int) async throws {
        let dates: [Double] = [946_684_800 - 0.00000075, 946_684_800 + 0.00000125, 1_750_000_000 + 0.1234567,
                               1_750_000_000 + 0.99999975, -0.00075, -210_866_803_200, 9_224_318_015_990]
        let seconds = dates[clockIndex]
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: seconds)
            let service = try V2PostgresAccountDisableService(database: database, operatorPrincipal: "timestamp-maintenance", now: { now })
            let command = try V2AccountDisableCommand(userID: senderID, operationID: UUID(), reason: .userRequested)
            let outcome = try await service.disable(command)
            let row = try await sql.raw("SELECT disabled_at AS value FROM im_v2.account_disables WHERE operation_id = \(bind: command.operationID)").first(decoding: RevocationClockDateRow.self)
            let persisted = try #require(row).value
            #expect(outcome == .disabled(disabledAt: persisted))
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.account_disables d JOIN im_v2.public_profile_update_outbox o ON o.source_event_id = d.operation_id JOIN im_v2.public_user_profiles p ON p.user_id = d.user_id JOIN im_v2.user_direct_send_policy_versions v ON v.user_id = d.user_id WHERE d.operation_id = \(bind: command.operationID) AND d.disabled_at = \(bind: now) AND o.profile_updated_at = d.disabled_at AND o.created_at = d.disabled_at AND p.updated_at = d.disabled_at AND v.updated_at = d.disabled_at").first(decoding: CountRow.self)?.value == 1)
            let other = try V2AccountDisableCommand(userID: senderID, operationID: UUID(), reason: .userRequested)
            for clock in [Double.nan, .infinity, seconds] {
                let retry = try V2PostgresAccountDisableService(database: database, operatorPrincipal: "timestamp-maintenance",
                    now: { Date(timeIntervalSince1970: clock) })
                #expect(try await retry.disable(command) == .idempotent(disabledAt: persisted))
                #expect(try await retry.disable(other) == .alreadyDisabled(disabledAt: persisted))
            }
            #expect(try await count("im_v2.account_disables", on: sql) == 1)
            #expect(try await count("im_v2.public_profile_update_outbox", on: sql) == 1)
        }
    }

    @Test("Account-disable clocks reject partial writes and preserve committed replay")
    func accountDisableClockBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let committedAt = base.addingTimeInterval(1)
            let clock = TestSequenceClock([base])
            let service = try V2PostgresAccountDisableService(database: database, operatorPrincipal: "clock-maintenance", now: { clock.now() })
            let command = try V2AccountDisableCommand(userID: senderID, operationID: UUID(), reason: .userRequested)
            let otherOperation = try V2AccountDisableCommand(userID: senderID, operationID: UUID(), reason: .userRequested)
            let conflicting = try V2AccountDisableCommand(userID: .init(uuid: memberTwoUUID), operationID: command.operationID, reason: .userRequested)
            func snapshot() async throws -> String {
                try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'disables', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.account_disables r),
                        'profiles', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.public_user_profiles r),
                        'policy', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.user_direct_send_policy_versions r),
                        'updates', (SELECT jsonb_agg(to_jsonb(r) ORDER BY source_event_id) FROM im_v2.public_profile_update_outbox r),
                        'devices', (SELECT count(*) FROM im_v2.auth_devices),
                        'refresh', (SELECT count(*) FROM im_v2.device_refresh_sessions),
                        'access', (SELECT count(*) FROM im_v2.device_access_tokens),
                        'revocations', (SELECT count(*) FROM im_v2.device_revocation_events)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)).value
            }
            let initial = try await snapshot()
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for bad in badDates {
                clock.set([bad])
                await #expect(throws: V2AccountDisableError.unavailable) { _ = try await service.disable(command) }
                #expect(try await snapshot() == initial)
            }
            clock.set([committedAt])
            // A downstream persistence failure also rolls back the disable
            // record and policy update before a retry commits exactly once.
            try await sql.raw("CREATE FUNCTION im_v2.fail_disable_profile_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test profile update failure'; END $$").run()
            try await sql.raw("CREATE TRIGGER fail_disable_profile_update BEFORE INSERT ON im_v2.public_profile_update_outbox FOR EACH ROW EXECUTE FUNCTION im_v2.fail_disable_profile_update()").run()
            await #expect(throws: (any Error).self) { _ = try await service.disable(command) }
            #expect(try await snapshot() == initial)
            try await sql.raw("DROP TRIGGER fail_disable_profile_update ON im_v2.public_profile_update_outbox").run()
            try await sql.raw("DROP FUNCTION im_v2.fail_disable_profile_update()").run()
            let results = try await withThrowingTaskGroup(of: V2AccountDisableOutcome.self) { group in
                for _ in 0..<8 { group.addTask { try await service.disable(command) } }
                var results: [V2AccountDisableOutcome] = []
                for try await result in group { results.append(result) }
                return results
            }
            #expect(results.count == 8)
            #expect(results.filter { $0 == .disabled(disabledAt: committedAt) }.count == 1)
            #expect(results.filter { $0 == .idempotent(disabledAt: committedAt) }.count == 7)
            #expect(try await count("im_v2.account_disables", on: sql) == 1)
            #expect(try await count("im_v2.public_user_profiles WHERE state = 'suspended'", on: sql) == 1)
            #expect(try await count("im_v2.public_profile_update_outbox", on: sql) == 1)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.account_disables WHERE user_id = \(bind: senderUUID) AND disabled_at = \(bind: committedAt)").first(decoding: CountRow.self)?.value == 1)
            let committed = try await snapshot()
            for bad in badDates {
                clock.set([bad])
                #expect(try await service.disable(command) == .idempotent(disabledAt: committedAt))
                #expect(try await service.disable(otherOperation) == .alreadyDisabled(disabledAt: committedAt))
                await #expect(throws: V2AccountDisableError.operationConflict) { _ = try await service.disable(conflicting) }
                #expect(try await snapshot() == committed)
            }
            // The other two fixture profiles exercise legitimate database
            // timestamp endpoints without acquiring or issuing credentials.
            for (user, valid) in [(memberTwoUUID, Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000)), (memberThreeUUID, Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10))] {
                clock.set([valid])
                let next = try V2AccountDisableCommand(userID: .init(uuid: user), operationID: UUID(), reason: .userRequested)
                #expect(try await service.disable(next) == .disabled(disabledAt: valid))
                #expect(try await service.disable(next) == .idempotent(disabledAt: valid))
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.account_disables WHERE user_id = \(bind: user) AND disabled_at = \(bind: valid)").first(decoding: CountRow.self)?.value == 1)
            }
            #expect(try await count("im_v2.account_disables", on: sql) == 3)
            #expect(try await count("im_v2.public_profile_update_outbox", on: sql) == 3)
            #expect(try await count("im_v2.auth_devices", on: sql) == 0)
            #expect(try await count("im_v2.device_refresh_sessions", on: sql) == 0)
            #expect(try await count("im_v2.device_access_tokens", on: sql) == 0)
            #expect(try await count("im_v2.device_revocation_events", on: sql) == 0)
        }
    }

    @Test("Admission credit clocks reject partial reservations and retire expired tokens", arguments: [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12])
    func admissionCreditClockBounds(seconds: Double) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let bad = Date(timeIntervalSince1970: seconds)
            let expiry = base.addingTimeInterval(100)
            func state(until: Date = expiry, id: UUID = leaseUUID, generation: UInt64 = 1) throws -> ShardAdmissionState {
                try .init(lease: .init(id: .init(id.uuidString), generation: generation, validUntil: until, commandWindow: .init(limit: 10)))
            }
            let valid = try state()
            let invalid = try state(until: bad)
            let shard = V2ShardAdmissionCommandCreditPool(database: database, batchSize: 5)
            let room = V2RoomAdmissionCommandCreditPool(database: database, batchSize: 5)
            func shardRequest(_ now: Date, _ value: ShardAdmissionState = valid) -> V2ShardAdmissionCommandCreditPool.BatchRequest {
                .init(roomShardID: "room-a", capacityProfileID: "standard", shardState: value, now: now)
            }
            func roomRequest(_ now: Date, _ value: ShardAdmissionState = valid) -> V2RoomAdmissionCommandCreditPool.BatchRequest {
                .init(roomID: roomUUID, shardState: value, now: now)
            }
            func durableSnapshot() async throws -> String {
                try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'shard', (SELECT to_jsonb(r) FROM im_v2.shard_admission_pools r WHERE room_shard_id = 'room-a'),
                        'room', (SELECT to_jsonb(r) FROM im_v2.room_admission r WHERE room_id = \(bind: roomUUID))
                    )::text AS value
                    """).first(decoding: StringValueRow.self)).value
            }
            func rejectClocksWithoutMutation() async throws {
                let shardBefore = await shard.snapshot()
                let roomBefore = await room.snapshot()
                let databaseBefore = try await durableSnapshot()
                await #expect(throws: V2ShardAdmissionCommandCreditError.self) {
                    _ = try await shard.acquire(roomShardID: "room-a", capacityProfileID: "standard", shardState: valid, now: bad)
                }
                await #expect(throws: V2RoomAdmissionCommandCreditError.self) {
                    _ = try await room.acquire(roomID: roomUUID, shardState: valid, now: bad)
                }
                await #expect(throws: V2ShardAdmissionCommandCreditError.self) {
                    _ = try await shard.acquire(roomShardID: "room-a", capacityProfileID: "standard", shardState: invalid, now: base)
                }
                await #expect(throws: V2RoomAdmissionCommandCreditError.self) {
                    _ = try await room.acquire(roomID: roomUUID, shardState: invalid, now: base)
                }
                for batch in [[shardRequest(base), shardRequest(bad)], [shardRequest(bad), shardRequest(base)], [shardRequest(base), shardRequest(base, invalid)]] {
                    await #expect(throws: V2ShardAdmissionCommandCreditError.self) { _ = try await shard.acquire(batch) }
                }
                for batch in [[roomRequest(base), roomRequest(bad)], [roomRequest(bad), roomRequest(base)], [roomRequest(base), roomRequest(base, invalid)]] {
                    await #expect(throws: V2RoomAdmissionCommandCreditError.self) { _ = try await room.acquire(batch) }
                }
                #expect(await shard.snapshot() == shardBefore)
                #expect(await room.snapshot() == roomBefore)
                #expect(try await durableSnapshot() == databaseBefore)
            }
            func acquireBoth(at now: Date, using value: ShardAdmissionState = valid) async throws -> (V2ShardAdmissionCommandCreditPool.Token, V2RoomAdmissionCommandCreditPool.Token) {
                guard case .granted(let shardToken, _) = try await shard.acquire(roomShardID: "room-a", capacityProfileID: "standard", shardState: value, now: now),
                      case .granted(let roomToken) = try await room.acquire(roomID: roomUUID, shardState: value, now: now)
                else { throw V2RoomWriteStoreError.corruptPersistenceState }
                return (shardToken, roomToken)
            }
            // Invalid prefixes and suffixes must neither precharge PostgreSQL
            // nor discard credits that belong to another in-flight message.
            try await rejectClocksWithoutMutation()
            let first = try await acquireBoth(at: base)
            let second = try await acquireBoth(at: base)
            try await rejectClocksWithoutMutation()
            let reserved = try await durableSnapshot()
            await shard.release(first.0, now: bad)
            await room.release(first.1, now: bad)
            let afterInvalidShard = await shard.snapshot()
            let afterInvalidRoom = await room.snapshot()
            #expect(afterInvalidShard.activeCredits == 3 && afterInvalidShard.inFlightCredits == 1 && afterInvalidShard.expiredCreditsDiscarded == 1)
            #expect(afterInvalidRoom.activeCredits == 3 && afterInvalidRoom.inFlightCredits == 1 && afterInvalidRoom.expiredCreditsDiscarded == 1)
            await shard.release(first.0, now: base)
            await room.release(first.1, now: base)
            #expect(await shard.snapshot() == afterInvalidShard)
            #expect(await room.snapshot() == afterInvalidRoom)
            await shard.commit(second.0)
            await room.commit(second.1)
            // A representable clock rollback can still reuse an already paid
            // credit in the same lease. Returning it never refunds PostgreSQL.
            let rolledBack = try await acquireBoth(at: base.addingTimeInterval(-1))
            await shard.release(rolledBack.0, now: base)
            await room.release(rolledBack.1, now: base)
            let shardBatch = try await shard.acquire([shardRequest(base), shardRequest(base)])
            let roomBatch = try await room.acquire([roomRequest(base), roomRequest(base)])
            let shardTokens = shardBatch.compactMap { result -> V2ShardAdmissionCommandCreditPool.Token? in
                guard case .granted(let token, _) = result else { return nil }; return token
            }
            let roomTokens = roomBatch.compactMap { result -> V2RoomAdmissionCommandCreditPool.Token? in
                guard case .granted(let token) = result else { return nil }; return token
            }
            try #require(shardTokens.count == 2 && roomTokens.count == 2)
            #expect(try await durableSnapshot() == reserved)
            // One remaining available credit and both outstanding tokens
            // expire together. Late acknowledgements must stay harmless.
            await shard.release(shardTokens[0], now: expiry)
            await room.release(roomTokens[0], now: expiry)
            let expiredShard = await shard.snapshot()
            let expiredRoom = await room.snapshot()
            #expect(expiredShard == .init(activeCredits: 0, inFlightCredits: 0, batchReservations: 1, databaseCreditsReserved: 5, committedCredits: 1, returnedCredits: 1, expiredCreditsDiscarded: 4, capacityRejections: 0))
            #expect(expiredRoom == .init(activeCredits: 0, inFlightCredits: 0, batchReservations: 1, databaseCreditsReserved: 5, committedCredits: 1, returnedCredits: 1, expiredCreditsDiscarded: 4, capacityRejections: 0, promotedHotRooms: 0))
            await shard.commit(shardTokens[1])
            await room.commit(roomTokens[1])
            await shard.release(shardTokens[1], now: base)
            await room.release(roomTokens[1], now: base)
            #expect(await shard.snapshot() == expiredShard)
            #expect(await room.snapshot() == expiredRoom)
            guard case .unavailable(.expiredShardLease) = try await shard.acquire(roomShardID: "room-a", capacityProfileID: "standard", shardState: valid, now: expiry),
                  case .unavailable(.expiredShardLease) = try await room.acquire(roomID: roomUUID, shardState: valid, now: expiry)
            else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(try await durableSnapshot() == reserved)
            // Advance the owned fixture to the next lease generation. Old
            // token completion cannot consume or return the new lease's credit.
            let nextID = UUID()
            let nextExpiry = expiry.addingTimeInterval(100)
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET lease_id = \(bind: nextID), generation = 2, valid_until = \(bind: nextExpiry), command_window_used = 0 WHERE room_shard_id = 'room-a'").run()
            try await sql.raw("UPDATE im_v2.room_admission SET shard_lease_id = \(bind: nextID), shard_lease_generation = 2, command_window_used = 0 WHERE room_id = \(bind: roomUUID)").run()
            let next = try await acquireBoth(at: expiry, using: state(until: nextExpiry, id: nextID, generation: 2))
            await shard.commit(next.0)
            await room.commit(next.1)
            let nextShard = await shard.snapshot()
            let nextRoom = await room.snapshot()
            #expect(nextShard.activeCredits == 4 && nextShard.inFlightCredits == 0 && nextShard.committedCredits == 2 && nextShard.databaseCreditsReserved == 10)
            #expect(nextRoom.activeCredits == 4 && nextRoom.inFlightCredits == 0 && nextRoom.committedCredits == 2 && nextRoom.databaseCreditsReserved == 10)
            await shard.release(shardTokens, now: expiry)
            await room.release(roomTokens.map { (token: $0, now: expiry) })
            #expect(await shard.snapshot() == nextShard)
            #expect(await room.snapshot() == nextRoom)
        }
    }

    #if os(macOS)
    @Test("authorization survives SIGKILL before and after both durable commits", .timeLimit(.minutes(3)),
          arguments: ["send", "batch", "forward"], ["before-reservation", "after-reservation", "after-owner", "after-ack"])
    func directAuthorizationProcessCrash(kind: String, checkpoint: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner), capacityProfile: profile, roomShardID: "room-b", now: { now })
            var rooms: [UUID] = [], operations: [UUID] = []
            for recipient in (kind == "batch" ? [memberTwoUUID, memberThreeUUID] : [memberTwoUUID]) {
                guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: .init(uuid: recipient)) else { throw CancellationError() }
                rooms.append(room.roomID.uuidValue!); operations.append(UUID())
            }
            var forward: V2ForwardExport?
            if kind == "forward" {
                let source = V2SendMessageService(store: PostgresV2RoomWriteStore(database: control), capacityProfile: profile,
                    limits: try .init(maxUTF8Bytes: 64), now: { now })
                guard case .accepted(let message) = try await source.send(.init(roomID: roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "crash authorization")) else { throw CancellationError() }
                let export = try await PostgresV2ForwardExportStore(database: control).prepare(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), source: .init(roomID: roomID, messageID: message.messageID, revision: .init(1)),
                    sourceRoute: .init(shardID: "room-a", epoch: 0), targetRoomID: .init(uuid: rooms[0]), targetRoute: .init(shardID: "room-b", epoch: 0), now: now)
                try await PostgresV2ForwardInboxStore(database: owner).receive(export, now: now)
                operations[0] = export.intent.targetClientMessageID; forward = export
            }
            let spec = DirectAuthorizationCrashSpec(kind: kind, checkpoint: checkpoint, rooms: rooms, operations: operations,
                payload: forward?.payload, digest: forward?.digest)
            let directory = FileManager.default.temporaryDirectory.appending(path: "imv2-auth-crash-" + UUID().uuidString)
            try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
            let specURL = directory.appending(path: "input.json")
            try JSONEncoder().encode(spec).write(to: specURL)
            let lockKey = Int64.random(in: 1...Int64.max)
            if checkpoint == "before-reservation" || checkpoint == "after-owner" {
                try await sql.raw("""
                    CREATE FUNCTION im_v2.test_pause_authorization() RETURNS trigger LANGUAGE plpgsql AS $$
                    BEGIN PERFORM pg_advisory_xact_lock(\(unsafeRaw: String(lockKey))); RETURN NEW; END; $$
                    """).run()
                let event = checkpoint == "before-reservation" ? "BEFORE INSERT" : "BEFORE UPDATE OF disposition"
                try await sql.raw("CREATE TRIGGER test_pause_authorization \(unsafeRaw: event) ON im_v2.direct_authorization_intents FOR EACH ROW EXECUTE FUNCTION im_v2.test_pause_authorization()").run()
            }
            let gate = PostgreSQLTransactionGate()
            let blockingDatabase = checkpoint == "after-reservation" ? owner : control
            let holder = Task {
                try await blockingDatabase.transaction { transaction in
                    let heldSQL = try #require(transaction as? any SQLDatabase)
                    if checkpoint == "after-reservation" {
                        try await heldSQL.raw("SELECT room_id FROM im_v2.rooms WHERE room_id = \(bind: spec.rooms[0]) FOR UPDATE").run()
                    } else { try await heldSQL.raw("SELECT pg_advisory_xact_lock(\(bind: lockKey))").run() }
                    await gate.holdTransaction()
                }
            }
            await gate.waitUntilHeld()
            let (process, output) = try authorizationCrashProcess(specURL: specURL, mode: "crash", log: directory.appending(path: "crash.log"))
            defer { try? output.close() }
            let exited = Task { try await waitAuthorizationCrashProcess(process) }
            let watchdog = Task {
                try? await Task.sleep(for: .seconds(30))
                if !Task.isCancelled && process.isRunning { kill(process.processIdentifier, SIGKILL) }
            }
            defer { watchdog.cancel() }
            do {
                if checkpoint != "after-ack" {
                    let observationSQL = checkpoint == "after-reservation" ? ownerSQL : sql
                    let query = checkpoint == "after-reservation" ? "%owner_epoch%" : "%direct_authorization_intents%"
                    var reached = false
                    for _ in 0..<1000 {
                        let waiters = try await observationSQL.raw("""
                            SELECT count(*) AS value FROM pg_stat_activity WHERE datname = current_database()
                            AND wait_event_type = 'Lock' AND query LIKE \(bind: query)
                            """).first(decoding: CountRow.self)?.value ?? 0
                        if waiters > 0 { reached = true; break }
                        try await Task.sleep(for: .milliseconds(10))
                    }
                    try #require(reached && process.isRunning)
                    try #require(kill(process.processIdentifier, SIGKILL) == 0)
                }
                try await exited.value
                try #require(process.terminationReason == .uncaughtSignal && process.terminationStatus == SIGKILL)
                if checkpoint == "after-ack" { try #require(FileManager.default.fileExists(atPath: specURL.appendingPathExtension("ready").path)) }
                await gate.releaseTransaction(); try await holder.value
                if checkpoint == "before-reservation" || checkpoint == "after-owner" {
                    try await sql.raw("DROP TRIGGER test_pause_authorization ON im_v2.direct_authorization_intents").run()
                    try await sql.raw("DROP FUNCTION im_v2.test_pause_authorization()").run()
                }
                let amount = Int64(spec.operations.count)
                #expect(try await count("im_v2.direct_authorization_intents", on: sql) == (checkpoint == "before-reservation" ? 0 : amount))
                #expect(try await count("im_v2.messages", on: ownerSQL) == (["after-owner", "after-ack"].contains(checkpoint) ? amount : 0))
                let (recovery, recoveryOutput) = try authorizationCrashProcess(specURL: specURL, mode: "recover", log: directory.appending(path: "recover.log"))
                defer { try? recoveryOutput.close() }
                try await waitAuthorizationCrashProcess(recovery)
                try #require(recovery.terminationReason == .exit && recovery.terminationStatus == 0)
                let report = try JSONDecoder().decode([String: Int].self, from: Data(contentsOf: specURL.appendingPathExtension("report")))
                let recoveryCount = ["after-reservation", "after-owner"].contains(checkpoint) ? spec.operations.count : 0
                #expect(report["claimed"] == recoveryCount && report["resolved"] == recoveryCount && report["deferred"] == 0)
                #expect(try await count("im_v2.messages", on: ownerSQL) == amount)
                let generation: Int64 = checkpoint == "after-reservation" ? 2 : 1
                #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition = 'accepted' AND generation = \(bind: generation)").first(decoding: CountRow.self)?.value == amount)
                #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == amount * generation)
                for index in spec.operations.indices {
                    #expect(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE room_id = \(bind: spec.rooms[index]) AND client_message_id = \(bind: spec.operations[index])").first(decoding: CountRow.self)?.value == 1)
                }
                print("Authorization SIGKILL evidence: \(directory.path); kind=\(kind); checkpoint=\(checkpoint); recovery=\(report)")
            } catch {
                if process.isRunning { kill(process.processIdentifier, SIGKILL) }
                _ = await exited.result
                await gate.releaseTransaction(); _ = await holder.result
                throw error
            }
        }
    }

    @Test("isolated authorization process crash and restart",
          .enabled(if: ProcessInfo.processInfo.environment["IMV2_AUTHORIZATION_CRASH_SPEC"] != nil))
    func directAuthorizationProcessCrashChild() async throws {
        let specURL = URL(fileURLWithPath: try #require(Environment.get("IMV2_AUTHORIZATION_CRASH_SPEC")))
        let spec = try JSONDecoder().decode(DirectAuthorizationCrashSpec.self, from: Data(contentsOf: specURL))
        let mode = try #require(Environment.get("IMV2_AUTHORIZATION_CRASH_MODE"))
        let primary = try #require(Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"))
        let secondary = try #require(Environment.get("IMV2_POSTGRES_TEST_SECONDARY_DATABASE_URL"))
        try #require(Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" && primary != secondary)
        try #require(!spec.rooms.isEmpty && spec.rooms.count == spec.operations.count)
        let app = try await Application.make(.testing)
        do {
            let ownerID = DatabaseID(string: "crash-owner"), reservationID = DatabaseID(string: "crash-reservation")
            app.databases.use(try .postgres(url: primary, maxConnectionsPerEventLoop: 4), as: .psql, isDefault: true)
            app.databases.use(try .postgres(url: primary, maxConnectionsPerEventLoop: 1), as: reservationID)
            app.databases.use(try .postgres(url: secondary, maxConnectionsPerEventLoop: 4), as: ownerID)
            let control = app.db(.psql), owner = app.db(ownerID)
            let initial = Date(timeIntervalSince1970: 1_750_000_000)
            if mode == "recover" {
                let result = try await V2DirectAuthorizationCoordinator(controlDatabase: control, ownerDatabases: ["room-b": owner]).recover(limit: 8, now: initial.addingTimeInterval(31))
                try JSONEncoder().encode(["claimed": result.claimed, "resolved": result.resolved, "deferred": result.deferred]).write(to: specURL.appendingPathExtension("report"))
            }
            let now = mode == "recover" ? initial.addingTimeInterval(32) : initial
            let writer = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled,
                directRoomLogAdmissionMode: .shardOnly, shardAdmissionCommandCreditPool: .init(database: owner, batchSize: 2))
                .usingControlDatabase(app.db(reservationID), authorizationResolutionDatabase: control)
            let profile = try forwardImportTestProfile()
            if spec.kind == "forward" {
                let export = try V2ForwardExport(payload: #require(spec.payload), digest: #require(spec.digest))
                guard case .accepted = try await writer.importForwardExport(export, capacityProfile: profile,
                    limits: .init(maxUTF8Bytes: 64), identifiers: V2AcceptanceIDFactory().make(at: now), now: now) else { throw CancellationError() }
            } else {
                let requests: [V2RoomWriteRequest] = try spec.operations.indices.map { index in
                    .init(command: try .init(roomID: .init(uuid: spec.rooms[index]), senderUserID: senderID,
                        clientMessageID: .init(uuid: spec.operations[index]), text: "crash authorization", limits: .init(maxUTF8Bytes: 64)),
                        capacityProfile: profile, identifiers: try V2AcceptanceIDFactory().make(at: now), now: now)
                }
                var outcomes: [V2SendMessageOutcome] = []
                if spec.kind == "batch" {
                    do { outcomes = try await writer.acceptAtomically(requests: requests) }
                    catch is V2AtomicRoomWriteBatchError {
                        for request in requests { outcomes.append(try await writer.accept(command: request.command, capacityProfile: profile, identifiers: request.identifiers, now: now)) }
                    }
                } else { outcomes = [try await writer.accept(command: requests[0].command, capacityProfile: profile, identifiers: requests[0].identifiers, now: now)] }
                try #require(outcomes.count == requests.count && outcomes.allSatisfy { if case .accepted = $0 { true } else if case .idempotent = $0 { true } else { false } })
            }
            if mode == "crash" {
                try #require(spec.checkpoint == "after-ack")
                try Data("acknowledged".utf8).write(to: specURL.appendingPathExtension("ready"))
                kill(getpid(), SIGKILL); fatalError("SIGKILL must terminate the child")
            }
            try await app.asyncShutdown()
        } catch { try? await app.asyncShutdown(); throw error }
    }

    private func authorizationCrashProcess(specURL: URL, mode: String, log: URL) throws -> (Process, FileHandle) {
        let process = Process(), host = URL(fileURLWithPath: CommandLine.arguments[0])
        let binary = try #require(Bundle(for: GroupJoinQuotaCrashBundleMarker.self).executableURL)
        try #require(host.lastPathComponent == "swiftpm-testing-helper")
        process.executableURL = host
        process.arguments = ["--test-bundle-path", binary.path, binary.path, "--testing-library", "swift-testing", "--filter", "directAuthorizationProcessCrashChild"]
        var environment = ProcessInfo.processInfo.environment
        environment["IMV2_AUTHORIZATION_CRASH_SPEC"] = specURL.path
        environment["IMV2_AUTHORIZATION_CRASH_MODE"] = mode
        process.environment = environment
        FileManager.default.createFile(atPath: log.path, contents: nil)
        let output = try FileHandle(forWritingTo: log)
        process.standardOutput = output; process.standardError = output
        return (process, output)
    }

    private func waitAuthorizationCrashProcess(_ process: Process) async throws {
        try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, any Error>) in
            process.terminationHandler = { _ in continuation.resume() }
            do { try process.run() } catch { continuation.resume(throwing: error) }
        }
    }

    @Test("control connection loss must not allow an owner append after revocation",
          .timeLimit(.minutes(1)), arguments: [false, true], [false, true])
    func directControlConnectionLoss(warm: Bool, isForward: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { _, _, _, _, _ in
            let report = FileManager.default.temporaryDirectory.appending(path: "imv2-control-loss-\(UUID()).json")
            let childLog = report.deletingPathExtension().appendingPathExtension("log")
            FileManager.default.createFile(atPath: childLog.path, contents: nil)
            let output = try FileHandle(forWritingTo: childLog)
            defer { try? output.close() }
            let binary = try #require(Bundle(for: GroupJoinQuotaCrashBundleMarker.self).executableURL)
            let host = URL(fileURLWithPath: CommandLine.arguments[0])
            try #require(host.lastPathComponent == "swiftpm-testing-helper")
            let process = Process()
            process.executableURL = host
            process.arguments = ["--test-bundle-path", binary.path, binary.path, "--testing-library", "swift-testing",
                "--filter", "directControlConnectionLossChild"]
            var environment = ProcessInfo.processInfo.environment
            environment["IMV2_DIRECT_CONTROL_FAULT_CHILD"] = "1"
            environment["IMV2_DIRECT_CONTROL_FAULT_WARM"] = warm ? "1" : "0"
            environment["IMV2_DIRECT_CONTROL_FAULT_FORWARD"] = isForward ? "1" : "0"
            environment["IMV2_DIRECT_CONTROL_FAULT_REPORT"] = report.path
            process.environment = environment
            process.standardOutput = output
            process.standardError = output
            let watchdog = Task {
                try? await Task.sleep(for: .seconds(30))
                if !Task.isCancelled && process.isRunning { process.terminate() }
            }
            defer { watchdog.cancel() }
            try await withCheckedThrowingContinuation { (continuation: CheckedContinuation<Void, any Error>) in
                process.terminationHandler = { _ in continuation.resume() }
                do { try process.run() } catch { continuation.resume(throwing: error) }
            }
            try #require(process.terminationStatus == 0)
            let values = try JSONDecoder().decode([String: Int64].self, from: Data(contentsOf: report))
            print("Control-loss probe report: \(report.path); warm=\(warm); forward=\(isForward); observation=\(values)")
            #expect(values["controlBlocks"] == 1)
            #expect(values["blocksWhileOwnerHeld"] == 0)
            #expect(values["ownerAtRevocation"] == 1)
            #expect(values["ownerCommitted"] == 1)
            #expect(values["callbackSettled"] == 1)
        }
    }

    @Test("isolated control connection loss probe",
          .enabled(if: ProcessInfo.processInfo.environment["IMV2_DIRECT_CONTROL_FAULT_CHILD"] == "1"))
    func directControlConnectionLossChild() async throws {
        let report = try #require(Environment.get("IMV2_DIRECT_CONTROL_FAULT_REPORT"))
        let primary = try #require(Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"))
        let secondary = try #require(Environment.get("IMV2_POSTGRES_TEST_SECONDARY_DATABASE_URL"))
        try #require(Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" && primary != secondary)
        let app = try await Application.make(.testing)
        let ownerID = DatabaseID(string: "fault-owner")
        app.databases.use(try .postgres(url: primary, maxConnectionsPerEventLoop: 4), as: .psql, isDefault: true)
        app.databases.use(try .postgres(url: secondary, maxConnectionsPerEventLoop: 4), as: ownerID)
        let reservationID = DatabaseID(string: "fault-reservation")
        app.databases.use(try .postgres(url: primary, maxConnectionsPerEventLoop: 1), as: reservationID)
        let reservation = app.db(reservationID)
        let reservationSQL = try #require(reservation as? any SQLDatabase)
        let backend = try #require(try await reservationSQL.raw("SELECT pg_backend_pid()::bigint AS value").first(decoding: CountRow.self)).value
        let control = app.db(.psql), owner = app.db(ownerID)
        let sql = try #require(control as? any SQLDatabase), ownerSQL = try #require(owner as? any SQLDatabase)
        try await runDirectControlLossProbe(control: control, reservation: reservation, backend: backend, owner: owner, sql: sql, ownerSQL: ownerSQL,
            warm: Environment.get("IMV2_DIRECT_CONTROL_FAULT_WARM") == "1",
            isForward: Environment.get("IMV2_DIRECT_CONTROL_FAULT_FORWARD") == "1", reportPath: report)
    }

    private func runDirectControlLossProbe(control: any Database, reservation: any Database, backend: Int64, owner: any Database,
        sql: any SQLDatabase, ownerSQL: any SQLDatabase, warm: Bool, isForward: Bool, reportPath: String
    ) async throws {
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let recipient = UserID(uuid: memberTwoUUID)
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
            let writer = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400),
                contentReviewMode: .disabled, directRoomLogAdmissionMode: .room,
                shardAdmissionCommandCreditPool: warm ? .init(database: owner, batchSize: 2) : nil)
                .usingControlDatabase(reservation, authorizationResolutionDatabase: control)
            let service = V2SendMessageService(store: writer, capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { now })
            if warm {
                for _ in 0..<2 {
                    guard case .accepted = try await service.send(.init(roomID: room.roomID, actorUserID: senderID,
                        clientMessageID: .init(uuid: UUID()), text: "warm")) else { throw CancellationError() }
                }
            }
            let forward: V2ForwardExport?
            if isForward {
                let source = V2SendMessageService(store: PostgresV2RoomWriteStore(database: control), capacityProfile: profile,
                    limits: try .init(maxUTF8Bytes: 64), now: { now })
                guard case .accepted(let message) = try await source.send(.init(roomID: roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "forward connection loss")) else { throw CancellationError() }
                let export = try await PostgresV2ForwardExportStore(database: control).prepare(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), source: .init(roomID: roomID, messageID: message.messageID, revision: .init(1)),
                    sourceRoute: .init(shardID: "room-a", epoch: 0), targetRoomID: room.roomID,
                    targetRoute: .init(shardID: "room-b", epoch: 0), now: now)
                // Receive before holding the owner room. This metadata step is
                // not acceptance; the formal import must still reserve its grant.
                try await PostgresV2ForwardInboxStore(database: owner).receive(export, now: now)
                forward = export
            } else { forward = nil }
            let operation = ClientMessageID(uuid: forward?.intent.targetClientMessageID ?? UUID())
            let gate = PostgreSQLTransactionGate()
            let holder = Task {
                try await owner.transaction { transaction in
                    let heldSQL = try #require(transaction as? any SQLDatabase)
                    try await heldSQL.raw("SELECT room_id FROM im_v2.rooms WHERE room_id = \(bind: room.roomID.uuidValue!) FOR UPDATE").run()
                    await gate.holdTransaction()
                }
            }
            await gate.waitUntilHeld()
            let settled = Mutex(false)
            let pending = Task {
                defer { settled.withLock { $0 = true } }
                if let forward {
                    guard case .accepted = try await writer.importForwardExport(forward, capacityProfile: profile,
                        limits: .init(maxUTF8Bytes: 64), identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
                    else { return false }
                } else {
                    guard case .accepted = try await service.send(.init(roomID: room.roomID, actorUserID: senderID,
                        clientMessageID: operation, text: "must not commit after lost authority")) else { return false }
                }
                return true
            }
            do {
                var waiting = false
                for _ in 0..<500 {
                    let count = try await ownerSQL.raw("""
                        SELECT count(*) AS value FROM pg_stat_activity WHERE datname = current_database()
                        AND wait_event_type = 'Lock'
                        AND (query LIKE '%SELECT room_id, room_shard_id, owner_epoch%'
                            OR query LIKE '%SELECT room_shard_id, owner_epoch%')
                        """).first(decoding: CountRow.self)?.value ?? 0
                    if count > 0 { waiting = true; break }
                    try await Task.sleep(for: .milliseconds(10))
                }
                try #require(waiting)
                // Only this test-owned, one-connection reservation pool is
                // terminated. Its grant must already be committed while owner
                // acceptance is waiting for the room lock.
                try #require(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE client_message_id = \(bind: operation.uuidValue!) AND disposition IS NULL").first(decoding: CountRow.self)?.value == 1)
                struct Terminated: Decodable { let value: Bool }
                try #require(try await sql.raw("SELECT pg_terminate_backend(\(bind: backend)::int4) AS value")
                    .first(decoding: Terminated.self)?.value == true)
                let revocation = Task {
                    _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(),
                        authorizationCoordinator: .init(controlDatabase: control, ownerDatabases: ["room-b": owner]))
                        .changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                            targetUserID: senderID, action: .block), now: now)
                    return try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE client_message_id = \(bind: operation.uuidValue!)")
                        .first(decoding: CountRow.self)?.value ?? -1
                }
                var revocationWaiting = false
                for _ in 0..<500 {
                    let count = try await ownerSQL.raw("""
                        SELECT count(*) AS value FROM pg_stat_activity WHERE datname = current_database()
                        AND wait_event_type = 'Lock' AND query LIKE '%pg_advisory_xact_lock(%'
                        """).first(decoding: CountRow.self)?.value ?? 0
                    if count > 0 { revocationWaiting = true; break }
                    try await Task.sleep(for: .milliseconds(10))
                }
                try #require(revocationWaiting)
                let blocksWhileHeld = try await count("im_v2.user_blocks", on: sql)
                try #require(blocksWhileHeld == 0)
                try #require(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE client_message_id = \(bind: operation.uuidValue!)")
                    .first(decoding: CountRow.self)?.value == 0)
                await gate.releaseTransaction()
                try await holder.value
                try #require(try await pending.value)
                let ownerAtRevocation = try await revocation.value
                let committed = try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE client_message_id = \(bind: operation.uuidValue!)")
                    .first(decoding: CountRow.self)?.value ?? -1
                guard case .denied = try await service.send(.init(roomID: room.roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "new request sees block")) else { throw CancellationError() }
                if let forward {
                    // Terminal replay after revocation cannot reserve a new
                    // generation or create a second forwarded message.
                    guard case .accepted = try await writer.importForwardExport(forward, capacityProfile: profile,
                        limits: .init(maxUTF8Bytes: 1), identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
                    else { throw CancellationError() }
                    try #require(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE client_message_id = \(bind: operation.uuidValue!) AND generation = 1 AND disposition = 'accepted'").first(decoding: CountRow.self)?.value == 1)
                    try #require(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE client_message_id = \(bind: operation.uuidValue!)").first(decoding: CountRow.self)?.value == 1)
                }
                let report: [String: Int64] = ["ownerCommitted": committed,
                    "blocksWhileOwnerHeld": blocksWhileHeld, "ownerAtRevocation": ownerAtRevocation,
                    "controlBlocks": try await count("im_v2.user_blocks", on: sql),
                    "callbackSettled": settled.withLock { $0 } ? 1 : 0]
                try JSONEncoder().encode(report).write(to: URL(fileURLWithPath: reportPath), options: .atomic)
                // This process owns no fixture cleanup. The parent waits for
                // exit, records the evidence and drops its disposable schemas.
                // Do not await a driver callback whose connection was killed.
                Darwin._exit(0)
            } catch {
                pending.cancel()
                await gate.releaseTransaction()
                _ = await holder.result
                throw error
            }
    }
    #endif


    @Test("routed sends complete with separate one-connection control and owner pools",
          .timeLimit(.minutes(1)), arguments: [false, true])
    func routedDirectControlPools(colocated: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { _, _, _, _, groupRoom in
            let primary = try #require(Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"))
            let secondary = try #require(Environment.get("IMV2_POSTGRES_TEST_SECONDARY_DATABASE_URL"))
            let app = try await Application.make(.testing)
            do {
                let controlID = DatabaseID(string: "send-authority")
                app.databases.use(try .postgres(url: secondary, maxConnectionsPerEventLoop: 1), as: .psql, isDefault: true)
                app.databases.use(try .postgres(url: colocated ? secondary : primary, maxConnectionsPerEventLoop: 1), as: controlID)
                let owner = app.db(.psql), control = app.db(controlID)
                let sql = try #require(control as? any SQLDatabase)
                let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
                let recipient = UserID(uuid: memberTwoUUID)
                let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                    capacityProfile: profile, roomShardID: "room-b", now: { now })
                guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: recipient) else {
                    throw V2RoomWriteStoreError.corruptPersistenceState
                }
                for id in [room.roomID, groupRoom] {
                    try await sql.raw("""
                        INSERT INTO im_v2.room_owner_routes(room_id, room_shard_id, route_epoch, created_at, updated_at)
                        VALUES (\(bind: id.uuidValue!), 'room-b', 0, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at
                """).run()
                }
                let write = PostgresV2RoomWriteStore(database: owner).usingControlDatabase(control)
                let routed = try V2RoutedRoomWriteStore(router: V2PostgresRoomShardRouter(database: control),
                    stores: ["room-b": write])
                let service = V2SendMessageService(store: routed, capacityProfile: profile,
                    limits: try .init(maxUTF8Bytes: 64), now: { now })
                guard case .accepted = try await service.send(.init(roomID: groupRoom, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "group stays on owner")) else {
                    throw V2RoomWriteStoreError.corruptPersistenceState
                }
                async let first = service.send(.init(roomID: room.roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "first"))
                async let second = service.send(.init(roomID: room.roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "second"))
                let results = try await [first, second]
                #expect(results.allSatisfy { if case .accepted = $0 { true } else { false } })
                _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder())
                    .changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                        targetUserID: senderID, action: .block), now: now)
                guard case .denied = try await service.send(.init(roomID: room.roomID, actorUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "blocked")) else {
                    throw V2RoomWriteStoreError.corruptPersistenceState
                }
                try await app.asyncShutdown()
            } catch {
                try? await app.asyncShutdown()
                throw error
            }
        }
    }

    @Test("direct forward imports enforce control blocks and preserve terminal replay")
    func directForwardControlAuthority() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, _, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let limits = try V2MessageCommandLimits(maxUTF8Bytes: 64)
            let actor = UserID(uuid: memberTwoUUID), recipient = UserID(uuid: memberThreeUUID)
            let sourceSend = V2SendMessageService(store: PostgresV2RoomWriteStore(database: control).usingControlDatabase(control),
                capacityProfile: profile, limits: limits, now: { now })
            guard case .accepted(let message) = try await sourceSend.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "forward control")) else {
                throw V2RoomWriteStoreError.corruptPersistenceState
            }
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: actor,
                operationID: .init(uuid: UUID()), targetUserID: recipient) else {
                throw V2RoomWriteStoreError.corruptPersistenceState
            }
            let exports = PostgresV2ForwardExportStore(database: control)
            @Sendable func prepare() async throws -> V2ForwardExport {
                try await exports.prepare(actorUserID: actor, operationID: .init(uuid: UUID()),
                    source: .init(roomID: roomID, messageID: message.messageID, revision: .init(1)),
                    sourceRoute: .init(shardID: "room-a", epoch: 0), targetRoomID: room.roomID,
                    targetRoute: .init(shardID: "room-b", epoch: 0), now: now)
            }
            let write = PostgresV2RoomWriteStore(database: owner).usingControlDatabase(control).usingWorkloadDatabase(owner)
            @Sendable func receive(_ value: V2ForwardExport) async throws -> V2ForwardImportOutcome {
                try await write.importForwardExport(value, capacityProfile: profile, limits: limits,
                    identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
            }
            let original = try await prepare(), accepted = try await receive(original)
            guard case .accepted = accepted else { throw V2RoomWriteStoreError.corruptPersistenceState }
            let social = PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder())
            _ = try await social.changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                targetUserID: actor, action: .block), now: now)
            #expect(try await receive(original) == accepted)
            let blocked = try await prepare(), denied = try await receive(blocked)
            guard case .rejected = denied else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(try await count("im_v2.messages", on: ownerSQL) == 1)
            #expect(try await count("im_v2.user_blocks", on: ownerSQL) == 0)
            _ = try await social.changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                targetUserID: actor, action: .unblock), now: now)
            #expect(try await receive(blocked) == denied)
            guard case .accepted = try await receive(prepare()) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(try await count("im_v2.messages", on: ownerSQL) == 2)
        }
    }

    @Test("real policy writers drain durable direct grants before revocation", arguments:
        ["block", "relationship", "preference", "disable"], ["configured", "missing", "unreachable"])
    func directDurablePolicyWriters(kind: String, mode: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let recipient = UserID(uuid: memberTwoUUID)
            for database in [control, owner] {
                let social = PostgresV2SocialRelationshipStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
                _ = try await social.changeRelationship(.init(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: recipient, action: .request), now: now)
                _ = try await social.changeRelationship(.init(actorUserID: recipient, operationID: .init(uuid: UUID()), targetUserID: senderID, action: .accept), now: now)
            }
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner), capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
            let command = try V2SendMessageCommand(roomID: room.roomID, senderUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "before revocation", limits: .init(maxUTF8Bytes: 64))
            let grant = try await directAuthorizationGrant(command, recipient: recipient, control: control, now: now)
            let writer = try PostgresV2RoomWriteStore(database: owner).usingAuthorizationGrants([grant], now: now)
            let intents = PostgresV2DirectAuthorizationIntentStore(database: control)
            let coordinator = V2DirectAuthorizationCoordinator(controlDatabase: control, ownerDatabases: ["room-b": owner])
            let unavailable = V2DirectAuthorizationCoordinator(controlDatabase: control, ownerDatabases: [:])
            let operationID = UUID()
            @Sendable func revoke(_ handler: V2DirectAuthorizationCoordinator?) async throws {
                switch kind {
                case "block":
                    _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(), authorizationCoordinator: handler)
                        .changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: operationID), targetUserID: senderID, action: .block), now: now)
                case "relationship":
                    _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(), authorizationCoordinator: handler)
                        .changeRelationship(.init(actorUserID: recipient, operationID: .init(uuid: operationID), targetUserID: senderID, action: .remove), now: now)
                case "preference":
                    _ = try await PostgresV2DirectMessagingStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(), authorizationCoordinator: handler)
                        .setStrangerMessagePermission(command: .init(actorUserID: recipient, operationID: .init(uuid: operationID), permission: .deny), now: now)
                default:
                    _ = try await V2PostgresAccountDisableService(database: control, operatorPrincipal: "authorization-test", authorizationCoordinator: handler, now: { now })
                        .disable(.init(userID: recipient, operationID: operationID, reason: .userRequested))
                }
            }
            @Sendable func send() async throws -> V2SendMessageOutcome {
                try await writer.accept(command: command, capacityProfile: profile, identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
            }
            if mode == "configured" {
                try await revoke(coordinator)
                await #expect(throws: V2DirectAuthorizationReceiptError.attemptAborted) { try await send() }
                #expect(try await count("im_v2.messages", on: ownerSQL) == 0)
            } else {
                if kind == "disable" {
                    await #expect(throws: V2AccountDisableError.unavailable) {
                        try await revoke(mode == "missing" ? nil : unavailable)
                    }
                } else {
                    await #expect(throws: V2DirectAuthorizationCoordinationError.ownerUnavailable) {
                        try await revoke(mode == "missing" ? nil : unavailable)
                    }
                }
                for table in ["user_blocks", "user_stranger_message_preferences", "account_disables"] {
                    #expect(try await count("im_v2." + table, on: sql) == 0)
                }
                #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.user_relationships WHERE state = 'accepted'").first(decoding: CountRow.self)?.value == 1)
                #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 1)
                // A failed revocation has not changed policy. If this request
                // commits now, the retry must acknowledge its accepted proof.
                guard case .accepted = try await send() else { throw CancellationError() }
                try await revoke(coordinator)
                guard case .idempotent = try await send() else { throw CancellationError() }
                #expect(try await count("im_v2.messages", on: ownerSQL) == 1)
            }
            #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 0)
            let freshCommand = try V2SendMessageCommand(roomID: room.roomID, senderUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "new policy", limits: .init(maxUTF8Bytes: 64))
            let fresh = try await directAuthorizationGrant(freshCommand, recipient: recipient, control: control, now: now)
            switch kind {
            case "block": #expect(fresh.policy.blocked)
            case "relationship": #expect(!fresh.policy.isFriend)
            case "preference": #expect(!fresh.policy.allowsStrangers)
            default: #expect(!fresh.policy.recipient.isActive)
            }
            // Exact policy operation replay is read-only and must not cancel
            // a later authorization just because its caller retried the reply.
            try await revoke(coordinator)
            let held = try await control.transaction { transaction in
                try await intents.held(in: .user(memberTwoUUID), limit: 10, transaction: transaction)
            }
            #expect(held.count == 1 && held.first?.attempt == fresh.attempt)
        }
    }

    @Test("automatic authorization ACK failure retains committed messages and consumed credits", arguments: [false, true])
    func directAutomaticAuthorizationAcknowledgementFailure(warm: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let recipient = UserID(uuid: memberTwoUUID)
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
            let credits = V2ShardAdmissionCommandCreditPool(database: owner, batchSize: 2)
            let cache = V2DirectRoomLogFastAppendCache()
            let writer = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400),
                contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                directRoomLogFastAppendCache: cache, shardAdmissionCommandCreditPool: credits)
                .usingControlDatabase(control, authorizationResolutionDatabase: control)
            func command(_ id: ClientMessageID = .init(uuid: UUID()), text: String = "automatic grant") throws -> V2SendMessageCommand {
                try .init(roomID: room.roomID, senderUserID: senderID, clientMessageID: id, text: text, limits: .init(maxUTF8Bytes: 64))
            }
            @Sendable func send(_ command: V2SendMessageCommand) async throws -> V2SendMessageOutcome {
                try await writer.accept(command: command, capacityProfile: profile, identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
            }
            if warm { for _ in 0..<2 { guard case .accepted = try await send(command()) else { throw CancellationError() } } }
            @Sendable func consumed() async throws -> Int64 {
                let used = try #require(try await ownerSQL.raw("SELECT command_window_used AS value FROM im_v2.shard_admission_pools WHERE room_shard_id = 'room-b'").first(decoding: CountRow.self)).value
                let local = await credits.snapshot()
                return used - Int64(local.activeCredits) - Int64(local.inFlightCredits)
            }
            let input = try command(), before = await credits.snapshot(), cacheBefore = await cache.snapshot()
            let consumedBefore = try await consumed()
            try await sql.raw("ALTER TABLE im_v2.direct_authorization_intents ADD CONSTRAINT test_reject_ack CHECK (disposition IS NULL) NOT VALID").run()
            await #expect(throws: V2DirectAuthorizationCoordinationError.ownerUnavailable) { try await send(input) }
            let after = await credits.snapshot()
            #expect(after.committedCredits == before.committedCredits + (warm ? 1 : 0))
            #expect(try await consumed() == consumedBefore + 1)
            #expect(after.inFlightCredits == 0)
            if warm { #expect(await cache.snapshot().committedAppends == cacheBefore.committedAppends + 1) }
            #expect(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE client_message_id = \(bind: input.clientMessageID.uuidValue!)").first(decoding: CountRow.self)?.value == 1)
            #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 1)
            try await sql.raw("ALTER TABLE im_v2.direct_authorization_intents DROP CONSTRAINT test_reject_ack").run()
            guard case .idempotent = try await send(input) else { throw CancellationError() }
            #expect(await credits.snapshot().committedCredits == after.committedCredits)
            #expect(await credits.snapshot().inFlightCredits == 0)
            #expect(try await consumed() == consumedBefore + 1)
            #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 0)
            guard case .idempotencyConflict = try await send(command(input.clientMessageID, text: "changed")) else { throw CancellationError() }
            #expect(await credits.snapshot().committedCredits == after.committedCredits)
            #expect(await credits.snapshot().inFlightCredits == 0)
            #expect(try await consumed() == consumedBefore + 1)
        }
    }

    @Test("formal direct acceptance persists authorization proof atomically", arguments:
        ["accepted", "denied", "aborted", "proof-failure"], [false, true])
    func directDurableOwnerAcceptance(kind: String, warm: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, _, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let recipient = UserID(uuid: memberTwoUUID)
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
            let cache = V2DirectRoomLogFastAppendCache()
            let base = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400),
                contentReviewMode: .disabled, directRoomLogAdmissionMode: .room,
                directRoomLogFastAppendCache: cache,
                shardAdmissionCommandCreditPool: warm ? .init(database: owner, batchSize: 2) : nil)
                .usingControlDatabase(control)
            func command() throws -> V2SendMessageCommand {
                try .init(roomID: room.roomID, senderUserID: senderID, clientMessageID: .init(uuid: UUID()),
                    text: "durable owner", limits: .init(maxUTF8Bytes: 64))
            }
            if warm {
                for _ in 0..<2 {
                    guard case .accepted = try await base.accept(command: command(), capacityProfile: profile,
                        identifiers: V2AcceptanceIDFactory().make(at: now), now: now) else { throw CancellationError() }
                }
            }
            if kind == "denied" {
                _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder())
                    .changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                        targetUserID: senderID, action: .block), now: now)
            }
            let input = try command()
            let grant = try await directAuthorizationGrant(input, recipient: recipient, control: control, now: now)
            let writer = try base.usingAuthorizationGrants([grant], now: now)
            let before = try await count("im_v2.messages", on: ownerSQL)
            let beforeSequence = try #require(try await ownerSQL.raw("SELECT room_sequence AS value FROM im_v2.rooms WHERE room_id = \(bind: room.roomID.uuidValue!)").first(decoding: CountRow.self)).value
            @Sendable func send(_ store: PostgresV2RoomWriteStore) async throws -> V2SendMessageOutcome {
                try await store.acceptOwnerValidated(request: .init(command: input, capacityProfile: profile,
                    identifiers: V2AcceptanceIDFactory().make(at: now), now: now), ownerRoute: .init(shardID: "room-b", epoch: 0))
            }
            if kind == "aborted" {
                let aborted = try await PostgresV2DirectAuthorizationReceiptStore().abort(grant.attempt, now: now, database: owner)
                await #expect(throws: V2DirectAuthorizationReceiptError.attemptAborted) { try await send(writer) }
                #expect(try await count("im_v2.messages", on: ownerSQL) == before)
                #expect(try await ownerSQL.raw("SELECT room_sequence AS value FROM im_v2.rooms WHERE room_id = \(bind: room.roomID.uuidValue!)").first(decoding: CountRow.self)?.value == beforeSequence)
                try await PostgresV2DirectAuthorizationIntentStore(database: control).resolve(grant.attempt, receipt: aborted, now: now)
                let renewed = try await directAuthorizationGrant(input, recipient: recipient, control: control, now: now)
                #expect(renewed.attempt.generation == 2)
                guard case .accepted = try await send(base.usingAuthorizationGrants([renewed], now: now)) else { throw CancellationError() }
                await #expect(throws: V2DirectAuthorizationReceiptError.attemptAborted) { try await send(writer) }
                #expect(try await count("im_v2.messages", on: ownerSQL) == before + 1)
                return
            }
            if kind == "proof-failure" {
                try await ownerSQL.raw("ALTER TABLE im_v2.direct_authorization_receipts ADD CONSTRAINT test_reject_proof CHECK (false) NOT VALID").run()
                await #expect(throws: (any Error).self) { try await send(writer) }
                #expect(try await count("im_v2.messages", on: ownerSQL) == before)
                #expect(try await ownerSQL.raw("SELECT room_sequence AS value FROM im_v2.rooms WHERE room_id = \(bind: room.roomID.uuidValue!)").first(decoding: CountRow.self)?.value == beforeSequence)
                #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == (warm ? 2 : 0))
                try await ownerSQL.raw("ALTER TABLE im_v2.direct_authorization_receipts DROP CONSTRAINT test_reject_proof").run()
            }
            let result = try await send(writer)
            if kind == "denied" {
                guard case .denied = result else { throw CancellationError() }
                #expect(try await count("im_v2.messages", on: ownerSQL) == before)
            } else {
                guard case .accepted = result else { throw CancellationError() }
                #expect(try await count("im_v2.messages", on: ownerSQL) == before + 1)
                if warm { #expect(await cache.snapshot().committedAppends > 0) }
            }
            let disposition = try await ownerSQL.raw("SELECT disposition AS value FROM im_v2.direct_authorization_receipts WHERE client_message_id = \(bind: input.clientMessageID.uuidValue!)")
                .first(decoding: StringValueRow.self)?.value
            #expect(disposition == (kind == "denied" ? "denied" : "accepted"))
            let replay = try await send(writer)
            if kind == "denied" { #expect(replay == result) }
            else { guard case .idempotent = replay else { throw CancellationError() }; #expect(replay.acceptanceReceipt == result.acceptanceReceipt) }
            #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == (warm ? 3 : 1))
        }
    }

    @Test("atomic direct authorization abort rolls back every message", arguments: [false, true], [false, true])
    func directDurableOwnerBatch(warm: Bool, abortFirst: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, _, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try V2CapacityProfile(id: "standard", limits: .init(maxEligibleMembers: 10, maxCommandsPerWindow: 100, retryAfterSeconds: 3))
            try await ownerSQL.raw("UPDATE im_v2.shard_admission_pools SET command_window_limit = 100").run()
            let recipients = [UserID(uuid: memberTwoUUID), UserID(uuid: memberThreeUUID)]
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner), capacityProfile: profile, roomShardID: "room-b", now: { now })
            let cache = V2DirectRoomLogFastAppendCache()
            let base = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 20, window: 86_400), contentReviewMode: .disabled,
                directRoomLogAdmissionMode: .shardOnly, directRoomLogFastAppendCache: cache,
                shardAdmissionCommandCreditPool: .init(database: owner, batchSize: 2)).usingControlDatabase(control)
            var requests: [V2RoomWriteRequest] = [], grants: [V2DirectAuthorizationGrant] = []
            for recipient in recipients {
                guard case .opened(let room) = try await direct.open(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
                if warm {
                    let command = try V2SendMessageCommand(roomID: room.roomID, senderUserID: senderID,
                        clientMessageID: .init(uuid: UUID()), text: "warm", limits: .init(maxUTF8Bytes: 64))
                    guard case .accepted = try await base.accept(command: command, capacityProfile: profile,
                        identifiers: V2AcceptanceIDFactory().make(at: now), now: now) else { throw CancellationError() }
                }
                let command = try V2SendMessageCommand(roomID: room.roomID, senderUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "durable batch", limits: .init(maxUTF8Bytes: 64))
                requests.append(.init(command: command, capacityProfile: profile, identifiers: try V2AcceptanceIDFactory().make(at: now), now: now))
                grants.append(try await directAuthorizationGrant(command, recipient: recipient, control: control, now: now))
            }
            let batch = requests, initial = grants
            let target = abortFirst ? 0 : 1
            let aborted = try await PostgresV2DirectAuthorizationReceiptStore().abort(initial[target].attempt, now: now, database: owner)
            let before = try await count("im_v2.messages", on: ownerSQL)
            await #expect(throws: V2DirectAuthorizationReceiptError.attemptAborted) {
                try await base.usingAuthorizationGrants(initial, now: now).acceptAtomically(requests: batch)
            }
            #expect(try await count("im_v2.messages", on: ownerSQL) == before)
            #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == (warm ? 3 : 1))
            try await PostgresV2DirectAuthorizationIntentStore(database: control).resolve(initial[target].attempt, receipt: aborted, now: now)
            grants[target] = try await directAuthorizationGrant(batch[target].command, recipient: recipients[target], control: control, now: now)
            let outcomes = try await base.usingAuthorizationGrants(grants, now: now).acceptAtomically(requests: batch)
            #expect(outcomes.count == 2 && outcomes.allSatisfy { if case .accepted = $0 { true } else { false } })
            #expect(try await count("im_v2.messages", on: ownerSQL) == before + 2)
            #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == (warm ? 5 : 3))
            if warm { #expect(await cache.snapshot().committedAppends == 2) }
        }
    }

    @Test("forward entry reserves only ready commands and recovers terminal authorization", arguments:
        ["accepted", "denied", "invalid", "ack-accepted", "ack-denied", "finalization", "admission", "revoked", "media-window"], [false, true])
    func directForwardAutomaticAuthorization(scenario: String, hasMedia: Bool) async throws {
        let useMedia = hasMedia || scenario == "media-window"
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let limits = try V2MessageCommandLimits(maxUTF8Bytes: 64)
            let actor = UserID(uuid: memberTwoUUID), recipient = UserID(uuid: memberThreeUUID)
            let root = FileManager.default.temporaryDirectory.appending(path: "forward-auth-" + UUID().uuidString)
            defer { try? FileManager.default.removeItem(at: root) }
            let sourceFiles = try V2LocalFilesystemMediaProvider(rootDirectory: root.appending(path: "source"),
                targetBaseURL: URL(string: "https://source.invalid")!, signingKey: Data(repeating: 1, count: 32), now: { now })
            let targetFiles = try V2LocalFilesystemMediaProvider(rootDirectory: root.appending(path: "target"),
                targetBaseURL: URL(string: "https://target.invalid")!, signingKey: Data(repeating: 2, count: 32), now: { now })
            var media: [V2MediaReference] = []
            if useMedia {
                try await sourceFiles.prepare(); try await targetFiles.prepare()
                let id = MediaID(uuid: UUID()), bytes = Data("authorization media".utf8)
                let upload = try await sourceFiles.issueUploadTarget(mediaID: id, contentType: "application/octet-stream", byteCount: Int64(bytes.count), expiresAt: now.addingTimeInterval(600))
                try await sourceFiles.storeUploadedObject(mediaID: id, targetURL: upload.url, contentType: "application/octet-stream", bytes: bytes)
                try await sql.raw("""
                    INSERT INTO im_v2.media_objects (media_id, owner_user_id, content_type, byte_count, state, upload_session_id, expires_at, state_updated_at, created_at)
                    VALUES (\(bind: id.uuidValue!), \(bind: senderUUID), 'application/octet-stream', \(bind: Int64(bytes.count)), 'available', \(bind: UUID()), \(bind: now.addingTimeInterval(600)), \(bind: now), \(bind: now))
                    """).run()
                media = [.init(mediaID: id)]
            }
            let source = V2SendMessageService(store: PostgresV2RoomWriteStore(database: control), capacityProfile: profile, limits: limits, now: { now })
            guard case .accepted(let original) = try await source.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "durable forward", media: media)) else { throw CancellationError() }
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner), capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: actor, operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
            let export = try await PostgresV2ForwardExportStore(database: control).prepare(actorUserID: actor, operationID: .init(uuid: UUID()),
                source: .init(roomID: roomID, messageID: original.messageID, revision: .init(1)), sourceRoute: .init(shardID: "room-a", epoch: 0),
                targetRoomID: room.roomID, targetRoute: .init(shardID: "room-b", epoch: 0), now: now)
            let writer = PostgresV2RoomWriteStore(database: owner).usingControlDatabase(control, authorizationResolutionDatabase: control).usingWorkloadDatabase(owner)
            @Sendable func deliver(_ maxBytes: Int = 64) async throws -> V2ForwardImportOutcome {
                try await writer.importForwardExport(export, capacityProfile: profile, limits: .init(maxUTF8Bytes: maxBytes),
                    identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
            }
            if useMedia {
                #expect(try await deliver() == .pending(.media))
                #expect(try await count("im_v2.direct_authorization_intents", on: sql) == 0)
                #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == 0)
            }
            let denied = scenario == "denied" || scenario == "ack-denied" || scenario == "revoked"
            if denied && scenario != "revoked" {
                _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(),
                    authorizationCoordinator: .init(controlDatabase: control, ownerDatabases: ["room-b": owner]))
                    .changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()), targetUserID: actor, action: .block), now: now)
            }
            if useMedia {
                let copier = try V2LocalFilesystemForwardMediaCopier(sources: ["room-a": sourceFiles], target: targetFiles, maximumBytes: 1024, now: { now })
                let worker = try V2ForwardMediaImportWorker(store: .init(database: owner), copier: copier,
                    scanner: V2LocalEICARMediaScanner(provider: targetFiles), now: { now })
                #expect(try await worker.runOnce(exportID: export.intent.exportID) == .ready)
                #expect(try await count("im_v2.direct_authorization_intents", on: sql) == 0)
            }
            if scenario == "media-window" {
                let gate = PostgreSQLTransactionGate()
                let key = "account-state:" + actor.uuidValue!.uuidString
                let holder = Task {
                    try await control.transaction { transaction in
                        let heldSQL = try #require(transaction as? any SQLDatabase)
                        try await heldSQL.raw("SELECT pg_advisory_xact_lock(hashtextextended(\(bind: key), 0))").run()
                        await gate.holdTransaction()
                    }
                }
                await gate.waitUntilHeld()
                let pending = Task { try await deliver() }
                do {
                    var waiting = false
                    for _ in 0..<500 {
                        waiting = try await sql.raw("SELECT count(*) AS value FROM pg_stat_activity WHERE datname = current_database() AND wait_event_type = 'Lock' AND query LIKE '%pg_advisory_xact_lock_shared%'").first(decoding: CountRow.self)?.value ?? 0 > 0
                        if waiting { break }
                        try await Task.sleep(for: .milliseconds(10))
                    }
                    try #require(waiting)
                    try #require(try await count("im_v2.direct_authorization_intents", on: sql) == 0)
                    // Preflight has committed; the blocked control reservation cannot
                    // protect owner media. Exercise state and timestamp independently.
                    if hasMedia {
                        try await ownerSQL.raw("UPDATE im_v2.media_objects SET state = 'expired' WHERE state = 'available'").run()
                    } else {
                        try await ownerSQL.raw("UPDATE im_v2.media_objects SET expires_at = \(bind: now) WHERE state = 'available'").run()
                    }
                    await gate.releaseTransaction(); try await holder.value
                    await #expect(throws: V2MediaStoreError.mediaUnavailable) { try await pending.value }
                    #expect(try await count("im_v2.messages", on: ownerSQL) == 0)
                    #expect(try await count("im_v2.message_media_references", on: ownerSQL) == 0)
                    #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == 0)
                    #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 1)
                    #expect(try await V2DirectAuthorizationCoordinator(controlDatabase: control, ownerDatabases: ["room-b": owner])
                        .recover(limit: 8, now: now.addingTimeInterval(31)) == .init(claimed: 1, resolved: 1, deferred: 0))
                    #expect(try await sql.raw("SELECT disposition AS value FROM im_v2.direct_authorization_intents").first(decoding: StringValueRow.self)?.value == "aborted")
                    #expect(try await ownerSQL.raw("SELECT disposition AS value FROM im_v2.direct_authorization_receipts").first(decoding: StringValueRow.self)?.value == "aborted")
                } catch {
                    await gate.releaseTransaction(); _ = await holder.result
                    _ = await pending.result
                    throw error
                }
                return
            }
            if scenario == "admission" || scenario == "revoked" {
                try await ownerSQL.raw("UPDATE im_v2.room_admission SET command_window_used = command_window_limit WHERE room_id = \(bind: room.roomID.uuidValue!)").run()
                #expect(try await deliver() == .pending(.admission))
                #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == 0)
                #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 1)
                if scenario == "revoked" {
                    let grant = try #require(try await PostgresV2DirectAuthorizationIntentStore(database: control)
                        .existing(roomID: room.roomID.uuidValue!, senderID: actor.uuidValue!, clientMessageID: export.intent.targetClientMessageID))
                    _ = try await PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(),
                        authorizationCoordinator: .init(controlDatabase: control, ownerDatabases: ["room-b": owner]))
                        .changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()), targetUserID: actor, action: .block), now: now)
                    try #require(try await sql.raw("SELECT disposition AS value FROM im_v2.direct_authorization_intents").first(decoding: StringValueRow.self)?.value == "aborted")
                    try #require(try await count("im_v2.user_blocks", on: sql) == 1)
                    try await ownerSQL.raw("UPDATE im_v2.room_admission SET command_window_used = 0 WHERE room_id = \(bind: room.roomID.uuidValue!)").run()
                    let stale = try writer.usingAuthorizationGrants([grant], now: now)
                    await #expect(throws: V2DirectAuthorizationReceiptError.attemptAborted) {
                        try await stale.importForwardExport(export, capacityProfile: profile, limits: limits,
                            identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
                    }
                    #expect(try await count("im_v2.messages", on: ownerSQL) == 0)
                    #expect(try await count("im_v2.message_media_references", on: ownerSQL) == 0)
                }
                try await ownerSQL.raw("UPDATE im_v2.room_admission SET command_window_used = 0 WHERE room_id = \(bind: room.roomID.uuidValue!)").run()
            }
            if scenario == "finalization" {
                try await ownerSQL.raw("ALTER TABLE im_v2.message_forward_inbox ADD CONSTRAINT test_reject_completion CHECK (state <> 'completed') NOT VALID").run()
                await #expect(throws: (any Error).self) { try await deliver() }
                #expect(try await count("im_v2.messages", on: ownerSQL) == 1)
                #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == 1)
                try await ownerSQL.raw("ALTER TABLE im_v2.message_forward_inbox DROP CONSTRAINT test_reject_completion").run()
            }
            if scenario.hasPrefix("ack-") {
                try await sql.raw("ALTER TABLE im_v2.direct_authorization_intents ADD CONSTRAINT test_reject_forward_ack CHECK (disposition IS NULL) NOT VALID").run()
                await #expect(throws: V2DirectAuthorizationCoordinationError.ownerUnavailable) { try await deliver() }
                #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE disposition IS NULL").first(decoding: CountRow.self)?.value == 1)
                try await sql.raw("ALTER TABLE im_v2.direct_authorization_intents DROP CONSTRAINT test_reject_forward_ack").run()
                #expect(try await PostgresV2ForwardInboxCompactor(database: owner).runOnce(now: now.addingTimeInterval(PostgresV2ForwardInboxCompactor.retentionSeconds), limit: 1) == 1)
                #expect(try await ownerSQL.raw("SELECT payload IS NULL AS exists FROM im_v2.message_forward_inbox").first(decoding: ExistsRow.self)?.exists == true)
            }
            let result = try await deliver(scenario == "invalid" || scenario == "finalization" ? 1 : 64)
            if scenario == "invalid" { #expect(result == .rejected(code: "INVALID_ARGUMENT")) }
            else if denied { #expect(result == .rejected(code: "DIRECT_MESSAGE_RESTRICTED")) }
            else { guard case .accepted = result else { throw CancellationError() } }
            #expect(try await deliver(1) == result)
            if scenario == "invalid" {
                #expect(try await V2DirectAuthorizationCoordinator(controlDatabase: control, ownerDatabases: ["room-b": owner])
                    .recover(limit: 8, now: now.addingTimeInterval(31)) == .init(claimed: 1, resolved: 1, deferred: 0))
                #expect(try await deliver() == result)
            }
            #expect(try await count("im_v2.messages", on: ownerSQL) == (denied || scenario == "invalid" ? 0 : 1))
            #expect(try await count("im_v2.direct_authorization_intents", on: sql) == 1)
            let expectedGeneration: Int64 = scenario == "revoked" ? 2 : 1
            #expect(try await count("im_v2.direct_authorization_receipts", on: ownerSQL) == expectedGeneration)
            #expect(try await sql.raw("SELECT count(*) AS value FROM im_v2.direct_authorization_intents WHERE generation = \(bind: expectedGeneration) AND disposition IS NOT NULL").first(decoding: CountRow.self)?.value == 1)
            if scenario == "revoked" {
                #expect(try await sql.raw("SELECT disposition AS value FROM im_v2.direct_authorization_intents").first(decoding: StringValueRow.self)?.value == "denied")
                #expect(try await count("im_v2.message_media_references", on: ownerSQL) == 0)
            }
            if useMedia && !denied && scenario != "invalid" {
                #expect(try await count("im_v2.message_media_references", on: ownerSQL) == 1)
            }
        }
    }

    @Test("forward import participates in durable authorization", arguments: [false, true])
    func directDurableOwnerForward(abort: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, _, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000), profile = try forwardImportTestProfile()
            let limits = try V2MessageCommandLimits(maxUTF8Bytes: 64)
            let actor = UserID(uuid: memberTwoUUID), recipient = UserID(uuid: memberThreeUUID)
            let source = V2SendMessageService(store: PostgresV2RoomWriteStore(database: control), capacityProfile: profile, limits: limits, now: { now })
            guard case .accepted(let message) = try await source.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "durable forward")) else { throw CancellationError() }
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner), capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: actor, operationID: .init(uuid: UUID()), targetUserID: recipient) else { throw CancellationError() }
            let export = try await PostgresV2ForwardExportStore(database: control).prepare(actorUserID: actor, operationID: .init(uuid: UUID()),
                source: .init(roomID: roomID, messageID: message.messageID, revision: .init(1)), sourceRoute: .init(shardID: "room-a", epoch: 0),
                targetRoomID: room.roomID, targetRoute: .init(shardID: "room-b", epoch: 0), now: now)
            let command = try ForwardInboxAuthorization(export: export, mediaIDs: []).command(limits: limits)
            let grant = try await directAuthorizationGrant(command, recipient: recipient, control: control, now: now)
            let writer = try PostgresV2RoomWriteStore(database: owner).usingControlDatabase(control)
                .usingAuthorizationGrants([grant], now: now).usingWorkloadDatabase(owner)
            if abort {
                _ = try await PostgresV2DirectAuthorizationReceiptStore().abort(grant.attempt, now: now, database: owner)
                await #expect(throws: V2DirectAuthorizationReceiptError.attemptAborted) {
                    try await writer.importForwardExport(export, capacityProfile: profile, limits: limits, identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
                }
                #expect(try await count("im_v2.messages", on: ownerSQL) == 0)
            } else {
                let accepted = try await writer.importForwardExport(export, capacityProfile: profile, limits: limits,
                    identifiers: V2AcceptanceIDFactory().make(at: now), now: now)
                guard case .accepted = accepted else { throw CancellationError() }
                #expect(try await writer.importForwardExport(export, capacityProfile: profile, limits: limits,
                    identifiers: V2AcceptanceIDFactory().make(at: now), now: now) == accepted)
                #expect(try await count("im_v2.messages", on: ownerSQL) == 1)
                #expect(try await ownerSQL.raw("SELECT disposition AS value FROM im_v2.direct_authorization_receipts")
                    .first(decoding: StringValueRow.self)?.value == "accepted")
            }
        }
    }

    private func directAuthorizationGrant(_ command: V2SendMessageCommand, recipient: UserID, control: any Database, now: Date) async throws -> V2DirectAuthorizationGrant {
        let request = V2DirectAuthorizationRequest(roomID: command.roomID.uuidValue!, senderID: command.senderUserID.uuidValue!,
            clientMessageID: command.clientMessageID.uuidValue!, recipientID: recipient.uuidValue!, ownerShardID: "room-b",
            ownerEpoch: 0, fingerprint: command.fingerprint.digest)
        return try #require(try await PostgresV2DirectAuthorizationIntentStore(database: control).reserve([request], now: now).first)
    }

    @Test("atomic direct batches apply control authority to every room before any append",
          arguments: [false, true], [false, true])
    func directBatchControlAuthority(warm: Bool, blockedFirst: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, _, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try V2CapacityProfile(id: "standard", limits: .init(
                maxEligibleMembers: 10, maxCommandsPerWindow: 100, retryAfterSeconds: 3))
            try await ownerSQL.raw("UPDATE im_v2.shard_admission_pools SET command_window_limit = 100").run()
            let recipients = [UserID(uuid: memberTwoUUID), UserID(uuid: memberThreeUUID)]
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                capacityProfile: profile, roomShardID: "room-b", now: { now })
            var rooms: [RoomID] = []
            for recipient in recipients {
                guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: recipient) else {
                    Issue.record("expected direct room"); return
                }
                rooms.append(room.roomID)
            }
            let cache = V2DirectRoomLogFastAppendCache()
            let writer = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 20, window: 86_400),
                contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                directRoomLogFastAppendCache: cache,
                shardAdmissionCommandCreditPool: .init(database: owner, batchSize: 2)).usingControlDatabase(control)
            let roomIDs = rooms
            @Sendable func requests(reversed: Bool = false) throws -> [V2OwnerValidatedRoomWriteRequest] {
                let ordered = reversed ? Array(roomIDs.reversed()) : roomIDs
                return try ordered.map { room in
                    .init(request: .init(command: try .init(roomID: room, senderUserID: senderID,
                        clientMessageID: .init(uuid: UUID()), text: "batch control",
                        limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                        identifiers: try V2AcceptanceIDFactory().make(at: now), now: now),
                        ownerRoute: try .init(shardID: "room-b", epoch: 0))
                }
            }
            if warm {
                for item in try requests() {
                    guard case .accepted = try await writer.acceptOwnerValidated(request: item.request,
                        ownerRoute: item.ownerRoute) else {
                        Issue.record("warm-up failed"); return
                    }
                }
            }
            let first = try await writer.acceptAtomicallyOwnerValidated(requests: requests())
            #expect(first.count == 2)
            #expect(first.allSatisfy { if case .accepted = $0 { true } else { false } })
            if warm { #expect(await cache.snapshot().committedAppends == 2) }
            // Reverse arrival order across concurrent batches while sharing a sender.
            let forwardInputs = try requests(), reverseInputs = try requests(reversed: true)
            async let forward = writer.acceptAtomicallyOwnerValidated(requests: forwardInputs)
            async let reverse = writer.acceptAtomicallyOwnerValidated(requests: reverseInputs)
            let concurrent = try await forward + reverse
            #expect(concurrent.count == 4)
            #expect(concurrent.allSatisfy { if case .accepted = $0 { true } else { false } })
            let before = try await count("im_v2.messages", on: ownerSQL)
            let blocked = recipients[blockedFirst ? 0 : 1]
            let social = PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(), authorizationCoordinator: .init(controlDatabase: control, ownerDatabases: ["room-b": owner]))
            _ = try await social.changeUserBlock(.init(actorUserID: blocked, operationID: .init(uuid: UUID()),
                targetUserID: senderID, action: .block), now: now)
            #expect(try await count("im_v2.user_blocks", on: ownerSQL) == 0)
            let rejected = try requests()
            await #expect(throws: V2AtomicRoomWriteBatchError.self) {
                try await writer.acceptAtomicallyOwnerValidated(requests: rejected)
            }
            #expect(try await count("im_v2.messages", on: ownerSQL) == before)
            for item in rejected {
                #expect(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.messages WHERE client_message_id = \(bind: item.request.command.clientMessageID.uuidValue!)")
                    .first(decoding: CountRow.self)?.value == 0)
            }
            _ = try await social.changeUserBlock(.init(actorUserID: blocked, operationID: .init(uuid: UUID()),
                targetUserID: senderID, action: .unblock), now: now)
            let restored = try await writer.acceptAtomicallyOwnerValidated(requests: rejected)
            #expect(restored.allSatisfy { if case .accepted = $0 { true } else { false } })
            #expect(try await count("im_v2.messages", on: ownerSQL) == before + 2)
            let fence = V2DirectSendControlPolicyFence(database: control)
            await #expect(throws: V2DirectSendControlPolicyError.invalidBatch) {
                try await fence.withLockedPolicies(pairs: []) { _, _ in Issue.record("empty scope accepted") }
            }
            await #expect(throws: V2DirectSendControlPolicyError.invalidBatch) {
                try await fence.withLockedPolicies(pairs: Array(repeating: .init(sender: senderUUID, recipient: memberTwoUUID), count: 129)) {
                    _, _ in Issue.record("oversized scope accepted")
                }
            }
        }
    }

    @Test("actual direct sends refresh control authority despite stale owner policies", arguments:
        ["block", "concurrent-block", "relationship", "preference", "disable-sender", "disable-recipient"], [false, true])
    func directSendControlAuthority(kind: String, warm: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let recipient = UserID(uuid: memberTwoUUID), profile = try forwardImportTestProfile()
            let coordinator = V2DirectAuthorizationCoordinator(controlDatabase: control, ownerDatabases: ["room-b": owner])
            let social = PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder(), authorizationCoordinator: coordinator)
            let directControl = PostgresV2DirectMessagingStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder())
            if kind == "relationship" {
                for database in [control, owner] {
                    let store = PostgresV2SocialRelationshipStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
                    _ = try await store.changeRelationship(.init(actorUserID: senderID, operationID: .init(uuid: UUID()),
                        targetUserID: recipient, action: .request), now: now)
                    _ = try await store.changeRelationship(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                        targetUserID: senderID, action: .accept), now: now)
                }
                _ = try await directControl.setStrangerMessagePermission(command: .init(actorUserID: recipient,
                    operationID: .init(uuid: UUID()), permission: .deny), now: now)
            }
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                capacityProfile: profile, roomShardID: "room-b", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                operationID: .init(uuid: UUID()), targetUserID: recipient) else {
                Issue.record("expected direct room"); return
            }
            let cache = V2DirectRoomLogFastAppendCache()
            let writer = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400),
                contentReviewMode: .disabled, directRoomLogAdmissionMode: .room,
                directRoomLogFastAppendCache: cache,
                shardAdmissionCommandCreditPool: warm ? .init(database: owner, batchSize: 2) : nil,
                roomAdmissionCommandCreditPool: warm ? .init(database: owner, batchSize: 2) : nil).usingControlDatabase(control)
            func request() throws -> V2RoomWriteRequest {
                .init(command: try .init(roomID: room.roomID, senderUserID: senderID,
                    clientMessageID: .init(uuid: UUID()), text: "control authority",
                    limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile,
                    identifiers: try V2AcceptanceIDFactory().make(at: now), now: now)
            }
            @Sendable func send(_ input: V2RoomWriteRequest) async throws -> V2SendMessageOutcome {
                try await writer.acceptOwnerValidated(request: input,
                    ownerRoute: .init(shardID: "room-b", epoch: 0))
            }
            let original = try request()
            let accepted = try await send(original)
            guard case .accepted = accepted else { Issue.record("expected initial acceptance"); return }
            if warm {
                for _ in 0..<2 {
                    guard case .accepted = try await send(request()) else { Issue.record("warm send rejected"); return }
                }
                #expect(await cache.snapshot().committedAppends > 0)
                let cached = try #require(await cache.value(for: .init(roomID: room.roomID.uuidValue!, senderID: senderUUID)))
                #expect(cached.policy.allowsStrangers) // owner truth; control denies this in relationship case
            }
            if kind == "concurrent-block" {
                let gate = PostgreSQLTransactionGate()
                let holder = Task {
                    try await owner.transaction { transaction in
                        let heldSQL = try #require(transaction as? any SQLDatabase)
                        try await heldSQL.raw("SELECT room_id FROM im_v2.rooms WHERE room_id = \(bind: room.roomID.uuidValue!) FOR UPDATE").run()
                        await gate.holdTransaction()
                    }
                }
                await gate.waitUntilHeld()
                let input = try request()
                let pending = Task { try await send(input) }
                @Sendable func waitForLock(_ database: any SQLDatabase, query: String) async throws -> Bool {
                    for _ in 0..<500 {
                        let waiting = try await database.raw("""
                            SELECT count(*) AS value FROM pg_stat_activity WHERE datname = current_database()
                            AND wait_event_type = 'Lock' AND query LIKE \(bind: query)
                            """).first(decoding: CountRow.self)?.value ?? 0
                        if waiting > 0 { return true }
                        try await Task.sleep(for: .milliseconds(10))
                    }
                    return false
                }
                do {
                    #expect(try await waitForLock(ownerSQL, query: "%SELECT room_id, room_shard_id, owner_epoch%"))
                    let revocation = Task {
                        try await social.changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                            targetUserID: senderID, action: .block), now: now)
                    }
                    do {
                        #expect(try await waitForLock(ownerSQL, query: "%pg_advisory_xact_lock(%"))
                        await gate.releaseTransaction()
                        try await holder.value
                        let outcome = try await pending.value
                        if case .accepted = outcome {} else { Issue.record("fenced send did not commit") }
                        _ = try await revocation.value
                    } catch {
                        revocation.cancel()
                        await gate.releaseTransaction()
                        _ = await revocation.result
                        throw error
                    }
                } catch {
                    pending.cancel()
                    await gate.releaseTransaction()
                    _ = await holder.result
                    _ = await pending.result
                    throw error
                }
            }
            let before = try await count("im_v2.messages", on: ownerSQL)
            switch kind {
            case "concurrent-block": break
            case "block":
                _ = try await social.changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                    targetUserID: senderID, action: .block), now: now)
            case "relationship":
                _ = try await social.changeRelationship(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                    targetUserID: senderID, action: .remove), now: now)
            case "preference":
                _ = try await directControl.setStrangerMessagePermission(command: .init(actorUserID: recipient,
                    operationID: .init(uuid: UUID()), permission: .deny), now: now)
            default:
                _ = try await V2PostgresAccountDisableService(database: control, operatorPrincipal: "send-policy-test", now: { now })
                    .disable(.init(userID: kind == "disable-sender" ? senderID : recipient,
                        operationID: UUID(), reason: .userRequested))
            }
            // Durable owner copies deliberately remain permissive, including warm-cache revisions.
            #expect(try await count("im_v2.user_blocks", on: ownerSQL) == 0)
            #expect(try await count("im_v2.account_disables", on: ownerSQL) == 0)
            if kind == "relationship" {
                #expect(try await ownerSQL.raw("SELECT count(*) AS value FROM im_v2.user_relationships WHERE state = 'accepted'")
                    .first(decoding: CountRow.self)?.value == 1)
            }
            let replay = try await send(original)
            guard case .idempotent(let receipt) = replay else { Issue.record("expected original receipt"); return }
            #expect(receipt == accepted.acceptanceReceipt)
            let deniedRequest = try request()
            if kind == "disable-sender" {
                await #expect(throws: V2RoomWriteStoreError.actorNotEligible) { try await send(deniedRequest) }
            } else {
                guard case .denied = try await send(deniedRequest) else { Issue.record("control revocation ignored"); return }
            }
            #expect(try await count("im_v2.messages", on: ownerSQL) == before)
            if kind == "block" || kind == "concurrent-block" {
                _ = try await social.changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                    targetUserID: senderID, action: .unblock), now: now)
            } else if kind == "relationship" || kind == "preference" {
                _ = try await directControl.setStrangerMessagePermission(command: .init(actorUserID: recipient,
                    operationID: .init(uuid: UUID()), permission: .allow), now: now)
            } else { return }
            guard case .accepted = try await send(request()) else { Issue.record("control permission restoration ignored"); return }
            #expect(try await count("im_v2.messages", on: ownerSQL) == before + 1)
            // Previously committed denial remains idempotent after permissions change.
            guard case .denied = try await send(deniedRequest) else { Issue.record("denial replay changed"); return }
        }
    }

    @Test("control direct policies remain locked through a cross-database callback", arguments: ["block", "relationship", "preference", "disable"])
    func directControlPolicyFence(kind: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, _, sql, ownerSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let recipient = UserID(uuid: memberTwoUUID)
            let social = PostgresV2SocialRelationshipStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder())
            let direct = PostgresV2DirectMessagingStore(database: control, shadowForwarder: SuccessfulProjectionShadowForwarder())
            if kind == "relationship" {
                _ = try await social.changeRelationship(.init(actorUserID: senderID, operationID: .init(uuid: UUID()),
                    targetUserID: recipient, action: .request), now: now)
                _ = try await social.changeRelationship(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                    targetUserID: senderID, action: .accept), now: now)
            }
            try await ownerSQL.raw("CREATE TABLE im_v2.control_policy_test_commits (value int NOT NULL)").run()
            let fence = V2DirectSendControlPolicyFence(database: control)
            let gate = PostgreSQLTransactionGate()
            let reader = Task {
                try await fence.withLockedPolicies(pairs: [.init(sender: senderUUID, recipient: memberTwoUUID)]) { _, policies in
                    let policy = try #require(policies[.init(sender: senderUUID, recipient: memberTwoUUID)])
                    #expect(policy.sender.isActive && policy.recipient.isActive)
                    #expect(!policy.blocked && policy.allowsStrangers)
                    #expect(policy.isFriend == (kind == "relationship"))
                    await gate.holdTransaction()
                    try await ownerSQL.raw("INSERT INTO im_v2.control_policy_test_commits VALUES (1)").run()
                }
            }
            await gate.waitUntilHeld()
            let writer = Task {
                switch kind {
                case "block":
                    _ = try await social.changeUserBlock(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                        targetUserID: senderID, action: .block), now: now)
                case "relationship":
                    _ = try await social.changeRelationship(.init(actorUserID: recipient, operationID: .init(uuid: UUID()),
                        targetUserID: senderID, action: .remove), now: now)
                case "preference":
                    _ = try await direct.setStrangerMessagePermission(command: .init(actorUserID: recipient,
                        operationID: .init(uuid: UUID()), permission: .deny), now: now)
                default:
                    _ = try await V2PostgresAccountDisableService(database: control, operatorPrincipal: "test-policy", now: { now })
                        .disable(.init(userID: recipient, operationID: UUID(), reason: .userRequested))
                }
            }
            do {
                var observed = false
                for _ in 0..<500 {
                    let waiting = try await sql.raw("""
                        SELECT count(*) AS value FROM pg_stat_activity
                        WHERE datname = current_database() AND wait_event_type = 'Lock'
                          AND query LIKE '%pg_advisory_xact_lock(%'
                        """).first(decoding: CountRow.self)?.value ?? 0
                    if waiting > 0 { observed = true; break }
                    try await Task.sleep(for: .milliseconds(10))
                }
                #expect(observed)
                #expect(try await count("im_v2.control_policy_test_commits", on: ownerSQL) == 0)
                await gate.releaseTransaction()
                try await reader.value
                try await writer.value
            } catch {
                writer.cancel()
                await gate.releaseTransaction()
                _ = await reader.result
                _ = await writer.result
                throw error
            }
            #expect(try await count("im_v2.control_policy_test_commits", on: ownerSQL) == 1)
            try await fence.withLockedPolicies(pairs: [.init(sender: senderUUID, recipient: memberTwoUUID)]) { _, policies in
                    let policy = try #require(policies[.init(sender: senderUUID, recipient: memberTwoUUID)])
                #expect(policy.blocked == (kind == "block"))
                #expect(!policy.isFriend)
                #expect(policy.allowsStrangers == (kind != "preference"))
                #expect(policy.recipient.isActive == (kind != "disable"))
            }
            // Target-local copies are deliberately unchanged: only control is authoritative.
            #expect(try await count("im_v2.user_blocks", on: ownerSQL) == 0)
            #expect(try await count("im_v2.account_disables", on: ownerSQL) == 0)
            await #expect(throws: CancellationError.self) {
                try await fence.withLockedPolicies(pairs: [.init(sender: senderUUID, recipient: memberTwoUUID)]) { _, _ in throw CancellationError() }
            }
            let pairKey = [senderUUID, memberTwoUUID].map { $0.uuidString.lowercased() }.sorted().joined(separator: "|")
            try await control.transaction { transaction in
                let check = try #require(transaction as? any SQLDatabase)
                struct Row: Decodable { let value: Bool }
                for key in [pairKey, "account-state:" + memberTwoUUID.uuidString,
                            "v2-stranger-message-preference:" + memberTwoUUID.uuidString.lowercased()] {
                    #expect(try await check.raw("SELECT pg_try_advisory_xact_lock(hashtextextended(\(bind: key), 0)) AS value")
                        .first(decoding: Row.self)?.value == true)
                }
            }
            try await fence.withLockedPolicies(pairs: [.init(sender: senderUUID, recipient: UUID())]) { _, policies in
                let policy = try #require(policies.values.first)
                #expect(!policy.recipient.isActive)
            }
            await #expect(throws: V2DirectSendControlPolicyError.invalidPair) {
                try await fence.withLockedPolicies(pairs: [.init(sender: senderUUID, recipient: senderUUID)]) { _, _ in Issue.record("invalid pair entered callback") }
            }
        }
    }


    @Test("Special-account audit clocks preserve message retries and concurrent recording", arguments: [V2AccountKind.system, .customerSupport])
    func specialAccountMessageClockBounds(kind: V2AccountKind) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let customer = UserID(uuid: memberTwoUUID)
            let profile = try forwardImportTestProfile()
            try await sql.raw("UPDATE im_v2.public_user_profiles SET account_kind = \(bind: kind.rawValue) WHERE user_id = \(bind: senderUUID)").run()
            try await sql.raw("INSERT INTO im_v2.special_accounts (account_user_id, stable_key, account_kind, allows_customer_messages, allows_service_messages, created_at, updated_at) VALUES (\(bind: senderUUID), 'clock_special_account', \(bind: kind.rawValue), \(bind: kind == .customerSupport), true, \(bind: base), \(bind: base))").run()
            let store = PostgresV2SpecialAccountMessagingStore(database: database)
            let account = try #require(try await store.resolveActiveAccount(stableKey: "clock_special_account"))
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder()), capacityProfile: profile, roomShardID: "room-a", now: { base })
            guard case .opened(let opened) = try await direct.open(actorUserID: customer, operationID: .init(uuid: UUID()), targetUserID: senderID) else { throw V2SpecialAccountMessagingError.corruptPersistenceState }
            let messages = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile, limits: .init(maxUTF8Bytes: 64), now: { base.addingTimeInterval(1) })
            if kind == .customerSupport {
                guard case .accepted = try await messages.send(.init(roomID: opened.roomID, actorUserID: customer, clientMessageID: .init(uuid: UUID()), text: "support request")) else { throw V2SpecialAccountMessagingError.corruptPersistenceState }
                #expect(try await count("im_v2.support_conversation_sessions WHERE state = 'open'", on: sql) == 1)
            }
            let clock = TestSequenceClock([base])
            let service = V2TrustedSpecialAccountMessagingService(store: store, directMessaging: direct, messages: messages, now: { clock.now() })
            func request(operation: ClientMessageID = .init(uuid: UUID()), fingerprint: String = "1234567890abcdef") throws -> V2TrustedSpecialAccountMessage {
                try .init(stableAccountKey: "clock_special_account", servicePrincipal: "clock-service", operatorID: kind == .customerSupport ? "clock-operator" : nil, operationID: operation, requestFingerprint: fingerprint, customerUserID: customer, text: "service message")
            }
            let original = try request()
            func snapshot() async throws -> String {
                try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.special_account_message_operations r),
                        'audit', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.special_account_message_audit r),
                        'messages', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.messages r),
                        'events', (SELECT jsonb_agg(to_jsonb(r) ORDER BY event_id) FROM im_v2.room_events r),
                        'direct_operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY actor_user_id, operation_id) FROM im_v2.direct_room_operations r),
                        'sessions', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.support_conversation_sessions r),
                        'admission', (SELECT jsonb_agg(to_jsonb(r) ORDER BY room_id) FROM im_v2.room_admission r),
                        'shard', (SELECT to_jsonb(r) FROM im_v2.shard_admission_pools r WHERE room_shard_id = 'room-a')
                    )::text AS value
                    """).first(decoding: StringValueRow.self)).value
            }
            let badClocks = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            var awaitingAudit: String?
            for bad in badClocks {
                clock.set([bad])
                await #expect(throws: V2SpecialAccountMessagingError.corruptPersistenceState) { _ = try await service.send(original) }
                #expect(try await count("im_v2.messages", on: sql) == (kind == .customerSupport ? 2 : 1))
                #expect(try await count("im_v2.special_account_message_operations", on: sql) == 0)
                #expect(try await count("im_v2.special_account_message_audit", on: sql) == 0)
                let state = try await snapshot()
                if let awaitingAudit { #expect(state == awaitingAudit) }
                else { awaitingAudit = state }
            }
            // A failure of the second insert must roll back the operation row,
            // while the independently accepted customer-visible message remains.
            clock.set([base.addingTimeInterval(2)])
            try await sql.raw("CREATE FUNCTION im_v2.fail_special_message_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'test audit failure'; END $$").run()
            try await sql.raw("CREATE TRIGGER fail_special_message_audit BEFORE INSERT ON im_v2.special_account_message_audit FOR EACH ROW EXECUTE FUNCTION im_v2.fail_special_message_audit()").run()
            await #expect(throws: (any Error).self) { _ = try await service.send(original) }
            #expect(try await snapshot() == awaitingAudit)
            try await sql.raw("DROP TRIGGER fail_special_message_audit ON im_v2.special_account_message_audit").run()
            try await sql.raw("DROP FUNCTION im_v2.fail_special_message_audit()").run()
            let results = try await withThrowingTaskGroup(of: V2SendMessageOutcome.self) { group in
                for _ in 0..<8 { group.addTask { try await service.send(original) } }
                var results: [V2SendMessageOutcome] = []
                for try await result in group { results.append(result) }
                return results
            }
            #expect(results.count == 8)
            let first = try #require(results.first)
            let receipt = try #require(first.acceptanceReceipt)
            for result in results { #expect(result == .idempotent(receipt)) }
            #expect(try await count("im_v2.special_account_message_operations", on: sql) == 1)
            #expect(try await count("im_v2.special_account_message_audit", on: sql) == 1)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.special_account_message_audit WHERE message_id = \(bind: receipt.messageID.uuidValue!) AND created_at = \(bind: base.addingTimeInterval(2)) AND (support_session_room_id IS NOT NULL) = \(bind: kind == .customerSupport)").first(decoding: CountRow.self)?.value == 1)
            let committed = try await snapshot()
            for bad in badClocks {
                clock.set([bad])
                #expect(try await service.send(original) == .idempotent(receipt))
                await #expect(throws: V2SpecialAccountMessagingError.idempotencyConflict) {
                    try await store.record(request: request(operation: original.operationID, fingerprint: "fedcba0987654321"), account: account, roomID: opened.roomID, outcome: first, now: bad)
                }
                #expect(try await snapshot() == committed)
            }
            for valid in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)] {
                clock.set([valid])
                let next = try request()
                guard case .accepted(let accepted) = try await service.send(next) else { throw V2SpecialAccountMessagingError.corruptPersistenceState }
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.special_account_message_audit WHERE message_id = \(bind: accepted.messageID.uuidValue!) AND created_at = \(bind: valid)").first(decoding: CountRow.self)?.value == 1)
            }
            #expect(try await count("im_v2.messages", on: sql) == (kind == .customerSupport ? 4 : 3))
            #expect(try await count("im_v2.special_account_message_operations", on: sql) == 3)
            #expect(try await count("im_v2.special_account_message_audit", on: sql) == 3)

        }
    }

    @Test("Moderation audit retention rejects invalid clocks and preserves authoritative operations")
    func moderationRetentionClockBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE user_id = \(bind: senderUUID)").run()
            let moderation = PostgresV2ModerationStore(database: database)
            var operations: [(V2ModerationCommand, V2ModerationResult)] = []
            for index in 0..<4 {
                let time = base.addingTimeInterval(Double(index) * 10)
                let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile, limits: .init(maxUTF8Bytes: 64), now: { time })
                guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "audit retention \(index)")) else { throw V2ModerationStoreError.corruptPersistenceState }
                let command = try V2ModerationCommand(roomID: roomID, actorUserID: senderID, operationID: .init(uuid: UUID()), action: .redactMessage, messageID: message.messageID, reasonCode: .init("abuse_spam"))
                guard case .applied(let result) = try await moderation.apply(command: command, capacityProfile: profile, eventID: .init(uuid: UUID()), now: time.addingTimeInterval(1)) else { throw V2ModerationStoreError.corruptPersistenceState }
                operations.append((command, result))
            }
            func snapshot(includeAudit: Bool) async throws -> String {
                try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'audit', CASE WHEN \(bind: includeAudit) THEN (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.moderation_audit_entries r) ELSE NULL END,
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.moderation_operations r),
                        'messages', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.messages r),
                        'events', (SELECT jsonb_agg(to_jsonb(r) ORDER BY event_id) FROM im_v2.room_events r),
                        'room', (SELECT to_jsonb(r) FROM im_v2.rooms r WHERE room_id = \(bind: roomUUID)),
                        'admission', (SELECT to_jsonb(r) FROM im_v2.room_admission r WHERE room_id = \(bind: roomUUID)),
                        'shard', (SELECT to_jsonb(r) FROM im_v2.shard_admission_pools r WHERE room_shard_id = 'room-a')
                    )::text AS value
                    """).first(decoding: StringValueRow.self)).value
            }
            let retention = PostgresV2ModerationAuditRetentionStore(database: database)
            let clock = TestSequenceClock([base])
            let worker = V2ModerationAuditRetentionWorker(store: retention, now: { clock.now() })
            let initial = try await snapshot(includeAudit: true)
            let business = try await snapshot(includeAudit: false)
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for bad in badDates {
                clock.set([bad])
                await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { _ = try await worker.runOnce(limit: 1) }
                await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { _ = try await retention.deleteExpiredAuditEntries(now: bad, limit: Int.max) }
                #expect(try await snapshot(includeAudit: true) == initial)
            }
            clock.set([base])
            for limit in [Int.min, -1, 0] {
                await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { _ = try await worker.runOnce(limit: limit) }
                await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { _ = try await retention.deleteExpiredAuditEntries(now: base, limit: limit) }
            }
            #expect(try await snapshot(includeAudit: true) == initial)
            let firstExpiry = base.addingTimeInterval(180 * 86_400 + 1)
            clock.set([firstExpiry.addingTimeInterval(-0.5)])
            #expect(try await worker.runOnce(limit: Int.max) == 0)
            #expect(try await snapshot(includeAudit: true) == initial)
            clock.set([firstExpiry])
            #expect(try await worker.runOnce(limit: 1) == 1)
            #expect(try await count("im_v2.moderation_audit_entries", on: sql) == 3)
            #expect(try await snapshot(includeAudit: false) == business)
            let afterFirst = try await snapshot(includeAudit: true)
            clock.set([base])
            #expect(try await worker.runOnce(limit: 1) == 0)
            #expect(try await snapshot(includeAudit: true) == afterFirst)
            for bad in badDates {
                clock.set([bad])
                await #expect(throws: V2ModerationStoreError.corruptPersistenceState) { _ = try await worker.runOnce(limit: 1) }
                #expect(try await snapshot(includeAudit: true) == afterFirst)
            }
            clock.set([firstExpiry.addingTimeInterval(20)])
            let removed = try await withThrowingTaskGroup(of: Int.self) { group in
                for _ in 0..<4 { group.addTask { try await worker.runOnce(limit: 1) } }
                var total = 0
                for try await value in group { #expect((0...1).contains(value)); total += value }
                return total
            }
            #expect(removed == 2)
            #expect(try await count("im_v2.moderation_audit_entries", on: sql) == 1)
            #expect(try await snapshot(includeAudit: false) == business)
            clock.set([firstExpiry.addingTimeInterval(30)])
            #expect(try await worker.runOnce(limit: Int.max) == 1)
            #expect(try await worker.runOnce(limit: 1) == 0)
            #expect(try await count("im_v2.moderation_audit_entries", on: sql) == 0)
            // Expiring an audit copy does not undo redaction or discard the
            // operation result. A normal retry must not recreate the audit.
            for (command, result) in operations {
                #expect(try await moderation.apply(command: command, capacityProfile: profile, eventID: .init(uuid: UUID()), now: base.addingTimeInterval(40)) == .idempotent(result))
            }
            #expect(try await count("im_v2.moderation_audit_entries", on: sql) == 0)
            #expect(try await snapshot(includeAudit: false) == business)
            #expect(try await count("im_v2.messages WHERE withdrawn_at IS NOT NULL", on: sql) == 4)
            #expect(try await count("im_v2.moderation_operations", on: sql) == 4)
        }
    }

    @Test("privacy closure waits for the first target receipt commit", arguments: [false, true])
    func directReceiptPreferenceCommitFence(closeViewer: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, target, controlSQL, targetSQL, _ in
            struct Fence: V2UserShardRouteFencing {
                let database: any Database
                func withCurrentRoute<Result: Sendable>(for userID: UserID,
                    _ operation: @escaping @Sendable (V2UserShardRoute, any Database) async throws -> Result) async throws -> Result {
                    try await database.transaction { transaction in
                        try await operation(.init(bucket: "user", observedRouterEpoch: 1), transaction)
                    }
                }
            }
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let source = EventID(uuid: UUID()), room = UUID()
            func candidate(_ source: EventID) throws -> V2UserStateEvent {
                try .init(sourceEventID: source, userID: .init(uuid: memberTwoUUID), kind: .directReadReceipt,
                    payload: JSONSerialization.data(withJSONObject: ["room_id": room.uuidString,
                        "reader_user_id": senderUUID.uuidString, "read_through_room_sequence": 7,
                        "recorded_at_ms": 1750000000000]), createdAt: now)
            }
            let event = try candidate(source)
            let projector = try V2RoutedUserStateEventProjector(routeFence: Fence(database: control),
                registry: V2StaticUserShardStorageRegistry(locations: [.init(bucket: "user", database: target, schema: "im_v2")]))
            try await targetSQL.raw("""
                CREATE FUNCTION im_v2.test_hold_first_receipt() RETURNS trigger LANGUAGE plpgsql AS $$
                BEGIN
                    PERFORM pg_advisory_xact_lock(8153782331::bigint);
                    RETURN NEW;
                END $$
                """).run()
            try await targetSQL.raw("CREATE TRIGGER test_hold_first_receipt BEFORE INSERT ON im_v2.user_state_event_receipts FOR EACH ROW EXECUTE FUNCTION im_v2.test_hold_first_receipt()").run()
            let gate = PostgreSQLTransactionGate()
            let blocker = Task {
                try await target.transaction { transaction in
                    let sql = try #require(transaction as? any SQLDatabase)
                    try await sql.raw("SELECT pg_advisory_xact_lock(8153782331::bigint)").run()
                    await gate.holdTransaction()
                }
            }
            await gate.waitUntilHeld()
            let delivery = Task { try await projector.project(event) }
            do {
                // Only the target INSERT can be waiting at this point. Its
                // control transaction has already acquired both shared locks.
                try await waitForAdvisoryWaiters(1, on: controlSQL)
            } catch {
                delivery.cancel()
                await gate.releaseTransaction()
                _ = try? await blocker.value
                _ = try? await delivery.value
                throw error
            }
            let preferences = PostgresV2ReadReceiptStore(database: control)
            let writer = Task {
                try await preferences.setPreferences(command: .init(actorUserID: .init(uuid: closeViewer ? memberTwoUUID : senderUUID),
                    operationID: .init(uuid: UUID()), allowsDirectReadReceipts: false, allowsGroupReadReceipts: true), now: now)
            }
            do {
                // The second blocked advisory request is the real preference
                // writer, not a simulated sleep or a second target candidate.
                try await waitForAdvisoryWaiters(2, on: controlSQL)
                #expect(try await count("im_v2.user_read_receipt_preferences", on: controlSQL) == 0)
                #expect(try await count("im_v2.user_state_event_receipts", on: targetSQL) == 0)
                #expect(try await count("im_v2.user_sync_log", on: targetSQL) == 0)
            } catch {
                delivery.cancel(); writer.cancel()
                await gate.releaseTransaction()
                _ = try? await blocker.value
                _ = try? await delivery.value
                _ = try? await writer.value
                throw error
            }
            await gate.releaseTransaction()
            try await blocker.value
            #expect(try await delivery.value == 1)
            guard case .updated = try await writer.value else { throw CancellationError() }
            #expect(try await targetSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: source.uuidValue!) AND (payload->>'is_visible')::boolean AND (payload->>'read_through_room_sequence')::bigint = 7").first(decoding: CountRow.self)?.value == 1)
            #expect(try await projector.project(event) == 1)
            let later = try candidate(.init(uuid: UUID()))
            #expect(try await projector.project(later) == 2)
            #expect(try await targetSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: later.sourceEventID.uuidValue!) AND NOT (payload->>'is_visible')::boolean AND (payload->>'read_through_room_sequence')::bigint = 0").first(decoding: CountRow.self)?.value == 1)
            #expect(try await count("im_v2.user_sync_log", on: targetSQL) == 2)
        }
    }


    @Test("Personal event operator replay is audited, bounded and fences previous leases")
    func userStateOperatorReplay() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let source = EventID(uuid: UUID())
            let outbox = try PostgresV2UserStateEventOutbox(database: database)
            for _ in 0..<3 {
                let event = try V2UserStateEvent(sourceEventID: source, userID: .init(uuid: UUID()),
                    kind: .membership, payload: Data("{}".utf8), createdAt: now)
                try await outbox.enqueue(event, in: sql)
            }
            let leases = try await outbox.claim(now: now, leaseDuration: 30, limit: 10)
            #expect(leases.count == 3)
            for lease in leases { try await outbox.retry(lease, disposition: .pause) }
            let first = try #require(leases.first)
            let store = PostgresV2DurableWorkReplayStore(database: database)
            let command = V2DurableWorkReplayCommand(operationID: UUID(), target: try .init(
                kind: .userStateEvent, sourceEventID: source, targetUserID: first.event.userID,
                projectionKind: "membership"), reason: .dataRepaired)
            let result = try await store.replay(command, operatorPrincipal: "test-operator", now: now)
            #expect(result.outcome == .requeued && !result.wasIdempotent)
            #expect(try await store.replay(command, operatorPrincipal: "test-operator", now: now).wasIdempotent)
            #expect(try await outbox.acknowledge(first, sequence: 1, now: now) == false)
            let batch = try V2DurableWorkEventReplayCommand(operationID: UUID(), kind: .userStateEvent,
                sourceEventID: source, reason: .dataRepaired, limit: 1)
            let pageOne = try await store.replayEvent(batch, operatorPrincipal: "test-operator", now: now)
            #expect(pageOne.requeued == 1 && pageOne.hasMore)
            let pageTwo = try await store.replayEvent(batch, operatorPrincipal: "test-operator", now: now)
            #expect(pageTwo.requeued == 1 && !pageTwo.hasMore)
            #expect(try await store.replayEvent(batch, operatorPrincipal: "test-operator", now: now).requeued == 0)
            #expect(try await count("im_v2.durable_work_replay_audit WHERE target_kind = 'user_state_event' AND outcome = 'requeued'", on: sql) == 3)
            #expect(try await count("im_v2.user_state_event_outbox WHERE state = 'pending' AND attempt = 0 AND delivered_at IS NULL AND user_sync_sequence IS NULL", on: sql) == 3)
            let replacements = try await outbox.claim(now: now, leaseDuration: 30, limit: 10)
            #expect(replacements.count == 3)
            for replacement in replacements {
                #expect(replacement.attempt == 1)
                #expect(!leases.contains { $0.token == replacement.token })
            }
            for lease in leases {
                try await outbox.retry(lease, disposition: .pause)
                #expect(try await outbox.acknowledge(lease, sequence: 1, now: now) == false)
            }
            #expect(try await count("im_v2.user_state_event_outbox WHERE state = 'leased'", on: sql) == 3)
            let conflict = V2DurableWorkReplayCommand(operationID: command.operationID, target: command.target,
                reason: .falsePositive)
            await #expect(throws: V2DurableWorkReplayStoreError.idempotencyConflict) {
                _ = try await store.replay(conflict, operatorPrincipal: "test-operator", now: now)
            }
        }
    }

    @Test("Durable replay audit clocks preserve not-paused results at database bounds", arguments: [946_684_800.0 - 211_813_488_000, 1_750_000_000.0, 946_684_800.0 + 9_223_371_331_200 - 10])
    func durableReplayAuditClockBounds(seconds: Double) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: seconds)
            let store = PostgresV2DurableWorkReplayStore(database: database)
            for kind in V2DurableWorkReplayTargetKind.allCases {
                let needsUser = kind == .userStateEvent || kind == .readReceiptPreferencePropagation || kind == .userProjection
                let target = try V2DurableWorkReplayTarget(kind: kind, sourceEventID: .init(uuid: UUID()), targetUserID: needsUser ? senderID : nil, projectionKind: kind == .userStateEvent ? "membership" : nil)
                let command = V2DurableWorkReplayCommand(operationID: UUID(), target: target, reason: .dependencyRecovered)
                let result = try await verifyDurableReplayClockRecovery(command, store: store, sql: sql, operatorPrincipal: "clock-replay", now: now, expected: .notPaused)
                #expect(result.outcome == .notPaused && !result.wasIdempotent)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.durable_work_replay_audit WHERE operation_id = \(bind: command.operationID) AND requested_at = \(bind: now)").first(decoding: CountRow.self)?.value == 1)
            }
            #expect(try await count("im_v2.durable_work_replay_audit WHERE outcome = 'not_paused'", on: sql) == Int64(V2DurableWorkReplayTargetKind.allCases.count))
            #expect(try await count("im_v2.durable_work_replay_audit WHERE outcome = 'processing'", on: sql) == 0)
        }
    }

    @Test("Invitation business clocks reject partial writes and preserve committed retries", arguments: ["approve", "reject"])
    func invitationStoreClockBounds(decision: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let applicant = UserID(uuid: UUID())
            try await sql.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE user_id = \(bind: senderUUID)").run()
            try await sql.raw("INSERT INTO im_v2.public_user_profiles (user_id, public_handle, display_name, created_at, updated_at) VALUES (\(bind: applicant.uuidValue!), 'invitation_clock_applicant', 'Clock Applicant', \(bind: base), \(bind: base))").run()
            let store = PostgresV2GroupInvitationStore(database: database)
            let profile = try forwardImportTestProfile()
            let inviteID = GroupInviteID(uuid: UUID())
            let creationID = GroupInviteOperationID(uuid: UUID())
            let submissionID = GroupJoinRequestOperationID(uuid: UUID())
            let requestID = GroupJoinRequestID(uuid: UUID())
            let decisionID = GroupJoinDecisionOperationID(uuid: UUID())
            let revocationID = GroupInviteOperationID(uuid: UUID())
            let digest = Data(repeating: 0x73, count: 32)
            func creation(createdAt: Date? = nil, evaluatedAt: Date? = nil, expiresAt: Date? = nil) -> V2GroupInviteCreatePersistenceRequest {
                .init(inviteID: inviteID, roomID: roomID, actorUserID: senderID, operationID: creationID, tokenDigest: digest, requestedLifetimeSeconds: 3600, expiresAt: expiresAt ?? base.addingTimeInterval(3600), maximumApprovedUses: 5, maximumActiveInvitesPerRoom: 20, createdAt: createdAt ?? base, evaluatedAt: evaluatedAt ?? base)
            }
            func submission(at date: Date) -> V2GroupJoinSubmissionPersistenceRequest {
                .init(requestID: requestID, applicantUserID: applicant, operationID: submissionID, tokenDigest: digest, note: "clock test", createdAt: date, maximumPendingRequestsPerApplicant: 20, maximumPendingRequestsPerInvite: 100)
            }
            func approve(at date: Date) async throws -> V2GroupJoinApprovalPersistenceOutcome {
                try await store.approve(roomID: roomID, requestID: requestID, reviewerUserID: senderID, operationID: decisionID, capacityProfile: profile, eventID: .init(uuid: UUID()), now: date)
            }
            func reject(at date: Date) async throws -> V2GroupJoinDecisionPreparationOutcome {
                try await store.reject(roomID: roomID, requestID: requestID, reviewerUserID: senderID, operationID: decisionID, now: date)
            }
            func snapshot() async throws -> String {
                try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'room', (SELECT to_jsonb(r) FROM im_v2.rooms r WHERE room_id = \(bind: roomUUID)),
                        'admission', (SELECT to_jsonb(r) FROM im_v2.room_admission r WHERE room_id = \(bind: roomUUID)),
                        'shard', (SELECT to_jsonb(r) FROM im_v2.shard_admission_pools r WHERE room_shard_id = 'room-a'),
                        'members', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, joined_revision) FROM im_v2.room_memberships r),
                        'invites', (SELECT jsonb_agg(to_jsonb(r) ORDER BY invite_id) FROM im_v2.group_invite_links r),
                        'requests', (SELECT jsonb_agg(to_jsonb(r) ORDER BY request_id) FROM im_v2.group_join_requests r),
                        'events', (SELECT count(*) FROM im_v2.room_events),
                        'operations', (SELECT count(*) FROM im_v2.room_membership_operations)
                    )::text AS value
                    """).first(decoding: StringValueRow.self)).value
            }
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let initial = try await snapshot()
            for bad in badDates {
                for request in [creation(createdAt: bad), creation(evaluatedAt: bad), creation(expiresAt: bad)] {
                    await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.preflightCreation(request) }
                    await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.create(request) }
                }
            }
            for request in [creation(expiresAt: base), creation(expiresAt: base.addingTimeInterval(-1)), creation(createdAt: Date(timeIntervalSince1970: 946_684_800.00000025), expiresAt: Date(timeIntervalSince1970: 946_684_800.00000075))] {
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.preflightCreation(request) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.create(request) }
            }
            #expect(try await snapshot() == initial)
            let invite = try await store.create(creation())
            #expect(invite.state == .active && invite.inviteID == inviteID)
            let invalidStoredTimes = ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"]
            for column in ["created_at", "expires_at"] {
                let literals = column == "created_at" ? ["-infinity", "294276-12-31 23:59:59.999999+00"] : ["infinity", "294276-12-31 23:59:59.999999+00"]
                for literal in literals {
                    // Preserve the production expiry > creation constraint.
                    try await sql.raw("UPDATE im_v2.group_invite_links SET created_at = \(bind: base), expires_at = \(bind: invite.expiresAt) WHERE invite_id = \(bind: inviteID.uuidValue!)").run()
                    if column == "created_at" && literal != "-infinity" {
                        try await sql.raw("UPDATE im_v2.group_invite_links SET created_at = \(bind: literal)::timestamptz, expires_at = 'infinity'::timestamptz WHERE invite_id = \(bind: inviteID.uuidValue!)").run()
                    } else {
                        try await sql.raw("UPDATE im_v2.group_invite_links SET \(unsafeRaw: column) = \(bind: literal)::timestamptz WHERE invite_id = \(bind: inviteID.uuidValue!)").run()
                    }
                    let before = try await snapshot()
                    await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.create(creation()) }
                    await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.preflightCreation(creation()) }
                    do {
                        await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.activeInvites(roomID: roomID, actorUserID: senderID, now: base) }
                        if column == "expires_at" {
                            await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.preview(tokenDigest: digest, applicantUserID: applicant, now: base) }
                            await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.submit(submission(at: base)) }
                            await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) {
                                try await store.submit(.init(requestID: .init(uuid: UUID()), applicantUserID: senderID, operationID: .init(uuid: UUID()),
                                    tokenDigest: digest, note: nil, createdAt: base, maximumPendingRequestsPerApplicant: 20, maximumPendingRequestsPerInvite: 100))
                            }
                        }
                    }
                    try #require(try await snapshot() == before)
                }
                try await sql.raw("UPDATE im_v2.group_invite_links SET created_at = \(bind: base), expires_at = \(bind: invite.expiresAt) WHERE invite_id = \(bind: inviteID.uuidValue!)").run()
            }
            let created = try await snapshot()
            for bad in badDates {
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.activeInvites(roomID: roomID, actorUserID: senderID, now: bad) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.preview(tokenDigest: digest, applicantUserID: applicant, now: bad) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.create(creation(evaluatedAt: bad)) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.preflightCreation(creation(evaluatedAt: bad)) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await store.submit(submission(at: bad)) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.revoke(inviteID: inviteID, roomID: roomID, actorUserID: senderID, operationID: revocationID, now: bad) }
                // Invalid replacement candidates do not replace a committed binding.
                let replay = try await store.create(creation(createdAt: bad, expiresAt: bad))
                #expect(replay.inviteID == inviteID && replay.createdAt == base && replay.expiresAt == invite.expiresAt)
                #expect(try await store.preflightCreation(creation(createdAt: bad, expiresAt: bad))?.inviteID == inviteID)
            }
            #expect(try await snapshot() == created)
            #expect(try await store.activeInvites(roomID: roomID, actorUserID: senderID, now: base).count == 1)
            guard case .available = try await store.preview(tokenDigest: digest, applicantUserID: applicant, now: base) else { throw V2GroupInvitationServiceError.corruptPersistenceState }
            guard case .submitted(let pending) = try await store.submit(submission(at: base.addingTimeInterval(10))) else { throw V2GroupInvitationServiceError.corruptPersistenceState }
            #expect(pending.requestID == requestID && pending.state == .pending)
            for literal in invalidStoredTimes {
                try await sql.raw("UPDATE im_v2.group_join_requests SET created_at = \(bind: literal)::timestamptz WHERE request_id = \(bind: requestID.uuidValue!)").run()
                let before = try await snapshot()
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.pendingRequests(roomID: roomID, reviewerUserID: senderID, cursor: nil, pageSize: 10, now: base) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.submit(submission(at: base)) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await approve(at: base.addingTimeInterval(20)) }
                try #require(try await snapshot() == before)
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await reject(at: base.addingTimeInterval(20)) }
                try #require(try await snapshot() == before)
            }
            try await sql.raw("UPDATE im_v2.group_join_requests SET created_at = \(bind: pending.createdAt) WHERE request_id = \(bind: requestID.uuidValue!)").run()
            let submitted = try await snapshot()
            for bad in badDates {
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await approve(at: bad) }
                await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { _ = try await reject(at: bad) }
                guard case .alreadyPending(let replay) = try await store.submit(submission(at: bad)) else { throw V2GroupInvitationServiceError.corruptPersistenceState }
                #expect(replay == pending)
                let page = try await store.pendingRequests(roomID: roomID, reviewerUserID: senderID, cursor: nil, pageSize: 10, now: bad)
                #expect(page.requests == [pending] && page.nextCursor == nil)
            }
            #expect(try await snapshot() == submitted)
            if decision == "approve" {
                guard case .approved(let result) = try await approve(at: base.addingTimeInterval(20)) else { throw V2GroupInvitationServiceError.corruptPersistenceState }
                #expect(result.state == .approved && result.decidedAt == base.addingTimeInterval(20))
                let completed = try await snapshot()
                for bad in badDates {
                    #expect(try await approve(at: bad) == .approved(result))
                    #expect(try await reject(at: bad) == .decisionConflict)
                }
                #expect(try await snapshot() == completed)
            } else {
                guard case .rejected(let result) = try await reject(at: base.addingTimeInterval(20)) else { throw V2GroupInvitationServiceError.corruptPersistenceState }
                #expect(result.state == .rejected && result.decidedAt == base.addingTimeInterval(20))
                let completed = try await snapshot()
                for bad in badDates {
                    #expect(try await reject(at: bad) == .rejected(result))
                    #expect(try await approve(at: bad) == .conflict)
                }
                #expect(try await snapshot() == completed)
            }
            func completedResponse() async throws -> V2GroupJoinRequestRecord {
                if decision == "approve" {
                    guard case .approved(let value) = try await approve(at: base) else { throw CancellationError() }
                    return value
                }
                guard case .rejected(let value) = try await reject(at: base) else { throw CancellationError() }
                return value
            }
            let originalResult = try await completedResponse()
            for column in ["created_at", "decided_at"] {
                for literal in invalidStoredTimes {
                    try await sql.raw("UPDATE im_v2.group_join_requests SET \(unsafeRaw: column) = \(bind: literal)::timestamptz WHERE request_id = \(bind: requestID.uuidValue!)").run()
                    let before = try await snapshot()
                    await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await completedResponse() }
                    if decision == "approve" { #expect(try await reject(at: base) == .decisionConflict) }
                    else {
                        #expect(try await approve(at: base) == .conflict)
                        await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.submit(submission(at: base)) }
                    }
                    #expect(try await snapshot() == before)
                }
                for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                             Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)] {
                    try await sql.raw("UPDATE im_v2.group_join_requests SET \(unsafeRaw: column) = \(bind: date) WHERE request_id = \(bind: requestID.uuidValue!)").run()
                    let before = try await snapshot()
                    let value = try await completedResponse()
                    #expect((column == "created_at" ? value.createdAt : value.decidedAt) == date)
                    #expect(value.requestID == originalResult.requestID && value.state == originalResult.state)
                    #expect(try await snapshot() == before)
                }
                let restored = column == "created_at" ? originalResult.createdAt : try #require(originalResult.decidedAt)
                try await sql.raw("UPDATE im_v2.group_join_requests SET \(unsafeRaw: column) = \(bind: restored) WHERE request_id = \(bind: requestID.uuidValue!)").run()
            }
            if decision == "approve" {
                for literal in ["infinity", "294276-12-31 23:59:59.999999+00"] {
                    try await sql.raw("UPDATE im_v2.group_invite_links SET expires_at = \(bind: literal)::timestamptz WHERE invite_id = \(bind: inviteID.uuidValue!)").run()
                    let before = try await snapshot()
                    await #expect(throws: V2GroupInvitationServiceError.corruptPersistenceState) { try await store.submit(submission(at: base)) }
                    #expect(try await snapshot() == before)
                }
                try await sql.raw("UPDATE im_v2.group_invite_links SET expires_at = \(bind: invite.expiresAt) WHERE invite_id = \(bind: inviteID.uuidValue!)").run()
            }
            #expect(try await count("im_v2.room_membership_operations", on: sql) == (decision == "approve" ? 1 : 0))
            #expect(try await sql.raw("SELECT approved_use_count::bigint AS value FROM im_v2.group_invite_links").first(decoding: CountRow.self)?.value == (decision == "approve" ? 1 : 0))
            // Exact expiry remains a normal business result, not a clock error.
            #expect(try await store.create(creation(evaluatedAt: invite.expiresAt)).state == .expired)
            #expect(try await store.activeInvites(roomID: roomID, actorUserID: senderID, now: invite.expiresAt).isEmpty)
            #expect(try await store.preview(tokenDigest: digest, applicantUserID: applicant, now: invite.expiresAt) == .unavailable)
            try await store.revoke(inviteID: inviteID, roomID: roomID, actorUserID: senderID, operationID: revocationID, now: base.addingTimeInterval(30))
            let revoked = try await snapshot()
            for bad in badDates {
                try await store.revoke(inviteID: inviteID, roomID: roomID, actorUserID: senderID, operationID: revocationID, now: bad)
                #expect(try await store.create(creation(evaluatedAt: bad)).state == .revoked)
            }
            #expect(try await snapshot() == revoked)
        }
    }

    @Test("Invite creation clocks retain recoverable work and preserve published bindings", arguments: ["resume", "retry", "pause"])
    func inviteCreationClockBounds(phase: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, owner, sql, ownerSQL, room in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            try await ownerSQL.raw("UPDATE im_v2.room_memberships SET role = 'owner' WHERE user_id = \(bind: senderUUID)").run()
            try await ownerSQL.raw("DELETE FROM im_v2.public_user_profiles").run()
            try await sql.raw("INSERT INTO im_v2.room_owner_routes(room_id, room_shard_id, route_epoch, created_at, updated_at) VALUES (\(bind: room.uuidValue!), 'room-b', 0, \(bind: base), \(bind: base)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at").run()
            let directory = PostgresV2GroupInviteDirectory(database: control)
            let routed = V2RoutedGroupInvitationStore(controlDatabase: control, router: V2PostgresRoomShardRouter(database: control), owners: try V2StaticRoomShardStorageRegistry(locations: [.init(shardID: "room-b", database: owner, schema: "im_v2")]))
            let operation = GroupInviteOperationID(uuid: UUID())
            let invite = GroupInviteID(uuid: UUID())
            let digest = Data(repeating: 0x65, count: 32)
            func candidate(createdAt: Date? = nil, evaluatedAt: Date? = nil, expiresAt: Date? = nil) -> V2GroupInviteCreatePersistenceRequest {
                .init(inviteID: invite, roomID: room, actorUserID: .init(uuid: senderUUID), operationID: operation, tokenDigest: digest, requestedLifetimeSeconds: 3600, expiresAt: expiresAt ?? base.addingTimeInterval(3600), maximumApprovedUses: 5, maximumActiveInvitesPerRoom: 20, createdAt: createdAt ?? base, evaluatedAt: evaluatedAt ?? base)
            }
            func snapshot() async throws -> [String] {
                struct State: Decodable { let value: String }
                let controlState = try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'directory', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.group_invite_directory r),
                        'jobs', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.group_invite_creation_recovery r)
                    )::text AS value
                    """).first(decoding: State.self)).value
                let ownerState = try #require(try await ownerSQL.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY invite_id), '[]'::jsonb)::text AS value FROM im_v2.group_invite_links r").first(decoding: State.self)).value
                return [controlState, ownerState]
            }
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let nearUpperBound = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            let initial = try await snapshot()
            for bad in invalidDates {
                for request in [candidate(createdAt: bad), candidate(evaluatedAt: bad), candidate(expiresAt: bad)] {
                    await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.prepare(request) }
                }
            }
            for request in [candidate(evaluatedAt: nearUpperBound), candidate(expiresAt: base), candidate(expiresAt: base.addingTimeInterval(-1)), candidate(createdAt: Date(timeIntervalSince1970: 946_684_800.00000025), expiresAt: Date(timeIntervalSince1970: 946_684_800.00000075))] {
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.prepare(request) }
            }
            #expect(try await snapshot() == initial)
            let intent = try await directory.prepare(candidate())
            let prepared = try await snapshot()
            for bad in invalidDates {
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.claim(limit: 1, now: bad, lease: 60, maximumActiveInvitesPerRoom: 20) }
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { try await directory.finalize(intent, now: bad) }
            }
            for duration in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 1e-9, 0, -1, 301] {
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.claim(limit: 1, now: base, lease: duration, maximumActiveInvitesPerRoom: 20) }
            }
            await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.claim(limit: 1, now: nearUpperBound, lease: 60, maximumActiveInvitesPerRoom: 20) }
            #expect(try await snapshot() == prepared)
            #expect(try await directory.claim(limit: 1, now: base.addingTimeInterval(29), lease: 60, maximumActiveInvitesPerRoom: 20).isEmpty)
            let first = try #require(try await directory.claim(limit: 1, now: base.addingTimeInterval(30), lease: 60, maximumActiveInvitesPerRoom: 20).first)
            #expect(first.attemptCount == 1)
            let claimed = try await snapshot()
            for bad in invalidDates {
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.fail(first, reason: .dependencyUnavailable, retryAt: bad, now: base.addingTimeInterval(31)) }
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.fail(first, reason: .permissionDenied, retryAt: nil, now: bad) }
            }
            for retry in [base, base.addingTimeInterval(31)] {
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await directory.fail(first, reason: .dependencyUnavailable, retryAt: retry, now: base.addingTimeInterval(31)) }
            }
            await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) {
                _ = try await directory.fail(first, reason: .dependencyUnavailable, retryAt: Date(timeIntervalSince1970: 946_684_800.00000075), now: Date(timeIntervalSince1970: 946_684_800.00000025))
            }
            #expect(try await snapshot() == claimed)
            #expect(try await directory.claim(limit: 1, now: base.addingTimeInterval(89), lease: 60, maximumActiveInvitesPerRoom: 20).isEmpty)
            let second = try #require(try await directory.claim(limit: 1, now: base.addingTimeInterval(90), lease: 60, maximumActiveInvitesPerRoom: 20).first)
            #expect(second.attemptCount == 2 && second.claimToken != first.claimToken)
            let reclaimed = try await snapshot()
            #expect(try await !directory.fail(first, reason: .permissionDenied, retryAt: nil, now: base.addingTimeInterval(91)))
            #expect(try await snapshot() == reclaimed)
            #expect(try await directory.fail(second, reason: .dependencyUnavailable, retryAt: base.addingTimeInterval(105), now: base.addingTimeInterval(91)))
            #expect(try await directory.claim(limit: 1, now: base.addingTimeInterval(104), lease: 60, maximumActiveInvitesPerRoom: 20).isEmpty)
            struct FailingResumer: V2GroupInviteCreationResuming {
                let shouldPause: Bool
                func resumeCreation(_ intent: V2GroupInviteCreationIntent, now: Date) async throws {
                    if shouldPause { throw V2GroupInvitationServiceError.permissionDenied }
                    throw ProfilePropagationShadowFailure.interrupted
                }
            }
            let clock = TestSequenceClock([base])
            let resumer: any V2GroupInviteCreationResuming = phase == "resume" ? routed : FailingResumer(shouldPause: phase == "pause")
            let worker = V2GroupInviteCreationRecoveryWorker(jobs: directory, invitations: resumer, now: { clock.now() })
            let attemptDates = phase == "pause" ? invalidDates : invalidDates + [nearUpperBound]
            for (index, bad) in attemptDates.enumerated() {
                let time = base.addingTimeInterval(105 + Double(index) * 60)
                clock.set(phase == "resume" ? [time, bad] : [time, time, bad])
                await #expect(throws: V2GroupInviteDirectoryError.invalidRequest) { _ = try await worker.runOnce(limit: 1) }
                #expect(try await count("im_v2.group_invite_creation_recovery WHERE state = 'claimed' AND completed_at IS NULL AND last_error_code = 'dependency_unavailable'", on: sql) == 1)
                #expect(try await sql.raw("SELECT attempt_count AS value FROM im_v2.group_invite_creation_recovery").first(decoding: CountRow.self)?.value == Int64(index + 3))
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.group_invite_creation_recovery WHERE lease_expires_at = \(bind: time.addingTimeInterval(60))").first(decoding: CountRow.self)?.value == 1)
                #expect(try await count("im_v2.group_invite_directory WHERE state = 'prepared'", on: sql) == 1)
                #expect(try await count("im_v2.group_invite_links", on: ownerSQL) == 0)
            }
            // The original operation recovers through the real current owner.
            // Its immutable creation/expiry dates are not replaced by retries.
            clock.set([base.addingTimeInterval(1000)])
            let healthy = V2GroupInviteCreationRecoveryWorker(jobs: directory, invitations: routed, now: { clock.now() })
            let report = try await healthy.runOnce()
            #expect(report.attempted == 1 && report.completed == 1 && report.deferred == 0 && report.paused == 0 && report.lostClaim == 0)
            #expect(try await healthy.runOnce().attempted == 0)
            #expect(try await directory.resolve(tokenDigest: digest) == .init(inviteID: invite, roomID: room))
            #expect(try await count("im_v2.group_invite_links", on: ownerSQL) == 1)
            #expect(try await count("im_v2.group_invite_creation_recovery WHERE state = 'completed'", on: sql) == 1)
            let replay = try await routed.create(candidate(evaluatedAt: base.addingTimeInterval(1001)))
            #expect(replay.inviteID == invite && replay.createdAt == base && replay.expiresAt == base.addingTimeInterval(3600))
            let completed = try await snapshot()
            #expect(try await !directory.fail(second, reason: .permissionDenied, retryAt: nil, now: base.addingTimeInterval(1001)))
            try await directory.finalize(intent, now: base.addingTimeInterval(1002))
            #expect(try await snapshot() == completed)
        }
    }

    @Test("Content review clocks preserve leases, retry recovery and durable decisions", arguments: ["clear", "review", "violation", "superseded"])
    func contentReviewClockBounds(scenario: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            try await sql.raw("UPDATE im_v2.shard_admission_pools SET valid_until = \(bind: base.addingTimeInterval(2000))").run()
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: profile, limits: .init(maxUTF8Bytes: 64), now: { base })
            guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "review clock boundary")) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            let store = PostgresV2ContentReviewStore(database: database)
            let finding = try V2ContentReviewFinding(category: "clock_policy", severity: 2, confidence: 0.8)
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'jobs', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.content_review_jobs r),
                        'decisions', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.content_review_decisions r),
                        'findings', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id, category) FROM im_v2.content_review_findings r),
                        'cases', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.content_review_cases r),
                        'messages', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.messages r),
                        'moderation', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.moderation_operations r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let initial = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.claimPending(now: invalid, leaseDuration: 30, limit: 1) }
            }
            for duration in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.000000001] {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.claimPending(now: base, leaseDuration: duration, limit: 1) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.claimPending(now: upper, leaseDuration: 30, limit: 1) }
            #expect(try await store.claimPending(now: badDates[0], leaseDuration: 30, limit: 0).isEmpty)
            #expect(try await snapshot() == initial)
            let first = try #require(try await store.claimPending(now: base, leaseDuration: 30, limit: 1).first)
            let claimed = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.validateAndRenew(first, now: invalid, leaseDuration: 30) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.resolve(first, verdict: .reviewRequired(finding), now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.scheduleRetry(first, disposition: .retry(at: invalid), now: base) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.scheduleRetry(first, disposition: .pause, now: invalid) }
                #expect(try await snapshot() == claimed)
            }
            for duration in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.000000001] {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.validateAndRenew(first, now: base, leaseDuration: duration) }
            }
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.validateAndRenew(first, now: upper, leaseDuration: 30) }
            #expect(try await snapshot() == claimed)
            #expect(try await store.validateAndRenew(first, now: base.addingTimeInterval(-20), leaseDuration: 30) == .current)
            #expect(try await sql.raw("SELECT lease_expires_at = \(bind: base.addingTimeInterval(30)) AS exists FROM im_v2.content_review_jobs").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await store.validateAndRenew(first, now: base.addingTimeInterval(5), leaseDuration: 30) == .current)
            #expect(try await store.validateAndRenew(first, now: base.addingTimeInterval(1), leaseDuration: 1) == .current)
            #expect(try await store.claimPending(now: base.addingTimeInterval(34), leaseDuration: 30, limit: 1).isEmpty)
            let second = try #require(try await store.claimPending(now: base.addingTimeInterval(35), leaseDuration: 30, limit: 1).first)
            #expect(second.claimToken != first.claimToken && second.attempt == 2)
            let reclaimed = try await snapshot()
            #expect(try await store.validateAndRenew(first, now: base.addingTimeInterval(36), leaseDuration: 30) == .lostLease)
            #expect(try await store.resolve(first, verdict: .clear, now: base.addingTimeInterval(36)) == false)
            #expect(try await store.stageViolation(first, finding: finding) == false)
            try await store.scheduleRetry(first, disposition: .retry(at: base), now: badDates[0])
            #expect(try await snapshot() == reclaimed)
            if scenario == "superseded" {
                try await sql.raw("UPDATE im_v2.messages SET content_revision = 2 WHERE message_id = \(bind: message.messageID.uuidValue!)").run()
                let edited = try await snapshot()
                for invalid in badDates {
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.validateAndRenew(second, now: invalid, leaseDuration: 30) }
                    #expect(try await snapshot() == edited)
                }
                #expect(try await store.validateAndRenew(second, now: base.addingTimeInterval(36), leaseDuration: 30) == .superseded)
                #expect(try await count("im_v2.content_review_jobs WHERE state = 'superseded' AND claim_token IS NULL AND completed_at IS NOT NULL", on: sql) == 1)
                #expect(try await count("im_v2.content_review_decisions", on: sql) == 0)
                return
            }
            try await store.scheduleRetry(second, disposition: .retry(at: base.addingTimeInterval(-1)), now: badDates[0])
            let retry = try #require(try await store.claimPending(now: base.addingTimeInterval(35), leaseDuration: 30, limit: 1).first)
            #expect(retry.attempt == 3)
            try await store.scheduleRetry(retry, disposition: .pause, now: base.addingTimeInterval(36))
            #expect(try await store.claimPending(now: base.addingTimeInterval(100), leaseDuration: 30, limit: 1).isEmpty)
            let replay = try await verifyDurableReplayClockRecovery(.init(operationID: UUID(), target: .init(kind: .contentReview, sourceEventID: .init(message.messageID.rawValue)), reason: .dependencyRecovered), store: PostgresV2DurableWorkReplayStore(database: database), sql: sql, operatorPrincipal: "integration-test", now: base.addingTimeInterval(40))
            #expect(replay.outcome == .requeued)
            let clock = TestSequenceClock([base])
            let moderation = V2TrustedSafetyModerationService(store: PostgresV2ModerationStore(database: database), safetyActorUserID: .init(uuid: UUID()), capacityProfile: profile, now: { clock.now() })
            struct Reviewer: V2ContentReviewing {
                let verdict: V2ContentReviewVerdict
                func review(_ input: V2ContentReviewInput) async throws -> V2ContentReviewVerdict { verdict }
            }
            let clearingWorker = try V2ContentReviewWorker(store: store, reviewer: Reviewer(verdict: .clear), moderation: moderation, retryPolicy: .init(initialDelay: 2, maximumDelay: 2, maximumAttempts: 100, jitterFraction: 0), now: { clock.now() })
            for (index, invalid) in badDates.enumerated() {
                for phase in 0..<2 {
                    let time = base.addingTimeInterval(100 + Double(index * 80 + phase * 40))
                    clock.set(phase == 0 ? [time, invalid] : [time, time, invalid])
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await clearingWorker.runOnce(limit: 1) }
                    #expect(try await sql.raw("SELECT state = 'claimed' AND retry_count = \(bind: Int64(index * 2 + phase + 1)) AND lease_expires_at = \(bind: time.addingTimeInterval(30)) AND completed_at IS NULL AND decision IS NULL AS exists FROM im_v2.content_review_jobs").first(decoding: ExistsRow.self)?.exists == true)
                    #expect(try await count("im_v2.content_review_decisions", on: sql) == 0)
                    #expect(try await count("im_v2.content_review_findings", on: sql) == 0)
                    #expect(try await count("im_v2.content_review_cases", on: sql) == 0)
                    #expect(try await count("im_v2.moderation_operations", on: sql) == 0)
                }
            }
            clock.set([base.addingTimeInterval(800)])
            let verdict: V2ContentReviewVerdict = scenario == "violation" ? .violation(finding) : (scenario == "review" ? .reviewRequired(finding) : .clear)
            let healthy = try V2ContentReviewWorker(store: store, reviewer: Reviewer(verdict: verdict), moderation: moderation, now: { clock.now() })
            #expect(try await healthy.runOnce(limit: 1) == .init(claimedCount: 1, resolvedCount: 1, redactedCount: scenario == "violation" ? 1 : 0, releasedCount: 0))
            #expect(try await healthy.runOnce(limit: 1) == .init(claimedCount: 0, resolvedCount: 0, redactedCount: 0, releasedCount: 0))
            #expect(try await count("im_v2.content_review_decisions", on: sql) == 1)
            #expect(try await count("im_v2.content_review_findings", on: sql) == (scenario == "clear" ? 0 : 1))
            #expect(try await count("im_v2.content_review_cases", on: sql) == (scenario == "review" ? 1 : 0))
            #expect(try await count("im_v2.moderation_operations", on: sql) == (scenario == "violation" ? 1 : 0))
            #expect(try await sql.raw("SELECT (withdrawn_at IS NOT NULL) = \(bind: scenario == "violation") AS exists FROM im_v2.messages WHERE message_id = \(bind: message.messageID.uuidValue!)").first(decoding: ExistsRow.self)?.exists == true)
        }
    }

