            #expect(try await snapshot(targetSQL) == importReclaimed)
            let recoveredCopier = try V2LocalFilesystemForwardMediaCopier(sources: ["room-a": sourceProvider], target: targetProvider, now: { badDates[0] })
            #expect(try await recoveredCopier.copy(nextImport) == copied)
            // Completion after a wall-clock rollback must not shorten the
            // already reserved object's retention deadline.
            #expect(try await importer.complete(nextImport, receipt: copied, result: passed ? .passed : .failed, now: base.addingTimeInterval(9)))
            if passed {
                #expect(try await targetSQL.raw("SELECT state = 'available' AND expires_at = \(bind: base.addingTimeInterval(610)) AS exists FROM im_v2.media_objects WHERE media_id = \(bind: nextImport.targetMediaID.uuidValue!)").first(decoding: ExistsRow.self)?.exists == true)
                let ready = try await snapshot(targetSQL)
                for invalid in badDates {
                    await #expect(throws: V2ForwardInboxError.corruptPersistenceState) {
                        try await PostgresV2RoomWriteStore(database: targetDB).importForwardExport(export, capacityProfile: profile, limits: limits, identifiers: V2AcceptanceIDFactory().make(at: base), now: invalid)
                    }
                    #expect(try await snapshot(targetSQL) == ready)
                    #expect(try await count("im_v2.messages", on: targetSQL) == 0)
                }
            }
            let outcome = try await PostgresV2RoomWriteStore(database: targetDB).importForwardExport(export, capacityProfile: profile, limits: limits, identifiers: V2AcceptanceIDFactory().make(at: base.addingTimeInterval(50)), now: base.addingTimeInterval(50))
            if passed { guard case .accepted = outcome else { throw V2ForwardInboxError.corruptPersistenceState } }
            else { #expect(outcome == .rejected(code: "MEDIA_UNAVAILABLE")) }
            let terminal = try #require(try await inbox.terminalReceipt(exportID: export.intent.exportID))
            let beforeReceipt = try await snapshot(sourceSQL)
            for invalid in badDates {
                await #expect(throws: V2ForwardExportError.corruptPersistenceState) { try await receipts.record(terminal, now: invalid) }
                #expect(try await snapshot(sourceSQL) == beforeReceipt)
            }
            try await receipts.record(terminal, now: base.addingTimeInterval(520))
            let receivedTerminal = try await snapshot(sourceSQL), finalTarget = try await snapshot(targetSQL)
            for invalid in badDates {
                try await receipts.record(terminal, now: invalid)
                #expect(try await prepare(invalid) == export)
                #expect(try await PostgresV2RoomWriteStore(database: targetDB).importForwardExport(export, capacityProfile: profile, limits: limits, identifiers: V2AcceptanceIDFactory().make(at: base), now: invalid) == outcome)
                #expect(try await importer.claim(exportID: export.intent.exportID, now: invalid, leaseDuration: 30) == nil)
                #expect(try await importer.reject(nextImport, now: invalid) == false)
            }
            #expect(try await snapshot(sourceSQL) == receivedTerminal)
            #expect(try await snapshot(targetSQL) == finalTarget)
            clock.set([base.addingTimeInterval(521)])
            let finished = try await delivery.runOnce(sourceShardID: "room-a", limit: 1)
            #expect(finished.completed == 1 && finished.deferred == 0)
            #expect(try await delivery.runOnce(sourceShardID: "room-a", limit: 1).claimed == 0)
            #expect(try await count("im_v2.message_forward_export_receipts", on: sourceSQL) == 1)
            #expect(try await count("im_v2.messages", on: targetSQL) == (passed ? 1 : 0))
        }
    }

    @Test("Media lifecycle clocks preserve durable replay and complete every scan scheduling state", arguments: ["pending", "claimed", "retry", "paused"], [false, true])
    func mediaLifecycleClockBounds(schedule: String, passed: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let device = DeviceID(uuid: UUID()), mediaID = MediaID(uuid: UUID()), operation = MediaUploadOperationID(uuid: UUID())
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at) VALUES (\(bind: senderUUID), \(bind: device.uuidValue!), \(bind: base), \(bind: base), \(bind: Date().addingTimeInterval(3600)))").run()
            let store = PostgresV2MediaStore(database: database)
            let command = try V2RequestMediaUploadCommand(actorUserID: senderID, operationID: operation, mediaID: mediaID, contentType: "image/png", byteCount: 42, limits: .init(maximumBytes: 1024))
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'media', (SELECT jsonb_agg(to_jsonb(r) ORDER BY media_id) FROM im_v2.media_objects r),
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.media_upload_operations r),
                        'uploads', (SELECT jsonb_agg(to_jsonb(r) ORDER BY upload_session_id) FROM im_v2.media_upload_grants r),
                        'downloads', (SELECT jsonb_agg(to_jsonb(r) ORDER BY download_session_id) FROM im_v2.media_download_grants r),
                        'scans', (SELECT jsonb_agg(to_jsonb(r) ORDER BY media_id) FROM im_v2.media_scan_outbox r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let invalidPairs = [(base, base), (base, base.addingTimeInterval(-1)), (Date(timeIntervalSince1970: 946_684_800.00000025), Date(timeIntervalSince1970: 946_684_800.00000075))]
            let initial = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.requestUpload(command, deviceID: device, expiresAt: base.addingTimeInterval(600), now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.requestUpload(command, deviceID: device, expiresAt: invalid, now: base) }
                #expect(try await snapshot() == initial)
            }
            for (start, end) in invalidPairs {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.requestUpload(command, deviceID: device, expiresAt: end, now: start) }
            }
            #expect(try await snapshot() == initial)
            let upload = try await store.requestUpload(command, deviceID: device, expiresAt: base.addingTimeInterval(600), now: base)
            let registered = try await snapshot()
            let conflict = try V2RequestMediaUploadCommand(actorUserID: senderID, operationID: operation, mediaID: mediaID, contentType: "image/png", byteCount: 43, limits: .init(maximumBytes: 1024))
            for invalid in badDates {
                #expect(try await store.requestUpload(command, deviceID: device, expiresAt: invalid, now: invalid) == upload)
                await #expect(throws: V2MediaStoreError.idempotencyConflict) { try await store.requestUpload(conflict, deviceID: device, expiresAt: invalid, now: invalid) }
                #expect(try await snapshot() == registered)
            }
            // A replay still works if only the newly proposed deadline is bad.
            let replayService = V2MediaService(store: store, limits: try .init(maximumBytes: 1024, temporaryLifetime: .infinity), now: { base })
            #expect(try await replayService.requestUpload(actorUserID: senderID, deviceID: device, operationID: operation, mediaID: mediaID, contentType: "image/png", byteCount: 42) == upload)
            let sessions = PostgresV2MediaUploadSessionStore(database: database)
            let claim = try await sessions.claimUpload(ownerUserID: senderID, deviceID: device, uploadSessionID: upload.uploadSessionID, now: base, leaseDuration: 30)
            try await sessions.completeUploadTarget(claim, now: base.addingTimeInterval(1))
            let consumed = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.markUploadCompleted(ownerUserID: senderID, deviceID: device, mediaID: mediaID, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.uploadStatus(ownerUserID: senderID, deviceID: device, mediaID: mediaID, now: invalid) }
                #expect(try await snapshot() == consumed)
            }
            try await store.markUploadCompleted(ownerUserID: senderID, deviceID: device, mediaID: mediaID, now: base.addingTimeInterval(2))
            let scans = PostgresV2MediaScanStore(database: database)
            if schedule != "pending" {
                let scan = try #require(try await scans.claimPending(now: base.addingTimeInterval(3), leaseDuration: 30, limit: 1).first)
                if schedule == "retry" { try await scans.scheduleRetry(scan, disposition: .retry(at: base.addingTimeInterval(60)), now: base.addingTimeInterval(3)) }
                if schedule == "paused" { try await scans.scheduleRetry(scan, disposition: .pause, now: base.addingTimeInterval(3)) }
            }
            let scanning = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.recordScanResult(mediaID: mediaID, passed: passed, now: invalid) }
                #expect(try await snapshot() == scanning)
            }
            try await store.recordScanResult(mediaID: mediaID, passed: passed, now: base.addingTimeInterval(4))
            #expect(try await sql.raw("SELECT state = 'completed' AND completed_at = \(bind: base.addingTimeInterval(4)) AND claim_token IS NULL AND lease_expires_at IS NULL AND next_attempt_at IS NULL AND paused_at IS NULL AS exists FROM im_v2.media_scan_outbox").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await store.uploadStatus(ownerUserID: senderID, deviceID: device, mediaID: mediaID, now: base.addingTimeInterval(5)) == (passed ? .available : .failed))
            let scanned = try await snapshot()
            await #expect(throws: V2MediaStoreError.invalidStateTransition) { try await store.recordScanResult(mediaID: mediaID, passed: !passed, now: base.addingTimeInterval(5)) }
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.assertAvailableForReference(ownerUserID: senderID, mediaIDs: [mediaID], now: invalid) }
                try await store.assertAvailableForReference(ownerUserID: senderID, mediaIDs: [], now: invalid)
            }
            #expect(try await store.uploadStatus(ownerUserID: senderID, deviceID: device, mediaID: mediaID, now: base.addingTimeInterval(600)) == .expired)
            #expect(try await snapshot() == scanned)
            if !passed { return }
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { base.addingTimeInterval(5) })
            guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "media lifecycle", media: [.init(mediaID: mediaID)])) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(try await count("im_v2.user_sync_log", on: sql) == 0)
            let beforeDownload = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.requestDownload(requesterUserID: senderID, deviceID: device, mediaID: mediaID, expiresAt: base.addingTimeInterval(60), now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.requestDownload(requesterUserID: senderID, deviceID: device, mediaID: mediaID, expiresAt: invalid, now: base) }
                #expect(try await snapshot() == beforeDownload)
            }
            for (start, end) in invalidPairs {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.requestDownload(requesterUserID: senderID, deviceID: device, mediaID: mediaID, expiresAt: end, now: start) }
            }
            #expect(try await snapshot() == beforeDownload)
            let download = try await store.requestDownload(requesterUserID: senderID, deviceID: device, mediaID: mediaID, expiresAt: base.addingTimeInterval(60), now: base.addingTimeInterval(8))
            let downloads = PostgresV2MediaDownloadSessionStore(database: database)
            let downloadClaim = try await downloads.claimDownload(requesterUserID: senderID, deviceID: device, downloadSessionID: download.downloadSessionID, now: base.addingTimeInterval(9), leaseDuration: 15)
            try await downloads.completeDownload(downloadClaim, now: base.addingTimeInterval(10))
            #expect(try await count("im_v2.media_download_grants WHERE state = 'consumed'", on: sql) == 1)
            #expect(try await count("im_v2.messages", on: sql) == 1)
        }
    }

    @Test("Media session clock failures preserve leases and normal provider exchange recovers")
    func mediaSessionClockBounds() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let device = DeviceID(uuid: UUID()), uploadMedia = MediaID(uuid: UUID()), downloadMedia = MediaID(uuid: UUID())
            // A fresh, live local device fixture; only business timestamps vary.
            let deviceExpiry = Date().addingTimeInterval(3600)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at) VALUES (\(bind: senderUUID), \(bind: device.uuidValue!), \(bind: base), \(bind: base), \(bind: deviceExpiry))").run()
            let media = PostgresV2MediaStore(database: database)
            let upload = try await media.requestUpload(.init(actorUserID: senderID, operationID: .init(uuid: UUID()), mediaID: uploadMedia, contentType: "image/png", byteCount: 42, limits: .init(maximumBytes: 1024)), deviceID: device, expiresAt: base.addingTimeInterval(600), now: base)
            try await sql.raw("INSERT INTO im_v2.media_objects (media_id, owner_user_id, content_type, byte_count, state, upload_session_id, expires_at, state_updated_at, created_at) VALUES (\(bind: downloadMedia.uuidValue!), \(bind: senderUUID), 'image/png', 42, 'available', \(bind: UUID()), \(bind: base.addingTimeInterval(600)), \(bind: base), \(bind: base))").run()
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { base })
            guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "media session clock", media: [.init(mediaID: downloadMedia)])) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(try await count("im_v2.user_sync_log", on: sql) == 0)
            let download = try await media.requestDownload(requesterUserID: senderID, deviceID: device, mediaID: downloadMedia, expiresAt: base.addingTimeInterval(600), now: base)
            let uploads = PostgresV2MediaUploadSessionStore(database: database)
            let downloads = PostgresV2MediaDownloadSessionStore(database: database)
            func claimUpload(at time: Date, duration: TimeInterval = 30) async throws -> V2ClaimedMediaUpload {
                try await uploads.claimUpload(ownerUserID: senderID, deviceID: device, uploadSessionID: upload.uploadSessionID, now: time, leaseDuration: duration)
            }
            func claimDownload(at time: Date, duration: TimeInterval = 30) async throws -> V2ClaimedMediaDownload {
                try await downloads.claimDownload(requesterUserID: senderID, deviceID: device, downloadSessionID: download.downloadSessionID, now: time, leaseDuration: duration)
            }
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'media', (SELECT jsonb_agg(to_jsonb(r) ORDER BY media_id) FROM im_v2.media_objects r),
                        'operations', (SELECT jsonb_agg(to_jsonb(r) ORDER BY operation_id) FROM im_v2.media_upload_operations r),
                        'uploads', (SELECT jsonb_agg(to_jsonb(r) ORDER BY upload_session_id) FROM im_v2.media_upload_grants r),
                        'downloads', (SELECT jsonb_agg(to_jsonb(r) ORDER BY download_session_id) FROM im_v2.media_download_grants r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let initial = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await claimUpload(at: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await claimDownload(at: invalid) }
            }
            for duration in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.000000001] {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await claimUpload(at: base, duration: duration) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await claimDownload(at: base, duration: duration) }
            }
            for duration in [Double.nan, 0, -1] {
                await #expect(throws: V2MediaUploadSessionStoreError.invalidRequest) { try await claimUpload(at: base, duration: duration) }
                await #expect(throws: V2MediaDownloadSessionStoreError.invalidRequest) { try await claimDownload(at: base, duration: duration) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await claimUpload(at: upper) }
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await claimDownload(at: upper) }
            #expect(try await snapshot() == initial)
            let firstUpload = try await claimUpload(at: base), firstDownload = try await claimDownload(at: base)
            let claimed = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await uploads.completeUploadTarget(firstUpload, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await downloads.completeDownload(firstDownload, now: invalid) }
                #expect(try await snapshot() == claimed)
            }
            await #expect(throws: V2MediaUploadSessionStoreError.sessionUnavailable) { try await claimUpload(at: base.addingTimeInterval(29)) }
            await #expect(throws: V2MediaDownloadSessionStoreError.sessionUnavailable) { try await claimDownload(at: base.addingTimeInterval(29)) }
            await #expect(throws: V2MediaUploadSessionStoreError.sessionUnavailable) { try await uploads.completeUploadTarget(firstUpload, now: base.addingTimeInterval(30)) }
            await #expect(throws: V2MediaDownloadSessionStoreError.sessionUnavailable) { try await downloads.completeDownload(firstDownload, now: base.addingTimeInterval(30)) }
            #expect(try await snapshot() == claimed)
            let nextUpload = try await claimUpload(at: base.addingTimeInterval(30)), nextDownload = try await claimDownload(at: base.addingTimeInterval(30))
            #expect(nextUpload.claimToken != firstUpload.claimToken && nextDownload.claimToken != firstDownload.claimToken)
            let reclaimed = try await snapshot()
            await #expect(throws: V2MediaUploadSessionStoreError.sessionUnavailable) { try await uploads.completeUploadTarget(firstUpload, now: base.addingTimeInterval(31)) }
            await #expect(throws: V2MediaDownloadSessionStoreError.sessionUnavailable) { try await downloads.completeDownload(firstDownload, now: badDates[0]) }
            try await uploads.releaseUploadTarget(firstUpload)
            try await downloads.releaseDownload(firstDownload)
            #expect(try await snapshot() == reclaimed)
            try await uploads.releaseUploadTarget(nextUpload)
            try await downloads.releaseDownload(nextDownload)
            struct Provider: V2MediaUploadObjectProvider, V2MediaObjectProvider {
                func issueUploadTarget(mediaID: MediaID, contentType: String, byteCount: Int64, expiresAt: Date) async throws -> V2MediaProviderObjectTarget {
                    .init(url: URL(string: "https://media.invalid/upload")!, expiresAt: expiresAt, expectedByteCount: byteCount)
                }
                func issueDownloadTarget(mediaID: MediaID, expiresAt: Date) async throws -> V2MediaProviderObjectTarget {
                    .init(url: URL(string: "https://media.invalid/download")!, expiresAt: expiresAt, expectedByteCount: 42)
                }
            }
            let clock = TestSequenceClock([base.addingTimeInterval(60)])
            let uploadService = try V2MediaUploadProviderSessionService(store: uploads, provider: Provider(), now: { clock.now() })
            let downloadService = try V2MediaProviderSessionService(store: downloads, provider: Provider(), now: { clock.now() })
            for (index, invalid) in badDates.enumerated() {
                // Signing succeeds, then the completion clock becomes invalid.
                // The service must release its exact claim so a healthy retry works.
                clock.set([base.addingTimeInterval(60), base.addingTimeInterval(60), invalid])
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await uploadService.exchangeUpload(actorUserID: senderID, deviceID: device, uploadSessionID: upload.uploadSessionID) }
                clock.set([base.addingTimeInterval(60), base.addingTimeInterval(60), invalid])
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await downloadService.exchangeDownload(actorUserID: senderID, deviceID: device, downloadSessionID: download.downloadSessionID) }
                for table in ["media_upload_grants", "media_download_grants"] {
                    #expect(try await sql.raw("SELECT state = 'pending' AND claim_token IS NULL AND lease_expires_at IS NULL AND redeemed_at IS NULL AND retry_count = \(bind: Int64(index + 3)) AS exists FROM im_v2.\(unsafeRaw: table)").first(decoding: ExistsRow.self)?.exists == true)
                }
            }
            clock.set([base.addingTimeInterval(61)])
            #expect(try await uploadService.exchangeUpload(actorUserID: senderID, deviceID: device, uploadSessionID: upload.uploadSessionID).expiresAt == upload.expiresAt)
            #expect(try await downloadService.exchangeDownload(actorUserID: senderID, deviceID: device, downloadSessionID: download.downloadSessionID).expiresAt == download.expiresAt)
            for table in ["media_upload_grants", "media_download_grants"] {
                #expect(try await sql.raw("SELECT state = 'consumed' AND claim_token IS NULL AND lease_expires_at IS NULL AND redeemed_at = \(bind: base.addingTimeInterval(61)) AS exists FROM im_v2.\(unsafeRaw: table)").first(decoding: ExistsRow.self)?.exists == true)
            }
            let completed = try await snapshot()
            await #expect(throws: V2MediaUploadSessionStoreError.sessionUnavailable) { try await claimUpload(at: base.addingTimeInterval(62)) }
            await #expect(throws: V2MediaDownloadSessionStoreError.sessionUnavailable) { try await claimDownload(at: base.addingTimeInterval(62)) }
            try await uploads.releaseUploadTarget(firstUpload)
            try await downloads.releaseDownload(firstDownload)
            #expect(try await snapshot() == completed)
            #expect(try await count("im_v2.messages", on: sql) == 1)
            #expect(try await count("im_v2.message_media_references", on: sql) == 1)
        }
    }

    @Test("Media maintenance validates clocks and preserves scan, purge and retention state", arguments: ["passed", "failed", "expired"])
    func mediaMaintenanceClockBounds(scenario: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let scanID = UUID(), purgeID = UUID(), unreferencedID = UUID(), referencedID = UUID()
            for (id, state, expiry) in [(scanID, "scanning", base.addingTimeInterval(scenario == "expired" ? 1 : 1000)), (purgeID, "expired", base), (unreferencedID, "available", base.addingTimeInterval(-1)), (referencedID, "available", base.addingTimeInterval(1000))] {
                try await sql.raw("""
                    INSERT INTO im_v2.media_objects (media_id, owner_user_id, content_type, byte_count, state, upload_session_id, expires_at, state_updated_at, created_at)
                    VALUES (\(bind: id), \(bind: senderUUID), 'image/png', 42, \(bind: state), \(bind: UUID()), \(bind: expiry), \(bind: base), \(bind: base))
                    """).run()
            }
            try await sql.raw("INSERT INTO im_v2.media_scan_outbox (media_id, state, created_at) VALUES (\(bind: scanID), 'pending', \(bind: base))").run()
            try await sql.raw("INSERT INTO im_v2.media_purge_outbox (media_id, reason, state, created_at) VALUES (\(bind: purgeID), 'unreferenced_expired', 'pending', \(bind: base))").run()
            let messages = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: try forwardImportTestProfile(), limits: try .init(maxUTF8Bytes: 64), now: { base })
            guard case .accepted(let message) = try await messages.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "retention boundary", media: [.init(mediaID: .init(uuid: referencedID))])) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            try await sql.raw("UPDATE im_v2.messages SET withdrawn_at = \(bind: base.addingTimeInterval(20)), withdrawn_by_user_id = \(bind: senderUUID) WHERE message_id = \(bind: message.messageID.uuidValue)").run()
            let scan = PostgresV2MediaScanStore(database: database)
            let purge = PostgresV2MediaPurgeStore(database: database)
            let retention = PostgresV2MediaRetentionStore(database: database)
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'media', (SELECT jsonb_agg(to_jsonb(r) ORDER BY media_id) FROM im_v2.media_objects r),
                        'scans', (SELECT jsonb_agg(to_jsonb(r) ORDER BY media_id) FROM im_v2.media_scan_outbox r),
                        'purges', (SELECT jsonb_agg(to_jsonb(r) ORDER BY media_id) FROM im_v2.media_purge_outbox r),
                        'messages', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id) FROM im_v2.messages r),
                        'references', (SELECT jsonb_agg(to_jsonb(r) ORDER BY message_id, media_id) FROM im_v2.message_media_references r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let initial = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scan.claimPending(now: invalid, leaseDuration: 30, limit: 1) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await purge.claimPending(now: invalid, leaseDuration: 30, limit: 1) }
                await #expect(throws: V2MediaRetentionStoreError.invalidRequest) { try await retention.expireEligibleMedia(now: invalid, withdrawnRetention: 60, limit: 10) }
            }
            for duration in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.000000001] {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scan.claimPending(now: base, leaseDuration: duration, limit: 1) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await purge.claimPending(now: base, leaseDuration: duration, limit: 1) }
                // The reference was withdrawn exactly now. A positive age
                // that vanishes must not expire this newly withdrawn media.
                await #expect(throws: V2MediaRetentionStoreError.invalidRequest) { try await retention.expireEligibleMedia(now: base.addingTimeInterval(20), withdrawnRetention: duration, limit: 10) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            let lower = Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + 30)
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scan.claimPending(now: upper, leaseDuration: 30, limit: 1) }
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await purge.claimPending(now: upper, leaseDuration: 30, limit: 1) }
            await #expect(throws: V2MediaRetentionStoreError.invalidRequest) { try await retention.expireEligibleMedia(now: lower, withdrawnRetention: 60, limit: 10) }
            #expect(try await scan.claimPending(now: badDates[0], leaseDuration: 30, limit: 0).isEmpty)
            #expect(try await purge.claimPending(now: badDates[0], leaseDuration: 30, limit: 0).isEmpty)
            #expect(try await snapshot() == initial)
            let firstScan = try #require(try await scan.claimPending(now: base, leaseDuration: 30, limit: 1).first)
            let firstPurge = try #require(try await purge.claimPending(now: base, leaseDuration: 30, limit: 1).first)
            let claimed = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scan.complete(firstScan, result: .passed, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await purge.markCompleted(firstPurge, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scan.scheduleRetry(firstScan, disposition: .retry(at: invalid), now: base) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await purge.scheduleRetry(firstPurge, disposition: .retry(at: invalid), now: base) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await scan.scheduleRetry(firstScan, disposition: .pause, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await purge.scheduleRetry(firstPurge, disposition: .pause, now: invalid) }
                #expect(try await snapshot() == claimed)
            }
            #expect(try await scan.claimPending(now: base.addingTimeInterval(29), leaseDuration: 30, limit: 1).isEmpty)
            #expect(try await purge.claimPending(now: base.addingTimeInterval(29), leaseDuration: 30, limit: 1).isEmpty)
            let nextScan = try #require(try await scan.claimPending(now: base.addingTimeInterval(30), leaseDuration: 30, limit: 1).first)
            let nextPurge = try #require(try await purge.claimPending(now: base.addingTimeInterval(30), leaseDuration: 30, limit: 1).first)
            #expect(nextScan.attempt == 2 && nextScan.claimToken != firstScan.claimToken)
            #expect(nextPurge.attempt == 2 && nextPurge.claimToken != firstPurge.claimToken)
            let reclaimed = try await snapshot()
            try await scan.complete(firstScan, result: .passed, now: badDates[0])
            try await purge.markCompleted(firstPurge, now: base)
            try await scan.scheduleRetry(firstScan, disposition: .retry(at: base), now: badDates[0])
            try await purge.scheduleRetry(firstPurge, disposition: .retry(at: base), now: badDates[0])
            #expect(try await snapshot() == reclaimed)
            try await scan.scheduleRetry(nextScan, disposition: .retry(at: base.addingTimeInterval(-1)), now: badDates[0])
            try await purge.scheduleRetry(nextPurge, disposition: .retry(at: base.addingTimeInterval(-1)), now: badDates[0])
            let retryScan = try #require(try await scan.claimPending(now: base.addingTimeInterval(30), leaseDuration: 30, limit: 1).first)
            let retryPurge = try #require(try await purge.claimPending(now: base.addingTimeInterval(30), leaseDuration: 30, limit: 1).first)
            #expect(retryScan.attempt == 3 && retryPurge.attempt == 3)
            try await scan.scheduleRetry(retryScan, disposition: .pause, now: base.addingTimeInterval(31))
            try await purge.scheduleRetry(retryPurge, disposition: .pause, now: base.addingTimeInterval(31))
            #expect(try await scan.claimPending(now: base.addingTimeInterval(100), leaseDuration: 30, limit: 1).isEmpty)
            #expect(try await purge.claimPending(now: base.addingTimeInterval(100), leaseDuration: 30, limit: 1).isEmpty)
            let replay = PostgresV2DurableWorkReplayStore(database: database)
            for (kind, id) in [(V2DurableWorkReplayTargetKind.mediaScan, scanID), (.mediaPurge, purgeID)] {
                let result = try await verifyDurableReplayClockRecovery(.init(operationID: UUID(), target: try .init(kind: kind, sourceEventID: .init(uuid: id)), reason: .dependencyRecovered), store: replay, sql: sql, operatorPrincipal: "integration-test", now: base.addingTimeInterval(32))
                #expect(result.outcome == .requeued)
            }
            struct Scanner: V2MediaScanProvider {
                let result: V2MediaScanResult
                func scan(mediaID: MediaID) async throws -> V2MediaScanResult { result }
            }
            struct Purger: V2MediaPurgeProvider { func purge(mediaID: MediaID) async throws {} }
            let scanner = try V2MediaScanWorker(store: scan, provider: Scanner(result: scenario == "failed" ? .failed : .passed), maximumConcurrency: 1, now: { base.addingTimeInterval(33) })
            #expect(try await scanner.runOnce(limit: 1) == .init(claimedCount: 1, completedCount: 1, releasedCount: 0))
            let expectedState = scenario == "expired" ? "scanning" : (scenario == "passed" ? "available" : "failed")
            #expect(try await sql.raw("SELECT state = \(bind: expectedState) AS exists FROM im_v2.media_objects WHERE media_id = \(bind: scanID)").first(decoding: ExistsRow.self)?.exists == true)
            let purger = try V2MediaPurgeWorker(store: purge, provider: Purger(), maximumConcurrency: 1, now: { base.addingTimeInterval(33) })
            #expect(try await purger.runOnce(limit: 1) == .init(claimedCount: 1, completedCount: 1, releasedCount: 0))
            #expect(try await count("im_v2.media_scan_outbox WHERE state = 'completed'", on: sql) == 1)
            #expect(try await count("im_v2.media_purge_outbox WHERE state = 'completed'", on: sql) == 1)
            #expect(try await retention.expireEligibleMedia(now: base.addingTimeInterval(79), withdrawnRetention: 60, limit: 10) == (scenario == "expired" ? 2 : 1))
            #expect(try await sql.raw("SELECT state = 'available' AS exists FROM im_v2.media_objects WHERE media_id = \(bind: referencedID)").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await retention.expireEligibleMedia(now: base.addingTimeInterval(80), withdrawnRetention: 60, limit: 10) == 1)
            #expect(try await retention.expireEligibleMedia(now: base.addingTimeInterval(80), withdrawnRetention: 60, limit: 10) == 0)
            let finalPurger = try V2MediaPurgeWorker(store: purge, provider: Purger(), maximumConcurrency: 1, now: { base.addingTimeInterval(81) })
            let pendingPurges = scenario == "expired" ? 3 : 2
            #expect(try await finalPurger.runOnce(limit: 10) == .init(claimedCount: pendingPurges, completedCount: pendingPurges, releasedCount: 0))
            #expect(try await count("im_v2.media_purge_outbox WHERE state = 'completed'", on: sql) == Int64(pendingPurges + 1))
            #expect(try await count("im_v2.messages", on: sql) == 1)
            #expect(try await count("im_v2.message_media_references", on: sql) == 1)
        }
    }

    @Test("Push endpoint clock failures preserve state and completed version replays", arguments: [false, true])
    func pushEndpointClockBounds(ownedDisable: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            // The device is a fresh, owned fixture with a live database-clock
            // session. Only the mutation timestamp is varied by this test.
            let base = Date(timeIntervalSince1970: Date().timeIntervalSince1970.rounded(.down))
            let deviceUUID = UUID(), device = DeviceID(uuid: deviceUUID)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at, session_expires_at) VALUES (\(bind: senderUUID), \(bind: deviceUUID), \(bind: base), \(bind: base), \(bind: base.addingTimeInterval(3600)))").run()
            let store = PostgresV2PushDeviceEndpointStore(database: database, envelopeKey: try .init(rawBytes: Data(repeating: 0x6a, count: 32)))
            let firstRegistration = try V2PushDeviceEndpointRegistration(provider: .apns, environment: .development, token: String(repeating: "a", count: 64))
            let replacement = try V2PushDeviceEndpointRegistration(provider: .apns, environment: .production, token: String(repeating: "b", count: 64))
            let badDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'devices', (SELECT jsonb_agg(to_jsonb(r) ORDER BY device_id) FROM im_v2.auth_devices r),
                        'endpoints', (SELECT jsonb_agg(to_jsonb(r) ORDER BY device_id, provider) FROM im_v2.push_device_endpoints r),
                        'intents', (SELECT jsonb_agg(to_jsonb(r) ORDER BY device_id) FROM im_v2.push_device_intents r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            func disable(_ endpoint: V2PushDeviceEndpoint, at time: Date) async throws {
                if ownedDisable {
                    try await store.disableOwnedEndpoint(actorUserID: senderID, deviceID: device, now: time)
                } else { try await store.disable(endpoint, now: time) }
            }
            let empty = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.register(actorUserID: senderID, deviceID: device, endpoint: firstRegistration, now: invalid) }
                #expect(try await snapshot() == empty)
            }
            try await store.register(actorUserID: senderID, deviceID: device, endpoint: firstRegistration, now: base)
            let first = try #require(try await store.endpoint(for: device))
            let registered = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.register(actorUserID: senderID, deviceID: device, endpoint: replacement, now: invalid) }
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await disable(first, at: invalid) }
                #expect(try await snapshot() == registered)
            }
            try await disable(first, at: base.addingTimeInterval(1))
            #expect(try await store.endpoint(for: device) == nil)
            try await store.register(actorUserID: senderID, deviceID: device, endpoint: replacement, now: base.addingTimeInterval(2))
            let replaced = try #require(try await store.endpoint(for: device))
            #expect(replaced.generation != first.generation)
            try await store.disable(first, now: base.addingTimeInterval(3))
            #expect(try await store.endpoint(for: device) == replaced)

            let firstClaim = try V2PushIntentSessionClaim(requestID: UUID(), expectedEpoch: 0)
            let beforeClaim = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: firstClaim, now: invalid) }
                #expect(try await snapshot() == beforeClaim)
            }
            #expect(try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: firstClaim, now: base.addingTimeInterval(4)) == 1)
            let secondClaim = try V2PushIntentSessionClaim(requestID: UUID(), expectedEpoch: 1)
            let versionOne = try V2PushIntentVersion(epoch: 1, revision: 1)
            let claimed = try await snapshot()
            for invalid in badDates {
                #expect(try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: firstClaim, now: invalid) == 1)
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: secondClaim, now: invalid) }
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionOne, intent: .enabled(firstRegistration), now: invalid) }
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionOne, intent: .disabled, now: invalid) }
                #expect(try await snapshot() == claimed)
            }
            try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionOne, intent: .enabled(firstRegistration), now: base.addingTimeInterval(5))
            let enabled = try await snapshot()
            let versionTwo = try V2PushIntentVersion(epoch: 1, revision: 2)
            for invalid in badDates {
                try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionOne, intent: .enabled(firstRegistration), now: invalid)
                await #expect(throws: V2PushDeviceEndpointError.intentConflict) { try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionOne, intent: .disabled, now: invalid) }
                await #expect(throws: V2PushDeviceEndpointError.unavailable) { try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionTwo, intent: .disabled, now: invalid) }
                #expect(try await snapshot() == enabled)
            }
            try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionTwo, intent: .disabled, now: base.addingTimeInterval(6))
            #expect(try await store.endpoint(for: device) == nil)
            let disabled = try await snapshot()
            for invalid in badDates {
                #expect(try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: firstClaim, now: invalid) == 1)
                try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionTwo, intent: .disabled, now: invalid)
                #expect(try await snapshot() == disabled)
            }
            #expect(try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: secondClaim, now: base.addingTimeInterval(7)) == 2)
            try await store.publishIntent(actorUserID: senderID, deviceID: device, version: .init(epoch: 2, revision: 1), intent: .enabled(replacement), now: base.addingTimeInterval(8))
            let restored = try #require(try await store.endpoint(for: device))
            #expect(restored.environment == .production && restored.token == replacement.token)
            let final = try await snapshot()
            for invalid in badDates {
                await #expect(throws: V2PushDeviceEndpointError.staleIntent) { try await store.publishIntent(actorUserID: senderID, deviceID: device, version: versionTwo, intent: .disabled, now: invalid) }
                #expect(try await store.claimIntentSession(actorUserID: senderID, deviceID: device, claim: secondClaim, now: invalid) == 2)
                #expect(try await snapshot() == final)
            }
        }
    }

    @Test("Push wake clock failures preserve admission and recover without double spending", arguments: ["sent", "failed", "suppressed"])
    func pushWakeClockBounds(outcome: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let messages = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: try forwardImportTestProfile(), limits: try .init(maxUTF8Bytes: 64), now: { base })
            guard case .accepted = try await messages.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "push clock")) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            struct Event: Decodable { let event_id: UUID }
            let event = try #require(try await sql.raw("SELECT event_id FROM im_v2.room_events WHERE room_id = \(bind: roomUUID) AND room_sequence = 1").first(decoding: Event.self)).event_id
            let device = UUID(), mutedDevice = UUID(), dispatch = UUID(), mutedDispatch = UUID()
            try await sql.raw("INSERT INTO im_v2.push_campaigns (campaign_id, state, updated_at) VALUES ('wake', 'enabled', \(bind: base))").run()
            try await sql.raw("""
                INSERT INTO im_v2.push_device_budgets (device_id, campaign_id, window_started_at, max_work_units, max_new_key_operations)
                VALUES (\(bind: device), 'wake', \(bind: base), 1, 1), (\(bind: mutedDevice), 'wake', \(bind: base), 1, 1)
                """).run()
            try await sql.raw("""
                INSERT INTO im_v2.push_wake_outbox (dispatch_id, source_event_id, target_user_id, target_device_id, campaign_id, budget_window_started_at, requires_new_key_operation, created_at)
                VALUES (\(bind: dispatch), \(bind: event), \(bind: memberTwoUUID), \(bind: device), 'wake', \(bind: base), TRUE, \(bind: base)),
                       (\(bind: mutedDispatch), \(bind: event), \(bind: memberThreeUUID), \(bind: mutedDevice), 'wake', \(bind: base), TRUE, \(bind: base))
                """).run()
            try await sql.raw("INSERT INTO im_v2.user_room_preferences (user_id, room_id, mute_until, updated_at) VALUES (\(bind: memberThreeUUID), \(bind: roomUUID), \(bind: base.addingTimeInterval(3600)), \(bind: base))").run()
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'wakes', (SELECT jsonb_agg(to_jsonb(r) ORDER BY dispatch_id) FROM im_v2.push_wake_outbox r),
                        'budgets', (SELECT jsonb_agg(to_jsonb(r) ORDER BY device_id, campaign_id, window_started_at) FROM im_v2.push_device_budgets r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let store = PostgresV2PushWakeStore(database: database)
            let initial = try await snapshot()
            let badSeconds: [Double] = [.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12]
            for seconds in badSeconds {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.claimAdmitted(now: Date(timeIntervalSince1970: seconds), leaseDuration: 30, limit: 1) }
                #expect(try await snapshot() == initial)
            }
            for duration in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.0000001] {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.claimAdmitted(now: base, leaseDuration: duration, limit: 1) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.claimAdmitted(now: upper, leaseDuration: 30, limit: 1) }
            for limit in [Int.min, 0] {
                #expect(try await store.claimAdmitted(now: .init(timeIntervalSince1970: .nan), leaseDuration: 30, limit: limit).isEmpty)
            }
            for duration in [Double.nan, 0, -1] {
                #expect(try await store.claimAdmitted(now: .init(timeIntervalSince1970: .nan), leaseDuration: duration, limit: 1).isEmpty)
            }
            #expect(try await snapshot() == initial)
            // The upper bound controls SQL work, not an eager allocation when
            // only one wake is eligible after muted work is suppressed.
            let first = try #require(try await store.claimAdmitted(now: base.addingTimeInterval(1), leaseDuration: 30, limit: Int.max).first)
            #expect(first.wake.dispatchID == dispatch)
            let claimed = try await snapshot()
            for seconds in badSeconds {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.markSent(first, now: Date(timeIntervalSince1970: seconds)) }
                #expect(try await snapshot() == claimed)
            }
            #expect(try await store.claimAdmitted(now: base.addingTimeInterval(30), leaseDuration: 30, limit: 1).isEmpty)
            let second = try #require(try await store.claimAdmitted(now: base.addingTimeInterval(31), leaseDuration: 30, limit: 1).first)
            #expect(second.claimToken != first.claimToken)
            let reclaimed = try await snapshot()
            try await store.release(first)
            try await store.suppress(first, reason: .endpointUnavailable)
            try await store.markSent(first, now: base.addingTimeInterval(32))
            #expect(try await snapshot() == reclaimed)
            try await store.release(second)

            let clock = TestSequenceClock([base])
            let provider = PushTimestampProvider(outcome: outcome)
            let worker = V2PushWakeWorker(store: store, provider: provider, maximumConcurrency: 1, now: { clock.now() })
            let invalidCompletions = outcome == "suppressed" ? [Double.nan] : badSeconds
            for (index, seconds) in invalidCompletions.enumerated() {
                clock.set([base.addingTimeInterval(40 + Double(index) * 40), Date(timeIntervalSince1970: seconds)])
                #expect(try await worker.runOnce(limit: 1) == .init(admittedCount: 1, sentCount: 0, releasedCount: outcome == "suppressed" ? 0 : 1))
                let state = outcome == "suppressed" ? "suppressed" : "pending"
                #expect(try await sql.raw("SELECT state = \(bind: state) AND claim_token IS NULL AND lease_expires_at IS NULL AND sent_at IS NULL AS exists FROM im_v2.push_wake_outbox WHERE dispatch_id = \(bind: dispatch)").first(decoding: ExistsRow.self)?.exists == true)
            }
            #expect(await provider.dispatches() == Array(repeating: dispatch, count: invalidCompletions.count))
            let recovery = PushTimestampProvider(outcome: "sent")
            clock.set([base.addingTimeInterval(400)])
            let healthy = V2PushWakeWorker(store: store, provider: recovery, maximumConcurrency: 1, now: { clock.now() })
            if outcome == "suppressed" {
                #expect(try await healthy.runOnce(limit: 1) == .init(admittedCount: 0, sentCount: 0, releasedCount: 0))
                #expect(await recovery.dispatches().isEmpty)
            } else {
                #expect(try await healthy.runOnce(limit: 1) == .init(admittedCount: 1, sentCount: 1, releasedCount: 0))
                #expect(await recovery.dispatches() == [dispatch])
                #expect(try await sql.raw("SELECT state = 'sent' AND sent_at = \(bind: base.addingTimeInterval(400)) AS exists FROM im_v2.push_wake_outbox WHERE dispatch_id = \(bind: dispatch)").first(decoding: ExistsRow.self)?.exists == true)
            }
            #expect(try await store.claimAdmitted(now: base.addingTimeInterval(401), leaseDuration: 30, limit: Int.max).isEmpty)
            #expect(try await sql.raw("SELECT used_work_units = 1 AND used_new_key_operations = 1 AS exists FROM im_v2.push_device_budgets WHERE device_id = \(bind: device)").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await sql.raw("SELECT used_work_units = 0 AND used_new_key_operations = 0 AS exists FROM im_v2.push_device_budgets WHERE device_id = \(bind: mutedDevice)").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await sql.raw("SELECT state = 'suppressed' AND suppression_reason = 'conversation_muted' AND admitted_at IS NULL AS exists FROM im_v2.push_wake_outbox WHERE dispatch_id = \(bind: mutedDispatch)").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await count("im_v2.messages", on: sql) == 1)
        }
    }

    @Test("Group wakes preserve leases and newer revisions across invalid clocks", arguments: [false, true])
    func groupWakeClockBounds(routed: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .large) { database, target, sql, targetSQL, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let messages = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: try forwardImportTestProfile(), limits: try .init(maxUTF8Bytes: 64), now: { base })
            func send() async throws {
                guard case .accepted = try await messages.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "wake boundary")) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            }
            try await send()
            let durable = PostgresV2GroupEventWakeStore(database: database)
            let store: any V2GroupEventWakeStore
            if routed {
                store = try V2RoutedGroupEventWakeStore(ownerStores: ["a": durable, "b": PostgresV2GroupEventWakeStore(database: target)])
            } else { store = durable }
            let limit = routed ? 2 : 1
            func snapshot(on connection: any SQLDatabase) async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await connection.raw("SELECT COALESCE(jsonb_agg(to_jsonb(w) ORDER BY room_id), '[]'::jsonb)::text AS value FROM im_v2.group_event_wake_outbox w").first(decoding: State.self)).value
            }
            let initial = try await snapshot(on: sql)
            let initialTarget = try await snapshot(on: targetSQL)
            let badSeconds: [Double] = [.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12]
            for seconds in badSeconds {
                await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await store.claimPending(now: Date(timeIntervalSince1970: seconds), leaseDuration: 15, limit: limit) }
            }
            for duration in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.0000001, 0, -1] {
                await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await store.claimPending(now: base, leaseDuration: duration, limit: limit) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)
            await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await store.claimPending(now: upper, leaseDuration: 15, limit: limit) }
            #expect(try await snapshot(on: sql) == initial)
            #expect(try await snapshot(on: targetSQL) == initialTarget)
            let first = try #require(try await store.claimPending(now: base.addingTimeInterval(10), leaseDuration: 15, limit: limit).first)
            #expect(first.wake.highWatermark == 1 && first.attempt == 1)
            let leased = try await snapshot(on: sql)
            for seconds in badSeconds {
                await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await store.scheduleRetry(first, nextAttemptAt: Date(timeIntervalSince1970: seconds)) }
                #expect(try await snapshot(on: sql) == leased)
            }
            // A past absolute retry date is valid and immediately eligible.
            try await store.scheduleRetry(first, nextAttemptAt: base.addingTimeInterval(9))
            let second = try #require(try await store.claimPending(now: base.addingTimeInterval(10), leaseDuration: 15, limit: limit).first)
            #expect(second.attempt == 2 && second.claimToken != first.claimToken)
            let reclaimed = try await snapshot(on: sql)
            try await durable.markPublished(first)
            try await durable.scheduleRetry(first, nextAttemptAt: base)
            #expect(try await snapshot(on: sql) == reclaimed)
            // A newer message replaces the in-flight wake revision. Finishing
            // the stale publication must leave that newer watermark pending.
            try await send()
            try await store.markPublished(second)
            let third = try #require(try await store.claimPending(now: base.addingTimeInterval(12), leaseDuration: 15, limit: limit).first)
            #expect(third.wake.highWatermark == 2 && third.revision > second.revision)
            for seconds in badSeconds {
                await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await store.claimPending(now: Date(timeIntervalSince1970: seconds), leaseDuration: 15, limit: limit) }
            }
            try await store.markPublished(third)
            #expect(try await count("im_v2.group_event_wake_outbox", on: sql) == 0)

            try await send()
            let clock = TestSequenceClock([base])
            struct Publisher: V2GroupEventWakePublishing {
                let fails: Bool
                func publish(_ wake: V2GroupEventWake) async throws {
                    if fails { throw V2GroupEventWakeStoreError.corruptPersistenceState }
                }
            }
            func relay(fails: Bool, retryMaximum: TimeInterval = 30) -> V2GroupEventWakeRelay {
                .init(store: store, publisher: Publisher(fails: fails), retryMaximumDelay: retryMaximum, now: { clock.now() })
            }
            for (index, seconds) in badSeconds.enumerated() {
                let claimTime = base.addingTimeInterval(40 + Double(index) * 40)
                clock.set([claimTime, Date(timeIntervalSince1970: seconds)])
                await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await relay(fails: true).runOnce(limit: limit) }
                #expect(try await sql.raw("""
                    SELECT state = 'leased' AND attempt_count = \(bind: index + 1)
                        AND lease_token IS NOT NULL AND lease_expires_at = \(bind: claimTime.addingTimeInterval(15)) AS exists
                    FROM im_v2.group_event_wake_outbox WHERE room_id = \(bind: roomUUID)
                    """).first(decoding: ExistsRow.self)?.exists == true)
            }
            clock.set([base.addingTimeInterval(400), Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 0.5)])
            await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await relay(fails: true).runOnce(limit: limit) }
            clock.set([base.addingTimeInterval(440)])
            await #expect(throws: V2GroupEventWakeStoreError.corruptPersistenceState) { try await relay(fails: true, retryMaximum: .leastNonzeroMagnitude).runOnce(limit: limit) }
            clock.set([base.addingTimeInterval(480)])
            #expect(try await relay(fails: true).runOnce(limit: limit) == .init(claimed: 1, published: 0, retryScheduled: 1))
            #expect(try await sql.raw("SELECT state = 'pending' AND next_attempt_at = \(bind: base.addingTimeInterval(510)) AS exists FROM im_v2.group_event_wake_outbox").first(decoding: ExistsRow.self)?.exists == true)
            #expect(try await store.claimPending(now: base.addingTimeInterval(509), leaseDuration: 15, limit: limit).isEmpty)
            clock.set([base.addingTimeInterval(510)])
            #expect(try await relay(fails: false).runOnce(limit: limit) == .init(claimed: 1, published: 1, retryScheduled: 0))
            #expect(try await count("im_v2.group_event_wake_outbox", on: sql) == 0)
            #expect(try await count("im_v2.messages", on: sql) == 3)
            #expect(try await snapshot(on: targetSQL) == initialTarget)
        }
    }

    @Test("Propagation sequence exhaustion preserves whole recipient effects and does not advance the checkpoint",
          arguments: ["profile", "receipt-actor", "receipt-peer"])
    func propagationSequenceBoundary(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, userDatabase, sql, userSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: database),
                capacityProfile: forwardImportTestProfile(), roomShardID: "room-a", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)) else { throw CancellationError() }
            let messages = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database),
                capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { now })
            guard case .accepted = try await messages.send(.init(roomID: room.roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "propagation sequence")) else { throw CancellationError() }
            let operation = UUID()
            let outbox = path == "profile" ? "public_profile_update_outbox" : "read_receipt_preference_propagation_outbox"
            let key = path == "profile" ? "source_event_id" : "operation_id"
            if path == "profile" {
                let directory = V2PostgresPublicIdentityDirectory(database: database,
                    policy: try .init(maximumQueries: 10, window: 60), makeUUID: { operation }, now: { now })
                _ = try await directory.updateDisplayName(for: senderID, displayName: "Sequence profile")
            } else {
                _ = try await V2ReadReceiptService(store: PostgresV2ReadReceiptStore(database: database), now: { now })
                    .setPreferences(actorUserID: senderID, operationID: .init(uuid: operation),
                        allowsDirectReadReceipts: false, allowsGroupReadReceipts: true)
            }
            if path != "profile" {
                let recipient = path == "receipt-actor" ? senderUUID : memberTwoUUID
                try await sql.raw("""
                    INSERT INTO im_v2.direct_room_owner_routes
                        (lower_user_id, higher_user_id, room_id, room_shard_id, route_epoch, created_at, updated_at)
                    SELECT pair.lower_user_id, pair.higher_user_id, pair.room_id, room.room_shard_id,
                           room.owner_epoch, \(bind: now), \(bind: now)
                    FROM im_v2.direct_room_pairs AS pair JOIN im_v2.rooms AS room USING (room_id)
                    """).run()
                try await userSQL.raw("INSERT INTO im_v2.user_sync_sequences(user_id, next_sequence) VALUES (\(bind: recipient), \(bind: Int64.max))").run()
                let worker = V2ReadReceiptPreferencePropagationWorker(database: database, now: { now })
                #expect(try await worker.runOnce(limit: 1) == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 1))
                let event = receiptTombstoneSourceEventID(operationID: operation, roomID: try #require(room.roomID.uuidValue))
                struct Fence: V2UserShardRouteFencing {
                    let database: any Database
                    func withCurrentRoute<Result: Sendable>(for userID: UserID,
                        _ operation: @escaping @Sendable (V2UserShardRoute, any Database) async throws -> Result) async throws -> Result {
                        try await database.transaction { transaction in
                            try await operation(.init(bucket: "user", observedRouterEpoch: 1), transaction)
                        }
                    }
                }
                let source = try PostgresV2UserStateEventOutbox(database: database)
                let projector = try V2RoutedUserStateEventProjector(routeFence: Fence(database: database),
                    registry: V2StaticUserShardStorageRegistry(locations: [.init(bucket: "user", database: userDatabase, schema: "im_v2")]))
                let candidates = try await source.claim(now: now, leaseDuration: 30, limit: 100)
                    .filter { $0.event.sourceEventID.uuidValue == event }
                #expect(candidates.count == 2)
                for lease in candidates {
                    if lease.event.userID.uuidValue == recipient {
                        for _ in 0..<2 {
                            await #expect(throws: V2UserStateEventError.corruptPersistenceState) { try await projector.project(lease.event) }
                        }
                        try await source.retry(lease, disposition: .pause)
                        #expect(try await userSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_receipts WHERE user_id = \(bind: recipient)").first(decoding: CountRow.self)?.value == 0)
                    } else {
                        let sequence = try await projector.project(lease.event)
                        #expect(try await source.acknowledge(lease, sequence: sequence, now: now))
                    }
                }
                #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt'", on: userSQL) == 1)
                #expect(try await count("im_v2.read_receipt_preference_propagation_outbox WHERE state = 'completed'", on: sql) == 1)
                try await userSQL.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max - 1) WHERE user_id = \(bind: recipient)").run()
                try await sql.raw("UPDATE im_v2.user_state_event_outbox SET state = 'pending', next_attempt_at = \(bind: now) WHERE source_event_id = \(bind: event) AND user_id = \(bind: recipient)").run()
                let resumed = try await source.claim(now: now, leaseDuration: 30, limit: 100)
                    .filter { $0.event.sourceEventID.uuidValue == event }
                #expect(resumed.count == 1)
                let lease = try #require(resumed.first)
                let sequence = try await projector.project(lease.event)
                #expect(sequence == UInt64(Int64.max))
                #expect(try await projector.project(lease.event) == sequence)
                #expect(try await source.acknowledge(lease, sequence: sequence, now: now))
                #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt'", on: userSQL) == 2)
                #expect(try await userSQL.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: recipient)").first(decoding: CountRow.self)?.value == Int64.max)
                let committed = try await crossStoreClockState(on: userSQL)
                try await sql.raw("UPDATE im_v2.read_receipt_preference_propagation_outbox SET state = 'pending', completed_at = NULL, enumeration_checkpoint = NULL WHERE operation_id = \(bind: operation)").run()
                #expect(try await worker.runOnce(limit: 1) == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 1))
                #expect(try await crossStoreClockState(on: userSQL) == committed)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: event) AND state = 'delivered'").first(decoding: CountRow.self)?.value == 2)
                return
            }
            let recipient = path == "receipt-actor" ? senderUUID : memberTwoUUID
            let needed: Int64 = path == "profile" ? 2 : 1
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: recipient), \(bind: Int64.max - needed + 1)) ON CONFLICT (user_id) DO UPDATE SET next_sequence = EXCLUDED.next_sequence").run()
            let before = try await crossStoreClockState(on: sql)
            func run(at date: Date, fails: Bool) async throws {
                if path == "profile" {
                    let worker = V2DirectRoomProfilePropagationWorker(database: database,
                        shadowForwarder: SuccessfulProjectionShadowForwarder(), leaseDuration: 1, now: { date })
                    if fails {
                        await #expect(throws: V2DirectRoomProfilePropagationError.corruptPersistenceState) { try await worker.runOnce(limit: 1) }
                    } else {
                        #expect(try await worker.runOnce(limit: 1) == .init(claimedUpdateCount: 1, projectedRecipientCount: 1, completedUpdateCount: 1))
                    }
                } else {
                    let worker = V2ReadReceiptPreferencePropagationWorker(database: database,
                        leaseDuration: 1,
                        retryPolicy: .init(initialDelay: 1, maximumDelay: 1, maximumAttempts: 10, jitterFraction: 0), now: { date })
                    let report = try await worker.runOnce(limit: 1)
                    #expect(report == .init(claimedOperationCount: 1,
                        projectedRoomCount: fails ? 0 : 1, completedOperationCount: fails ? 0 : 1,
                        releasedOperationCount: fails ? 1 : 0))
                }
            }
            for seconds in [0.0, 2.0] {
                try await run(at: now.addingTimeInterval(seconds), fails: true)
                #expect(try await crossStoreClockState(on: sql) == before)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: outbox) WHERE \(unsafeRaw: key) = \(bind: operation) AND enumeration_checkpoint IS NULL AND completed_at IS NULL AND state = \(bind: path == "profile" ? "claimed" : "pending")").first(decoding: CountRow.self)?.value == 1)
            }
            try await sql.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max - needed) WHERE user_id = \(bind: recipient)").run()
            try await run(at: now.addingTimeInterval(4), fails: false)
            let event = path == "profile" ? operation : receiptTombstoneSourceEventID(operationID: operation, roomID: try #require(room.roomID.uuidValue))
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_projection_effects WHERE source_event_id = \(bind: event)").first(decoding: CountRow.self)?.value == 2)
            #expect(try await sql.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: recipient)").first(decoding: CountRow.self)?.value == Int64.max)
            let committed = try await crossStoreClockState(on: sql)
            // Revisit the completed page at the exhausted counter. Durable
            // effects must satisfy replay without another allocation.
            try await sql.raw("UPDATE im_v2.\(unsafeRaw: outbox) SET state = 'pending', completed_at = NULL, enumeration_checkpoint = NULL WHERE \(unsafeRaw: key) = \(bind: operation)").run()
            try await run(at: now.addingTimeInterval(6), fails: false)
            #expect(try await crossStoreClockState(on: sql) == committed)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: outbox) WHERE \(unsafeRaw: key) = \(bind: operation) AND state = 'completed'").first(decoding: CountRow.self)?.value == 1)
        }
    }

    @Test("Profile and receipt propagation retain source timestamp bytes across completed-work replay", arguments: ["profile", "receipt"])
    func propagationPersistedTimestampPrecision(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, userDatabase, sql, userSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: database),
                capacityProfile: forwardImportTestProfile(), roomShardID: "room-a", now: { now })
            guard case .opened(let room) = try await direct.open(actorUserID: senderID,
                operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)) else { throw CancellationError() }
            let messages = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database),
                capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { now })
            guard case .accepted = try await messages.send(.init(roomID: room.roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "propagation clock")) else { throw CancellationError() }
            if path == "receipt" {
                try await sql.raw("""
                    INSERT INTO im_v2.direct_room_owner_routes
                        (lower_user_id, higher_user_id, room_id, room_shard_id, route_epoch, created_at, updated_at)
                    SELECT pair.lower_user_id, pair.higher_user_id, pair.room_id, room.room_shard_id,
                           room.owner_epoch, \(bind: now), \(bind: now)
                    FROM im_v2.direct_room_pairs AS pair JOIN im_v2.rooms AS room USING (room_id)
                    """).run()
            }
            struct Fence: V2UserShardRouteFencing {
                let database: any Database
                func withCurrentRoute<Result: Sendable>(for userID: UserID,
                    _ operation: @escaping @Sendable (V2UserShardRoute, any Database) async throws -> Result) async throws -> Result {
                    try await database.transaction { transaction in
                        try await operation(.init(bucket: "user", observedRouterEpoch: 1), transaction)
                    }
                }
            }
            let projector = try V2RoutedUserStateEventProjector(routeFence: Fence(database: database),
                registry: V2StaticUserShardStorageRegistry(locations: [.init(bucket: "user", database: userDatabase, schema: "im_v2")]))
            let preferences = V2ReadReceiptService(store: PostgresV2ReadReceiptStore(database: database), now: { now })
            let offsets: [Int64] = [-1, 1, 803_315_200_123_457, -211_813_487_999_999_999, 9_223_371_331_199_999_999]
            for (index, offset) in offsets.enumerated() {
                var buffer = ByteBuffer()
                buffer.writeInteger(offset)
                let timestamp = try V2PostgresTimestamp(from: &buffer, type: .timestamptz, format: .binary, context: .default)
                let operation = UUID()
                let event: UUID
                let outbox: String
                if path == "profile" {
                    let directory = V2PostgresPublicIdentityDirectory(database: database,
                        policy: try .init(maximumQueries: 10, window: 60), makeUUID: { operation }, now: { now })
                    _ = try await directory.updateDisplayName(for: senderID, displayName: "Clock profile \(index)")
                    event = operation
                    outbox = "public_profile_update_outbox"
                    try await sql.raw("UPDATE im_v2.public_profile_update_outbox SET profile_updated_at = \(bind: timestamp) WHERE source_event_id = \(bind: operation)").run()
                } else {
                    _ = try await preferences.setPreferences(actorUserID: senderID, operationID: .init(uuid: UUID()),
                        allowsDirectReadReceipts: true, allowsGroupReadReceipts: true)
                    _ = try await preferences.setPreferences(actorUserID: senderID, operationID: .init(uuid: operation),
                        allowsDirectReadReceipts: false, allowsGroupReadReceipts: true)
                    event = receiptTombstoneSourceEventID(operationID: operation, roomID: try #require(room.roomID.uuidValue))
                    outbox = "read_receipt_preference_propagation_outbox"
                    try await sql.raw("UPDATE im_v2.read_receipt_preference_propagation_outbox SET recorded_at = \(bind: timestamp) WHERE operation_id = \(bind: operation)").run()
                }
                var original: [String]?
                for replay in [false, true] {
                    if replay {
                        let key = path == "profile" ? "source_event_id" : "operation_id"
                        try await sql.raw("UPDATE im_v2.\(unsafeRaw: outbox) SET state = 'pending', completed_at = NULL, enumeration_checkpoint = NULL WHERE \(unsafeRaw: key) = \(bind: operation)").run()
                    }
                    if path == "profile" {
                        let worker = V2DirectRoomProfilePropagationWorker(database: database,
                            shadowForwarder: SuccessfulProjectionShadowForwarder(), now: { now })
                        #expect(try await worker.runOnce(limit: 1) == .init(claimedUpdateCount: 1, projectedRecipientCount: 1, completedUpdateCount: 1))
                    } else {
                        let worker = V2ReadReceiptPreferencePropagationWorker(database: database,
                            now: { now })
                        #expect(try await worker.runOnce(limit: 1) == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 1))
                    }
                    if path == "receipt" {
                        struct Candidate: Decodable {
                            let userID: UUID
                            let payload: String
                            let createdAt: V2PostgresTimestamp
                        }
                        let candidates = try await sql.raw("SELECT user_id AS \"userID\", payload::text AS payload, created_at AS \"createdAt\" FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: event)").all(decoding: Candidate.self)
                        #expect(candidates.count == 2)
                        for candidate in candidates {
                            #expect(candidate.createdAt == timestamp)
                            let personal = try V2UserStateEvent(sourceEventID: .init(uuid: event), userID: .init(uuid: candidate.userID), kind: .directReadReceipt, payload: Data(candidate.payload.utf8), createdAt: candidate.createdAt)
                            let sequence = try await projector.project(personal)
                            #expect(try await projector.project(personal) == sequence)
                        }
                    }
                    let projectionSQL = path == "profile" ? sql : userSQL
                    var current: [String] = []
                    for table in ["user_sync_log", "user_projection_effects"] {
                        #expect(try await projectionSQL.raw("SELECT COUNT(*) = 2 AND bool_and(created_at = \(bind: timestamp)) AS exists FROM im_v2.\(unsafeRaw: table) WHERE source_event_id = \(bind: event)").first(decoding: ExistsRow.self)?.exists == true)
                        guard let rows = try await projectionSQL.raw("SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, projection_kind)::text AS value FROM im_v2.\(unsafeRaw: table) r WHERE source_event_id = \(bind: event)").first(decoding: StringValueRow.self) else { throw CancellationError() }
                        current.append(rows.value)
                    }
                    if let original { #expect(current == original) } else { original = current }
                    let column = path == "profile" ? "updated_at_ms" : "recorded_at_ms"
                    let kind = path == "profile" ? "direct_room_profile" : "direct_read_receipt"
                    #expect(try await projectionSQL.raw("SELECT bool_and((payload->>\(bind: column))::bigint = \(bind: try v2GatewayMilliseconds(timestamp.date))) AS exists FROM im_v2.user_sync_log WHERE source_event_id = \(bind: event) AND projection_kind = \(bind: kind)").first(decoding: ExistsRow.self)?.exists == true)
                }
            }
        }
    }

    @Test("Profile propagation bounds clocks, empty work and replayed pages", arguments: [false, true])
    func profilePropagationClockBounds(hasTargets: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            if hasTargets {
                let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: database), capacityProfile: forwardImportTestProfile(), roomShardID: "room-a", now: { base })
                let messages = V2SendMessageService(store: PostgresV2RoomWriteStore(database: database, strangerMessagePolicy: try .init(maximumMessagesPerWindow: 3, window: 86_400)), capacityProfile: try forwardImportTestProfile(), limits: try .init(maxUTF8Bytes: 64), now: { base })
                for peer in [memberTwoUUID, memberThreeUUID] {
                    guard case .opened(let room) = try await direct.open(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: peer)) else { throw V2RoomWriteStoreError.corruptPersistenceState }
                    guard case .accepted = try await messages.send(.init(roomID: room.roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "existing conversation")) else { throw V2RoomWriteStoreError.corruptPersistenceState }
                }
            }
            let event = UUID()
            let clock = TestSequenceClock([base.addingTimeInterval(1)])
            let directory = V2PostgresPublicIdentityDirectory(database: database, policy: try .init(maximumQueries: 10, window: 60), makeUUID: { event }, now: { clock.now() })
            func worker(lifetime: TimeInterval = 30) -> V2DirectRoomProfilePropagationWorker {
                .init(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder(), leaseDuration: lifetime, now: { clock.now() })
            }
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'profiles', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.public_user_profiles r),
                        'outbox', (SELECT jsonb_agg(to_jsonb(r) ORDER BY source_event_id) FROM im_v2.public_profile_update_outbox r),
                        'sequences', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.user_sync_sequences r),
                        'logs', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, user_sync_sequence) FROM im_v2.user_sync_log r),
                        'effects', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, source_event_id, projection_kind) FROM im_v2.user_projection_effects r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let badSeconds: [Double] = [.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12]
            let beforeUpdate = try await snapshot()
            for seconds in badSeconds {
                clock.set([Date(timeIntervalSince1970: seconds)])
                await #expect(throws: V2PublicIdentityDirectoryError.unavailable) { try await directory.updateDisplayName(for: senderID, displayName: "new profile") }
                #expect(try await directory.updateDisplayName(for: senderID, displayName: "发送者").displayName == "发送者")
                #expect(try await snapshot() == beforeUpdate)
            }
            clock.set([base.addingTimeInterval(1)])
            #expect(try await directory.updateDisplayName(for: senderID, displayName: "new profile").displayName == "new profile")
            let pending = try await snapshot()
            for limit in [Int.min, -1, 0, Int.max] {
                await #expect(throws: V2DirectRoomProfilePropagationError.invalidLimit) { try await worker().runOnce(limit: limit) }
            }
            for seconds in badSeconds {
                clock.set([Date(timeIntervalSince1970: seconds)])
                await #expect(throws: V2DirectRoomProfilePropagationError.corruptPersistenceState) { try await worker().runOnce(limit: 2) }
                #expect(try await snapshot() == pending)
            }
            clock.set([Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)])
            await #expect(throws: V2DirectRoomProfilePropagationError.corruptPersistenceState) { try await worker().runOnce(limit: 2) }
            clock.set([base])
            for lifetime in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.0000001] {
                await #expect(throws: V2DirectRoomProfilePropagationError.corruptPersistenceState) { try await worker(lifetime: lifetime).runOnce(limit: 2) }
            }
            #expect(try await snapshot() == pending)

            for (index, seconds) in badSeconds.enumerated() {
                let claimTime = base.addingTimeInterval(2 + Double(index) * 40)
                clock.set([claimTime, Date(timeIntervalSince1970: seconds)])
                await #expect(throws: V2DirectRoomProfilePropagationError.corruptPersistenceState) { try await worker().runOnce(limit: hasTargets ? 2 : 1) }
                #expect(try await sql.raw("""
                    SELECT state = 'claimed' AND retry_count = \(bind: index)
                        AND enumeration_checkpoint IS NULL AND completed_at IS NULL
                        AND claim_token IS NOT NULL AND lease_expires_at = \(bind: claimTime.addingTimeInterval(30)) AS exists
                    FROM im_v2.public_profile_update_outbox WHERE source_event_id = \(bind: event)
                    """).first(decoding: ExistsRow.self)?.exists == true)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: event)").first(decoding: CountRow.self)?.value == (hasTargets ? 4 : 0))
            }
            let resumedAt = base.addingTimeInterval(400)
            clock.set([resumedAt, Date(timeIntervalSince1970: .nan)])
            if hasTargets {
                // A partial-page checkpoint has no timestamp to bind. Its
                // progress remains valid even if that unused sample fails.
                #expect(try await worker().runOnce(limit: 1) == .init(claimedUpdateCount: 1, projectedRecipientCount: 1, completedUpdateCount: 0))
                #expect(try await count("im_v2.public_profile_update_outbox WHERE state = 'pending' AND enumeration_checkpoint IS NOT NULL", on: sql) == 1)
            }
            clock.set([resumedAt.addingTimeInterval(1)])
            #expect(try await worker().runOnce(limit: 1) == .init(claimedUpdateCount: 1, projectedRecipientCount: hasTargets ? 1 : 0, completedUpdateCount: 1))
            #expect(try await worker().runOnce(limit: 1).claimedUpdateCount == 0)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE source_event_id = \(bind: event)").first(decoding: CountRow.self)?.value == (hasTargets ? 4 : 0))
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_projection_effects WHERE source_event_id = \(bind: event)").first(decoding: CountRow.self)?.value == (hasTargets ? 4 : 0))
            #expect(try await sql.raw("""
                SELECT state = 'completed' AND claim_token IS NULL AND lease_expires_at IS NULL
                    AND completed_at = \(bind: resumedAt.addingTimeInterval(1)) AS exists
                FROM im_v2.public_profile_update_outbox WHERE source_event_id = \(bind: event)
                """).first(decoding: ExistsRow.self)?.exists == true)
            if !hasTargets {
                // No direct recipients must not allow an unlimited number of
                // source updates to evade a one-item worker budget.
                for peer in [memberTwoUUID, memberThreeUUID] {
                    let other = V2PostgresPublicIdentityDirectory(database: database, policy: try .init(maximumQueries: 10, window: 60), now: { resumedAt })
                    _ = try await other.updateDisplayName(for: .init(uuid: peer), displayName: "empty graph")
                }
                #expect(try await count("im_v2.public_profile_update_outbox WHERE state = 'pending'", on: sql) == 2)
                #expect(try await worker().runOnce(limit: 1) == .init(claimedUpdateCount: 1, projectedRecipientCount: 0, completedUpdateCount: 1))
                #expect(try await count("im_v2.public_profile_update_outbox WHERE state = 'pending'", on: sql) == 1)
                #expect(try await worker().runOnce(limit: 1) == .init(claimedUpdateCount: 1, projectedRecipientCount: 0, completedUpdateCount: 1))
                #expect(try await count("im_v2.public_profile_update_outbox WHERE state = 'pending'", on: sql) == 0)
            }
        }
    }

    @Test("Receipt propagation rejects invalid clocks and recovers without duplicate tombstones", arguments: ["complete", "retry", "pause"])
    func receiptPropagationClockBounds(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: database), capacityProfile: forwardImportTestProfile(), roomShardID: "room-a", now: { base })
            guard case .opened = try await direct.open(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            try await sql.raw("""
                INSERT INTO im_v2.direct_room_owner_routes
                    (lower_user_id, higher_user_id, room_id, room_shard_id, route_epoch, created_at, updated_at)
                SELECT pair.lower_user_id, pair.higher_user_id, pair.room_id, room.room_shard_id,
                       room.owner_epoch, \(bind: base), \(bind: base)
                FROM im_v2.direct_room_pairs AS pair JOIN im_v2.rooms AS room USING (room_id)
                """).run()
            try await sql.raw("CREATE TABLE im_v2.test_receipt_finalize_failure(enabled boolean NOT NULL)").run()
            try await sql.raw("INSERT INTO im_v2.test_receipt_finalize_failure VALUES (false)").run()
            try await sql.raw("""
                CREATE FUNCTION im_v2.test_reject_receipt_finalize() RETURNS trigger LANGUAGE plpgsql AS $$
                BEGIN
                    IF NEW.state = 'completed' AND (SELECT enabled FROM im_v2.test_receipt_finalize_failure) THEN
                        RAISE EXCEPTION 'injected receipt finalization interruption' USING ERRCODE = '08006';
                    END IF;
                    RETURN NEW;
                END $$
                """).run()
            try await sql.raw("CREATE TRIGGER test_receipt_finalize BEFORE UPDATE ON im_v2.read_receipt_preference_propagation_outbox FOR EACH ROW EXECUTE FUNCTION im_v2.test_reject_receipt_finalize()").run()
            let operation = UUID()
            let preferences = V2ReadReceiptService(store: PostgresV2ReadReceiptStore(database: database), now: { base })
            guard case .updated = try await preferences.setPreferences(actorUserID: senderID, operationID: .init(uuid: operation), allowsDirectReadReceipts: false, allowsGroupReadReceipts: true) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            let clock = TestSequenceClock([base])
            let policy = V2DurableRetryPolicy(initialDelay: 2, maximumDelay: 2, maximumAttempts: path == "pause" ? 1 : 3, jitterFraction: 0)
            func run(limit: Int = 1, lifetime: TimeInterval = 30, retry: V2DurableRetryPolicy? = nil,
                     fails: Bool = false) async throws -> V2ReadReceiptPreferencePropagationReport {
                try await sql.raw("UPDATE im_v2.test_receipt_finalize_failure SET enabled = \(bind: fails)").run()
                return try await V2ReadReceiptPreferencePropagationWorker(database: database,
                    leaseDuration: lifetime, retryPolicy: retry ?? policy, now: { clock.now() }).runOnce(limit: limit)
            }
            func snapshot() async throws -> String {
                struct State: Decodable { let value: String }
                return try #require(try await sql.raw("""
                    SELECT jsonb_build_object(
                        'outbox', (SELECT jsonb_agg(to_jsonb(r) ORDER BY actor_user_id, operation_id) FROM im_v2.read_receipt_preference_propagation_outbox r),
                        'events', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, source_event_id, projection_kind) FROM im_v2.user_state_event_outbox r),
                        'sequences', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.user_sync_sequences r),
                        'logs', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, user_sync_sequence) FROM im_v2.user_sync_log r),
                        'effects', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, source_event_id, projection_kind) FROM im_v2.user_projection_effects r)
                    )::text AS value
                    """).first(decoding: State.self)).value
            }
            let initial = try await snapshot()
            for limit in [Int.min, -1, 0, Int.max] {
                await #expect(throws: V2ReadReceiptPreferencePropagationError.invalidLimit) { try await run(limit: limit) }
            }
            let badSeconds: [Double] = [.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12]
            for seconds in badSeconds {
                clock.set([Date(timeIntervalSince1970: seconds)])
                await #expect(throws: V2ReadReceiptPreferencePropagationError.corruptPersistenceState) { try await run() }
                #expect(try await snapshot() == initial)
            }
            clock.set([Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10)])
            await #expect(throws: V2ReadReceiptPreferencePropagationError.corruptPersistenceState) { try await run() }
            clock.set([base])
            for lifetime in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude, 0.0000001] {
                await #expect(throws: V2ReadReceiptPreferencePropagationError.corruptPersistenceState) { try await run(lifetime: lifetime) }
            }
            #expect(try await snapshot() == initial)

            // Each attempt owns a valid lease. The clock fails only after
            // candidates have committed and the finalization transaction fails.
            // Advancing real time lets the next worker recover that lease.
            for (index, seconds) in badSeconds.enumerated() {
                let claimTime = base.addingTimeInterval(Double(index) * 40)
                let invalid = Date(timeIntervalSince1970: seconds)
                clock.set(path == "complete" ? [claimTime, invalid, invalid] : [claimTime, invalid])
                await #expect(throws: V2ReadReceiptPreferencePropagationError.corruptPersistenceState) {
                    try await run(fails: path != "complete")
                }
                #expect(try await sql.raw("""
                    SELECT state = 'claimed' AND retry_count = 0 AND enumeration_checkpoint IS NULL
                        AND next_attempt_at IS NULL AND paused_at IS NULL AND completed_at IS NULL
                        AND claim_token IS NOT NULL AND lease_expires_at = \(bind: claimTime.addingTimeInterval(30)) AS exists
                    FROM im_v2.read_receipt_preference_propagation_outbox
                    WHERE actor_user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)
                    """).first(decoding: ExistsRow.self)?.exists == true)
                #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt'", on: sql) == 0)
                #expect(try await count("im_v2.user_state_event_outbox WHERE projection_kind = 'direct_read_receipt'", on: sql) == 2)
            }
            var resumedAt = base.addingTimeInterval(400)
            if path == "retry" {
                // The clock can encode while the derived retry deadline cannot.
                clock.set([resumedAt, Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 0.5)])
                await #expect(throws: V2ReadReceiptPreferencePropagationError.corruptPersistenceState) { try await run(fails: true) }
                resumedAt = resumedAt.addingTimeInterval(40)
                clock.set([resumedAt])
                let excessive = V2DurableRetryPolicy(initialDelay: .greatestFiniteMagnitude, maximumDelay: .greatestFiniteMagnitude, maximumAttempts: 3, jitterFraction: 0)
                await #expect(throws: V2ReadReceiptPreferencePropagationError.corruptPersistenceState) { try await run(retry: excessive, fails: true) }
                #expect(try await count("im_v2.read_receipt_preference_propagation_outbox WHERE state = 'claimed' AND retry_count = 0 AND next_attempt_at IS NULL", on: sql) == 1)
                resumedAt = resumedAt.addingTimeInterval(40)
            }
            clock.set([resumedAt])
            if path != "complete" {
                // 依赖缺失是瞬时失败：两条路径都只安排重试，不再因预算耗尽而暂停。
                #expect(try await run(fails: true) == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 0, releasedOperationCount: 1))
                clock.set([resumedAt.addingTimeInterval(1)])
                #expect(try await run().claimedOperationCount == 0)
                if path == "pause" {
                    // 新契约下暂停只来自确定性失败；这里显式构造暂停行，
                    // 以继续覆盖 replay 的时钟恢复路径。
                    try await sql.raw("""
                        UPDATE im_v2.read_receipt_preference_propagation_outbox
                        SET state = 'paused', paused_at = \(bind: resumedAt), next_attempt_at = NULL,
                            claim_token = NULL, lease_expires_at = NULL
                        WHERE actor_user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)
                        """).run()
                    let result = try await verifyDurableReplayClockRecovery(
                        .init(operationID: UUID(), target: try .init(kind: .readReceiptPreferencePropagation, sourceEventID: .init(uuid: operation), targetUserID: senderID), reason: .dependencyRecovered),
                        store: PostgresV2DurableWorkReplayStore(database: database), sql: sql, operatorPrincipal: "integration-test", now: resumedAt.addingTimeInterval(2))
                    #expect(result.outcome == .requeued)
                }
                resumedAt = resumedAt.addingTimeInterval(2)
                clock.set([resumedAt])
            }
            #expect(try await run() == .init(claimedOperationCount: 1, projectedRoomCount: 1, completedOperationCount: 1))
            #expect(try await run(limit: Int.max - 1).claimedOperationCount == 0)
            #expect(try await count("im_v2.user_sync_log WHERE projection_kind = 'direct_read_receipt'", on: sql) == 0)
            #expect(try await count("im_v2.user_state_event_outbox WHERE projection_kind = 'direct_read_receipt'", on: sql) == 2)
            #expect(try await sql.raw("""
                SELECT state = 'completed' AND claim_token IS NULL AND lease_expires_at IS NULL
                    AND completed_at = \(bind: resumedAt) AS exists
                FROM im_v2.read_receipt_preference_propagation_outbox
                WHERE actor_user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)
                """).first(decoding: ExistsRow.self)?.exists == true)
        }
    }

    @Test("Shadow forwarding retains exact source timestamps across scalar and batch replay",
          arguments: [false, true], ["scalar", "batch", "batch-fallback"])
    func shadowForwardingTimestampPrecision(coLocated: Bool, path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { control, target, controlSQL, targetSQL, _ in
            let user = UUID(), userID = UserID(uuid: user)
            let liveSchema = coLocated ? "im_v2" : "im_v2_live_clock"
            if !coLocated { try await installSchema(on: targetSQL, schema: liveSchema) }
            do {
                let now = Date(timeIntervalSince1970: 1_750_000_000)
                try await configureDefaultUserShardRoute(.init(bucket: "users-source", observedRouterEpoch: 1), now: now, on: controlSQL)
                let registry = try V2StaticUserShardStorageRegistry(locations: [
                    .init(bucket: "users-source", database: coLocated ? control : target, schema: liveSchema)])
                let router = V2PostgresUserShardRouter(database: control)
                let shadow = V2PostgresUserShardProjectionShadowForwarder(registry: registry, routeFence: router,
                    batchRouteFence: path == "batch" ? router : nil,
                    coLocatedControlBuckets: coLocated ? ["users-source"] : [])
                let offsets: [Int64] = [-1, 1, 803_315_200_123_457, -211_813_487_999_999_999, 9_223_371_331_199_999_999]
                try await controlSQL.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: user), \(bind: Int64(offsets.count * 2)))").run()
                func snapshot(schema: String, on sql: any SQLDatabase) async throws -> String {
                    guard let row = try await sql.raw("""
                        SELECT jsonb_build_object(
                            'log', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_sync_sequence) FROM \(unsafeRaw: schema).user_sync_log r WHERE user_id = \(bind: user)),
                            'effects', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_sync_sequence) FROM \(unsafeRaw: schema).user_projection_effects r WHERE user_id = \(bind: user))
                        )::text AS value
                        """).first(decoding: StringValueRow.self) else { throw CancellationError() }
                    return row.value
                }
                for (index, offset) in offsets.enumerated() {
                    var buffer = ByteBuffer()
                    buffer.writeInteger(offset)
                    let timestamp = try V2PostgresTimestamp(from: &buffer, type: .timestamptz, format: .binary, context: .default)
                    var requests: [V2UserShardProjectionShadowRequest] = []
                    for item in 0..<2 {
                        let event = UUID()
                        let sequence = Int64(index * 2 + item + 1)
                        try await controlSQL.raw("""
                            INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at)
                            VALUES (\(bind: user), \(bind: sequence), \(bind: event), 'stranger_message_permission',
                                '{"permission":"allow","updated_at_ms":1000}'::jsonb, \(bind: timestamp))
                            """).run()
                        requests.append(.init(userID: userID, sourceEventID: .init(uuid: event), projectionKinds: ["stranger_message_permission"]))
                    }
                    let expected = try await snapshot(schema: "im_v2", on: controlSQL)
                    for _ in 0..<2 {
                        var sequences: [UInt64?] = []
                        if path == "scalar" {
                            for request in requests {
                                sequences.append(try await shadow.shadowIfForwarding(userID: request.userID, sourceEventID: request.sourceEventID, projectionKinds: request.projectionKinds))
                            }
                        } else { sequences = try await shadow.shadowIfForwarding(requests) }
                        #expect(sequences == [UInt64(index * 2 + 1), UInt64(index * 2 + 2)])
                        #expect(try await snapshot(schema: liveSchema, on: coLocated ? controlSQL : targetSQL) == expected)
                        #expect(try await snapshot(schema: "im_v2", on: controlSQL) == expected)
                    }
                }
            } catch {
                if !coLocated { try? await targetSQL.raw("DROP SCHEMA IF EXISTS im_v2_live_clock CASCADE").run() }
                throw error
            }
            if !coLocated { try await targetSQL.raw("DROP SCHEMA im_v2_live_clock CASCADE").run() }
        }
    }








    @Test("Cross-store writes reject invalid clocks before effects and preserve durable replay", arguments: ["mirror", "allocated"])
    func crossStoreWriteClockBoundaries(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { _, database, _, sql, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let user = UserID(uuid: UUID()), event = EventID(uuid: UUID()), nextEvent = EventID(uuid: UUID())
            let projector = try PostgresV2UserProjectionStore(database: database, schema: "im_v2")
            func write(_ source: EventID, at date: Date) async throws -> UInt64 {
                switch path {
                case "mirror":
                    return try await projector.mirror(.init(userID: user, sequence: source == event ? 1 : 2, sourceEventID: source, projectionKind: "stranger_permission", payloadJSON: "{}", createdAt: date))
                default:
                    return try await projector.projectAllocated(userID: user, sourceEventID: source, projectionKind: "stranger_permission", payloadJSON: "{}", createdAt: date)
                }
            }
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let empty = try await crossStoreClockState(on: sql)
            for invalid in invalidDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await write(event, at: invalid) }
            }
            #expect(try await crossStoreClockState(on: sql) == empty)
            #expect(try await write(event, at: now) == 1)
            #expect(try await write(event, at: now.addingTimeInterval(1)) == 1)
            let committed = try await crossStoreClockState(on: sql)
            for invalid in invalidDates {
                if path == "mirror" || path == "allocated" {
                    // These paths find the immutable effect before writing
                    // any timestamp. Preserve their clock-independent replay.
                    #expect(try await write(event, at: invalid) == 1)
                } else {
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await write(event, at: invalid) }
                }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await write(nextEvent, at: invalid) }
            }
            #expect(try await crossStoreClockState(on: sql) == committed)
            #expect(try await write(nextEvent, at: now.addingTimeInterval(2)) == 2)
            #expect(try await write(event, at: now.addingTimeInterval(3)) == 1)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 2)
            #expect(try await count("im_v2.user_projection_effects", on: sql) == 2)
            #expect(try await count("im_v2.user_sync_sequences WHERE next_sequence = 2", on: sql) == 1)
        }
    }

    @Test("Concurrent conversation preferences and favorites replay one committed timestamp and projection",
          arguments: ["conversation", "favorite-add", "favorite-remove"], [false, true])
    func personalPreferenceConcurrentReplay(path: String, mismatch: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let baseline = Date(timeIntervalSince1970: 1_750_000_000)
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database),
                capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { baseline })
            guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "preference replay")) else { throw CancellationError() }
            if path == "favorite-remove" {
                try await sql.raw("INSERT INTO im_v2.user_message_favorites (user_id, message_id, room_id, created_at) VALUES (\(bind: senderUUID), \(bind: message.messageID.uuidValue!), \(bind: roomUUID), \(bind: baseline))").run()
            }
            let now = Date(timeIntervalSince1970: 946_684_800 + 0.00000125)
            let operation = UUID()
            let store = PostgresV2ConversationCapabilitiesStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
            func perform(changed: Bool, date: Date) async throws -> V2ConversationCapabilitiesOutcome<Date> {
                if path == "conversation" {
                    let command = try V2ConversationStateCommand(operationID: .init(uuid: operation), roomID: roomID,
                        isPinned: !changed, isArchived: true, muteUntil: now.addingTimeInterval(600))
                    switch try await store.setConversationState(actorUserID: senderID, command: command, now: date) {
                    case .applied(let value): return .applied(value.updatedAt)
                    case .idempotent(let value): return .idempotent(value.updatedAt)
                    case .idempotencyConflict: return .idempotencyConflict
                    }
                }
                let command = V2MessageFavoriteCommand(operationID: .init(uuid: operation), roomID: roomID,
                    messageID: message.messageID, isFavorited: (path == "favorite-add") != changed)
                switch try await store.setMessageFavorite(actorUserID: senderID, command: command, now: date) {
                case .applied(let value): return .applied(value.updatedAt)
                case .idempotent(let value): return .idempotent(value.updatedAt)
                case .idempotencyConflict: return .idempotencyConflict
                }
            }
            let gate = PostgreSQLTransactionGate()
            let holder = Task {
                try await database.transaction { transaction in
                    let held = try #require(transaction as? any SQLDatabase)
                    try await held.raw("SELECT room_id FROM im_v2.rooms WHERE room_id = \(bind: roomUUID) FOR UPDATE").run()
                    await gate.holdTransaction()
                }
            }
            await gate.waitUntilHeld()
            func waitForWriters(_ expected: Int64) async throws {
                for _ in 0..<500 {
                    let waiting = try await sql.raw("SELECT COUNT(*) AS value FROM pg_stat_activity WHERE datname = current_database() AND wait_event_type = 'Lock' AND (query LIKE '%FROM im_v2.rooms%' OR query LIKE '%pg_advisory_xact_lock%')").first(decoding: CountRow.self)?.value ?? 0
                    if waiting == expected { return }
                    try await Task.sleep(for: .milliseconds(10))
                }
                Issue.record("Expected overlapping preference writers to wait on database locks")
                throw CancellationError()
            }
            let first = Task { try await perform(changed: false, date: now) }
            var second: Task<V2ConversationCapabilitiesOutcome<Date>, Error>?
            do {
                try await waitForWriters(1)
                second = Task { try await perform(changed: mismatch, date: baseline) }
                try await waitForWriters(2)
                await gate.releaseTransaction()
                try await holder.value
                let operationTable = path == "conversation" ? "user_room_preference_operations" : "user_message_favorite_operations"
                guard case .applied(let appliedAt) = try await first.value else { throw CancellationError() }
                #expect(try await #require(second).value == (mismatch ? .idempotencyConflict : .idempotent(appliedAt)))
                #expect(try await sql.raw("SELECT updated_at AS value FROM im_v2.\(unsafeRaw: operationTable) WHERE actor_user_id = \(bind: senderUUID) AND operation_id = \(bind: operation)").first(decoding: RevocationClockDateRow.self)?.value == appliedAt)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: operationTable) op JOIN im_v2.user_sync_log log ON log.user_id = op.actor_user_id AND log.source_event_id = op.operation_id WHERE op.actor_user_id = \(bind: senderUUID) AND op.operation_id = \(bind: operation) AND op.updated_at = \(bind: now) AND log.created_at = op.updated_at").first(decoding: CountRow.self)?.value == 1)
                func snapshot() async throws -> [String] {
                    var values: [String] = []
                    for table in ["user_room_preferences", "user_room_preference_operations", "user_message_favorites", "user_message_favorite_operations", "user_sync_sequences", "user_sync_log"] {
                        guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                        values.append(row.value)
                    }
                    return values
                }
                let committed = try await snapshot()
                for date in [Date(timeIntervalSince1970: .nan), Date(timeIntervalSince1970: .infinity), baseline] {
                    #expect(try await perform(changed: false, date: date) == .idempotent(appliedAt))
                    #expect(try await perform(changed: true, date: date) == .idempotencyConflict)
                    #expect(try await snapshot() == committed)
                }
                #expect(try await count("im_v2." + operationTable, on: sql) == 1)
                #expect(try await sql.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == 1)
                #expect(try await count("im_v2.user_message_favorites", on: sql) == (path == "favorite-add" ? 1 : 0))
            } catch {
                first.cancel()
                second?.cancel()
                await gate.releaseTransaction()
                _ = await holder.result
                _ = await first.result
                if let second { _ = await second.result }
                throw error
            }
        }
    }

    @Test("Personal sequence boundaries preserve control transactions and room outbox recovery",
          arguments: ["conversation", "favorite", "stranger", "user-add", "receipt-preferences", "relationship", "block-remove", "direct-open", "direct-receipt"])
    func personalProjectionSequenceBoundary(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, userDatabase, sql, userSQL, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let operation = UUID(), target = UserID(uuid: memberTwoUUID), createdRoom = RoomID(uuid: UUID())
            let profile = try forwardImportTestProfile()
            let direct = PostgresV2DirectMessagingStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
            let personal = PostgresV2ConversationCapabilitiesStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
            let receipts = PostgresV2ReadReceiptStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
            let social = PostgresV2SocialRelationshipStore(database: database, shadowForwarder: SuccessfulProjectionShadowForwarder())
            var messageRoom = roomID
            if path == "direct-receipt" {
                guard case .opened(let opened) = try await direct.open(command: .init(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: target), capacityProfile: profile,
                    roomShardID: "room-a", roomID: createdRoom, now: now) else { throw CancellationError() }
                messageRoom = opened.roomID
            }
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database),
                capacityProfile: profile, limits: .init(maxUTF8Bytes: 64), now: { now })
            guard case .accepted(let message) = try await sender.send(.init(roomID: messageRoom, actorUserID: senderID,
                clientMessageID: .init(uuid: UUID()), text: "personal sequence boundary")) else { throw CancellationError() }
            if path == "block-remove" {
                try await sql.raw("INSERT INTO im_v2.user_relationships (lower_user_id, higher_user_id, state, requested_by_user_id, updated_at) VALUES (LEAST(\(bind: senderUUID), \(bind: memberTwoUUID)), GREATEST(\(bind: senderUUID), \(bind: memberTwoUUID)), 'accepted', \(bind: senderUUID), \(bind: now))").run()
            }
            func perform() async throws -> Bool {
                switch path {
                case "conversation":
                    switch try await personal.setConversationState(actorUserID: senderID, command: .init(operationID: .init(uuid: operation), roomID: roomID, isPinned: true, isArchived: true, muteUntil: nil), now: now) {
                    case .applied: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "favorite":
                    switch try await personal.setMessageFavorite(actorUserID: senderID, command: .init(operationID: .init(uuid: operation), roomID: roomID, messageID: message.messageID, isFavorited: true), now: now) {
                    case .applied: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "stranger":
                    switch try await direct.setStrangerMessagePermission(command: .init(actorUserID: senderID, operationID: .init(uuid: operation), permission: .deny), now: now) {
                    case .updated: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "user-add":
                    switch try await direct.setUserAddPermission(command: .init(actorUserID: senderID, operationID: .init(uuid: operation), permission: .deny), now: now) {
                    case .updated: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "receipt-preferences":
                    switch try await receipts.setPreferences(command: .init(actorUserID: senderID, operationID: .init(uuid: operation), allowsDirectReadReceipts: false, allowsGroupReadReceipts: true), now: now) {
                    case .updated: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "relationship":
                    switch try await social.changeRelationship(.init(actorUserID: senderID, operationID: .init(uuid: operation), targetUserID: target, action: .request), now: now) {
                    case .changed: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "block-remove":
                    switch try await social.changeUserBlock(.init(actorUserID: senderID, operationID: .init(uuid: operation), targetUserID: target, action: .block), now: now) {
                    case .changed: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                case "direct-open":
                    switch try await direct.open(command: .init(actorUserID: senderID, operationID: .init(uuid: operation), targetUserID: target), capacityProfile: profile, roomShardID: "room-a", roomID: createdRoom, now: now) {
                    case .opened: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                default:
                    switch try await receipts.record(command: .init(roomID: messageRoom, actorUserID: target, operationID: .init(uuid: operation), readThroughRoomSequence: message.roomSequence), now: now) {
                    case .recorded: return false
                    case .idempotent: return true
                    default: throw CancellationError()
                    }
                }
            }
            let needed: Int64 = path == "block-remove" ? 2 : 1
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: senderUUID), \(bind: Int64.max - needed + 1)) ON CONFLICT (user_id) DO UPDATE SET next_sequence = EXCLUDED.next_sequence").run()
            func snapshot() async throws -> [String] {
                var result = [try await crossStoreClockState(on: sql)]
                for table in ["user_room_preferences", "user_room_preference_operations", "user_message_favorites", "user_message_favorite_operations", "user_stranger_message_preferences", "stranger_message_preference_operations", "user_add_preferences", "user_add_preference_operations", "user_read_receipt_preferences", "read_receipt_preference_operations", "read_receipt_preference_propagation_outbox", "room_read_receipts", "read_receipt_operations", "user_relationships", "user_relationship_operations", "user_blocks", "user_block_operations", "rooms", "room_memberships", "direct_room_pairs", "direct_room_operations", "user_direct_send_policy_versions", "room_admission", "shard_admission_pools", "user_state_event_outbox"] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    result.append(row.value)
                }
                return result
            }
            if path == "direct-open" || path == "direct-receipt" {
                struct Fence: V2UserShardRouteFencing {
                    let database: any Database
                    func withCurrentRoute<Result: Sendable>(for userID: UserID,
                        _ operation: @escaping @Sendable (V2UserShardRoute, any Database) async throws -> Result) async throws -> Result {
                        try await database.transaction { transaction in
                            try await operation(.init(bucket: "user", observedRouterEpoch: 1), transaction)
                        }
                    }
                }
                let outbox = try PostgresV2UserStateEventOutbox(database: database)
                let projector = try V2RoutedUserStateEventProjector(routeFence: Fence(database: database),
                    registry: V2StaticUserShardStorageRegistry(locations: [.init(bucket: "user", database: userDatabase, schema: "im_v2")]))
                try await userSQL.raw("INSERT INTO im_v2.user_sync_sequences(user_id, next_sequence) VALUES (\(bind: senderUUID), \(bind: Int64.max))").run()
                #expect(try await perform() == false)
                let sourceEventCount: Int64 = path == "direct-open" ? 1 : 2
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: operation)").first(decoding: CountRow.self)?.value == sourceEventCount)
                let committed = try await snapshot()
                #expect(try await perform())
                #expect(try await snapshot() == committed)
                let leases = try await outbox.claim(now: now, leaseDuration: 30, limit: 100)
                    .filter { $0.event.sourceEventID.uuidValue == operation }
                #expect(leases.count == Int(sourceEventCount))
                for lease in leases {
                    if lease.event.userID == senderID {
                        await #expect(throws: V2UserStateEventError.corruptPersistenceState) {
                            _ = try await projector.project(lease.event)
                        }
                        try await outbox.retry(lease, disposition: .pause)
                    } else {
                        let sequence = try await projector.project(lease.event)
                        #expect(try await outbox.acknowledge(lease, sequence: sequence, now: now))
                    }
                }
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: operation) AND state = 'paused'").first(decoding: CountRow.self)?.value == 1)
                #expect(try await userSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == 0)
                try await userSQL.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max - 1) WHERE user_id = \(bind: senderUUID)").run()
                try await sql.raw("UPDATE im_v2.user_state_event_outbox SET state = 'pending', next_attempt_at = \(bind: now) WHERE source_event_id = \(bind: operation) AND state = 'paused'").run()
                let recovery = try await outbox.claim(now: now, leaseDuration: 30, limit: 100)
                #expect(recovery.count == 1)
                for lease in recovery {
                    #expect(try await projector.project(lease.event) == UInt64(Int64.max))
                    #expect(try await projector.project(lease.event) == UInt64(Int64.max))
                    #expect(try await outbox.acknowledge(lease, sequence: UInt64(Int64.max), now: now))
                }
                #expect(try await perform())
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_state_event_outbox WHERE source_event_id = \(bind: operation) AND state = 'delivered'").first(decoding: CountRow.self)?.value == sourceEventCount)
                #expect(try await userSQL.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE user_id = \(bind: senderUUID) AND user_sync_sequence = \(bind: Int64.max)").first(decoding: CountRow.self)?.value == 1)
                return
            }
            let before = try await snapshot()
            for _ in 0..<2 {
                do { _ = try await perform(); Issue.record("Expected a sequence-exhaustion domain error") }
                catch {
                    switch path {
                    case "conversation", "favorite": #expect(error as? V2ConversationCapabilitiesStoreError == .corruptPersistenceState)
                    case "receipt-preferences", "direct-receipt": #expect(error as? V2ReadReceiptStoreError == .corruptPersistenceState)
                    case "relationship", "block-remove": #expect(error as? V2SocialRelationshipStoreError == .corruptPersistenceState)
                    default: #expect(error as? V2DirectMessagingStoreError == .corruptPersistenceState)
                    }
                }
                #expect(try await snapshot() == before)
            }
            try await sql.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max - needed) WHERE user_id = \(bind: senderUUID)").run()
            #expect(try await perform() == false)
            #expect(try await sql.raw("SELECT next_sequence AS value FROM im_v2.user_sync_sequences WHERE user_id = \(bind: senderUUID)").first(decoding: CountRow.self)?.value == Int64.max)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_sync_log WHERE user_id = \(bind: senderUUID) AND user_sync_sequence > \(bind: Int64.max - needed)").first(decoding: CountRow.self)?.value == needed)
            let committed = try await snapshot()
            for _ in 0..<2 { #expect(try await perform()); #expect(try await snapshot() == committed) }
        }
    }

    @Test("Personal sequence exhaustion rolls back new effects while committed records remain replayable")
    func crossStoreSequenceReservationBoundary() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { _, database, controlSQL, sql, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let user = UserID(uuid: UUID()), old = EventID(uuid: UUID()), pending = EventID(uuid: UUID())
            let userUUID = try #require(user.uuidValue)
            let projector = try PostgresV2UserProjectionStore(database: database, schema: "im_v2")
            func write(_ event: EventID) async throws -> UInt64 {
                try await projector.projectAllocated(userID: user, sourceEventID: event, projectionKind: "stranger_permission", payloadJSON: "{}", createdAt: now)
            }
            #expect(try await write(old) == 1)
            try await sql.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max) WHERE user_id = \(bind: userUUID)").run()
            let before = try await crossStoreClockState(on: sql)
            let sourceBefore = try await crossStoreClockState(on: controlSQL)
            for _ in 0..<2 {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await write(pending) }
                #expect(try await write(old) == 1)
                #expect(try await crossStoreClockState(on: sql) == before)
            }
            try await sql.raw("UPDATE im_v2.user_sync_sequences SET next_sequence = \(bind: Int64.max - 1) WHERE user_id = \(bind: userUUID)").run()
            #expect(try await write(pending) == UInt64(Int64.max))
            let committed = try await crossStoreClockState(on: sql)
            for _ in 0..<2 {
                #expect(try await write(pending) == UInt64(Int64.max))
                #expect(try await write(old) == 1)
                #expect(try await crossStoreClockState(on: sql) == committed)
            }
            #expect(try await crossStoreClockState(on: controlSQL) == sourceBefore)
        }

    }

    private func crossStoreClockState(on sql: any SQLDatabase) async throws -> String {
        struct State: Decodable { let value: String }
        return try #require(try await sql.raw("""
            SELECT jsonb_build_object(
                'sequences', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.user_sync_sequences r),
                'sync', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id, user_sync_sequence) FROM im_v2.user_sync_log r),
                'effects', (SELECT jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text) FROM im_v2.user_projection_effects r),
                'ready', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.user_projection_ready r),
                'checkpoints', (SELECT jsonb_agg(to_jsonb(r) ORDER BY user_id) FROM im_v2.user_projection_checkpoints r)
            )::text AS value
            """).first(decoding: State.self)).value
    }

    @Test("Projection clocks reject invalid work and retry dates without consuming failure state", arguments: [false, true])
    func projectionWorkerTimestampBoundaries(poisoned: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let user = UUID(), event = UUID(), target = UUID()
            let payload = "{\"target_user_id\":\"\(target.uuidString.lowercased())\",\"state\":\"accepted\",\"updated_at_ms\":1750000000000}"
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: user), 1)").run()
            let storedPayload = poisoned ? "[]" : payload
            try await sql.raw("INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at) VALUES (\(bind: user), 1, \(bind: event), 'relationship', \(bind: storedPayload)::jsonb, \(bind: now))").run()
            let worker = PostgresV2UserProjectionWorker(database: database, retryPolicy: .init(initialDelay: 2, maximumDelay: 2, maximumAttempts: 2, jitterFraction: 0))
            let versions = PostgresV2ProjectionVersionGCWorker(database: database)
            let states = PostgresV2MessageProjectionStateGCWorker(database: database, retention: 60)
            for seconds in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12] {
                let invalid = Date(timeIntervalSince1970: seconds)
                await #expect(throws: V2UserProjectionWorkerError.corruptPersistence) { try await worker.runOnce(now: invalid) }
                await #expect(throws: V2ProjectionVersionGCError.corruptPersistence) { try await versions.runOnce(now: invalid) }
                await #expect(throws: V2MessageProjectionStateGCError.corruptPersistence) { try await states.runOnce(now: invalid) }
            }
            let lower = Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + 30)
            await #expect(throws: V2MessageProjectionStateGCError.corruptPersistence) { try await states.runOnce(now: lower) }
            for duration in [Double.greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                let invalidGC = PostgresV2MessageProjectionStateGCWorker(database: database, retention: duration)
                await #expect(throws: V2MessageProjectionStateGCError.corruptPersistence) { try await invalidGC.runOnce(now: now) }
            }
            if poisoned {
                // The clock is encodable and the row really fails projection,
                // but the derived retry time is not a usable database date.
                let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 0.5)
                #expect(v2PostgresTimestampCanEncode(upper))
                await #expect(throws: V2UserProjectionWorkerError.corruptPersistence) { try await worker.runOnce(now: upper) }
                for duration in [Double.greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                    let invalidRetry = PostgresV2UserProjectionWorker(database: database, retryPolicy: .init(initialDelay: duration, maximumDelay: duration, maximumAttempts: 2, jitterFraction: 0))
                    await #expect(throws: V2UserProjectionWorkerError.corruptPersistence) { try await invalidRetry.runOnce(now: now) }
                }
            }
            #expect(try await count("im_v2.user_projection_checkpoints WHERE state = 'ready' AND projected_sequence = 0 AND failure_count = 0 AND failed_sequence IS NULL AND next_attempt_at IS NULL AND paused_at IS NULL", on: sql) == 1)
            #expect(try await count("im_v2.user_projection_ready", on: sql) == 1)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 1)
            #expect(try await count("im_v2.user_projection_versions", on: sql) == 0)
            if poisoned {
                #expect(try await worker.runOnce(now: now) == .init(claimed: true, appliedRecordCount: 0, failedRecordCount: 1))
                #expect(try await count("im_v2.user_projection_checkpoints WHERE state = 'ready' AND projected_sequence = 0 AND failure_count = 1 AND failed_sequence = 1 AND paused_at IS NULL", on: sql) == 1)
                #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_projection_ready WHERE available_at = \(bind: now.addingTimeInterval(2))").first(decoding: CountRow.self)?.value == 1)
                #expect(try await worker.runOnce(now: now.addingTimeInterval(1)).claimed == false)
                try await sql.raw("UPDATE im_v2.user_sync_log SET payload = \(bind: payload)::jsonb WHERE user_id = \(bind: user) AND source_event_id = \(bind: event)").run()
            }
            let resumedAt = poisoned ? now.addingTimeInterval(2) : now
            #expect(try await worker.runOnce(now: resumedAt) == .init(claimed: true, appliedRecordCount: 1))
            #expect(try await worker.runOnce(now: resumedAt).claimed == false)
            #expect(try await count("im_v2.user_projection_checkpoints WHERE state = 'ready' AND projected_sequence = 1 AND failure_count = 0 AND failed_sequence IS NULL AND next_attempt_at IS NULL AND paused_at IS NULL", on: sql) == 1)
            #expect(try await count("im_v2.user_projection_ready", on: sql) == 0)
            #expect(try await count("im_v2.user_projection_versions", on: sql) == 1)
            #expect(try await versions.runOnce(now: resumedAt) == 0)
            #expect(try await states.runOnce(now: resumedAt) == 0)
        }
    }

    @Test("Room-log read bounds reject invalid requests before SQL or cache lookup", arguments: [false, true])
    func roomLogReadIntegerBounds(cached: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .large) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let cache = V2DirectRoomLogEventCache(configuration: .init(maximumEvents: 16, maximumBytes: 65_536, maximumEventsPerRoom: 16, shardCount: 1))
            let sender = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: database), capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { now })
            for text in ["one", "two"] {
                guard case .accepted(let message) = try await sender.send(.init(roomID: roomID, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: text)) else { throw V2RoomWriteStoreError.corruptPersistenceState }
                if cached { await cache.recordCommittedPlainDirectMessage(message) }
            }
            let reader = PostgresV2GroupEventLogStore(database: database, directRoomLogEventCache: cached ? cache : nil)
            let preparedCache = V2PreparedGroupEventPageCache(configuration: .init(maximumEntries: 8, maximumBytes: 65_536, shardCount: 1))
            let context = V2PreparedGroupEventPageEncodingContext(requestID: 7, frameVersion: 21, compression: nil, maximumUncompressedPayloadBytes: 65_536, compressionThresholdBytes: 1_024, maximumExpansionRatio: 64, maximumGroupEventPagePayloadBytes: 48 * 1_024, cache: preparedCache)
            let cacheBefore = await cache.snapshot()
            for size in [Int.min, -1, 0, V2GroupEventLogService.maximumPageSize + 1, Int.max] {
                await #expect(throws: V2GroupEventLogError.invalidRequest) { try await reader.pull(roomID: roomID, actorUserID: senderID, afterRoomSequence: 0, pageSize: size) }
                await #expect(throws: V2GroupEventLogError.invalidRequest) { try await reader.pullPrepared(roomID: roomID, actorUserID: senderID, afterRoomSequence: 0, pageSize: size, context: context) }
            }
            for sequence in [UInt64(Int64.max) + 1, UInt64.max] {
                await #expect(throws: V2GroupEventLogError.invalidRequest) { try await reader.pull(roomID: roomID, actorUserID: senderID, afterRoomSequence: sequence, pageSize: 1) }
                await #expect(throws: V2GroupEventLogError.invalidRequest) { try await reader.pullPrepared(roomID: roomID, actorUserID: senderID, afterRoomSequence: sequence, pageSize: 1, context: context) }
            }
            let cacheAfter = await cache.snapshot()
            #expect(cacheBefore.cachedEvents == cacheAfter.cachedEvents && cacheBefore.hits == cacheAfter.hits && cacheBefore.misses == cacheAfter.misses)
            let first = try await reader.pull(roomID: roomID, actorUserID: senderID, afterRoomSequence: 0, pageSize: 1)
            #expect(first.events.map(\.roomSequence) == [1] && first.hasMore && first.nextRoomSequence == 1)
            let last = try await reader.pull(roomID: roomID, actorUserID: senderID, afterRoomSequence: first.nextRoomSequence, pageSize: 1)
            #expect(last.events.map(\.roomSequence) == [2] && !last.hasMore && last.nextRoomSequence == 2)
            for _ in 0..<2 {
                let prepared = try await reader.pullPrepared(roomID: roomID, actorUserID: senderID, afterRoomSequence: 0, pageSize: V2GroupEventLogService.maximumPageSize, context: context)
                switch prepared {
                case .prepared(let response):
                    #expect(cached)
                    let decoded = try V2ServerProtobufFrameCodec.decode(response.frame)
                    #expect(decoded.requestID == 7)
                    #expect(decoded.groupEventPage.events.map(\.roomSequence) == [1, 2])
                    #expect(!decoded.groupEventPage.hasMore_p && decoded.groupEventPage.nextRoomSequence == 2)
                case .page(let page):
                    #expect(!cached)
                    #expect(page.events.map(\.roomSequence) == [1, 2] && !page.hasMore && page.nextRoomSequence == 2)
                case .eventTooLarge: throw V2GroupEventLogError.corruptPersistenceState
                }
            }
            if cached { #expect(preparedCache.snapshot().hits == 1) }
            let exhausted = try await reader.pull(roomID: roomID, actorUserID: senderID, afterRoomSequence: UInt64(Int64.max), pageSize: 1)
            #expect(exhausted.events.isEmpty && exhausted.nextRoomSequence == UInt64(Int64.max) && !exhausted.hasMore)
            #expect(try await count("im_v2.room_events", on: sql) == 2)
            await cache.finish()
        }
    }

    @Test("Snapshot building and log compaction reject invalid clocks and recover at the retention boundary")
    func snapshotMaintenanceTimestampBoundaries() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let userUUID = UUID(), deviceUUID = UUID()
            let user = UserID(uuid: userUUID), device = DeviceID(uuid: deviceUUID)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: deviceUUID), \(bind: now), \(bind: now))").run()
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: userUUID), 2)").run()
            for (index, age) in [(1, 120.0), (2, 30.0)] {
                let payload = "{\"allows_stranger_messages\":true,\"updated_at_ms\":\(1_750_000_000_000 + index)}"
                try await sql.raw("INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at) VALUES (\(bind: userUUID), \(bind: index), \(bind: UUID()), 'stranger_message_permission', \(bind: payload)::jsonb, \(bind: now.addingTimeInterval(-age)))").run()
            }
            try await drainV3Projection(database: database)
            let sync = PostgresV2SyncStore(database: database, capabilityLifetime: 600)
            guard case .resetPreparing(let snapshot, let generation, _) = try await sync.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, requireSnapshot: true, now: now) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(generation == 2)
            let builder = PostgresV2SnapshotArtifactBuilder(database: database, leaseDuration: 30)
            let compactor = PostgresV2UserSyncLogCompactionWorker(database: database, minimumLogAge: 60)
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for invalid in invalidDates {
                await #expect(throws: V2SnapshotArtifactBuilderError.corruptPersistence) { try await builder.runOnce(now: invalid) }
                await #expect(throws: V2UserSyncLogCompactionError.corruptPersistence) { try await compactor.runOnce(now: invalid, userLimit: 1, rowLimit: 10) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 15)
            await #expect(throws: V2SnapshotArtifactBuilderError.corruptPersistence) { try await builder.runOnce(now: upper) }
            let lower = Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + 30)
            await #expect(throws: V2UserSyncLogCompactionError.corruptPersistence) { try await compactor.runOnce(now: lower, userLimit: 1, rowLimit: 10) }
            for duration in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                let invalidBuilder = PostgresV2SnapshotArtifactBuilder(database: database, leaseDuration: duration)
                await #expect(throws: V2SnapshotArtifactBuilderError.corruptPersistence) { try await invalidBuilder.runOnce(now: now) }
            }
            for duration in [Double.greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                let invalidCompactor = PostgresV2UserSyncLogCompactionWorker(database: database, minimumLogAge: duration)
                await #expect(throws: V2UserSyncLogCompactionError.corruptPersistence) { try await invalidCompactor.runOnce(now: now, userLimit: 1, rowLimit: 10) }
            }
            #expect(try await count("im_v2.sync_snapshot_artifacts WHERE state = 'building' AND lease_token IS NULL AND lease_expires_at IS NULL AND next_page_index = 0 AND item_count = 0", on: sql) == 1)
            #expect(try await count("im_v2.sync_snapshot_pages", on: sql) == 0)
            #expect(try await count("im_v2.device_sync_cursors WHERE state = 'reset_preparing' AND reset_generation = 2 AND acknowledged_sequence = 0", on: sql) == 1)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 2)
            #expect(try await count("im_v2.user_sync_retention WHERE compacted_through_sequence = 0", on: sql) == 1)
            #expect(try await builder.runOnce(now: now) == .init(claimed: true, published: false, pageCount: 1, itemCount: 1))
            #expect(try await compactor.runOnce(now: now, userLimit: 1, rowLimit: 10).deletedLogRowCount == 1)
            #expect(try await count("im_v2.user_sync_log WHERE user_sync_sequence = 2", on: sql) == 1)
            #expect(try await count("im_v2.user_sync_retention WHERE compacted_through_sequence = 1", on: sql) == 1)
            #expect(try await compactor.runOnce(now: now.addingTimeInterval(29), userLimit: 1, rowLimit: 10).deletedLogRowCount == 0)
            #expect(try await compactor.runOnce(now: now.addingTimeInterval(30), userLimit: 1, rowLimit: 10).deletedLogRowCount == 1)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 0)
            #expect(try await count("im_v2.user_sync_retention WHERE compacted_through_sequence = 2", on: sql) == 1)
            #expect(try await builder.runOnce(now: now.addingTimeInterval(31)) == .init(claimed: true, published: true, pageCount: 1, itemCount: 1))
            let manifest = try await sync.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, now: now.addingTimeInterval(31))
            #expect(manifest.baseSequence == 2 && manifest.totalItems == 1)
            _ = try await sync.fetchSnapshotPage(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, rootDigest: manifest.rootDigest, index: 0, now: now.addingTimeInterval(31))
            try await sync.acknowledgeSnapshot(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, baseSequence: 2, receipt: manifest.receipt, now: now.addingTimeInterval(31))
            guard case .ready(let resumed, let records, _, _, _) = try await sync.pull(userID: user, deviceID: device, syncToken: manifest.nextSyncToken, maxRecords: 20, now: now.addingTimeInterval(31)) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(resumed == 2 && records.isEmpty)
            #expect(try await builder.runOnce(now: now.addingTimeInterval(31)).claimed == false)
        }
    }

    @Test("Sync clocks reject invalid dates before cursors, capabilities and reset assignments change")
    func syncTimestampBoundaries() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let userUUID = UUID(), deviceUUID = UUID()
            let user = UserID(uuid: userUUID), device = DeviceID(uuid: deviceUUID)
            let missingSnapshot = SnapshotID(uuid: UUID()), missingReceipt = try V2SyncReceipt("unused")
            let store = PostgresV2SyncStore(database: database, capabilityLifetime: 60)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: userUUID), \(bind: deviceUUID), \(bind: now), \(bind: now))").run()
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for invalid in invalidDates {
                for reset in [false, true] {
                    await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                        try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, requireSnapshot: reset, now: invalid)
                    }
                }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.acknowledge(userID: user, deviceID: device, generation: 1, highestContiguousSequence: 0, receipt: missingReceipt, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: missingSnapshot, generation: 2, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.fetchSnapshotPage(userID: user, deviceID: device, snapshotID: missingSnapshot, generation: 2, rootDigest: "unused", index: 0, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.acknowledgeSnapshot(userID: user, deviceID: device, snapshotID: missingSnapshot, generation: 2, baseSequence: 0, receipt: missingReceipt, now: invalid) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                    try await PostgresV2SnapshotResetStager.stage(sql: sql, schema: "im_v2", userID: userUUID, deviceID: deviceUUID, currentGeneration: 1, retainedFloor: 0, capabilityProfile: "base", capabilityLifetime: 60, now: invalid, makeUUID: UUID.init)
                }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 30)
            await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: upper) }
            for interval in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                let invalidStore = PostgresV2SyncStore(database: database, capabilityLifetime: interval)
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await invalidStore.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: now) }
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) {
                    try await PostgresV2SnapshotResetStager.stage(sql: sql, schema: "im_v2", userID: userUUID, deviceID: deviceUUID, currentGeneration: 1, retainedFloor: 0, capabilityProfile: "base", capabilityLifetime: interval, now: now, makeUUID: UUID.init)
                }
            }
            for limit in [Int.min, 0, Int.max] {
                await #expect(throws: V2SyncStoreError.invalidRecordLimit) { try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: limit, now: now) }
            }
            for table in ["device_sync_cursors", "sync_tokens", "sync_receipts", "device_snapshot_resets", "sync_snapshot_artifacts", "user_projection_checkpoints"] { #expect(try await count("im_v2." + table, on: sql) == 0) }
            try await sql.raw("INSERT INTO im_v2.user_sync_sequences (user_id, next_sequence) VALUES (\(bind: userUUID), 1)").run()
            try await sql.raw("INSERT INTO im_v2.user_sync_log (user_id, user_sync_sequence, source_event_id, projection_kind, payload, created_at) VALUES (\(bind: userUUID), 1, \(bind: UUID()), 'stranger_message_permission', '{\"allows_stranger_messages\":true,\"updated_at_ms\":1750000000000}'::jsonb, \(bind: now))").run()
            try await drainV3Projection(database: database)
            guard case .ready(let generation, let records, let token, let receipt, _) = try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, now: now) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(generation == 1 && records.count == 1)
            for invalid in invalidDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.acknowledge(userID: user, deviceID: device, generation: 1, highestContiguousSequence: 1, receipt: receipt, now: invalid) }
            }
            #expect(try await count("im_v2.device_sync_cursors WHERE state = 'ready' AND acknowledged_sequence = 0", on: sql) == 1)
            #expect(try await count("im_v2.sync_tokens", on: sql) == 1)
            #expect(try await count("im_v2.sync_receipts", on: sql) == 1)
            try await store.acknowledge(userID: user, deviceID: device, generation: 1, highestContiguousSequence: 1, receipt: receipt, now: now)
            try await store.acknowledge(userID: user, deviceID: device, generation: 1, highestContiguousSequence: 1, receipt: receipt, now: now)
            guard case .ready(_, let remaining, _, _, _) = try await store.pull(userID: user, deviceID: device, syncToken: token, maxRecords: 20, now: now) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(remaining.isEmpty)
            guard case .resetPreparing(let snapshot, let resetGeneration, _) = try await store.pull(userID: user, deviceID: device, syncToken: nil, maxRecords: 20, requireSnapshot: true, now: now) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(resetGeneration == 2)
            let builder = PostgresV2SnapshotArtifactBuilder(database: database)
            while try await builder.runOnce(now: now).claimed { try Task.checkCancellation() }
            let manifest = try await store.fetchSnapshotManifest(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, now: now)
            #expect(manifest.totalItems == 1)
            _ = try await store.fetchSnapshotPage(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, rootDigest: manifest.rootDigest, index: 0, now: now)
            for invalid in invalidDates {
                await #expect(throws: V2RoomWriteStoreError.corruptPersistenceState) { try await store.acknowledgeSnapshot(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, baseSequence: 1, receipt: manifest.receipt, now: invalid) }
            }
            #expect(try await count("im_v2.device_sync_cursors WHERE state = 'reset_pending' AND acknowledged_sequence = 1", on: sql) == 1)
            for _ in 0..<2 { try await store.acknowledgeSnapshot(userID: user, deviceID: device, snapshotID: snapshot, generation: 2, baseSequence: 1, receipt: manifest.receipt, now: now) }
            guard case .ready(let resumed, let tail, _, _, _) = try await store.pull(userID: user, deviceID: device, syncToken: manifest.nextSyncToken, maxRecords: 20, now: now) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            #expect(resumed == 2 && tail.isEmpty)
        }
    }

    @Test("Operator snapshot retries report existing state without calculating a new deadline",
          arguments: ["preparing", "ready", "acknowledged"])
    func operatorSnapshotReplayClockBoundary(state: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let user = UUID(), device = UUID(), sibling = UUID()
            let command = V2DeviceSnapshotResetCommand(operationID: UUID(), userID: .init(uuid: user), deviceID: .init(uuid: device))
            let fresh = V2DeviceSnapshotResetCommand(operationID: UUID(), userID: .init(uuid: user), deviceID: .init(uuid: sibling))
            for id in [device, sibling] {
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: user), \(bind: id), \(bind: now), \(bind: now))").run()
            }
            let route = try V2UserShardRoute(bucket: "control", observedRouterEpoch: 1)
            let registry = try V2StaticUserShardStorageRegistry(locations: [.init(bucket: route.bucket, database: database, schema: "im_v2")])
            func service(at date: Date) throws -> V2PostgresDeviceSnapshotResetService {
                try .init(registry: registry, deviceAvailability: V2PostgresDeviceAvailabilityChecker(database: database),
                    routeFence: V2FixedUserShardRouteFence(route: route, database: database), capabilityProfile: "base",
                    capabilityLifetime: 60, now: { date })
            }
            #expect(try await service(at: now).stage(command) == .init(generation: 2, state: .preparing, wasIdempotent: false))
            if state != "preparing" {
                let builder = PostgresV2SnapshotArtifactBuilder(database: database)
                while try await builder.runOnce(now: now).claimed { try Task.checkCancellation() }
            }
            if state == "acknowledged" {
                let store = PostgresV2SyncStore(database: database)
                let snapshot = SnapshotID(uuid: command.operationID)
                let manifest = try await store.fetchSnapshotManifest(userID: command.userID, deviceID: command.deviceID,
                    snapshotID: snapshot, generation: 2, now: now)
                try await store.acknowledgeSnapshot(userID: command.userID, deviceID: command.deviceID,
                    snapshotID: snapshot, generation: 2, baseSequence: manifest.baseSequence, receipt: manifest.receipt, now: now)
            }
            func snapshot() async throws -> [String] {
                var result: [String] = []
                for table in ["device_sync_cursors", "sync_tokens", "sync_receipts", "device_snapshot_resets", "sync_snapshot_artifacts", "user_projection_checkpoints"] {
                    guard let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self) else { throw CancellationError() }
                    result.append(row.value)
                }
                return result
            }
            let before = try await snapshot()
            let expected = V2DeviceSnapshotResetResult(generation: 2, state: state == "preparing" ? .preparing : .ready, wasIdempotent: true)
            let dates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude,
                1e14, -1e14, -1e12, 946_684_800 + 9_223_371_331_200 - 30].map { Date(timeIntervalSince1970: $0) }
            for date in dates {
                for replayClock in [date, now, date] {
                    #expect((try? await service(at: replayClock).stage(command)) == expected)
                    #expect(try await snapshot() == before)
                }
                await #expect(throws: V2DeviceSnapshotResetError.unavailable) { try await service(at: date).stage(fresh) }
                #expect(try await snapshot() == before)
            }
            #expect(try await service(at: now).stage(fresh) == .init(generation: 2, state: .preparing, wasIdempotent: false))
        }
    }

    @Test("Operator snapshot reset rejects invalid lifetimes without consuming its operation ID")
    func operatorSnapshotTimestampBoundaries() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let user = UUID(), device = UUID()
            let command = V2DeviceSnapshotResetCommand(operationID: UUID(), userID: .init(uuid: user), deviceID: .init(uuid: device))
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: user), \(bind: device), \(bind: now), \(bind: now))").run()
            let route = try V2UserShardRoute(bucket: "control", observedRouterEpoch: 1)
            let registry = try V2StaticUserShardStorageRegistry(locations: [.init(bucket: route.bucket, database: database, schema: "im_v2")])
            func service(at date: Date, lifetime: TimeInterval = 60) throws -> V2PostgresDeviceSnapshotResetService {
                try .init(registry: registry, deviceAvailability: V2PostgresDeviceAvailabilityChecker(database: database),
                    routeFence: V2FixedUserShardRouteFence(route: route, database: database), capabilityProfile: "base", capabilityLifetime: lifetime, now: { date })
            }
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) } + [Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 30)]
            for invalid in invalidDates {
                await #expect(throws: V2DeviceSnapshotResetError.unavailable) { try await service(at: invalid).stage(command) }
            }
            for lifetime in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                await #expect(throws: V2DeviceSnapshotResetError.unavailable) { try await service(at: now, lifetime: lifetime).stage(command) }
            }
            for table in ["device_sync_cursors", "sync_tokens", "device_snapshot_resets", "sync_snapshot_artifacts", "user_projection_checkpoints"] { #expect(try await count("im_v2." + table, on: sql) == 0) }
            let reset = try service(at: now)
            #expect(try await reset.stage(command) == .init(generation: 2, state: .preparing, wasIdempotent: false))
            #expect(try await reset.stage(command) == .init(generation: 2, state: .preparing, wasIdempotent: true))
            for table in ["device_sync_cursors", "sync_tokens", "device_snapshot_resets", "sync_snapshot_artifacts", "user_projection_checkpoints"] { #expect(try await count("im_v2." + table, on: sql) == 1) }
        }
    }

    @Test("nickname routing uses the room owner and fences reads, writes and replay",
          arguments: [V2GroupCapacityClass.standard, .large])
    func routedNicknameOwnerFence(_ mode: V2GroupCapacityClass) async throws {
        try await withForwardOwnerDatabases(mode: mode) { control, owner, sql, ownerSQL, room in
            let now = Date(timeIntervalSince1970: 1_750_000_000), operation = GroupNicknameOperationID(uuid: UUID())
            try await sql.raw("""
                INSERT INTO im_v2.room_owner_routes(room_id, room_shard_id, route_epoch, created_at, updated_at)
                VALUES (\(bind: room.uuidValue!), 'room-b', 0, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at
                """).run()
            let router = V2PostgresRoomShardRouter(database: control)
            let registry = try V2StaticRoomShardStorageRegistry(locations: [.init(shardID: "room-b", database: owner, schema: "im_v2")])
            let aliases = PostgresV2ProfilePresentationStore(database: control, now: { now })
            func routed(_ routing: any V2RoomShardRouting) -> V2RoutedProfilePresentationStore {
                .init(aliases: aliases, router: routing, owners: registry, now: { now })
            }
            let store = routed(router)
            let original = try await store.updateOwnGroupNickname(actorUserID: senderID, roomID: room,
                operationID: operation, expectedRevision: nil, nickname: "owner nickname")
            #expect(try await store.groupNicknames(actorUserID: senderID, roomID: room, afterUserID: nil, limit: 1).values == [original])
            #expect(try await store.groupNicknames(actorUserID: senderID, roomID: room, afterUserID: senderID, limit: 1).values.isEmpty)
            #expect(try await count("im_v2.room_member_nicknames", on: sql) == 0)
            #expect(try await count("im_v2.room_member_nickname_operations", on: sql) == 0)
            // Contact aliases still belong to the configured alias store.
            try await sql.raw("""
                INSERT INTO im_v2.user_relationships(lower_user_id, higher_user_id, state, requested_by_user_id, updated_at)
                VALUES (\(bind: senderUUID), \(bind: memberTwoUUID), 'accepted', \(bind: senderUUID), \(bind: now))
                """).run()
            let alias = try await store.updateContactAlias(ownerUserID: senderID, targetUserID: .init(uuid: memberTwoUUID),
                operationID: .init(uuid: UUID()), expectedRevision: nil, remarkName: "control alias")
            #expect(try await store.contactAliases(ownerUserID: senderID, afterTargetUserID: nil, limit: 10).values == [alias])
            #expect(try await count("im_v2.user_contact_aliases", on: ownerSQL) == 0)
            let cached = V2CachedRoomShardRouter(source: router)
            _ = try await cached.route(for: room)
            try await ownerSQL.raw("UPDATE im_v2.rooms SET owner_epoch = 1 WHERE room_id = \(bind: room.uuidValue!)").run()
            try await sql.raw("UPDATE im_v2.room_owner_routes SET route_epoch = 1 WHERE room_id = \(bind: room.uuidValue!)").run()
            func assertRejected(_ selected: V2RoutedProfilePresentationStore) async {
                await #expect(throws: V2RoomOwnerFenceError.ownerChanged) {
                    _ = try await selected.groupNicknames(actorUserID: senderID, roomID: room, afterUserID: nil, limit: 10)
                }
                for op in [operation, GroupNicknameOperationID(uuid: UUID())] {
                    await #expect(throws: V2RoomOwnerFenceError.ownerChanged) {
                        _ = try await selected.updateOwnGroupNickname(actorUserID: senderID, roomID: room,
                            operationID: op, expectedRevision: nil, nickname: "owner nickname")
                    }
                }
            }
            await assertRejected(routed(cached))
            #expect(try await store.updateOwnGroupNickname(actorUserID: senderID, roomID: room,
                operationID: operation, expectedRevision: nil, nickname: "owner nickname") == original)
            let wrong = V2RoutedProfilePresentationStore(aliases: aliases, router: router,
                owners: try V2StaticRoomShardStorageRegistry(locations: [.init(shardID: "room-b", database: control, schema: "im_v2")]), now: { now })
            await assertRejected(wrong)
            try await sql.raw("UPDATE im_v2.room_owner_routes SET room_shard_id = 'unknown' WHERE room_id = \(bind: room.uuidValue!)").run()
            await #expect(throws: V2RoomShardStorageRegistryError.unknownShardID) {
                _ = try await store.groupNicknames(actorUserID: senderID, roomID: room, afterUserID: nil, limit: 10)
            }
            try await sql.raw("UPDATE im_v2.room_owner_routes SET room_shard_id = 'room-b' WHERE room_id = \(bind: room.uuidValue!)").run()
        }
    }


    @Test("Profile writes reject unsupported clocks but completed operations remain replayable", arguments: ["profile", "alias", "nickname"], [false, true])
    func profileWriteTimestampBoundaries(kind: String, change: Bool) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let operation = UUID()
            let target = UserID(uuid: memberTwoUUID)
            let before = try await PostgresV2ProfileUpdateStore(database: database).currentProfile(for: senderID)
            let original = kind == "profile" ? try #require(before.publicIdentity).displayName : "original"
            let name = change ? "changed" : original
            let revision = try #require(V2ProfileRevision(rawValue: 1))
            if kind == "alias" {
                try await sql.raw("INSERT INTO im_v2.user_relationships (lower_user_id, higher_user_id, state, requested_by_user_id, updated_at) VALUES (\(bind: senderUUID), \(bind: memberTwoUUID), 'accepted', \(bind: senderUUID), \(bind: now))").run()
                try await sql.raw("INSERT INTO im_v2.user_contact_aliases (owner_user_id, target_user_id, remark_name, revision, updated_at) VALUES (\(bind: senderUUID), \(bind: memberTwoUUID), 'original', 1, \(bind: now))").run()
            } else if kind == "nickname" {
                try await sql.raw("INSERT INTO im_v2.room_member_nicknames (room_id, user_id, nickname, revision, updated_at) VALUES (\(bind: roomUUID), \(bind: senderUUID), 'original', 1, \(bind: now))").run()
            }
            let command = try V2ProfileUpdateCommand(actorUserID: senderID, operationID: .init(uuid: operation), expectedRevision: before.revision, displayName: name, avatar: nil)
            func update(at date: Date) async throws -> V2ProfileRevision {
                if kind == "profile" {
                    let result = try await PostgresV2ProfileUpdateStore(database: database, now: { date }).update(command)
                    switch result {
                    case .updated(let view), .idempotent(let view): return view.revision
                    }
                }
                let store = PostgresV2ProfilePresentationStore(database: database, now: { date })
                if kind == "alias" {
                    return try await store.updateContactAlias(ownerUserID: senderID, targetUserID: target, operationID: .init(uuid: operation), expectedRevision: revision, remarkName: name).revision
                }
                return try await store.updateOwnGroupNickname(actorUserID: senderID, roomID: roomID, operationID: .init(uuid: operation), expectedRevision: revision, nickname: name).revision
            }
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            for invalid in invalidDates {
                if kind == "profile" {
                    await #expect(throws: V2ProfileUpdateError.corruptPersistenceState) { try await update(at: invalid) }
                } else {
                    await #expect(throws: V2ProfilePresentationError.corruptPersistenceState) { try await update(at: invalid) }
                }
            }
            let operations = ["public_profile_update_operations", "user_contact_alias_operations", "room_member_nickname_operations"]
            for table in operations + ["public_profile_update_outbox"] { #expect(try await count("im_v2." + table, on: sql) == 0) }
            #expect(try await PostgresV2ProfileUpdateStore(database: database).currentProfile(for: senderID) == before)
            if kind != "profile" {
                let table = kind == "alias" ? "user_contact_aliases" : "room_member_nicknames"
                #expect(try await sql.raw("SELECT revision AS value FROM im_v2.\(unsafeRaw: table)").first(decoding: CountRow.self)?.value == 1)
            }
            #expect(try await update(at: now).signedValue == (change ? 2 : 1))
            // The original ledger response needs no new timestamp, so it is
            // still available while a later server clock is invalid.
            for invalid in invalidDates { #expect(try await update(at: invalid).signedValue == (change ? 2 : 1)) }
            let selected = kind == "profile" ? operations[0] : (kind == "alias" ? operations[1] : operations[2])
            for table in operations { #expect(try await count("im_v2." + table, on: sql) == (table == selected ? 1 : 0)) }
            #expect(try await count("im_v2.public_profile_update_outbox", on: sql) == (kind == "profile" && change ? 1 : 0))
        }
    }

    @Test("Group creation checks timestamps across inline, staged and control manifest paths", arguments: ["inline", "control-inline", "staged", "control-staged"])
    func groupCreationTimestampBoundaries(path: String) async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let store = PostgresV2GroupMessagingStore(database: database)
            let control = PostgresV2GroupRoomCreationIntentStore(database: database)
            let operation = GroupRoomOperationID(uuid: UUID())
            let newRoom = RoomID(uuid: UUID()), event = EventID(uuid: UUID())
            let command = try V2CreateGroupRoomCommand(actorUserID: senderID, operationID: operation, title: "clock group", capacityClass: .standard, initialMemberUserIDs: [.init(uuid: memberTwoUUID)])
            let staged = try V2StagedGroupRoomCommand(actorUserID: senderID, operationID: operation, title: command.title, capacityClass: command.capacityClass, stagedMemberCount: 1)
            let intent = try V2GroupRoomCreationIntent(actorUserID: senderID, operationID: operation, roomID: newRoom, eventID: event, roomShardID: "room-a", routeEpoch: 0, requestFingerprint: Data(repeating: 0x12, count: 32), audienceMemberCount: 2)
            let page = try V2GroupRoomCreationManifestPage(pageNumber: 0, memberUserIDs: command.allMemberUserIDs, isFinal: true)
            func create(at date: Date, operationOverride: GroupRoomOperationID? = nil, titleOverride: String? = nil) async throws -> V2CreateGroupRoomOutcome {
                let requested = try V2CreateGroupRoomCommand(actorUserID: senderID, operationID: operationOverride ?? operation,
                    title: titleOverride ?? command.title, capacityClass: command.capacityClass, initialMemberUserIDs: command.initialMemberUserIDs)
                let requestedStaged = try V2StagedGroupRoomCommand(actorUserID: senderID, operationID: requested.operationID,
                    title: requested.title, capacityClass: requested.capacityClass, stagedMemberCount: 1)
                let requestedIntent = try V2GroupRoomCreationIntent(actorUserID: senderID, operationID: requested.operationID,
                    roomID: newRoom, eventID: event, roomShardID: "room-a", routeEpoch: 0,
                    requestFingerprint: intent.requestFingerprint, audienceMemberCount: 2)
                switch path {
                case "inline": return try await store.create(command: requested, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, eventID: event, now: date)
                case "control-inline": return try await store.createControlValidated(command: requested, validatedMemberUserIDs: requested.allMemberUserIDs, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, eventID: event, now: date)
                case "staged": return try await store.createStaged(command: requestedStaged, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, eventID: event, now: date)
                default: return try await store.createControlValidatedStaged(command: requestedStaged, intent: requestedIntent, capacityProfile: profile, now: date)
                }
            }
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) }
            let routesBefore = try await count("im_v2.room_owner_routes", on: sql)
            for invalid in invalidDates {
                await #expect(throws: V2GroupMessagingStoreError.corruptPersistenceState) { try await create(at: invalid) }
                await #expect(throws: V2GroupMessagingStoreError.corruptPersistenceState) { try await store.stageControlValidatedAudience(intent: intent, page: page, now: invalid) }
                await #expect(throws: V2GroupRoomCreationIntentStoreError.corruptPersistenceState) { try await control.prepare(intent, memberUserIDs: command.allMemberUserIDs, now: invalid) }
                await #expect(throws: V2GroupRoomCreationIntentStoreError.corruptPersistenceState) { try await control.prepareStaged(intent, command: staged, now: invalid) }
                await #expect(throws: V2GroupRoomCreationIntentStoreError.corruptPersistenceState) { try await control.finalizeCommitted(intent, now: invalid) }
            }
            for table in ["group_room_operations", "room_events", "user_state_event_outbox", "group_room_creation_intents", "group_room_creation_intent_members", "group_room_creation_intent_pages"] {
                #expect(try await count("im_v2." + table, on: sql) == 0)
            }
            #expect(try await count("im_v2.rooms", on: sql) == 1)
            #expect(try await count("im_v2.room_memberships", on: sql) == 3)
            #expect(try await count("im_v2.room_owner_routes", on: sql) == routesBefore)
            if path == "staged" || path == "control-staged" {
                let drafts = PostgresV2GroupAudienceImportStore(database: database)
                let policy = V2GroupAudienceImportPolicy(maximumStagedMembersPerActor: 10)
                _ = try await drafts.begin(actorUserID: senderID, operationID: operation, title: command.title, policy: policy, now: now)
                _ = try await drafts.append(actorUserID: senderID, operationID: operation, memberUserIDs: command.initialMemberUserIDs, maximumMembers: 10, policy: policy, now: now)
                _ = try await drafts.freeze(actorUserID: senderID, operationID: operation, policy: policy, now: now)
            }
            if path == "control-staged" {
                #expect(try await control.prepareStaged(intent, command: staged, now: now) == .prepared(intent))
                try await store.stageControlValidatedAudience(intent: intent, page: page, now: now)
                try await store.stageControlValidatedAudience(intent: intent, page: page, now: now)
            } else if path == "control-inline" {
                #expect(try await control.prepare(intent, memberUserIDs: command.allMemberUserIDs, now: now) == .prepared(intent))
            }
            guard case .created(let created) = try await create(at: now) else { throw V2GroupMessagingStoreError.corruptPersistenceState }
            #expect(created.roomID == newRoom && created.createdAt == now && created.memberCount == 2)
            #expect(try await create(at: now.addingTimeInterval(1)) == .idempotent(created))
            func snapshot() async throws -> [String] {
                var values: [String] = []
                for table in ["rooms", "group_rooms", "room_memberships", "group_room_operations", "room_events",
                    "user_state_event_outbox", "room_admission", "shard_admission_pools", "room_owner_routes",
                    "group_room_creation_drafts", "group_room_creation_draft_members", "group_room_creation_intents",
                    "group_room_creation_intent_members", "group_room_creation_intent_pages"] {
                    let row = try await sql.raw("SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY to_jsonb(r)::text), '[]'::jsonb)::text AS value FROM im_v2.\(unsafeRaw: table) r").first(decoding: StringValueRow.self)
                    values.append(try #require(row).value)
                }
                return values
            }
            let committedState = try await snapshot()
            for invalid in invalidDates {
                #expect(try await create(at: invalid) == .idempotent(created))
                #expect(try await create(at: invalid, titleOverride: "different group") == .idempotencyConflict)
                await #expect(throws: V2GroupMessagingStoreError.corruptPersistenceState) {
                    try await create(at: invalid, operationOverride: .init(uuid: UUID()))
                }
                #expect(try await snapshot() == committedState)
            }
            let operationUUID = try #require(UUID(uuidString: operation.rawValue))
            for literal in ["infinity", "-infinity", "294276-12-31 23:59:59.999999+00"] {
                try await sql.raw("UPDATE im_v2.group_room_operations SET created_at = \(bind: literal)::timestamptz WHERE operation_id = \(bind: operationUUID)").run()
                let before = try await snapshot()
                await #expect(throws: V2GroupMessagingStoreError.corruptPersistenceState) { try await create(at: now) }
                #expect(try await create(at: now, titleOverride: "different group") == .idempotencyConflict)
                #expect(try await snapshot() == before)
            }
            for date in [Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000),
                         Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 10), now] {
                try await sql.raw("UPDATE im_v2.group_room_operations SET created_at = \(bind: date) WHERE operation_id = \(bind: operationUUID)").run()
                let before = try await snapshot()
                let expected = try V2GroupRoom(roomID: created.roomID, ownerUserID: created.ownerUserID, title: created.title,
                    capacityClass: created.capacityClass, memberUserIDs: created.memberUserIDs, memberCount: created.memberCount, createdAt: date)
                #expect(try await create(at: now) == .idempotent(expected))
                #expect(try await snapshot() == before)
            }
            #expect(try await snapshot() == committedState)
            if path.hasPrefix("control-") {
                // An owner may already have committed before the control
                // clock fails. A retry must still publish the original route.
                for invalid in invalidDates {
                    await #expect(throws: V2GroupRoomCreationIntentStoreError.corruptPersistenceState) { try await control.finalizeCommitted(intent, now: invalid) }
                }
                #expect(try await count("im_v2.room_owner_routes", on: sql) == routesBefore)
                let committed = try await control.finalizeCommitted(intent, now: now)
                #expect(committed.state == .committed && committed.roomID == newRoom)
                #expect(try await control.finalizeCommitted(intent, now: now.addingTimeInterval(1)) == committed)
                #expect(try await count("im_v2.room_owner_routes", on: sql) == routesBefore + 1)
            }
            for table in ["group_room_operations", "room_events"] { #expect(try await count("im_v2." + table, on: sql) == 1) }
            #expect(try await count("im_v2.user_state_event_outbox", on: sql) == 2)
            #expect(try await count("im_v2.rooms", on: sql) == 2)
            #expect(try await count("im_v2.room_memberships", on: sql) == 5)
            #expect(try await sql.raw("SELECT (payload->>'created_at_ms')::bigint AS value FROM im_v2.room_events").first(decoding: CountRow.self)?.value == 1_750_000_000_000)
        }
    }

    @Test("Direct room and preference timestamps are rejected before durable writes")
    func directMessagingTimestampBoundaries() async throws {
        guard let databaseURL = Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"),
              Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" else { return }
        let app = try await Application.make(.testing)
        do {
            app.databases.use(try .postgres(url: databaseURL), as: .psql, isDefault: true)
            let sql = try #require(app.db(.psql) as? any SQLDatabase)
            try await installSchema(on: sql)
            try await seedRoom(on: sql)
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let store = PostgresV2DirectMessagingStore(database: app.db(.psql))
            let profile = try V2CapacityProfile(id: "standard", limits: .init(maxEligibleMembers: 10, maxCommandsPerWindow: 10,    retryAfterSeconds: 3))
            let open = try V2OpenDirectRoomCommand(actorUserID: senderID, operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID))
            let stranger = V2SetStrangerMessagePermissionCommand(actorUserID: senderID, operationID: .init(uuid: UUID()), permission: .deny)
            let userAdd = V2SetUserAddPermissionCommand(actorUserID: senderID, operationID: .init(uuid: UUID()), permission: .deny)
            let newRoom = RoomID(uuid: UUID())
            for seconds in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12] {
                let invalid = Date(timeIntervalSince1970: seconds)
                await #expect(throws: V2DirectMessagingStoreError.corruptPersistenceState) { try await store.open(command: open, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, now: invalid) }
                await #expect(throws: V2DirectMessagingStoreError.corruptPersistenceState) { try await store.setStrangerMessagePermission(command: stranger, now: invalid) }
                await #expect(throws: V2DirectMessagingStoreError.corruptPersistenceState) { try await store.setUserAddPermission(command: userAdd, now: invalid) }
            }
            let tables = ["direct_room_pairs", "direct_room_operations", "user_stranger_message_preferences", "stranger_message_preference_operations", "user_add_preferences", "user_add_preference_operations"]
            for table in tables { #expect(try await count("im_v2." + table, on: sql) == 0) }
            #expect(try await count("im_v2.rooms", on: sql) == 1)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 0)
            guard case .opened(let opened) = try await store.open(command: open, capacityProfile: profile, roomShardID: "room-a", roomID: newRoom, now: now) else { throw CancellationError() }
            #expect(opened.roomID == newRoom && opened.createdAt == now)
            #expect(try await store.open(command: open, capacityProfile: profile, roomShardID: "room-a", roomID: .init(uuid: UUID()), now: now.addingTimeInterval(1)) == .idempotent(opened))
            #expect(try await store.setStrangerMessagePermission(command: stranger, now: now) == .updated(permission: .deny, updatedAt: now))
            #expect(try await store.setStrangerMessagePermission(command: stranger, now: now.addingTimeInterval(1)) == .idempotent(permission: .deny, updatedAt: now))
            #expect(try await store.setUserAddPermission(command: userAdd, now: now) == .updated(permission: .deny, updatedAt: now))
            #expect(try await store.setUserAddPermission(command: userAdd, now: now.addingTimeInterval(1)) == .idempotent(permission: .deny, updatedAt: now))
            for table in tables { #expect(try await count("im_v2." + table, on: sql) == 1) }
            #expect(try await count("im_v2.rooms", on: sql) == 2)
            #expect(try await count("im_v2.user_sync_log", on: sql) == 2)
            #expect(try await count("im_v2.user_state_event_outbox", on: sql) == 1)
            let outbox = try PostgresV2UserStateEventOutbox(database: app.db(.psql))
            let projector = try PostgresV2UserStateEventProjector(database: app.db(.psql))
            let leases = try await outbox.claim(now: now, leaseDuration: 1, limit: 10)
            #expect(leases.count == 1)
            for lease in leases {
                let sequence = try await projector.project(lease.event)
                #expect(try await projector.project(lease.event) == sequence)
                #expect(try await outbox.acknowledge(lease, sequence: sequence, now: now))
            }
            #expect(try await count("im_v2.user_sync_log", on: sql) == 3)
            try await sql.raw("DROP SCHEMA im_v2 CASCADE").run()
            try await app.asyncShutdown()
        } catch {
            if let sql = app.db(.psql) as? any SQLDatabase { try? await sql.raw("DROP SCHEMA IF EXISTS im_v2 CASCADE").run() }
            try? await app.asyncShutdown()
            throw error
        }
    }

    @Test("Group audience timestamps preserve staging, recovery and completion after rejection")
    func groupAudienceTimestampBoundaries() async throws {
        guard let databaseURL = Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"),
              Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" else { return }
        let app = try await Application.make(.testing)
        do {
            app.databases.use(try .postgres(url: databaseURL), as: .psql, isDefault: true)
            let sql = try #require(app.db(.psql) as? any SQLDatabase)
            try await installSchema(on: sql)
            try await seedRoom(on: sql)
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let store = PostgresV2GroupAudienceImportStore(database: app.db(.psql))
            let policy = V2GroupAudienceImportPolicy(maximumStagedMembersPerActor: 10, stagingLifetime: 60, completedRetention: 120, finalizingRecoveryInterval: 10)
            let operation = GroupRoomOperationID(uuid: UUID())
            let members = [UserID(uuid: memberTwoUUID)]
            _ = try await store.begin(actorUserID: senderID, operationID: operation, title: "clock", policy: policy, now: now)
            #expect(try await store.append(actorUserID: senderID, operationID: operation, memberUserIDs: members, maximumMembers: 10, policy: policy, now: now).stagedMemberCount == 1)
            for seconds in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12] {
                let invalid = Date(timeIntervalSince1970: seconds)
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.begin(actorUserID: senderID, operationID: operation, title: "clock", policy: policy, now: invalid) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.append(actorUserID: senderID, operationID: operation, memberUserIDs: members, maximumMembers: 10, policy: policy, now: invalid) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.freeze(actorUserID: senderID, operationID: operation, policy: policy, now: invalid) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.complete(actorUserID: senderID, operationID: operation, roomID: roomID, policy: policy, now: invalid) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.cancel(actorUserID: senderID, operationID: operation, now: invalid) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.purgeExpired(now: invalid, limit: 8) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.recoverableFinalizing(now: invalid, staleAfter: 10, limit: 8) }
            }
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 30)
            #expect(v2PostgresTimestampCanEncode(upper))
            #expect(!v2PostgresTimestampCanEncode(upper.addingTimeInterval(60)))
            await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.begin(actorUserID: senderID, operationID: operation, title: "clock", policy: policy, now: upper) }
            await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.append(actorUserID: senderID, operationID: operation, memberUserIDs: members, maximumMembers: 10, policy: policy, now: upper) }
            await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.freeze(actorUserID: senderID, operationID: operation, policy: policy, now: upper) }
            await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.complete(actorUserID: senderID, operationID: operation, roomID: roomID, policy: policy, now: upper) }
            let lower = Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + 5)
            #expect(v2PostgresTimestampCanEncode(lower))
            await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.recoverableFinalizing(now: lower, staleAfter: 10, limit: 8) }
            for duration in [Double.infinity, .greatestFiniteMagnitude, 0.0000001] {
                let invalidPolicy = V2GroupAudienceImportPolicy(maximumStagedMembersPerActor: 10, stagingLifetime: duration, completedRetention: duration)
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.begin(actorUserID: senderID, operationID: operation, title: "clock", policy: invalidPolicy, now: now) }
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.complete(actorUserID: senderID, operationID: operation, roomID: roomID, policy: invalidPolicy, now: now) }
            }
            for interval in [Double.infinity, .greatestFiniteMagnitude, .leastNonzeroMagnitude] {
                await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) { try await store.recoverableFinalizing(now: now, staleAfter: interval, limit: 8) }
            }
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.group_room_creation_drafts WHERE state = 'staging' AND updated_at = \(bind: now) AND expires_at = \(bind: now.addingTimeInterval(60))").first(decoding: CountRow.self)?.value == 1)
            #expect(try await count("im_v2.group_room_creation_draft_members", on: sql) == 1)
            #expect(try await store.begin(actorUserID: senderID, operationID: operation, title: "clock", policy: policy, now: now).stagedMemberCount == 1)
            #expect(try await store.append(actorUserID: senderID, operationID: operation, memberUserIDs: members, maximumMembers: 10, policy: policy, now: now).stagedMemberCount == 1)
            #expect(try await store.freeze(actorUserID: senderID, operationID: operation, policy: policy, now: now.addingTimeInterval(1)).stagedMemberCount == 1)
            await #expect(throws: V2GroupAudienceImportError.corruptPersistenceState) {
                try await store.recoverableFinalizing(now: now.addingTimeInterval(12), staleAfter: .leastNonzeroMagnitude, limit: 8)
            }
            #expect(try await store.recoverableFinalizing(now: now.addingTimeInterval(5), staleAfter: 10, limit: 8).isEmpty)
            let recovery = try await store.recoverableFinalizing(now: now.addingTimeInterval(12), staleAfter: 10, limit: 8)
            #expect(recovery == [.init(actorUserID: senderID, operationID: operation)])
            #expect(try await store.recoverableFinalizing(now: now.addingTimeInterval(12), staleAfter: 10, limit: 8).isEmpty)
            try await store.complete(actorUserID: senderID, operationID: operation, roomID: roomID, policy: policy, now: now.addingTimeInterval(13))
            try await store.complete(actorUserID: senderID, operationID: operation, roomID: roomID, policy: policy, now: now.addingTimeInterval(13))
            #expect(try await store.purgeExpired(now: now.addingTimeInterval(132), limit: 8) == 0)
            #expect(try await store.purgeExpired(now: now.addingTimeInterval(133), limit: 8) == 1)
            #expect(try await count("im_v2.group_room_creation_draft_members", on: sql) == 0)
            let cancelled = GroupRoomOperationID(uuid: UUID()), discarded = GroupRoomOperationID(uuid: UUID())
            _ = try await store.begin(actorUserID: senderID, operationID: cancelled, title: "cancel", policy: policy, now: now.addingTimeInterval(140))
            try await store.cancel(actorUserID: senderID, operationID: cancelled, now: now.addingTimeInterval(141))
            try await store.cancel(actorUserID: senderID, operationID: cancelled, now: now.addingTimeInterval(141))
            _ = try await store.begin(actorUserID: senderID, operationID: discarded, title: "discard", policy: policy, now: now.addingTimeInterval(142))
            _ = try await store.freeze(actorUserID: senderID, operationID: discarded, policy: policy, now: now.addingTimeInterval(143))
            // Discarding an explicitly frozen draft does not bind or compare
            // a clock; this cleanup remains available independently of it.
            try await store.discardFrozen(actorUserID: senderID, operationID: discarded, now: Date(timeIntervalSince1970: .nan))
            #expect(try await count("im_v2.group_room_creation_drafts", on: sql) == 0)
            #expect(try await count("im_v2.group_room_creation_draft_members", on: sql) == 0)
            try await sql.raw("DROP SCHEMA im_v2 CASCADE").run()
            try await app.asyncShutdown()
        } catch {
            if let sql = app.db(.psql) as? any SQLDatabase { try? await sql.raw("DROP SCHEMA IF EXISTS im_v2 CASCADE").run() }
            try? await app.asyncShutdown()
            throw error
        }
    }

    @Test("Small control housekeeping budgets reach late cleanup categories", arguments: [0, 60, 600, 3_600])
    func housekeepingSmallBudgetDoesNotStarve(interval: Int) async throws {
        guard let databaseURL = Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"),
              Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" else { return }
        let app = try await Application.make(.testing)
        do {
            app.databases.use(try .postgres(url: databaseURL), as: .psql, isDefault: true)
            let sql = try #require(app.db(.psql) as? any SQLDatabase)
            try await installSchema(on: sql)
            let user = UUID(), device = UUID()
            let retention = V2IdempotencyPolicy.minimumServerRetention
            let base = Date(timeIntervalSince1970: 1_750_000_000)
            let old = base.addingTimeInterval(-retention - 86_400)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: user), \(bind: device), \(bind: old), \(bind: old))").run()
            try await sql.raw("INSERT INTO im_v2.user_live_presence_leases (user_id, device_id, connection_id, updated_at, expires_at) VALUES (\(bind: user), \(bind: device), \(bind: UUID()), \(bind: old), \(bind: old))").run()
            try await sql.raw("INSERT INTO im_v2.user_live_activity_preference_operations (actor_user_id, operation_id, allows_online_presence, allows_typing_indicators, updated_at) VALUES (\(bind: user), \(bind: UUID()), true, true, \(bind: old))").run()
            if interval == 0 {
                try await V2SchemaReadiness.verify(database: app.db(.psql))
                try await sql.raw("DELETE FROM im_v2.control_housekeeping_cursor").run()
                await #expect(throws: V2SchemaReadinessError.self) {
                    try await V2SchemaReadiness.verify(database: app.db(.psql))
                }
                try await sql.raw("INSERT INTO im_v2.control_housekeeping_cursor VALUES (true, 8)").run()
                let store = PostgresV2ControlPlaneHousekeepingStore(database: app.db(.psql))
                try await sql.raw("CREATE FUNCTION im_v2.fail_housekeeping() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'cleanup rollback fixture'; END; $$").run()
                try await sql.raw("CREATE TRIGGER fail_housekeeping BEFORE DELETE ON im_v2.user_live_presence_leases FOR EACH ROW EXECUTE FUNCTION im_v2.fail_housekeeping()").run()
                await #expect(throws: (any Error).self) {
                    try await store.purgeTerminal(now: base, retention: 60, idempotencyRetention: retention, limit: 1)
                }
                #expect(try await count("im_v2.control_housekeeping_cursor WHERE rotation = 8", on: sql) == 1)
                #expect(try await count("im_v2.user_live_presence_leases", on: sql) == 1)
                try await sql.raw("DROP TRIGGER fail_housekeeping ON im_v2.user_live_presence_leases").run()
                try await sql.raw("UPDATE im_v2.control_housekeeping_cursor SET rotation = 0").run()
                async let first = store.purgeTerminal(now: base, retention: 60, idempotencyRetention: retention, limit: 1)
                async let second = PostgresV2ControlPlaneHousekeepingStore(database: app.db(.psql)).purgeTerminal(now: base, retention: 60, idempotencyRetention: retention, limit: 1)
                _ = try await (first, second)
                #expect(try await count("im_v2.control_housekeeping_cursor WHERE rotation = 2", on: sql) == 1)
                try await sql.raw("UPDATE im_v2.control_housekeeping_cursor SET rotation = 0").run()
            }
            var leases = 0, operations = 0
            // Recreate the store every pass; fairness belongs to committed
            // database state, even for frozen clocks or hourly scheduling.
            for pass in 0..<300 {
                let store = PostgresV2ControlPlaneHousekeepingStore(database: app.db(.psql))
                let report = try await store.purgeTerminal(now: base.addingTimeInterval(Double(pass * interval)),
                    retention: 60, idempotencyRetention: retention, limit: 1)
                #expect(report.deletedRows <= 1)
                leases += report.purgedExpiredConnectionLeaseRows
                operations += report.purgedIdempotencyRows
                if leases == 1 && operations == 1 { break }
            }
            #expect(leases == 1)
            #expect(operations == 1)
            #expect(try await count("im_v2.user_live_presence_leases", on: sql) == 0)
            #expect(try await count("im_v2.user_live_activity_preference_operations", on: sql) == 0)
            try await sql.raw("DROP SCHEMA im_v2 CASCADE").run()
            try await app.asyncShutdown()
        } catch {
            if let sql = app.db(.psql) as? any SQLDatabase { try? await sql.raw("DROP SCHEMA IF EXISTS im_v2 CASCADE").run() }
            try? await app.asyncShutdown()
            throw error
        }
    }

    @Test("Housekeeping validates all cutoffs before deletion and recovers after bad clocks", arguments: [Date(timeIntervalSince1970: 1_750_000_000), Date(timeIntervalSince1970: -3_600.5)])
    func housekeepingTimestampBoundaries(now: Date) async throws {
        guard let databaseURL = Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"),
              Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" else { return }
        let app = try await Application.make(.testing)
        do {
            app.databases.use(try .postgres(url: databaseURL), as: .psql, isDefault: true)
            let sql = try #require(app.db(.psql) as? any SQLDatabase)
            try await installSchema(on: sql)
            let user = UUID(), device = UUID()
            let retention = V2IdempotencyPolicy.minimumServerRetention
            let old = now.addingTimeInterval(-retention - 60)
            try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: user), \(bind: device), \(bind: old), \(bind: old))").run()
            try await sql.raw("INSERT INTO im_v2.device_sync_cursors (user_id, device_id, state, reset_generation, acknowledged_sequence) VALUES (\(bind: user), \(bind: device), 'ready', 1, 7)").run()
            try await sql.raw("INSERT INTO im_v2.user_live_activity_preferences (user_id, updated_at) VALUES (\(bind: user), \(bind: old))").run()
            for (label, date, expiry) in [("old", old, now.addingTimeInterval(-1)), ("live", now, now.addingTimeInterval(60))] {
                try await sql.raw("INSERT INTO im_v2.user_live_presence_leases (user_id, device_id, connection_id, updated_at, expires_at) VALUES (\(bind: user), \(bind: device), \(bind: UUID()), \(bind: date), \(bind: expiry))").run()
                try await sql.raw("INSERT INTO im_v2.sync_tokens (token, user_id, device_id, reset_generation, watermark, expires_at, created_at) VALUES (\(bind: label + "-token"), \(bind: user), \(bind: device), 1, 7, \(bind: expiry), \(bind: date))").run()
                try await sql.raw("INSERT INTO im_v2.sync_receipts (receipt, user_id, device_id, reset_generation, first_sequence, last_sequence, expires_at, created_at) VALUES (\(bind: label + "-receipt"), \(bind: user), \(bind: device), 1, 7, 7, \(bind: expiry), \(bind: date))").run()
                try await sql.raw("INSERT INTO im_v2.user_live_activity_preference_operations (actor_user_id, operation_id, allows_online_presence, allows_typing_indicators, updated_at) VALUES (\(bind: user), \(bind: UUID()), true, true, \(bind: date))").run()
            }
            let control = PostgresV2ControlPlaneHousekeepingStore(database: app.db(.psql))
            let sync = PostgresV2SyncHousekeepingStore(database: app.db(.psql))
            // This clock and its short terminal cutoff are valid, but the
            // longer replay/effect retention crosses PostgreSQL's lower bound.
            let lower = Date(timeIntervalSince1970: 946_684_800 - 211_813_488_000 + 120)
            #expect(v2PostgresTimestampCanEncode(lower))
            #expect(v2PostgresTimestampCanEncode(lower.addingTimeInterval(-60)))
            #expect(!v2PostgresTimestampCanEncode(lower.addingTimeInterval(-retention)))
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12, Double(Int.min) * 60].map { Date(timeIntervalSince1970: $0) } + [lower]
            for invalid in invalidDates {
                await #expect(throws: V2ControlPlaneHousekeepingError.corruptPersistenceState) {
                    try await V2ControlPlaneHousekeepingWorker(store: control, retention: 60, now: { invalid }).runOnce(limit: 1_024)
                }
                await #expect(throws: V2SyncHousekeepingError.corruptPersistenceState) {
                    try await V2SyncHousekeepingWorker(store: sync, now: { invalid }).runOnce(limit: 8)
                }
            }
            await #expect(throws: V2ControlPlaneHousekeepingError.corruptPersistenceState) {
                try await control.purgeTerminal(now: now, retention: .greatestFiniteMagnitude, idempotencyRetention: retention, limit: 1_024)
            }
            await #expect(throws: V2ControlPlaneHousekeepingError.corruptPersistenceState) {
                try await control.purgeTerminal(now: now, retention: 60, idempotencyRetention: .greatestFiniteMagnitude, limit: 1_024)
            }
            await #expect(throws: V2SyncHousekeepingError.corruptPersistenceState) {
                try await sync.purgeExpired(now: now, projectionEffectRetention: .greatestFiniteMagnitude, limit: 8)
            }
            let tables = ["user_live_presence_leases", "user_live_activity_preference_operations", "sync_tokens", "sync_receipts"]
            for table in tables { #expect(try await count("im_v2." + table, on: sql) == 2) }
            #expect(try await count("im_v2.device_sync_cursors WHERE state = 'ready' AND acknowledged_sequence = 7", on: sql) == 1)
            let controlReport = try await V2ControlPlaneHousekeepingWorker(store: control, retention: 60, now: { now }).runOnce(limit: 1_024)
            #expect(controlReport == .init(deletedRows: 2, purgedIdempotencyRows: 1, purgedExpiredConnectionLeaseRows: 1))
            let syncReport = try await V2SyncHousekeepingWorker(store: sync, now: { now }).runOnce(limit: 8)
            #expect(syncReport == .init(expiredTokenCount: 1, expiredReceiptCount: 1, recoveredResetCount: 0, purgedSnapshotCount: 0))
            for table in tables { #expect(try await count("im_v2." + table, on: sql) == 1) }
            #expect(try await count("im_v2.user_live_activity_preferences", on: sql) == 1)
            #expect(try await count("im_v2.device_sync_cursors WHERE state = 'ready' AND acknowledged_sequence = 7", on: sql) == 1)
            #expect(try await control.purgeTerminal(now: now, retention: 60, idempotencyRetention: retention, limit: 1_024).didWork == false)
            #expect(try await sync.purgeExpired(now: now, projectionEffectRetention: retention, limit: 8).didWork == false)
            try await sql.raw("DROP SCHEMA im_v2 CASCADE").run()
            try await app.asyncShutdown()
        } catch {
            if let sql = app.db(.psql) as? any SQLDatabase { try? await sql.raw("DROP SCHEMA IF EXISTS im_v2 CASCADE").run() }
            try? await app.asyncShutdown()
            throw error
        }
    }

    @Test("Vanished presence durations leave no leases or renewal mutations and allow corrected lifetimes")
    func liveLeaseVanishedDuration() async throws {
        try await withForwardOwnerDatabases(mode: .standard) { database, _, sql, _, _ in
            let valid = try PostgresV2LiveActivityStore(database: database, onlineLease: 0.5)
            let tiny = try PostgresV2LiveActivityStore(database: database, onlineLease: 1e-12)
            let policy = V2AuthenticatedConnectionAdmissionPolicy(maximumConnectionsPerDevice: 2, maximumConnectionsPerUser: 8)
            for seconds in [Double(-1.0005), -1_000_000_000.1255, -210_866_803_199.1255, 1_750_000_000.1255] {
                let now = Date(timeIntervalSince1970: seconds)
                let user = UUID(), device = UUID(), connection = UUID(), newConnection = UUID()
                try await sql.raw("""
                    INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at)
                    VALUES (\(bind: user), \(bind: device), \(bind: now), \(bind: now))
                    """).run()
                let identity = V2AuthenticatedConnection(userID: .init(uuid: user), deviceID: .init(uuid: device), capabilityProfile: "base")
                guard case .accepted = try await valid.admitConnection(identity: identity, connectionID: connection, policy: policy, now: now) else {
                    Issue.record("Expected a usable half-second presence lease")
                    throw CancellationError()
                }
                func snapshot() async throws -> String {
                    let row = try await sql.raw("""
                        SELECT COALESCE(jsonb_agg(to_jsonb(lease) ORDER BY connection_id), '[]'::jsonb)::text AS value
                        FROM im_v2.user_live_presence_leases lease WHERE user_id = \(bind: user)
                        """).first(decoding: StringValueRow.self)
                    return try #require(row).value
                }
                let before = try await snapshot()
                let observed = now.addingTimeInterval(0.125)
                #expect(observed.addingTimeInterval(1e-12) == observed)
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) {
                    _ = try await tiny.admitConnection(identity: identity, connectionID: newConnection, policy: policy, now: observed)
                }
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) {
                    _ = try await tiny.renewConnection(identity: identity, connectionID: connection, now: observed)
                }
                let rejected = try await tiny.renewConnections([connection, newConnection].map {
                    .init(identity: identity, connectionID: $0, now: observed)
                })
                for value in rejected.values { #expect(value == .init(outcome: .rejected, allowsOnlinePresence: false)) }
                #expect(rejected.count == 2)
                #expect(try await snapshot() == before)

                guard case .accepted = try await valid.renewConnection(identity: identity, connectionID: connection, now: observed) else {
                    Issue.record("Expected scalar renewal after correcting the configured lifetime")
                    throw CancellationError()
                }
                let later = now.addingTimeInterval(0.25)
                let renewed = try await valid.renewConnections([.init(identity: identity, connectionID: connection, now: later)])
                guard case .accepted? = renewed[connection]?.outcome else {
                    Issue.record("Expected batch renewal after correcting the configured lifetime")
                    throw CancellationError()
                }
                #expect(try await sql.raw("""
                    SELECT COUNT(*)::bigint AS value FROM im_v2.user_live_presence_leases
                    WHERE user_id = \(bind: user) AND connection_id = \(bind: connection)
                      AND expires_at > updated_at AND updated_at = \(bind: later)
                      AND expires_at = \(bind: later.addingTimeInterval(0.5))
                    """).first(decoding: CountRow.self)?.value == 1)
            }
        }
    }

    @Test("Presence leases validate database bounds and never regress on older heartbeats")
    func liveLeaseTimestampBoundaries() async throws {
        guard let databaseURL = Environment.get("IMV2_POSTGRES_TEST_DATABASE_URL"),
              Environment.get("IMV2_POSTGRES_TEST_DATABASE_IS_DISPOSABLE") == "1" else { return }
        let app = try await Application.make(.testing)
        do {
            app.databases.use(try .postgres(url: databaseURL), as: .psql, isDefault: true)
            let sql = try #require(app.db(.psql) as? any SQLDatabase)
            try await installSchema(on: sql)
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let users = [UUID(), UUID()], devices = [UUID(), UUID()], connections = [UUID(), UUID()]
            var identities: [V2AuthenticatedConnection] = []
            for (user, device) in zip(users, devices) {
                try await sql.raw("INSERT INTO im_v2.auth_devices (user_id, device_id, created_at, last_active_at) VALUES (\(bind: user), \(bind: device), \(bind: now), \(bind: now))").run()
                identities.append(.init(userID: .init(uuid: user), deviceID: .init(uuid: device), capabilityProfile: "base"))
            }
            for duration in [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, 0, -1, Double(Int64.max) / 1_000_000] {
                #expect(throws: V2LiveActivityConfigurationError.invalidOnlineLease) {
                    try PostgresV2LiveActivityStore(database: app.db(.psql), onlineLease: duration)
                }
            }
            let store = try PostgresV2LiveActivityStore(database: app.db(.psql))
            let policy = V2AuthenticatedConnectionAdmissionPolicy(maximumConnectionsPerDevice: 2, maximumConnectionsPerUser: 8)
            let upper = Date(timeIntervalSince1970: 946_684_800 + 9_223_371_331_200 - 45)
            #expect(v2PostgresTimestampCanEncode(upper))
            #expect(!v2PostgresTimestampCanEncode(upper.addingTimeInterval(90)))
            let invalidDates = [Double.nan, .infinity, -.infinity, .greatestFiniteMagnitude, -.greatestFiniteMagnitude, 1e14, -1e14, -1e12].map { Date(timeIntervalSince1970: $0) } + [upper]
            for invalid in invalidDates {
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) {
                    try await store.admitConnection(identity: identities[0], connectionID: connections[0], policy: policy, now: invalid)
                }
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) {
                    try await store.renewConnection(identity: identities[0], connectionID: connections[0], now: invalid)
                }
                let batch = try await store.renewConnections([.init(identity: identities[0], connectionID: connections[0], now: invalid)])
                #expect(batch[connections[0]] == .init(outcome: .rejected, allowsOnlinePresence: false))
            }
            let tiny = try PostgresV2LiveActivityStore(database: app.db(.psql), onlineLease: 0.0000001)
            await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) {
                try await tiny.admitConnection(identity: identities[0], connectionID: connections[0], policy: policy, now: now)
            }
            #expect(try await count("im_v2.user_live_presence_leases", on: sql) == 0)
            for index in identities.indices {
                #expect(try await store.admitConnection(identity: identities[index], connectionID: connections[index], policy: policy, now: now) == .accepted(expiresAt: now.addingTimeInterval(90)))
            }
            // A bad clock during cleanup must neither bind an invalid date
            // nor partially delete the still-owned lease.
            for invalid in invalidDates.dropLast() {
                await #expect(throws: V2LiveActivityStoreError.corruptPersistenceState) {
                    try await store.removePresence(identity: identities[0], connectionID: connections[0], now: invalid)
                }
            }
            #expect(try await count("im_v2.user_live_presence_leases", on: sql) == 2)
            #expect(try await store.renewConnection(identity: identities[0], connectionID: connections[0], now: now.addingTimeInterval(20)) == .accepted(expiresAt: now.addingTimeInterval(110)))
            #expect(try await store.renewConnection(identity: identities[0], connectionID: connections[0], now: now.addingTimeInterval(10)) == .accepted(expiresAt: now.addingTimeInterval(110)))
            #expect(try await store.admitConnection(identity: identities[0], connectionID: connections[0], policy: policy, now: now.addingTimeInterval(5)) == .accepted(expiresAt: now.addingTimeInterval(110)))
            _ = try await store.setPreferences(command: .init(actorUserID: identities[1].userID, operationID: .init(uuid: UUID()), allowsOnlinePresence: false, allowsTypingIndicators: true), now: now)
            let invalidConnection = UUID()
            let mixed = try await store.renewConnections([
                .init(identity: identities[0], connectionID: connections[0], now: Date(timeIntervalSince1970: .nan)),
                .init(identity: identities[0], connectionID: connections[0], now: now.addingTimeInterval(30)),
                .init(identity: identities[1], connectionID: invalidConnection, now: Date(timeIntervalSince1970: -1e12)),
                .init(identity: identities[1], connectionID: connections[1], now: now.addingTimeInterval(40)),
                .init(identity: identities[0], connectionID: connections[0], now: now.addingTimeInterval(15)),
                .init(identity: identities[1], connectionID: connections[1], now: Date(timeIntervalSince1970: 1e14))
            ])
            #expect(mixed.count == 3)
            #expect(mixed[connections[0]] == .init(outcome: .accepted(expiresAt: now.addingTimeInterval(120)), allowsOnlinePresence: true))
            #expect(mixed[connections[1]] == .init(outcome: .accepted(expiresAt: now.addingTimeInterval(130)), allowsOnlinePresence: false))
            #expect(mixed[invalidConnection] == .init(outcome: .rejected, allowsOnlinePresence: false))
            let stale = try await store.renewConnections(identities.indices.map { .init(identity: identities[$0], connectionID: connections[$0], now: now.addingTimeInterval(1)) })
            #expect(stale[connections[0]] == mixed[connections[0]])
            #expect(stale[connections[1]] == mixed[connections[1]])
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.user_live_presence_leases WHERE (connection_id = \(bind: connections[0]) AND updated_at = \(bind: now.addingTimeInterval(30)) AND expires_at = \(bind: now.addingTimeInterval(120))) OR (connection_id = \(bind: connections[1]) AND updated_at = \(bind: now.addingTimeInterval(40)) AND expires_at = \(bind: now.addingTimeInterval(130)))").first(decoding: CountRow.self)?.value == 2)
            #expect(try await store.renewConnection(identity: identities[1], connectionID: connections[1], now: now.addingTimeInterval(130)) == .rejected)
            let expired = try await store.renewConnections(identities.indices.map { .init(identity: identities[$0], connectionID: connections[$0], now: now.addingTimeInterval(130)) })
            for value in expired.values { #expect(value.outcome == .rejected) }
            for index in identities.indices {
                #expect(try await store.removePresence(identity: identities[index], connectionID: connections[index], now: now.addingTimeInterval(131)) == false)
            }
            #expect(try await count("im_v2.user_live_presence_leases", on: sql) == 0)
            // A valid database date before Date.distantPast must not be
            // discarded by the duplicate-heartbeat selection default.
            let historical = Date(timeIntervalSince1970: -100_000_000_000)
            #expect(historical < Date.distantPast)
            #expect(try await store.admitConnection(identity: identities[0], connectionID: connections[0], policy: policy, now: historical) == .accepted(expiresAt: historical.addingTimeInterval(90)))
            let historicalBatch = try await store.renewConnections([.init(identity: identities[0], connectionID: connections[0], now: historical.addingTimeInterval(1))])
            #expect(historicalBatch[connections[0]]?.outcome == .accepted(expiresAt: historical.addingTimeInterval(91)))
            #expect(try await store.removePresence(identity: identities[0], connectionID: connections[0], now: historical.addingTimeInterval(2)) == false)
            try await sql.raw("DROP SCHEMA im_v2 CASCADE").run()
            try await app.asyncShutdown()
        } catch {
            if let sql = app.db(.psql) as? any SQLDatabase { try? await sql.raw("DROP SCHEMA IF EXISTS im_v2 CASCADE").run() }
            try? await app.asyncShutdown()
            throw error
        }
    }

