    @Test("routed sends reject stale owners before commit or replay", arguments: ["standard", "hybrid", "hybridBatch", "direct", "directBatch", "directRich"])
    func routedSendOwnerEpochFence(_ kind: String) async throws {
        let mode: V2GroupCapacityClass = kind.hasPrefix("hybrid") ? .large : .standard
        try await withForwardOwnerDatabases(mode: mode) { control, owner, sql, ownerSQL, fixtureRoom in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let room: RoomID
            if kind.hasPrefix("direct") {
                let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                    capacityProfile: profile, roomShardID: "room-b", now: { now })
                guard case .opened(let value) = try await direct.open(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberTwoUUID)) else {
                    throw V2RoomWriteStoreError.corruptPersistenceState
                }
                room = value.roomID
            } else { room = fixtureRoom }
            let batchPeer: RoomID?
            if kind == "directBatch" {
                let direct = try V2DirectMessagingService(store: PostgresV2DirectMessagingStore(database: owner),
                    capacityProfile: profile, roomShardID: "room-b", now: { now })
                guard case .opened(let value) = try await direct.open(actorUserID: senderID,
                    operationID: .init(uuid: UUID()), targetUserID: .init(uuid: memberThreeUUID)) else {
                    throw V2RoomWriteStoreError.corruptPersistenceState
                }
                batchPeer = value.roomID
                try await sql.raw("INSERT INTO im_v2.room_owner_routes(room_id,room_shard_id,route_epoch,created_at,updated_at) VALUES (\(bind: value.roomID.uuidValue!), 'room-b', 0, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at").run()
            } else { batchPeer = nil }
            let writer = PostgresV2RoomWriteStore(database: owner,
                strangerMessagePolicy: try .init(maximumMessagesPerWindow: 10, window: 86_400), contentReviewMode: .disabled, directRoomLogAdmissionMode: .shardOnly,
                shardAdmissionCommandCreditPool: .init(database: owner, batchSize: 2))
            try await sql.raw("INSERT INTO im_v2.room_owner_routes(room_id,room_shard_id,route_epoch,created_at,updated_at) VALUES (\(bind: room.uuidValue!), 'room-b', 1, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at").run()
            func routed() throws -> V2RoutedRoomWriteStore {
                try .init(router: V2CachedRoomShardRouter(source: V2PostgresRoomShardRouter(database: control)), stores: ["room-b": writer, "colocated": writer], physicalStoreKeyByShard: ["room-b": "physical", "colocated": "physical"])
            }
            func requests() throws -> [V2RoomWriteRequest] {
                try (0..<(kind.hasSuffix("Batch") ? 2 : 1)).map { index in
                    .init(command: try .init(roomID: index == 1 ? (batchPeer ?? room) : room, senderUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "send owner", entities: kind == "directRich" ? [try .init(offsetUTF16: 0, lengthUTF16: 4, kind: .bold)] : [], limits: .init(maxUTF8Bytes: 64)), capacityProfile: profile, identifiers: try V2AcceptanceIDFactory().make(at: now), now: now)
                }
            }
            func run(_ store: any V2AtomicRoomWriteBatchStore, _ inputs: [V2RoomWriteRequest]) async throws -> [V2SendMessageOutcome] {
                if kind.hasSuffix("Batch") { return try await store.acceptAtomically(requests: inputs) }
                let input = inputs[0]
                return [try await store.accept(command: input.command, capacityProfile: input.capacityProfile, identifiers: input.identifiers, now: input.now)]
            }
            let inputs = try requests()
            await #expect(throws: V2RoomOwnerFenceError.ownerChanged) { _ = try await run(routed(), inputs) }
            let count = try #require(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.messages").first(decoding: CountRow.self)).value
            #expect(count == 0)
            guard count == 0 else { return }
            try await sql.raw("UPDATE im_v2.room_owner_routes SET route_epoch=0 WHERE room_id=\(bind: room.uuidValue!)").run()
            let cached = try routed()
            let accepted = try await run(cached, inputs)
            #expect(accepted.allSatisfy { if case .accepted = $0 { true } else { false } })
            try await ownerSQL.raw("UPDATE im_v2.rooms SET owner_epoch=1 WHERE room_id=\(bind: room.uuidValue!)").run()
            try await sql.raw("UPDATE im_v2.room_owner_routes SET route_epoch=1 WHERE room_id=\(bind: room.uuidValue!)").run()
            await #expect(throws: V2RoomOwnerFenceError.ownerChanged) { _ = try await run(cached, inputs) }
            await #expect(throws: V2RoomOwnerFenceError.ownerChanged) { _ = try await run(cached, requests()) }
            // Atomic batches reject replay and fall back to scalar in the real batcher.
            let fresh = try routed()
            for input in inputs {
                guard case .idempotent = try await fresh.accept(command: input.command, capacityProfile: input.capacityProfile, identifiers: input.identifiers, now: input.now) else { throw V2RoomWriteStoreError.corruptPersistenceState }
            }
            #expect(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.messages").first(decoding: CountRow.self)?.value == Int64(inputs.count))
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.messages").first(decoding: CountRow.self)?.value == 0)
            try await ownerSQL.raw("UPDATE im_v2.rooms SET room_shard_id='retired' WHERE room_id=\(bind: room.uuidValue!)").run()
            await #expect(throws: V2RoomOwnerFenceError.ownerChanged) { _ = try await run(routed(), requests()) }
            try await ownerSQL.raw("UPDATE im_v2.rooms SET room_shard_id='room-b' WHERE room_id=\(bind: room.uuidValue!)").run()
            try await sql.raw("UPDATE im_v2.room_owner_routes SET room_shard_id='unknown' WHERE room_id=\(bind: room.uuidValue!)").run()
            await #expect(throws: V2RoomShardStorageRegistryError.unknownShardID) { _ = try await run(routed(), requests()) }
            try await sql.raw("UPDATE im_v2.room_owner_routes SET room_shard_id='room-b' WHERE room_id=\(bind: room.uuidValue!)").run()
            let wrong = try V2RoutedRoomWriteStore(router: V2PostgresRoomShardRouter(database: control), stores: ["room-b": PostgresV2RoomWriteStore(database: control)])
            await #expect(throws: V2RoomOwnerFenceError.ownerChanged) { _ = try await wrong.accept(command: inputs[0].command, capacityProfile: profile, identifiers: inputs[0].identifiers, now: now) }
            let barrier = InviteImportTestBarrier()
            let holder = Task {
                try await owner.transaction { transaction in
                    let locked = try #require(transaction as? any SQLDatabase)
                    try await locked.raw("SELECT room_id FROM im_v2.rooms WHERE room_id=\(bind: room.uuidValue!) FOR UPDATE").run()
                    await barrier.hold()
                    try await locked.raw("UPDATE im_v2.rooms SET owner_epoch=2 WHERE room_id=\(bind: room.uuidValue!)").run()
                }
            }
            await barrier.waitUntilHeld()
            let queuedInputs = try requests()
            let queued = Task { try await run(routed(), queuedInputs) }
            do {
                var waiting = false
                for _ in 0..<1000 {
                    waiting = try await ownerSQL.raw("SELECT COUNT(*) AS value FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE '%owner_epoch%' AND query LIKE '%FOR NO KEY UPDATE%'").first(decoding: CountRow.self)?.value == 1
                    if waiting { break }
                    try await Task.sleep(for: .milliseconds(10))
                }
                #expect(waiting)
                guard waiting else { throw TestConfigurationError.schemaAlreadyExists }
                try await sql.raw("UPDATE im_v2.room_owner_routes SET route_epoch=2 WHERE room_id=\(bind: room.uuidValue!)").run()
                await barrier.release(); try await holder.value
                await #expect(throws: V2RoomOwnerFenceError.ownerChanged) { _ = try await queued.value }
            } catch {
                await barrier.release(); _ = try? await holder.value; _ = try? await queued.value
                throw error
            }
            #expect(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.messages").first(decoding: CountRow.self)?.value == Int64(inputs.count))
            let freshInputs = try requests()
            #expect(try await run(routed(), freshInputs).allSatisfy { if case .accepted = $0 { true } else { false } })
        }
    }

    @Test("shared receipt batches isolate owner errors and keep scalar replay consistent", arguments: [V2GroupCapacityClass.standard, .large])
    func readReceiptOwnerMixedBatch(_ mode: V2GroupCapacityClass) async throws {
        try await withForwardOwnerDatabases(mode: mode) { control, owner, sql, ownerSQL, room in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let service = try V2SendMessageService(store: PostgresV2RoomWriteStore(database: owner), capacityProfile: forwardImportTestProfile(), limits: .init(maxUTF8Bytes: 64), now: { now })
            var lastMessageID: MessageID?
            for _ in 0..<2 {
                guard case .accepted(let message) = try await service.send(.init(roomID: room, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "receipt owner")) else { throw V2ReadReceiptStoreError.corruptPersistenceState }
                lastMessageID = message.messageID
            }
            let messageID = try #require(lastMessageID)
            try await ownerSQL.raw("DELETE FROM im_v2.public_user_profiles").run()
            try await ownerSQL.raw("UPDATE im_v2.rooms SET owner_epoch=2 WHERE room_id=\(bind: room.uuidValue!)").run()
            let ownerStore = PostgresV2ReadReceiptStore(database: owner)
            let current = try V2RoomShardRoute(shardID: "room-b", epoch: 2)
            let stale = try V2RoomShardRoute(shardID: "room-b", epoch: 1)
            let missingRoom = RoomID(uuid: UUID())
            func request(_ user: UserID, _ sequence: UInt64, roomID: RoomID? = nil) throws -> V2ReadReceiptRecordRequest {
                .init(command: try .init(roomID: roomID ?? room, actorUserID: user, operationID: .init(uuid: UUID()), readThroughRoomSequence: sequence), now: now)
            }
            let first = try request(.init(uuid: memberTwoUUID), 1)
            let expired = try request(.init(uuid: memberTwoUUID), 2)
            let wrongShard = try request(.init(uuid: memberThreeUUID), 2)
            let missing = try request(.init(uuid: memberThreeUUID), 1, roomID: missingRoom)
            let overSequence = try request(.init(uuid: memberThreeUUID), 3)
            let outsider = try request(.init(uuid: UUID()), 1)
            let second = try request(.init(uuid: memberThreeUUID), 2)
            let results = try await ownerStore.recordGroupsOwnerValidated([
                .init(request: first, ownerRoute: current), .init(request: expired, ownerRoute: stale),
                .init(request: wrongShard, ownerRoute: .init(shardID: "wrong", epoch: 2)),
                .init(request: missing, ownerRoute: current), .init(request: overSequence, ownerRoute: current),
                .init(request: outsider, ownerRoute: current), .init(request: second, ownerRoute: current)
            ])
            #expect(results.count == 7)
            guard case .success(.handled(.recorded(let firstValue))) = results[0], case .success(.handled(.recorded(let secondValue))) = results[6] else { throw V2ReadReceiptStoreError.corruptPersistenceState }
            #expect(firstValue.readThroughRoomSequence == 1 && secondValue.readThroughRoomSequence == 2)
            #expect(Array(results[1...3]) == [.failure(.ownerChanged), .failure(.ownerChanged), .failure(.ownerChanged)])
            #expect(results[4] == .failure(.roomSequenceNotFound) && results[5] == .failure(.actorNotMember))
            #expect(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.read_receipt_operations").first(decoding: CountRow.self)?.value == 2)
            await #expect(throws: V2ReadReceiptStoreError.ownerChanged) { _ = try await ownerStore.recordGroupOwnerValidated(command: first.command, ownerRoute: stale, now: now) }
            let conflicting = try V2RecordReadReceiptCommand(roomID: room, actorUserID: first.command.actorUserID, operationID: first.command.operationID, readThroughRoomSequence: 2)
            #expect(try await ownerStore.recordGroupOwnerValidated(command: conflicting, ownerRoute: current, now: now) == .handled(.idempotencyConflict))
            try await sql.raw("INSERT INTO im_v2.room_owner_routes(room_id,room_shard_id,route_epoch,created_at,updated_at) VALUES (\(bind: room.uuidValue!), 'room-b', 2, \(bind: now), \(bind: now)), (\(bind: missingRoom.uuidValue!), 'colocated', 2, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at").run()
            let routed = try V2RoutedReadReceiptStore(router: V2PostgresRoomShardRouter(database: control), ownerStores: ["room-b": ownerStore, "colocated": ownerStore], controlStore: PostgresV2ReadReceiptStore(database: control), physicalStoreKeyByShard: ["room-b": "physical", "colocated": "physical"])
            let routedResults = try await routed.recordBatch([first, missing, second])
            #expect(routedResults[1] == .failure(.ownerChanged))
            guard case .success(.idempotent) = routedResults[0], case .success(.idempotent) = routedResults[2] else { throw V2ReadReceiptStoreError.corruptPersistenceState }
            let raced = try request(.init(uuid: memberTwoUUID), 2)
            let races = try await withThrowingTaskGroup(of: V2ReadReceiptOutcome.self) { tasks in
                for i in 0..<20 {
                    tasks.addTask {
                        if i.isMultiple(of: 2) { return try await routed.record(command: raced.command, now: now) }
                        let values = try await routed.recordBatch([raced])
                        switch try #require(values.first) { case .success(let value): return value; case .failure(let error): throw error }
                    }
                }
                var values: [V2ReadReceiptOutcome] = []
                for try await value in tasks { values.append(value) }
                return values
            }
            #expect(races.filter { if case .recorded = $0 { true } else { false } }.count == 1)
            #expect(races.filter { if case .idempotent = $0 { true } else { false } }.count == 19)
            let visible = try await routed.readers(roomID: room, messageID: messageID, actorUserID: senderID, cursor: nil, pageSize: 10)
            #expect(Set(visible.readers.map(\.userID)) == [UserID(uuid: memberTwoUUID), UserID(uuid: memberThreeUUID)])
            try await sql.raw("INSERT INTO im_v2.user_read_receipt_preferences(user_id, allows_group_read_receipts, updated_at) VALUES (\(bind: memberThreeUUID), false, \(bind: now)) ON CONFLICT(user_id) DO UPDATE SET allows_group_read_receipts=false").run()
            let privatePage = try await routed.readers(roomID: room, messageID: messageID, actorUserID: senderID, cursor: nil, pageSize: 10)
            #expect(privatePage.readers.map(\.userID) == [UserID(uuid: memberTwoUUID)])
            #expect(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.read_receipt_operations").first(decoding: CountRow.self)?.value == 3)
            #expect(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.public_user_profiles").first(decoding: CountRow.self)?.value == 0)
            #expect(try await sql.raw("SELECT COUNT(*) AS value FROM im_v2.read_receipt_operations").first(decoding: CountRow.self)?.value == 0)
            print("PASS shared receipt owner batch \(mode): per-row epoch/shard/missing/domain errors; scalar/batch twenty retries commit once; control privacy retained")
        }
    }

    @Test("read receipts and reader pages fence the selected room owner", arguments: [V2GroupCapacityClass.standard, .large], ["single", "batch", "readers"])
    func routedReadReceiptOwnerEpochFence(_ mode: V2GroupCapacityClass, _ kind: String) async throws {
        try await withForwardOwnerDatabases(mode: mode) { control, owner, sql, ownerSQL, room in
            let now = Date(timeIntervalSince1970: 1_750_000_000)
            let profile = try forwardImportTestProfile()
            let send = V2SendMessageService(store: PostgresV2RoomWriteStore(database: owner), capacityProfile: profile,
                limits: try .init(maxUTF8Bytes: 64), now: { now })
            guard case .accepted(let message) = try await send.send(.init(roomID: room, actorUserID: senderID, clientMessageID: .init(uuid: UUID()), text: "original")) else {
                throw V2RoomWriteStoreError.corruptPersistenceState
            }
            try await ownerSQL.raw("DELETE FROM im_v2.public_user_profiles").run()
            try await sql.raw("INSERT INTO im_v2.room_owner_routes(room_id,room_shard_id,route_epoch,created_at,updated_at) VALUES (\(bind: room.uuidValue!), 'room-b', 1, \(bind: now), \(bind: now)) ON CONFLICT (room_id) DO UPDATE SET room_shard_id = EXCLUDED.room_shard_id, route_epoch = EXCLUDED.route_epoch, updated_at = EXCLUDED.updated_at").run()
            let router = V2PostgresRoomShardRouter(database: control)
            let operation = UUID()
            @Sendable func run(_ route: any V2RoomShardRouting, on database: any Database, operationID: UUID) async throws -> String {
                let ownerStore = PostgresV2ReadReceiptStore(database: database)
                let routed = try V2RoutedReadReceiptStore(router: route, ownerStores: ["room-b": ownerStore, "colocated": ownerStore],
                    controlStore: PostgresV2ReadReceiptStore(database: control), physicalStoreKeyByShard: ["room-b": "owner", "colocated": "owner"])
                let command = try V2RecordReadReceiptCommand(roomID: room, actorUserID: .init(uuid: memberTwoUUID), operationID: .init(uuid: operationID), readThroughRoomSequence: message.roomSequence)
                if kind == "readers" {
                    _ = try await routed.readers(roomID: room, messageID: message.messageID, actorUserID: senderID, cursor: nil, pageSize: 10)
                    return "read"
                }
                let outcome: V2ReadReceiptOutcome
                if kind == "batch" {
                    let values = try await routed.recordBatch([.init(command: command, now: now)])
                    switch try #require(values.first) { case .success(let result): outcome = result; case .failure(let error): throw error }
                } else { outcome = try await routed.record(command: command, now: now) }
                switch outcome { case .recorded: return "changed"; case .idempotent: return "replay"; case .idempotencyConflict: return "conflict" }
            }
            let table = "read_receipt_operations"
            let before = try await ownerSQL.raw("SELECT to_jsonb(x)::text AS value FROM im_v2.messages x WHERE message_id=\(bind: message.messageID.uuidValue!)").first(decoding: StringValueRow.self)?.value
            let sequenceBefore = try await ownerSQL.raw("SELECT room_sequence AS value FROM im_v2.rooms WHERE room_id=\(bind: room.uuidValue!)").first(decoding: CountRow.self)?.value
            await #expect(throws: V2ReadReceiptStoreError.ownerChanged) { _ = try await run(router, on: owner, operationID: operation) }
            #expect(try await ownerSQL.raw("SELECT COUNT(*) AS value FROM im_v2.\(unsafeRaw: table)").first(decoding: CountRow.self)?.value == 0)
            #expect(try await ownerSQL.raw("SELECT to_jsonb(x)::text AS value FROM im_v2.messages x WHERE message_id=\(bind: message.messageID.uuidValue!)").first(decoding: StringValueRow.self)?.value == before)
            #expect(try await ownerSQL.raw("SELECT room_sequence AS value FROM im_v2.rooms WHERE room_id=\(bind: room.uuidValue!)").first(decoding: CountRow.self)?.value == sequenceBefore)
            try await sql.raw("UPDATE im_v2.room_owner_routes SET route_epoch=0 WHERE room_id=\(bind: room.uuidValue!)").run()
