            try await sql.raw("INSERT INTO im_v2.group_role_policies (room_id, role) VALUES (\(bind: roomUUID), 'member')").run()
            #expect(try await v2ResolvedGroupPermissions(roomID: roomUUID, role: .member, sql: sql) == [])

