            #expect(try await builder.runOnce(now: now) == .init(claimed: true, published: false, pageCount: 2, itemCount: 2))
            #expect(try await builder.runOnce(now: now) == .init(claimed: true, published: true, pageCount: 2, itemCount: 2))

