                VALUES
                    (\(bind: firstUUID), 'reciprocal01', '双向一', 1, \(bind: now), \(bind: now)),
                    (\(bind: secondUUID), 'reciprocal02', '双向二', 1, \(bind: now), \(bind: now))
                """).run()
            let direct = try V2DirectMessagingService(
