private actor ForwardMediaFailOnceScanner: V2MediaScanProvider {
    let scanner: V2LocalEICARMediaScanner
    /// 首次扫描抛出确定性失败，使导入工作进入暂停而不是持续重试。
    ///
    /// 瞬时失败在新契约下不再因预算耗尽而暂停，因此需要构造暂停行的场景
    /// 必须注入一个重试无法改变结论的失败。
    let deterministicFailure: Bool
    private var fail = true
    init(scanner: V2LocalEICARMediaScanner, deterministicFailure: Bool = false) {
        self.scanner = scanner
        self.deterministicFailure = deterministicFailure
    }
    func scan(mediaID: MediaID) async throws -> V2MediaScanResult {
        if fail {
            fail = false
            if deterministicFailure { throw V2ForwardInboxError.corruptPersistenceState }
            throw V2ForwardMediaCopyError.sourceUnavailable
        }
        return try await scanner.scan(mediaID: mediaID)
    }
}

private actor ForwardMediaBlockingScanner: V2MediaScanProvider {
    private(set) var started = false
    func scan(mediaID: MediaID) async throws -> V2MediaScanResult {
        started = true
        try await Task.sleep(for: .seconds(3_600))
        return .passed
    }
}

private actor ForwardDeliveryTestTarget: V2ForwardExportDelivering {
    let target: any V2ForwardExportDelivering
    let mode: String
    private(set) var calls = 0
    private(set) var waiting = false
    private(set) var drained = false
    init(target: any V2ForwardExportDelivering, mode: String) { self.target = target; self.mode = mode }
    func deliver(_ export: V2ForwardExport) async throws -> V2ForwardTerminalReceipt? {
        calls += 1
        if mode == "paused" { throw V2ForwardDeliveryError.targetUnavailable }
        if mode == "deadline" {
            waiting = true
            defer { drained = true }
            try await Task.sleep(for: .seconds(60))
        }
        let receipt = try await target.deliver(export)
        if mode == "target-ack-loss" && calls == 1 { throw V2ForwardDeliveryError.targetUnavailable }
        if mode == "cancel" {
            waiting = true
            try await Task.sleep(for: .seconds(60))
        }
        return receipt
    }
}

